def _seed_reference_books():
    """主要教材の初期データを reference_books に投入 (重複は skip・冪等)。"""
    conn = db()
    c = conn.cursor()
    inserted = 0
    skipped = 0
    for book in REFERENCE_BOOKS_SEED:
        try:
            c.execute(
                "INSERT INTO reference_books (name, publisher, subject, sub_genre, total_units, unit_type, "
                "suitable_dev_min, suitable_dev_max, level, weeks_to_complete, notes) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                (book["name"], book.get("publisher"), book["subject"], book.get("sub_genre"),
                 book.get("total_units"), book.get("unit_type"),
                 book.get("suitable_dev_min"), book.get("suitable_dev_max"),
                 book.get("level"), book.get("weeks_to_complete"), book.get("notes"))
            )
            conn.commit()
            inserted += 1
        except IntegrityError:
            try: conn.rollback()
            except Exception: pass
            skipped += 1
        except Exception as e:
            try: conn.rollback()
            except Exception: pass
            log.warning(f"[seed_reference_books] {book['name']}: {type(e).__name__}: {str(e)[:100]}")
            skipped += 1
    conn.close()
    # 🔧 Round 2 改善 (2026-05-14): multi-replica log noise 最適化 (案 B: idempotent check)
    # 新規 INSERT 有り → info / 全件 skip (idempotent) → debug / 想定外パターン → warning
    total_seed = len(REFERENCE_BOOKS_SEED)
    if inserted > 0:
        log.info(f"[seed_reference_books] inserted={inserted} skipped={skipped} (total seed={total_seed})")
    elif skipped == total_seed:
        # multi-replica の primary 以外: 全件 idempotent skip → debug でログ抑制 (運用観察性 OK)
        log.debug(f"[seed_reference_books] all skipped - idempotent state (seed={total_seed})")
    else:
        # 想定外 (例: 一部 INSERT 失敗で count 不一致) → warning で alert
        log.warning(f"[seed_reference_books] UNEXPECTED state: inserted={inserted} skipped={skipped} != {total_seed}")
    return inserted, skipped


try:
    _seed_reference_books()
except Exception as _se:
    log.warning(f"[seed_reference_books] failed: {_se}")


