# Auth helpers: magic link token sign/verify & email send
# ==========================================================================
# セキュリティ起動チェック (4番手 監査 2026-04-30):
# 本番 (USE_POSTGRES=True = Railway) で MAGIC_LINK_SECRET が dev fallback または
# 32文字未満の場合は警告ログを出力 (HMAC 署名が予測可能になりトークン偽造のリスク)。
if USE_POSTGRES:
    if MAGIC_LINK_SECRET == "dev-secret-DO-NOT-USE-IN-PROD":
        log.error(
            "[SECURITY] MAGIC_LINK_SECRET が dev fallback のまま本番運用中! "
            "Railway env で 32文字以上のランダム値を MAGIC_LINK_SECRET (または APP_SECRET) に設定してください。"
        )
    elif len(MAGIC_LINK_SECRET) < 32:
        log.warning(
            f"[SECURITY] MAGIC_LINK_SECRET が短い (len={len(MAGIC_LINK_SECRET)} chars). "
            "32文字以上のランダム値を推奨。"
        )


def _sign_session_token(student_id: int, ttl_seconds: int = SESSION_TTL_SECONDS, token_type: str = "session") -> str:
    """student_id, expiry, token_type を HMAC-SHA256 で署名し、URL-safe Base64 エンコード。

    token_type:
    - 'session' (default): 30日有効、Authorization: Bearer で認証 API を叩く長期トークン
    - 'magic': magic link URL に埋め込むトークン。default 30日有効 (_MAGIC_LINK_TTL_SECONDS・
       2026-05-31「時間制限を無しに」で旧 1時間から延長)。/api/auth/verify で長期 session に交換。

    後方互換: 旧フォーマット ("sid.exp.sig" 3 parts) は session として受理する。"""
    import time
    exp = int(time.time()) + ttl_seconds
    payload = f"{token_type}.{student_id}.{exp}"
    sig = hmac.new(MAGIC_LINK_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    raw = f"{payload}.{sig}"
    return base64.urlsafe_b64encode(raw.encode()).decode().rstrip("=")


def _create_magic_link_token(student_id: int, ttl_seconds: int = None) -> str:
    """Magic link 用のトークン。
    🔑 2026-05-31 塾長指示「時間制限を無しに」: デフォルト 30 日 (_MAGIC_LINK_TTL_SECONDS)。
    URL に直入れ + 複数回クリック可なので、漏洩時の保険として 30 日で eventual expiry を残す。
    ttl_seconds 明示指定が無ければ env (_MAGIC_LINK_TTL_SECONDS・default 30 日) を使用。"""
    _eff = ttl_seconds if ttl_seconds is not None else _MAGIC_LINK_TTL_SECONDS
    return _sign_session_token(student_id, ttl_seconds=_eff, token_type="magic")


def _student_email_hash(email: str) -> str:
    """magicv トークンに埋める子メールの短縮ハッシュ (16 hex)。発行後に student_email が
    変更された場合、古いリンクのクリックで新アドレスを誤って確認済み化しないための束縛。"""
    return hashlib.sha256((email or "").strip().lower().encode()).hexdigest()[:16]


def _create_student_email_verify_token(student_id: int, email: str, ttl_seconds: int = None) -> str:
    """🛡️ 子メール (student_email) 宛 welcome 専用 magic link トークン (security review 2026-06-11)。
    通常の magic と同じく /api/auth/verify でログインできるが、token type 'magicv' を見た
    verify 側が「このリンクは student_email 宛にのみ送られた = クリック者はそのアドレスを
    受信できた」とみなし student_email_verified=1 を立てる (メール確認フロー)。
    親宛リンク (type 'magic') の転送では確認されない点が重要 — 確認に使えるのは
    子アドレスの受信箱に届いた本トークンだけ。payload にアドレスのハッシュを含め、
    発行後に student_email が変わっていたら確認しない。
    フォーマット: base64("magicv.{sid}.{exp}.{email_hash16}.{sig}") — _verify_session_token の
    5 パート分岐で検証。"""
    import time as _t
    _eff = ttl_seconds if ttl_seconds is not None else _MAGIC_LINK_TTL_SECONDS
    exp = int(_t.time()) + _eff
    payload = f"magicv.{student_id}.{exp}.{_student_email_hash(email)}"
    sig = hmac.new(MAGIC_LINK_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    raw = f"{payload}.{sig}"
    return base64.urlsafe_b64encode(raw.encode()).decode().rstrip("=")


def _verify_session_token(token: str, expected_type: str = "session") -> Optional[dict]:
    """トークンを検証して {student_id, exp, token_type} を返す。無効/期限切れなら None。

    新フォーマット: "type.sid.exp.sig" (4 parts)
    旧フォーマット: "sid.exp.sig" (3 parts) — 後方互換として 'session' 扱いで受理。
    expected_type を None にすると type チェックをスキップ (verify endpoint で session/magic
    両方を許容するため)。
    """
    import time
    if not token:
        return None
    try:
        padded = token + "=" * (-len(token) % 4)
        raw = base64.urlsafe_b64decode(padded).decode()
        parts = raw.split(".")
        # 子メール確認付き magic link (magicv.sid.exp.emailhash.sig・5 parts) — 2026-06-12
        # security review: クリックでログイン + student_email_verified=1 (/api/auth/verify 側)。
        # expected_type チェックにより session を要求する認証 API には使えない (verify 専用)。
        if len(parts) == 5:
            ttype, sid_str, exp_str, ehash, sig = parts
            if ttype != "magicv":
                return None
            payload = f"{ttype}.{sid_str}.{exp_str}.{ehash}"
            expected = hmac.new(MAGIC_LINK_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, expected):
                return None
            if expected_type and ttype != expected_type:
                return None
            exp = int(exp_str)
            if exp < int(time.time()):
                return None
            return {"student_id": int(sid_str), "exp": exp, "token_type": ttype, "email_hash": ehash}
        # 新フォーマット (type.sid.exp.sig)
        if len(parts) == 4:
            ttype, sid_str, exp_str, sig = parts
            payload = f"{ttype}.{sid_str}.{exp_str}"
            expected = hmac.new(MAGIC_LINK_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, expected):
                return None
            if expected_type and ttype != expected_type:
                # 🔐 管理者なりすまし(impersonation)トークンは、session を要求する全 API で
                #   session と同様に受理する (status gate の回避は _get_current_student が
                #   token_type='impersonation' を見て行う)。impersonation は admin 認証経由でしか
                #   発行されない。それ以外の型不一致 (magic 等) は従来どおり拒否。
                if not (expected_type == "session" and ttype == "impersonation"):
                    # session を期待した API に magic を投げてきた等は拒否
                    return None
            exp = int(exp_str)
            if exp < int(time.time()):
                return None
            return {"student_id": int(sid_str), "exp": exp, "token_type": ttype}
        # 旧フォーマット (sid.exp.sig) — session として受理 (後方互換)
        if len(parts) == 3:
            sid_str, exp_str, sig = parts
            expected = hmac.new(MAGIC_LINK_SECRET.encode(), f"{sid_str}.{exp_str}".encode(), hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, expected):
                return None
            if expected_type and expected_type != "session":
                return None
            exp = int(exp_str)
            if exp < int(time.time()):
                return None
            return {"student_id": int(sid_str), "exp": exp, "token_type": "session"}
        return None
    except Exception:
        return None


# ==========================================================================
# 紹介ループ (Referral): 既存生徒が新規生徒を呼ぶと両者に特典 (2026-05-05)
# 紹介URL: https://trillion-ai-juku.com/?ref=<HMAC code>
# code = base64(<student_id>.<HMAC(student_id)>)
# 既存 MAGIC_LINK_SECRET を流用 (新規 secret 設定不要)
# ==========================================================================
def _generate_referral_code(student_id: int) -> str:
    """生徒IDから予測不能な紹介コードを生成。HMAC ベースなのでDB不要で検証可能。
    Security: full 256-bit HMAC (brute force 困難)"""
    payload = f"ref.{student_id}"
    sig = hmac.new(MAGIC_LINK_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    raw = f"{student_id}.{sig}"
    return base64.urlsafe_b64encode(raw.encode()).decode().rstrip("=")


def _verify_referral_code(code: str) -> Optional[int]:
    """紹介コードを検証して referrer の student_id を返す。無効なら None。
    Security: full 256-bit HMAC verification"""
    if not code or len(code) > 200:
        return None
    try:
        padded = code + "=" * (-len(code) % 4)
        raw = base64.urlsafe_b64decode(padded).decode()
        parts = raw.split(".")
        if len(parts) != 2:
            return None
        sid_str, sig = parts
        # 後方互換: 旧 16 char 切り詰め HMAC も受理 (deploy 直後の旧コード対応)
        expected_full = hmac.new(MAGIC_LINK_SECRET.encode(), f"ref.{sid_str}".encode(), hashlib.sha256).hexdigest()
        if not (hmac.compare_digest(sig, expected_full) or hmac.compare_digest(sig, expected_full[:16])):
            return None
        return int(sid_str)
    except Exception:
        return None


# In-memory rate limit tracker: {(ip, bucket): [timestamps]}
_RATE_LIMIT_STORE: dict = {}

def _client_ip(request) -> str:
    """X-Forwarded-For を考慮して本物のクライアントIPを取得（Railway等のプロキシ対応）。"""
    if not request:
        return "unknown"
    xff = request.headers.get("x-forwarded-for", "")
    if xff:
        # 先頭が元のクライアントIP（カンマ区切り）
        return xff.split(",")[0].strip()
    xri = request.headers.get("x-real-ip", "")
    if xri:
        return xri.strip()
    return request.client.host if request.client else "unknown"


def _check_rate_limit_ip(request, bucket: str, limit: int = 10, window: int = 60) -> None:
    """IPアドレス単位の簡易レートリミッタ。超過時は HTTPException 429 を投げる。
    プロセス内のin-memoryなのでマルチワーカーでは厳密ではないが、ブルートフォース抑制には十分。"""
    import time as _t
    ip = _client_ip(request)
    key = (ip, bucket)
    now = _t.time()
    timestamps = _RATE_LIMIT_STORE.get(key, [])
    timestamps = [t for t in timestamps if now - t < window]
    if len(timestamps) >= limit:
        raise HTTPException(status_code=429, detail="リクエストが多すぎます。しばらく待ってから再度お試しください。")
    timestamps.append(now)
    _RATE_LIMIT_STORE[key] = timestamps
    # メモリ肥大化対策: 古いバケットを定期的にクリーンアップ
    if len(_RATE_LIMIT_STORE) > 10000:
        cutoff = now - 3600
        for k in list(_RATE_LIMIT_STORE.keys()):
            _RATE_LIMIT_STORE[k] = [t for t in _RATE_LIMIT_STORE[k] if t > cutoff]
            if not _RATE_LIMIT_STORE[k]:
                del _RATE_LIMIT_STORE[k]


def _check_recipient_send_cap(to_email: str, limit: int = 10, window: int = 3600) -> bool:
    """🛡️ 2026-06-12 security MEDIUM fix: 送信先メールアドレス単位の送信上限。
    IP rate limit は IP 分散 + 複数アカウント (student_email に第三者アドレスを設定して
    magic-link を連打) で迂回できるため、最終的な受信者単位で 1 時間 limit 通に制限し
    メール爆撃の踏み台化を防ぐ。正規フローの再送はせいぜい数通/時なので影響なし。
    超過時は False (呼び出し側で送信スキップ)。in-memory per-process のベストエフォート
    (render.yaml は uvicorn 単一プロセス起動なので実効・workers 追加時は要共有ストア化)。"""
    import time as _t
    key = (f"rcpt:{(to_email or '').lower().strip()}", "magic_link_send")
    now = _t.time()
    timestamps = [t for t in _RATE_LIMIT_STORE.get(key, []) if now - t < window]
    if len(timestamps) >= limit:
        return False
    timestamps.append(now)
    _RATE_LIMIT_STORE[key] = timestamps
    return True


def _recipient_send_cap_exceeded(to_email: str, limit: int = 10, window: int = 3600) -> bool:
    """_check_recipient_send_cap の消費しない事前 peek 版 (3 視点 review HIGH 指摘)。
    request_magic_link で旧 OTP を無効化する前に cap 到達を判定するために使う —
    cap 到達後の再送連打が「旧コードを殺して新コードは誰にも届かない」状態を作り、
    正規ユーザーが最大 1 時間ログイン不能になる事故を防ぐ。limit/window は
    _check_recipient_send_cap と必ず同値にすること。"""
    import time as _t
    key = (f"rcpt:{(to_email or '').lower().strip()}", "magic_link_send")
    now = _t.time()
    return len([t for t in _RATE_LIMIT_STORE.get(key, []) if now - t < window]) >= limit


def _check_rate_limit_caller(request, authorization: Optional[str], bucket: str, limit: int = 10, window: int = 60) -> None:
    """🛡️ 2026-05-26 audit M5 fix: 生徒 session_token があれば student_id 単位、無ければ IP 単位。
    校内 NAT で複数生徒が同時に同 endpoint を叩く scene で false positive 429 を防ぐ。
    admin Bearer は IP fallback (CEO ダッシュ少人数想定で支障なし)。"""
    import time as _t
    caller_key: str = f"ip:{_client_ip(request)}"
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if not _verify_admin_token(token):
            claims = _verify_session_token(token)
            if claims and claims.get("student_id"):
                try:
                    sid = int(claims["student_id"])
                    caller_key = f"sid:{sid}"
                except (TypeError, ValueError):
                    pass
    key = (caller_key, bucket)
    now = _t.time()
    timestamps = _RATE_LIMIT_STORE.get(key, [])
    timestamps = [t for t in timestamps if now - t < window]
    if len(timestamps) >= limit:
        raise HTTPException(status_code=429, detail="リクエストが多すぎます。しばらく待ってから再度お試しください。")
    timestamps.append(now)
    _RATE_LIMIT_STORE[key] = timestamps


