def _get_recent_sns_posts(days: int = 30) -> list:
    """過去N日間にdaily_sns_postで生成済みのテキストを返す(重複回避用)"""
    conn = db()
    c = conn.cursor()
    since = datetime.now(timezone.utc) - timedelta(days=days)
    try:
        c.execute(
            "SELECT props FROM events WHERE name = 'daily_sns_post' AND created_at >= ?",
            (since,)
        )
        rows = c.fetchall()
    except Exception as e:
        log.warning(f"_get_recent_sns_posts query failed: {e}")
        rows = []
    conn.close()
    texts = []
    for r in rows:
        try:
            props = json.loads(r["props"] or "{}")
            for p in props.get("posts", []):
                t = (p.get("text") or "")[:120]
                if t:
                    texts.append(t)
        except Exception:
            pass
    return texts


def _check_daily_sns_sent_today_jst() -> bool:
    """今日(JST)のdaily_sns_postが既に events に記録されているか確認"""
    JST = timezone(timedelta(hours=9))
    today_jst = datetime.now(JST).date()
    today_start_utc = datetime.combine(today_jst, dt_time(0, 0), tzinfo=JST).astimezone(timezone.utc)
    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            "SELECT COUNT(*) AS n FROM events WHERE name = 'daily_sns_post' AND created_at >= ?",
            (today_start_utc,)
        )
        n = c.fetchone()["n"]
    except Exception as e:
        log.warning(f"_check_daily_sns_sent_today_jst failed: {e}")
        n = 0
    conn.close()
    return n > 0


def _compute_sns_utm_cv(days: int = 30) -> dict:
    """utm_content (authority/testimonial) ごとの LP CV を集計。
    返却: {utm_content: {views, submits, cv_rate}}
    Threads 経由の流入 (utm_source=threads) のみ対象。"""
    conn = db()
    c = conn.cursor()
    cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
    try:
        c.execute(
            """SELECT name, props, session_id FROM events
               WHERE name IN ('lp_view', 'lp_form_submit') AND created_at > ?
               LIMIT 20000""",
            (cutoff,)
        )
        rows = list(c.fetchall())
    finally:
        conn.close()

    views = {}  # utm_content -> set(session_ids)
    submits = {}
    for r in rows:
        name = r["name"] if hasattr(r, "keys") else r[0]
        props_raw = r["props"] if hasattr(r, "keys") else r[1]
        sess = (r["session_id"] if hasattr(r, "keys") else r[2]) or "_anon"
        try:
            props = json.loads(props_raw) if isinstance(props_raw, str) else (props_raw or {})
        except Exception:
            props = {}
        # Threads からの流入のみ
        utm_source = props.get("utm_source", "")
        if utm_source != "threads":
            continue
        content = props.get("utm_content", "unknown")
        if name == "lp_view":
            views.setdefault(content, set()).add(sess)
        elif name == "lp_form_submit":
            submits.setdefault(content, set()).add(sess)

    out = {}
    for content, view_set in views.items():
        v_count = len(view_set)
        s_count = len(submits.get(content, set()))
        cv = (s_count / v_count) if v_count > 0 else 0.0
        out[content] = {"views": v_count, "submits": s_count, "cv_rate": cv}
    return out


SNS_UTM_ALLOWLIST = {"authority": "数字×権威型", "testimonial": "体験談ストーリー型"}

# 📡 集客チャネル別バンディット (utm_source 別 CV 集計 + epsilon-greedy)
# 2026-05-11 塾長指示「AI チームで半自動で集客〜収益化」の集客 phase 強化
SNS_CHANNEL_ALLOWLIST = {"threads", "x", "instagram", "chatgpt_store", "google", "youtube"}
SNS_CHANNEL_BANDIT_EPSILON = 0.20  # 20% 探索 / 80% 活用 (LP variant bandit と同値・project_ai_juku_lp_bandit.md)
# CV 評価のための最小 view 数 (binomial CI 妥当性の最低ライン)。
# 集客 channel が 6 個に分散することを考慮し LP variant bandit の cold start (30) と同値で運用。
# 100+ が理想だが初期数か月は探索フェーズになるため許容範囲。
SNS_CHANNEL_BANDIT_MIN_VIEWS = 30


def _compute_channel_bandit_weights(days: int = 30) -> dict:
    """過去N日の utm_source 別 CV を集計し epsilon-greedy weight を返す。
    Allowlist (threads/x/instagram/chatgpt_store/google/youtube) のみ採用 (prompt injection 防止)。
    探索 (epsilon=0.20) / 活用 (1-epsilon=0.80) で各 channel に最低保証。
    早期段階 (views < 30) は均等配分。

    return: {channel: {"views": int, "submits": int, "cv_rate": float, "weight": float}}
    weight の合計は 1.0 になる。
    """
    if days <= 0 or days > 365:
        days = 30
    conn = db()
    c = conn.cursor()
    cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
    try:
        c.execute(
            """SELECT name, props, session_id FROM events
               WHERE name IN ('lp_view', 'lp_form_submit') AND created_at > ?
               LIMIT 20000""",
            (cutoff,)
        )
        rows = list(c.fetchall())
    finally:
        conn.close()

    views = {ch: set() for ch in SNS_CHANNEL_ALLOWLIST}
    submits = {ch: set() for ch in SNS_CHANNEL_ALLOWLIST}
    for r in rows:
        name = r["name"] if hasattr(r, "keys") else r[0]
        props_raw = r["props"] if hasattr(r, "keys") else r[1]
        sess = (r["session_id"] if hasattr(r, "keys") else r[2]) or "_anon"
        try:
            props = json.loads(props_raw) if isinstance(props_raw, str) else (props_raw or {})
        except Exception:
            props = {}
        utm_source = (props.get("utm_source") or "").strip().lower()
        if utm_source not in SNS_CHANNEL_ALLOWLIST:
            continue
        if name == "lp_view":
            views[utm_source].add(sess)
        elif name == "lp_form_submit":
            submits[utm_source].add(sess)

    # CV 計算
    raw_cv = {}
    total_views_known = 0
    for ch in SNS_CHANNEL_ALLOWLIST:
        v = len(views[ch])
        s = len(submits[ch])
        cv = (s / v) if v > 0 else 0.0
        raw_cv[ch] = {"views": v, "submits": s, "cv_rate": cv}
        if v >= SNS_CHANNEL_BANDIT_MIN_VIEWS:
            total_views_known += v

    # epsilon-greedy weight 計算
    # 全 channel で views < min なら完全均等 (early-stage exploration)
    qualified = [ch for ch in SNS_CHANNEL_ALLOWLIST if raw_cv[ch]["views"] >= SNS_CHANNEL_BANDIT_MIN_VIEWS]
    n_channels = len(SNS_CHANNEL_ALLOWLIST)
    epsilon = SNS_CHANNEL_BANDIT_EPSILON
    exploration_weight = epsilon / n_channels  # 全 channel に均等な探索枠

    out = {}
    if not qualified:
        # 全 channel が min_views 未満 → 完全均等 (1/n)
        for ch in SNS_CHANNEL_ALLOWLIST:
            out[ch] = {**raw_cv[ch], "weight": 1.0 / n_channels}
        return out

    # 活用フェーズ: qualified channel の CV 比に基づいて exploitation 枠を配分
    total_cv = sum(raw_cv[ch]["cv_rate"] for ch in qualified)
    for ch in SNS_CHANNEL_ALLOWLIST:
        weight = exploration_weight  # 最低保証 (探索枠)
        if ch in qualified and total_cv > 0:
            cv_share = raw_cv[ch]["cv_rate"] / total_cv  # qualified 内での相対 CV
            weight += (1 - epsilon) * cv_share
        out[ch] = {**raw_cv[ch], "weight": weight}

    # 念のため正規化 (浮動小数誤差吸収)
    total_w = sum(v["weight"] for v in out.values())
    if total_w > 0:
        for ch in out:
            out[ch]["weight"] = out[ch]["weight"] / total_w
    return out


def _build_channel_bandit_hint() -> str:
    """過去30日 channel 別 CV から bandit weight を計算 → SNS 生成 prompt 用ヒント文。
    投稿頻度の割合を「最優先チャネル」「補助チャネル」「探索チャネル」に分類して指示。
    Statistical: 各 channel 30 views 以上 (binomial CI 妥当性) + 全体 100 views 以上で hint 出力。
    """
    weights = _compute_channel_bandit_weights(days=30)
    total_views = sum(w["views"] for w in weights.values())
    if total_views < 100:
        # 全体 100 views 未満は均等配分継続 (ヒント出さない)
        return ""

    # weight 高い順
    sorted_ch = sorted(weights.items(), key=lambda x: x[1]["weight"], reverse=True)
    top_ch, top_data = sorted_ch[0]
    weak_ch = [ch for ch, d in sorted_ch[1:] if d["weight"] < 0.10]  # 10% 未満は弱い

    ch_label = {
        "threads": "Threads",
        "x": "X (Twitter)",
        "instagram": "Instagram",
        "chatgpt_store": "ChatGPT Store",
        "google": "Google 検索",
        "youtube": "YouTube",
    }
    top_label = ch_label.get(top_ch, top_ch)
    top_cv = top_data["cv_rate"] * 100
    weak_labels = "・".join(ch_label.get(c, c) for c in weak_ch) if weak_ch else "(なし)"
    return (
        f"\n\n【📡 過去30日 集客チャネル別 CV (bandit weight)】\n"
        f"最強チャネル: {top_label} (CV {top_cv:.1f}% / views {top_data['views']} / weight {top_data['weight']*100:.0f}%) → 投稿を集中させる\n"
        f"弱い・未測定チャネル: {weak_labels} → 探索投稿は最小限\n"
        f"今回の生成では、{top_label} に最適化された訴求を中心にしてください。"
    )


def _build_sns_winning_hint() -> str:
    """過去30日 CV データから「効いている型」を判定し、prompt 用ヒント文を返す。
    Security: UTM 値は SNS_UTM_ALLOWLIST にあるもののみ採用 (prompt 注入攻撃防止)。
    Statistical: 150 views 以上 (binomial CI 妥当性) + 30% 以上の差 (hysteresis 兼ねた安定性)。"""
    cv_data = _compute_sns_utm_cv(days=30)
    candidates = []
    for utm, data in cv_data.items():
        # Allowlist のみ採用 (prompt injection 防御)
        if utm not in SNS_UTM_ALLOWLIST:
            continue
        # 統計的有意性確保: 150 views 必須 (CI が狭まる)
        if data["views"] >= 150:
            candidates.append((SNS_UTM_ALLOWLIST[utm], data["cv_rate"], data["views"]))
    if len(candidates) < 2:
        return ""
    candidates.sort(key=lambda x: x[1], reverse=True)
    winner_type, winner_cv, winner_views = candidates[0]
    loser_type, loser_cv, _ = candidates[1]
    # 30% 以上の差がない時はヒント出さない (hysteresis: borderline で flicker しない)
    if winner_cv <= loser_cv * 1.3:
        return ""
    # winner/loser はハードコード辞書値なので f-string 安全
    return (f"\n\n【📊 過去30日 Threads 経由 CV データ (重要)】\n"
            f"「{winner_type}」が「{loser_type}」より CV 率が高い (CV {winner_cv*100:.1f}% vs {loser_cv*100:.1f}%、views {winner_views}+).\n"
            f"今回の生成では、「{winner_type}」のスタイル・訴求パターンを他の型にも一部反映させ、"
            f"より高い engagement を狙ってください。各 type の本数は崩さない (1本ずつ)。")


def _generate_daily_sns_posts() -> list:
    """塾長キャラのThreads投稿5本(5型ローテ)を生成。
    _call_ai_safe(task_type='daily_sns') 経由 = Gemini Flash 優先 (低 stake + 課金抑制)。
    Gemini 失敗時は Anthropic にフォールバック (4段降格 + Tier 4 Gemini で結局止まらない)。
    Phase 3 (2026-05-05): 過去30日 CV データから効いてる型のヒントを prompt に注入。
    """
    # ANTHROPIC / GEMINI / OPENAI のいずれか 1 つでもあれば動く設計 (3段防御)
    if not ANTHROPIC_API_KEY and not GEMINI_API_KEY and not OPENAI_API_KEY:
        log.warning("[DailySNS] ANTHROPIC_API_KEY / GEMINI_API_KEY / OPENAI_API_KEY すべて未設定でスキップ")
        return []
    recent = _get_recent_sns_posts(days=30)
    avoid_section = ""
    if recent:
        joined = "\n".join(f"- {t}" for t in recent[-25:])  # 直近25本まで
        avoid_section = f"\n\n【重複回避】以下は過去30日に生成済み。同じ訴求/同じ書き出しは避けてください:\n{joined}"

    winning_hint = _build_sns_winning_hint()
    channel_hint = _build_channel_bandit_hint()
    types_section = "\n".join(f"{i+1}. {t['name']}: {t['desc']}" for i, t in enumerate(POST_TYPES))
    user_msg = f"""今日のThreads投稿を5本作成してください。5型を1本ずつ:

{types_section}
{avoid_section}{winning_hint}{channel_hint}

【🔗 LP誘導リンクの自動挿入】
以下の 2 type の本文末尾には、必ず空行を挟んで誘導リンクを含めてください:

- **数字×権威型**: 末尾に「→ https://trillion-ai-juku.com/lp.html?utm_source=threads&utm_content=authority」
- **体験談ストーリー型**: 末尾に「→ https://trillion-ai-juku.com/lp.html?utm_source=threads&utm_content=testimonial」

リンク前には「気になる方は」「詳細はこちら」「14日間無料体験」などの自然な導入文を1行で書いてください。
他の3 type (逆説型/保護者あるある共感型/二択問いかけ型) はリンクを含めないこと。

【出力形式】純粋なJSONのみ、他のテキストは含めない:
{{
  "posts": [
    {{"type": "逆説型", "text": "本文(改行は\\n)"}},
    {{"type": "保護者あるある共感型", "text": "本文"}},
    {{"type": "数字×権威型", "text": "本文(末尾にリンク必須)"}},
    {{"type": "体験談ストーリー型", "text": "本文(末尾にリンク必須)"}},
    {{"type": "二択問いかけ型", "text": "本文"}}
  ]
}}"""

    system_prompt = f"{JUKUCHO_PERSONA}\n\n{THREADS_RULES}"
    try:
        data = _call_ai_safe(
            {
                "model": DAILY_SNS_MODEL,
                "max_tokens": 3000,
                "system": system_prompt,
                "messages": [{"role": "user", "content": user_msg}],
            },
            task_type="daily_sns",
        )
        content_text = data["content"][0]["text"].strip()
        # コードブロックで囲まれている場合は除去
        if content_text.startswith("```"):
            content_text = content_text.split("```", 2)[1]
            if content_text.startswith("json"):
                content_text = content_text[4:]
            content_text = content_text.strip()
            if content_text.endswith("```"):
                content_text = content_text[:-3].strip()
        parsed = json.loads(content_text)
        posts = parsed.get("posts", [])
        actual_model = data.get("_actual_model") or DAILY_SNS_MODEL
        provider = data.get("_provider") or "anthropic"
        log.info(f"[DailySNS] Generated {len(posts)} posts via {actual_model} ({provider})")
        return posts
    except Exception as e:
        log.error(f"[DailySNS] Generation failed: {type(e).__name__}: {e}")
        return []


def _record_daily_sns_sent(posts: list, resend_id: str = ""):
    """events に履歴を保存"""
    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            ("daily_sns_post", json.dumps({"posts": posts, "resend_id": resend_id, "model": DAILY_SNS_MODEL}, ensure_ascii=False), "daily_sns_scheduler")
        )
        conn.commit()
    except Exception as e:
        log.error(f"[DailySNS] Failed to record event: {e}")
    conn.close()


def _send_daily_sns_email(posts: list, to_email: str) -> dict:
    """Resend で塾長 Gmail に投稿候補を送信"""
    if not RESEND_API_KEY:
        log.warning("[DailySNS] RESEND_API_KEY 未設定でスキップ")
        return {"sent": False, "reason": "no_api_key"}
    if not to_email:
        log.warning("[DailySNS] 送信先未設定でスキップ")
        return {"sent": False, "reason": "no_to"}
    if not posts:
        return {"sent": False, "reason": "no_posts"}

    JST = timezone(timedelta(hours=9))
    today_jst = datetime.now(JST).strftime("%Y-%m-%d (%a)")
    subject = f"📱 今日のThreads投稿候補 5本 / {today_jst}"

    def card(p):
        text = (p.get("text") or "").replace("\n", "<br>")
        ptype = p.get("type") or "?"
        char_count = len(p.get("text") or "")
        return f"""
<div style="background:#fafafa;border-left:4px solid #6366f1;border-radius:8px;padding:1.2rem;margin-bottom:1.2rem;">
  <div style="display:flex;align-items:center;gap:0.5rem;margin-bottom:0.5rem;flex-wrap:wrap;">
    <span style="background:#6366f1;color:white;font-weight:900;padding:0.15rem 0.6rem;border-radius:4px;font-size:0.78rem;">{ptype}</span>
    <span style="color:#888;font-size:0.78rem;">{char_count}字</span>
  </div>
  <div style="background:white;border:1px solid #e5e5e5;border-radius:6px;padding:1rem;font-family:'Hiragino Sans','Yu Gothic',sans-serif;line-height:1.7;color:#222;font-size:0.95rem;white-space:pre-wrap;">{text}</div>
</div>"""

    posts_html = "".join(card(p) for p in posts)
    html = f"""<!DOCTYPE html>
<html lang="ja"><head><meta charset="UTF-8"></head>
<body style="font-family:-apple-system,'Hiragino Sans','Yu Gothic',sans-serif;line-height:1.7;color:#333;max-width:680px;margin:0 auto;padding:1.5rem;background:#f5f5f7;">
<div style="background:white;border-radius:14px;padding:1.5rem;margin-bottom:1.5rem;">
<h1 style="font-size:1.3rem;color:#6366f1;margin:0 0 0.4rem;">📱 今日のThreads投稿候補</h1>
<p style="color:#666;font-size:0.85rem;margin:0;">{today_jst} / 5型ローテ・塾長キャラ・過去30日と重複回避済み</p>
</div>
<div style="background:white;border-radius:14px;padding:1.5rem;margin-bottom:1.5rem;">
<p style="font-size:0.85rem;color:#666;margin-top:0;">朝7-8時 / 夜21時前後が母親ターゲット最適。リプ起爆装置の<strong>二択問いかけ型</strong>を朝に投げて、夜は<strong>体験談ストーリー型</strong>か<strong>共感型</strong>がおすすめ。</p>
{posts_html}
</div>
<div style="background:#eef2ff;border-radius:14px;padding:1.2rem;font-size:0.85rem;color:#444;line-height:1.8;">
<strong>📌 投稿後の運用</strong><br>
1. <strong>投稿後1時間が勝負</strong>。リプライ即返信でStage1突破<br>
2. 反応の良かった型を覚えておく → 翌日以降の生成にフィードバック<br>
3. 5本全部使う必要なし。気に入ったものだけでOK
</div>
<p style="font-size:0.78rem;color:#999;text-align:center;margin-top:1.5rem;">🤖 AIコーチングSNS研究員 (claude-sonnet-4-6) / 毎朝{DAILY_SNS_HOUR_JST}時に自動配信</p>
</body></html>"""

    try:
        req = urllib.request.Request(
            "https://api.resend.com/emails",
            data=json.dumps({
                "from": FROM_EMAIL,
                "to": [to_email],
                "subject": subject,
                "html": html,
            }).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {RESEND_API_KEY}",
                "Content-Type": "application/json",
                "User-Agent": "ai-juku-daily-sns/1.0",
            },
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=15) as resp:
            result = json.loads(resp.read().decode())
            log.info(f"[DailySNS] Email sent to {to_email}: {result.get('id')}")
            return {"sent": True, "resend_id": result.get("id")}
    except Exception as e:
        log.error(f"[DailySNS] Email send failed: {type(e).__name__}: {e}")
        return {"sent": False, "error": str(e)}


def _run_daily_sns_post() -> dict:
    """1日分の生成→送信→記録 を実行(scheduler / admin 共用)"""
    if _check_daily_sns_sent_today_jst():
        log.info("[DailySNS] Already sent today (JST), skipping")
        return {"ran": False, "reason": "already_sent_today"}
    if not DAILY_SNS_TO_EMAIL:
        log.warning("[DailySNS] DAILY_SNS_TO_EMAIL 未設定でスキップ")
        return {"ran": False, "reason": "no_recipient"}
    posts = _generate_daily_sns_posts()
    if not posts:
        return {"ran": False, "reason": "generation_failed"}
    result = _send_daily_sns_email(posts, DAILY_SNS_TO_EMAIL)
    if result.get("sent"):
        _record_daily_sns_sent(posts, resend_id=result.get("resend_id", ""))
    return {"ran": True, "posts_count": len(posts), "send_result": result}


# ==========================================================================
# 体験管理 in-process scheduler (毎日 JST 10:00)
# 外部 cron が無くても expire-trials / trial-reminders / trial-followups を自動実行
# ==========================================================================
def _check_scheduler_ran_today_jst(event_name: str) -> bool:
    """今日(JST)に同じスケジューラタスクが events に記録されているか確認。
    multi-replica の重複実行を防ぐ (DB 共有 = lock 代わり)。"""
    JST = timezone(timedelta(hours=9))
    today_jst = datetime.now(JST).date()
    today_start_utc = datetime.combine(today_jst, dt_time(0, 0), tzinfo=JST).astimezone(timezone.utc)
    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            "SELECT COUNT(*) AS n FROM events WHERE name = ? AND created_at >= ?",
            (event_name, today_start_utc)
        )
        n = c.fetchone()["n"]
    except Exception as e:
        log.warning(f"_check_scheduler_ran_today_jst({event_name}) failed: {e}")
        n = 0
    finally:
        conn.close()
    return n > 0


def _record_scheduler_run(event_name: str, payload: dict):
    """events テーブルに scheduler 実行記録を残す (重複検出用)"""
    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, 'in_process_scheduler')",
            (event_name, json.dumps(payload, ensure_ascii=False)[:4000])
        )
        conn.commit()
    except Exception as e:
        log.warning(f"_record_scheduler_run({event_name}) failed: {e}")
    finally:
        conn.close()


async def _trial_management_scheduler():
    """体験管理 3 タスクを毎日 JST 10:00 に内部実行。同じ FastAPI process 内なので
    HTTP 越しでなく直接 endpoint 関数を呼ぶ。multi-replica は events テーブル lock で防止。
    daily-alerts は dedup が無いため敢えて含めない (重複 LINE push 事故防止)。"""
    JST = timezone(timedelta(hours=9))
    TARGET_HOUR_JST = 10
    log.info(f"[TrialMgr] Scheduler started, target hour JST {TARGET_HOUR_JST}:00")
    secret = CRON_SECRET

    while True:
        try:
            now_jst = datetime.now(JST)
            target = now_jst.replace(hour=TARGET_HOUR_JST, minute=0, second=0, microsecond=0)
            if target <= now_jst:
                target += timedelta(days=1)
            sleep_secs = (target - now_jst).total_seconds()
            log.info(f"[TrialMgr] Next run at {target.isoformat()} (in {int(sleep_secs)}s)")
            await asyncio.sleep(sleep_secs)

            # multi-replica 重複実行防止: 今日既に他 replica が走っていればスキップ
            if _check_scheduler_ran_today_jst("trial_mgmt_run"):
                log.info("[TrialMgr] Skipped (already ran today by another replica)")
                continue

            # 7 タスクを順次実行 (例外は個別に握りつぶしてループ継続)
            tasks = [
                ("expire-trials", lambda: cron_expire_trials(x_cron_secret=secret, dry_run=False)),
                ("trial-reminders", lambda: cron_trial_reminders(x_cron_secret=secret, dry_run=False)),
                ("trial-followups", lambda: cron_trial_followups(x_cron_secret=secret, dry_run=False)),
                ("trial-unused-warning", lambda: cron_trial_unused_warning(x_cron_secret=secret, dry_run=False)),
                # 🚨 体験中・離脱予兆者への AI 個別フォロー (2026-05-11 追加)
                ("trial-rescue", lambda: admin_trial_rescue_now(payload={"dry_run": False}, x_cron_secret=secret)),
                # 📧 体験 Day 2 / Day 5 nurture メール (集客 funnel #3・2026-05-19 追加)
                ("trial-nurture", lambda: cron_trial_nurture(x_cron_secret=secret, dry_run=False)),
                # 🔄 Stripe ↔ DB 整合性同期 (webhook 取りこぼし救済・双方向・2026-05-29 追加)
                # 昇格(active→paid) + 降格(past_due/canceled) を毎日 reconcile。STRIPE 未設定なら内部で 503→例外で skip。
                ("stripe-reconcile", lambda: admin_stripe_reconcile(authorization=None, x_cron_secret=secret)),
                # 💰 payments 記録の自己修復 (2026-06-11 追加): webhook 失敗/生徒未紐付けで取りこぼした
                # paid invoice を日次で冪等 backfill (dedup キーは invoice id 正規化済・35日窓で十分)
                # details は invoice 明細で巨大になり得るため scheduler 記録 (4000字 truncate) からは落とす
                ("stripe-backfill-payments", lambda: {k: v for k, v in admin_stripe_backfill_payments(payload={"dry_run": False, "days": 35}, authorization=None, x_cron_secret=secret).items() if k != "details"}),
                # 🔍 trialing 残留サブスク検出 (2026-06-12 追加): reconcile は active のみ・
                # diagnose-orphan-subs は deleted のみで「生きている残留 trial サブ」が課金開始まで
                # 不可視だった穴を塞ぐ。leftover/orphan があれば critical event で塾長に可視化。
                # STRIPE 未設定なら内部で 503→例外で skip。normal (進行中 trial_extended 全件) は
                # scheduler 記録の肥大化防止で落とす (backfill の details と同じ規約)。
                ("trialing-leftovers", lambda: {k: v for k, v in admin_stripe_diagnose_trialing_leftovers(notify=1, authorization=None, x_cron_secret=secret).items() if k != "normal"}),
            ]
            results = {}
            for task_name, fn in tasks:
                try:
                    r = fn()
                    results[task_name] = r
                    log.info(f"[TrialMgr] {task_name}: {r}")
                except Exception as e:
                    results[task_name] = {"error": f"{type(e).__name__}: {e}"}
                    log.error(f"[TrialMgr] {task_name} failed: {type(e).__name__}: {e}", exc_info=True)
            _record_scheduler_run("trial_mgmt_run", results)
        except asyncio.CancelledError:
            log.info("[TrialMgr] Scheduler cancelled")
            raise
        except Exception as e:
            log.error(f"[TrialMgr] Scheduler loop error: {e}", exc_info=True)
            await asyncio.sleep(3600)


async def _weekly_reports_scheduler():
    """週次レポートを毎週日曜 JST 19:00 に内部実行。multi-replica 重複防止付き。"""
    JST = timezone(timedelta(hours=9))
    TARGET_HOUR_JST = 19
    TARGET_WEEKDAY = 6  # Sunday (Mon=0..Sun=6)
    log.info(f"[WeeklyReports] Scheduler started, target Sun JST {TARGET_HOUR_JST}:00")
    secret = CRON_SECRET

    while True:
        try:
            now_jst = datetime.now(JST)
            # 次の日曜 19:00
            days_ahead = (TARGET_WEEKDAY - now_jst.weekday()) % 7
            target = now_jst.replace(hour=TARGET_HOUR_JST, minute=0, second=0, microsecond=0)
            if days_ahead == 0 and target <= now_jst:
                days_ahead = 7
            target += timedelta(days=days_ahead)
            sleep_secs = (target - now_jst).total_seconds()
            log.info(f"[WeeklyReports] Next run at {target.isoformat()} (in {int(sleep_secs)}s)")
            await asyncio.sleep(sleep_secs)
            if _check_scheduler_ran_today_jst("weekly_reports_run"):
                log.info("[WeeklyReports] Skipped (already ran today by another replica)")
                continue
            try:
                result = cron_weekly_reports(x_cron_secret=secret, dry_run=False)
                log.info(f"[WeeklyReports] result: {result}")
                _record_scheduler_run("weekly_reports_run", result if isinstance(result, dict) else {})
            except Exception as e:
                log.error(f"[WeeklyReports] failed: {type(e).__name__}: {e}", exc_info=True)
                _record_scheduler_run("weekly_reports_run", {"error": f"{type(e).__name__}: {e}"})
        except asyncio.CancelledError:
            log.info("[WeeklyReports] Scheduler cancelled")
            raise
        except Exception as e:
            log.error(f"[WeeklyReports] Scheduler loop error: {e}", exc_info=True)
            await asyncio.sleep(3600)


async def _weekly_worksheet_scheduler():
    """📅 2026-05-22 塾長指示: 週次弱点プリント自動配信 scheduler。
    毎週日曜 JST 05:00 に全生徒の弱点 TOP3 から問題を選別し worksheet_archives へ保存 + メール/LINE 通知。
    AI 生成は使わず pool から選別 ($0 / 既存問題プール 1500+ 問活用)。multi-replica dedup 付き。"""
    JST = timezone(timedelta(hours=9))
    TARGET_HOUR_JST = 5
    TARGET_WEEKDAY = 6  # Sunday
    log.info(f"[WeeklyWorksheet] Scheduler started, target Sun JST {TARGET_HOUR_JST}:00")

    while True:
        try:
            now_jst = datetime.now(JST)
            days_ahead = (TARGET_WEEKDAY - now_jst.weekday()) % 7
            target = now_jst.replace(hour=TARGET_HOUR_JST, minute=0, second=0, microsecond=0)
            if days_ahead == 0 and target <= now_jst:
                days_ahead = 7
            target += timedelta(days=days_ahead)
            sleep_secs = (target - now_jst).total_seconds()
            log.info(f"[WeeklyWorksheet] Next run at {target.isoformat()} (in {int(sleep_secs)}s)")
            await asyncio.sleep(sleep_secs)
            if _check_scheduler_ran_today_jst("weekly_worksheet_run"):
                log.info("[WeeklyWorksheet] Skipped (already ran today by another replica)")
                continue
            try:
                result = _run_weekly_worksheet_generation()
                log.info(f"[WeeklyWorksheet] result: {result}")
                _record_scheduler_run("weekly_worksheet_run", result)
            except Exception as e:
                log.error(f"[WeeklyWorksheet] failed: {type(e).__name__}: {e}", exc_info=True)
                _record_scheduler_run("weekly_worksheet_run", {"error": f"{type(e).__name__}: {e}"})
        except asyncio.CancelledError:
            log.info("[WeeklyWorksheet] Scheduler cancelled")
            raise
        except Exception as e:
            log.error(f"[WeeklyWorksheet] Scheduler loop error: {e}", exc_info=True)
            await asyncio.sleep(3600)


def _run_weekly_worksheet_generation() -> dict:
    """📅 全生徒の弱点プリント生成・保存。
    各生徒の student_weakness TOP3 (count desc + low score) から bank endpoint で 3 問ずつ抽出、
    worksheet_archives に保存 + メール/LINE 通知。
    返却: {students_processed, worksheets_created, notifications_sent, errors}
    """
    conn = db()
    c = conn.cursor()
    try:
        # ✅ 2026-05-22 P1 fix: 曜日に依らず「次週月曜」を一意に計算 (admin manual trigger でも整合)
        # weekday(): Mon=0..Sun=6 → 月曜まで何日先かを計算 (today が月曜なら 0、日曜なら 1、土曜なら 2 等)
        JST = timezone(timedelta(hours=9))
        now_jst = datetime.now(JST)
        days_to_next_monday = (7 - now_jst.weekday()) % 7
        if days_to_next_monday == 0 and now_jst.hour < 12:
            # 月曜の午前中は当日を week_start として使う (cron は日曜朝に走るので普段はここに来ない)
            days_to_next_monday = 0
        elif days_to_next_monday == 0:
            # 月曜の午後以降は次の月曜
            days_to_next_monday = 7
        week_start = (now_jst + timedelta(days=days_to_next_monday)).date().isoformat()

        # 全アクティブ生徒 (paid または trial・最終ログイン 60 日以内)
        # Postgres / SQLite 両対応: cutoff を Python 側で計算してパラメータ化
        login_cutoff = (datetime.now(timezone.utc) - timedelta(days=60)).isoformat()
        c.execute(
            "SELECT id, name, email, line_user_id FROM students "
            "WHERE status IN ('paid', 'trial') "
            "AND (last_login_at IS NULL OR last_login_at >= ?) "
            "LIMIT 500",
            (login_cutoff,)
        )
        students = c.fetchall() or []

        worksheets_created = 0
        notifications_sent = 0
        errors = []

        for st in students:
            try:
                sid = st["id"] if hasattr(st, "keys") else st[0]
                sname = (st["name"] if hasattr(st, "keys") else st[1]) or ""
                semail = (st["email"] if hasattr(st, "keys") else st[2]) or ""
                sline = (st["line_user_id"] if hasattr(st, "keys") else st[3]) or ""

                # 既に今週分が生成済か (dedup)
                c.execute("SELECT id FROM worksheet_archives WHERE student_id=? AND week_start_date=?", (sid, week_start))
                if c.fetchone():
                    continue

                # 弱点 TOP3 取得 (未克服順・習得済みは除外)
                # 🎯 [習得クローズドループ 2026-06-17] weakness-top3 と同基準: qa_accuracy>=0.8 かつ
                #   qa_attempts>=5 の「習得済み(卒業)」単元は週次プリントに再出題しない。順序も未克服優先に。
                c.execute(
                    "SELECT subject, topic, question_count, avg_confidence_score "
                    "FROM student_weakness "
                    "WHERE student_id=? AND question_count >= 1 "
                    "AND NOT (COALESCE(qa_accuracy, -1) >= ? AND COALESCE(qa_attempts, 0) >= ?) "
                    "ORDER BY (CASE WHEN COALESCE(qa_attempts, 0) >= 2 THEN qa_accuracy ELSE 1.0 END) ASC, "
                    "question_count DESC, COALESCE(avg_confidence_score, 0.5) ASC "
                    "LIMIT 3",
                    (sid, _WEAKNESS_MASTERY_ACCURACY, _WEAKNESS_MASTERY_MIN_ATTEMPTS)
                )
                weaknesses = c.fetchall() or []
                if not weaknesses:
                    continue  # 弱点データが無ければスキップ

                # 各弱点について pool から 3 問 fetch
                # ✅ 2026-05-22 P0 fix: ORDER BY RANDOM() を OFFSET (random) + LIMIT 3 に置換し性能改善
                # (全件 sort なしで O(log n)・500 生徒 × 3 弱点 × 2 pool = 3,000 回が秒以下に)
                import random as _rnd
                all_problem_ids = []  # P0-4: questions_json 軽量化用 (id のみ保存)
                subject_topics = []
                for w in weaknesses:
                    wsubj = w["subject"] if hasattr(w, "keys") else w[0]
                    wtopic = (w["topic"] if hasattr(w, "keys") else w[1]) or None
                    pool_keys = _WEAKNESS_SUBJECT_TO_POOL.get((wsubj or "").lower(), [])
                    if not pool_keys:
                        continue
                    subject_topics.append({"subject": wsubj, "topic": wtopic})
                    for (pool_exam, pool_part) in pool_keys[:2]:  # 最大 2 pool まで試す
                        try:
                            # まず該当 pool の COUNT を取得 (高速・index 利用)
                            count_params = ["exam_id=?"]
                            count_args = [pool_exam]
                            if pool_part:
                                count_params.append("part_key=?")
                                count_args.append(pool_part)
                            count_sql = f"SELECT COUNT(*) FROM exam_questions WHERE {' AND '.join(count_params)}"
                            c.execute(count_sql, tuple(count_args))
                            cnt_row = c.fetchone()
                            total = (cnt_row[0] if not hasattr(cnt_row, 'keys') else cnt_row[0]) if cnt_row else 0
                            if total <= 0:
                                continue
                            # ランダムオフセットを 3 つ生成し IN 句で一括 fetch
                            sample_size = min(3, total)
                            offsets = _rnd.sample(range(total), sample_size)
                            picked_ids = []
                            # 📜 2026-06-16: japanese 弱点が gendai/kobun/kanbun pool を引くようになった (4307) ため、
                            #   国語 pool では question_data も取得し、本文欠落/傍線部不一致の破損大問 (解答不能) を
                            #   週次プリントに混入させない。bank API:21136 と同じ _validate_kokugo_question 規約。
                            #   未修復の既存 kokugo 行 (repair_kokugo_questions.py 未適用) への配信側防御。
                            _is_kokugo_pool = (pool_exam == "daigaku" and pool_part in DAIGAKU_KOKUGO_PARTS)
                            for off in offsets:
                                if _is_kokugo_pool:
                                    off_sql = f"SELECT id, question_data FROM exam_questions WHERE {' AND '.join(count_params)} LIMIT 1 OFFSET ?"
                                else:
                                    off_sql = f"SELECT id FROM exam_questions WHERE {' AND '.join(count_params)} LIMIT 1 OFFSET ?"
                                c.execute(off_sql, tuple(count_args) + (off,))
                                row_id = c.fetchone()
                                if row_id:
                                    qid = row_id[0] if not hasattr(row_id, 'keys') else row_id[0]
                                    if _is_kokugo_pool:
                                        try:
                                            _qd_raw = row_id[1]
                                            _qd = json.loads(_qd_raw) if isinstance(_qd_raw, str) else (_qd_raw or {})
                                        except Exception:
                                            _qd = {}
                                        if not _validate_kokugo_question(_qd if isinstance(_qd, dict) else {}, pool_part, strict=False)[0]:
                                            continue  # 解答不能の不良大問はスキップ (次 offset / 次 pool へ fallthrough)
                                    picked_ids.append(qid)
                            if picked_ids:
                                # P0-4: id のみ記録 (full question_data 保存を回避し容量 1/200 に削減)
                                for qid in picked_ids:
                                    all_problem_ids.append({
                                        "question_id": qid,
                                        "exam_id": pool_exam,
                                        "part_key": pool_part,
                                        "weakness_subject": wsubj,
                                        "weakness_topic": wtopic,
                                    })
                                break  # 取得できたら次の pool は不要
                        except Exception as e:
                            log.warning(f"[WeeklyWorksheet] pool fetch failed for sid={sid} subj={wsubj}: {e}")

                if not all_problem_ids:
                    continue
                all_problems = all_problem_ids  # 後方互換変数名

                # worksheet_archives に保存
                c.execute(
                    "INSERT INTO worksheet_archives (student_id, week_start_date, subject_topics, questions_json, question_count, delivered_via, delivered_at, created_at) "
                    "VALUES (?,?,?,?,?,?,?,?) RETURNING id",
                    (
                        sid,
                        week_start,
                        json.dumps(subject_topics, ensure_ascii=False),
                        json.dumps(all_problems, ensure_ascii=False),
                        len(all_problems),
                        None,  # 後で UPDATE
                        None,
                        datetime.now(timezone.utc).isoformat(),
                    )
                )
                row = c.fetchone()
                wid = None
                if row:
                    try:
                        wid = row["id"] if hasattr(row, "keys") else row[0]
                    except (KeyError, IndexError, TypeError):
                        wid = row[0] if row else None
                worksheets_created += 1

                # メール通知 (Resend 経由)・LINE 通知 (line_user_id があれば)
                delivered_via = []
                # subject 概要文字列 (LINE/メール本文用)
                subject_summary = ', '.join(((s.get('subject') or '') for s in subject_topics)) or '弱点 TOP3'
                try:
                    if semail and ("@" in semail and not semail.endswith("@synthetic-monitor.local")):
                        # 既存 _send_weekly_report_email パターンに合わせて simple HTML を組み立て
                        subj = "📅 今週の弱点プリント (AI が選んだ 9-15 問) が届きました"
                        body_html = (
                            f"<p>{sname or 'こんにちは'} さん、</p>"
                            f"<p>今週の弱点プリントを準備しました。マイページから確認できます:</p>"
                            f"<p><a href='{BASE_URL}/mypage.html?focus=worksheet'>📅 今週の弱点プリントを開く</a></p>"
                            f"<p>苦手分野 ({subject_summary}) から計 {len(all_problems)} 問を抽出しました。</p>"
                        )
                        # 既存 _send_monitor_email 関数を流用 (subject + body_html + to_email)
                        if "_send_monitor_email" in globals():
                            mail_resp = _send_monitor_email(subj, body_html, to_email=semail)
                            # _send_monitor_email 戻り値は {"sent": True/False} (他 callsite と整合)
                            if isinstance(mail_resp, dict) and mail_resp.get("sent"):
                                delivered_via.append("email")
                                notifications_sent += 1
                except Exception as e:
                    log.warning(f"[WeeklyWorksheet] email failed for sid={sid}: {e}")

                try:
                    if sline and isinstance(sid, int):
                        # _do_line_push(student_id:int, template:str, params:dict) の正規 signature
                        params = {
                            "name": sname,
                            "subject_summary": subject_summary,
                            "question_count": len(all_problems),
                            "url": BASE_URL,
                        }
                        line_resp = _do_line_push(int(sid), "weekly_worksheet", params)
                        if isinstance(line_resp, dict) and line_resp.get("ok"):
                            delivered_via.append("line")
                except Exception as e:
                    log.warning(f"[WeeklyWorksheet] line failed for sid={sid}: {e}")

                if delivered_via and wid:
                    c.execute(
                        "UPDATE worksheet_archives SET delivered_via=?, delivered_at=? WHERE id=?",
                        (",".join(delivered_via), datetime.now(timezone.utc).isoformat(), wid)
                    )
            except Exception as e:
                errors.append(f"sid={sid}: {type(e).__name__}: {e}")
                log.warning(f"[WeeklyWorksheet] student loop error: {e}")

        conn.commit()
        return {
            "students_processed": len(students),
            "worksheets_created": worksheets_created,
            "notifications_sent": notifications_sent,
            "errors": errors[:10],  # 最初の 10 件のみ
            "week_start_date": week_start,
        }
    finally:
        conn.close()


@app.get("/api/student/worksheet/this-week")
def student_worksheet_this_week(authorization: Optional[str] = Header(None)):
    """📅 mypage 表示用: 今週の弱点プリントを取得 (生徒自身)。
    返却: {ok, worksheet: {id, week_start_date, subject_topics, questions, question_count, attempted_at, score_total, score_max}}
    """
    student = _get_current_student(authorization) if "_get_current_student" in globals() else None
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    sid = student["id"]
    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            "SELECT id, week_start_date, subject_topics, questions_json, question_count, attempted_at, score_total, score_max, delivered_via, created_at "
            "FROM worksheet_archives WHERE student_id=? ORDER BY week_start_date DESC LIMIT 1",
            (sid,)
        )
        row = c.fetchone()
        if not row:
            return {"ok": True, "worksheet": None}
        def _g(key, idx):
            return row[key] if hasattr(row, "keys") and key in row.keys() else row[idx]
        questions_raw = json.loads(_g("questions_json", 3) or "[]")
        # ✅ 2026-05-22 P0 fix: P0-4 軽量化で id のみ保存に変更したため、
        # mypage 表示用に question_data を exam_questions から hydrate
        question_ids = [q.get("question_id") for q in questions_raw if isinstance(q, dict) and q.get("question_id")]
        eq_map = {}
        if question_ids:
            try:
                placeholders = ",".join("?" * len(question_ids))
                c.execute(f"SELECT id, exam_id, part_key, eiken_grade, question_data FROM exam_questions WHERE id IN ({placeholders})", tuple(question_ids))
                for eqrow in c.fetchall() or []:
                    qid = eqrow["id"] if hasattr(eqrow, "keys") else eqrow[0]
                    qd_raw = eqrow["question_data"] if hasattr(eqrow, "keys") else eqrow[4]
                    try:
                        qd = json.loads(qd_raw) if isinstance(qd_raw, str) else (qd_raw or {})
                    except Exception:
                        qd = {}
                    eq_map[qid] = {
                        "exam_id": eqrow["exam_id"] if hasattr(eqrow, "keys") else eqrow[1],
                        "part_key": eqrow["part_key"] if hasattr(eqrow, "keys") else eqrow[2],
                        "eiken_grade": eqrow["eiken_grade"] if hasattr(eqrow, "keys") else eqrow[3],
                        "question_data": qd,
                    }
            except Exception as e:
                log.warning(f"[worksheet hydrate] failed (non-fatal): {e}")
        # hydrate: mypage の render に必要な question_data フィールドを ID 経由で復元
        hydrated_questions = []
        for q in questions_raw:
            if not isinstance(q, dict):
                continue
            qid = q.get("question_id")
            eq_info = eq_map.get(qid) or {}
            _exam_id = q.get("exam_id") or eq_info.get("exam_id")
            _part_key = q.get("part_key") or eq_info.get("part_key")
            _qdata = q.get("question_data") or eq_info.get("question_data") or {}
            # 📜 2026-06-16: 二重防御 — 国語 (古文/漢文/現代文) の破損大問 (本文欠落/傍線部不一致 = 解答不能)
            #   は描画前にドロップ (bank API:21136 と同規約)。選定時 (3721 付近) でも弾くが、旧プリントや
            #   別経路で worksheet_archives に混入した行に対する最終防御。
            if _exam_id == "daigaku" and _part_key in DAIGAKU_KOKUGO_PARTS:
                if not _validate_kokugo_question(_qdata if isinstance(_qdata, dict) else {}, _part_key, strict=False)[0]:
                    continue
            hydrated_questions.append({
                "question_id": qid,
                "exam_id": _exam_id,
                "part_key": _part_key,
                "eiken_grade": eq_info.get("eiken_grade"),
                "weakness_subject": q.get("weakness_subject"),
                "weakness_topic": q.get("weakness_topic"),
                "question_data": _qdata,
            })
        ws = {
            "id": _g("id", 0),
            "week_start_date": _g("week_start_date", 1),
            "subject_topics": json.loads(_g("subject_topics", 2) or "[]") if _g("subject_topics", 2) else [],
            "questions": hydrated_questions,
            "question_count": _g("question_count", 4),
            "attempted_at": _g("attempted_at", 5),
            "score_total": _g("score_total", 6),
            "score_max": _g("score_max", 7),
            "delivered_via": _g("delivered_via", 8),
            "created_at": _g("created_at", 9),
        }
        return {"ok": True, "worksheet": ws}
    finally:
        conn.close()


