@app.post("/api/admin/worksheet/run-weekly-now")
def admin_run_weekly_worksheet_now(authorization: Optional[str] = Header(None),
                                    x_cron_secret: Optional[str] = Header(None)):
    """🧪 週次弱点プリント生成を即時実行 (CEO ダッシュ「今すぐ生成」/ 動作確認用)
    通常は毎週日曜 JST 5:00 だが、手動でテスト時に使用。"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")
    try:
        result = _run_weekly_worksheet_generation()
        return {"ok": True, **result}
    except Exception as e:
        log.error(f"[WeeklyWorksheet] manual run failed: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e))


async def _anthropic_credit_monitor_scheduler():
    """💸 Anthropic credit_low 監視 scheduler (2026-05-13 塾長指示)
    毎日 JST 8:00 に credit-status を確認 → critical/warning なら塾長メール通知。
    補充忘れによるサービス停止を予防。1 日 1 回・events で dedup。"""
    JST = timezone(timedelta(hours=9))
    TARGET_HOUR_JST = 8
    log.info(f"[CreditMonitor] Scheduler started, target hour JST {TARGET_HOUR_JST}:00 daily")

    while True:
        try:
            now_jst = datetime.now(JST)
            target = now_jst.replace(hour=TARGET_HOUR_JST, minute=0, second=0, microsecond=0)
            if target <= now_jst:
                target += timedelta(days=1)
            sleep_secs = (target - now_jst).total_seconds()
            log.info(f"[CreditMonitor] Next run at {target.isoformat()} (in {int(sleep_secs)}s)")
            await asyncio.sleep(sleep_secs)
            if _check_scheduler_ran_today_jst("credit_monitor_run"):
                log.info("[CreditMonitor] Skipped (already ran today)")
                continue
            try:
                result = _run_credit_monitor()
                log.info(f"[CreditMonitor] result: {result}")
                _record_scheduler_run("credit_monitor_run", result)
            except Exception as e:
                log.error(f"[CreditMonitor] failed: {type(e).__name__}: {e}", exc_info=True)
                _record_scheduler_run("credit_monitor_run", {"error": f"{type(e).__name__}: {e}"})
        except asyncio.CancelledError:
            log.info("[CreditMonitor] Scheduler cancelled")
            raise
        except Exception as e:
            log.error(f"[CreditMonitor] Scheduler loop error: {e}", exc_info=True)
            await asyncio.sleep(3600)


def _run_credit_monitor() -> dict:
    """credit-status を内部計算 → critical/warning なら塾長メール通知。
    返却: {status_level, days_remaining, notified}"""
    from datetime import timedelta as _td
    conn = db()
    try:
        c = conn.cursor()
        # 累計補充
        c.execute("SELECT COALESCE(SUM(amount_usd), 0) FROM anthropic_credit_recharge")
        row = c.fetchone()
        try:
            total_recharged = float(row[0] or 0)
        except Exception:
            try: total_recharged = float(list(row.values())[0] or 0)
            except Exception: total_recharged = 0.0
        # 累計使用
        c.execute("SELECT COALESCE(SUM(cost_usd), 0) FROM anthropic_usage_log")
        row = c.fetchone()
        try:
            total_used = float(row[0] or 0)
        except Exception:
            try: total_used = float(list(row.values())[0] or 0)
            except Exception: total_used = 0.0
        # 直近 7 日
        cutoff_7d = datetime.utcnow() - _td(days=7)
        c.execute("SELECT COALESCE(SUM(cost_usd), 0) FROM anthropic_usage_log WHERE created_at >= ?", (cutoff_7d,))
        row = c.fetchone()
        try:
            last_7d = float(row[0] or 0)
        except Exception:
            try: last_7d = float(list(row.values())[0] or 0)
            except Exception: last_7d = 0.0
    finally:
        conn.close()

    remaining = max(0.0, total_recharged - total_used)
    avg_daily = last_7d / 7.0
    days_remaining = (remaining / avg_daily) if avg_daily > 0.001 else None

    if total_recharged <= 0:
        return {"status_level": "unknown", "notified": False, "reason": "no recharge record"}
    if days_remaining is None:
        return {"status_level": "ok", "notified": False, "reason": "no usage data"}
    if days_remaining >= 7:
        return {"status_level": "ok", "notified": False, "days_remaining": round(days_remaining, 1)}

    # critical / warning → メール通知
    status_level = "critical" if days_remaining < 3 else "warning"
    icon = "🚨" if status_level == "critical" else "⚠️"
    subject = f"{icon} Anthropic credit 残量 {status_level} (残り {round(days_remaining,1)} 日)"
    body_text = (
        f"ai-juku-system Anthropic credit 残量 monitor\n\n"
        f"状態: {status_level}\n"
        f"残額: ${round(remaining, 2)}\n"
        f"累計補充: ${round(total_recharged, 2)}\n"
        f"累計使用: ${round(total_used, 4)}\n"
        f"直近 7 日使用: ${round(last_7d, 4)}\n"
        f"日平均使用: ${round(avg_daily, 4)}\n"
        f"予測残日数: 約 {round(days_remaining, 1)} 日\n\n"
        f"→ Anthropic Console で補充してください: https://console.anthropic.com/settings/billing\n"
        f"→ 補充後、CEO ダッシュ「💰 補充を記録」で金額を入力してください\n"
    )
    notified = False
    try:
        body_html = "<pre style='font-family:monospace;font-size:13px;'>" + body_text.replace("<", "&lt;").replace(">", "&gt;") + "</pre>"
        result = _send_monitor_email(subject, body_html)
        notified = bool(result and result.get("sent"))
        if notified:
            log.info(f"[CreditMonitor] alert sent: {subject}")
    except Exception as e:
        log.error(f"[CreditMonitor] alert send failed: {e}")
    return {
        "status_level": status_level,
        "days_remaining": round(days_remaining, 1),
        "remaining_usd": round(remaining, 2),
        "notified": notified,
    }


async def _weakness_aggregation_scheduler():
    """🎯 弱点分類 cron: 毎日 JST 4:00 (低トラフィック帯) に ai_tutor_solve_log → student_weakness 集計。
    塾長指示 2026-05-13「個別問題推薦」の基盤。multi-replica 重複防止付き。"""
    JST = timezone(timedelta(hours=9))
    TARGET_HOUR_JST = 4
    log.info(f"[Weakness] Scheduler started, target hour JST {TARGET_HOUR_JST}:00 daily")

    while True:
        try:
            now_jst = datetime.now(JST)
            target = now_jst.replace(hour=TARGET_HOUR_JST, minute=0, second=0, microsecond=0)
            if target <= now_jst:
                target += timedelta(days=1)
            sleep_secs = (target - now_jst).total_seconds()
            log.info(f"[Weakness] Next run at {target.isoformat()} (in {int(sleep_secs)}s)")
            await asyncio.sleep(sleep_secs)
            if _check_scheduler_ran_today_jst("weakness_aggregation_run"):
                log.info("[Weakness] Skipped (already ran today by another replica)")
                continue
            try:
                result = _run_weakness_aggregation()
                log.info(f"[Weakness] result: {result}")
                _record_scheduler_run("weakness_aggregation_run", result)
            except Exception as e:
                log.error(f"[Weakness] failed: {type(e).__name__}: {e}", exc_info=True)
                _record_scheduler_run("weakness_aggregation_run", {"error": f"{type(e).__name__}: {e}"})
        except asyncio.CancelledError:
            log.info("[Weakness] Scheduler cancelled")
            raise
        except Exception as e:
            log.error(f"[Weakness] Scheduler loop error: {e}", exc_info=True)
            await asyncio.sleep(3600)


def _run_weakness_aggregation(only_student_id: Optional[int] = None) -> dict:
    """🎯 2026-05-22 塾長指示で UNION 拡張: ai_tutor_solve_log + question_attempts (mock_exam/practice/essay_grade)
    の 2 系統 (過去 30 日) を student × subject × topic で集計し student_weakness を更新。
    既存レコードは UPSERT (UNIQUE 制約に依拠)。
    confidence/正誤 score: high=1.0 / medium=0.6 / low=0.2 / 正解=1.0 / 不正解=0.0 → 低いほど弱点。
    qa_attempts = 採点済み(is_correct あり)演習回数。qa_accuracy = その実測正答率 → 習得(卒業)判定に使う。
    only_student_id を渡すと「その生徒だけ」を即時集計 (ドリル直後の弱点反映=閉ループの即応性)。
    None なら全生徒 (毎晩 cron / ミニ診断後 / 手動)。
    返却: {students_processed, weaknesses_inserted, weaknesses_updated, rows_examined}
    """
    from datetime import timedelta as _td
    from collections import defaultdict
    conn = db()
    c = conn.cursor()
    try:
        cutoff = datetime.utcnow() - _td(days=30)
        agg: dict = defaultdict(lambda: {"count": 0, "score_sum": 0.0, "score_n": 0, "last": None,
                                         "reasons": {}, "elapsed_sum": 0.0, "elapsed_n": 0,
                                         "qa_correct": 0, "qa_graded": 0})
        conf_score_map = {"high": 1.0, "medium": 0.6, "low": 0.2}
        rows_examined = 0
        # 🎯 [習得クローズドループ] only_student_id 指定時は WHERE に student_id を足して 1 人分だけ集計
        _only_sid = int(only_student_id) if only_student_id else None
        _sid_clause = " AND student_id = ?" if _only_sid else ""

        # === 系統 1: 過去 30 日の ai_tutor_solve_log (写真質問) ===
        c.execute(
            "SELECT student_id, subject_guess, topic_guess, confidence, created_at "
            "FROM ai_tutor_solve_log "
            "WHERE student_id IS NOT NULL AND student_id > 0 "
            "AND subject_guess IS NOT NULL "
            "AND created_at >= ?" + _sid_clause,
            ((cutoff, _only_sid) if _only_sid else (cutoff,)),
        )
        tutor_rows = c.fetchall()
        rows_examined += len(tutor_rows)
        for r in tutor_rows:
            try:
                sid = r["student_id"]; subj = r["subject_guess"]; topic = r["topic_guess"]
                conf = r["confidence"]; created = r["created_at"]
            except (TypeError, KeyError, IndexError):
                sid, subj, topic, conf, created = r[0], r[1], r[2], r[3], r[4]
            if not sid or not subj:
                continue
            topic_norm = (topic or "")[:120]
            key = (int(sid), str(subj).strip().lower(), topic_norm)
            agg[key]["count"] += 1
            sc = conf_score_map.get((conf or "").lower())
            if sc is not None:
                agg[key]["score_sum"] += sc
                agg[key]["score_n"] += 1
            if created and (agg[key]["last"] is None or str(created) > str(agg[key]["last"])):
                agg[key]["last"] = created

        # === 系統 2: 過去 30 日の question_attempts (mock_exam / practice / essay_grade) ===
        c.execute(
            "SELECT student_id, subject, topic, is_correct, score_got, score_max, created_at, metadata, elapsed_ms "
            "FROM question_attempts "
            "WHERE student_id IS NOT NULL AND student_id > 0 "
            "AND subject IS NOT NULL "
            "AND created_at >= ?" + _sid_clause,
            ((cutoff, _only_sid) if _only_sid else (cutoff,)),
        )
        qa_rows = c.fetchall()
        rows_examined += len(qa_rows)
        for r in qa_rows:
            try:
                sid = r["student_id"]; subj = r["subject"]; topic = r["topic"]
                ic = r["is_correct"]; sg = r["score_got"]; sm = r["score_max"]; created = r["created_at"]
                meta_raw = r["metadata"]; elapsed_raw = r["elapsed_ms"]
            except (TypeError, KeyError, IndexError):
                sid, subj, topic, ic, sg, sm, created = r[0], r[1], r[2], r[3], r[4], r[5], r[6]
                meta_raw = r[7] if len(r) > 7 else None
                elapsed_raw = r[8] if len(r) > 8 else None
            if not sid or not subj:
                continue
            topic_norm = (topic or "")[:120]
            key = (int(sid), str(subj).strip().lower(), topic_norm)
            agg[key]["count"] += 1
            # score 推定: is_correct 優先 → score_got/score_max
            sc = None
            if ic is not None:
                sc = 1.0 if int(ic) == 1 else 0.0
            elif sg is not None and sm is not None and int(sm) > 0:
                sc = max(0.0, min(1.0, float(sg) / float(sm)))
            if sc is not None:
                agg[key]["score_sum"] += sc
                agg[key]["score_n"] += 1
            # 🎯 Phase2 (+review fix #1): つまずき理由を集計。記録形式が起点で2通りある:
            #   - 隙間ドリル (dojo-drill): 小問1件=1 attempt・不正解時 metadata.reason
            #   - 大学別1問深掘り (university-exam): 1大問=1 attempt・metadata.total_reason_counts {reason:count}
            #   両対応しないと過去問のみ解く生徒で dominant_reason が永遠に None になる。
            md = None
            if meta_raw:
                try:
                    md = json.loads(meta_raw) if isinstance(meta_raw, str) else (meta_raw if isinstance(meta_raw, dict) else None)
                except Exception:
                    md = None
            if md:
                trc = md.get("total_reason_counts")
                if isinstance(trc, dict) and trc:
                    for rk, rv in trc.items():
                        try:
                            n = int(rv)
                        except (TypeError, ValueError):
                            continue
                        if rk and n > 0:
                            k2 = str(rk)[:40]
                            agg[key]["reasons"][k2] = agg[key]["reasons"].get(k2, 0) + n
                elif ic is not None and int(ic) == 0:
                    rsn = md.get("reason")
                    if rsn:
                        rsn = str(rsn)[:40]
                        agg[key]["reasons"][rsn] = agg[key]["reasons"].get(rsn, 0) + 1
            # 🎯 review fix #6: question_attempts のみの実測正答率 (AI自信度を混ぜずに slow_but_correct 判定するため)
            if ic is not None:
                agg[key]["qa_graded"] += 1
                if int(ic) == 1:
                    agg[key]["qa_correct"] += 1
            # 🎯 Phase2: 所要時間 (elapsed_ms) を集計 (「正答だが遅い単元」検出用)。0〜60分の妥当値のみ。
            if elapsed_raw is not None:
                try:
                    elv = int(elapsed_raw)
                    if 0 < elv < 3_600_000:
                        agg[key]["elapsed_sum"] += elv
                        agg[key]["elapsed_n"] += 1
                except Exception:
                    pass
            if created and (agg[key]["last"] is None or str(created) > str(agg[key]["last"])):
                agg[key]["last"] = created

        if not agg:
            return {"students_processed": 0, "weaknesses_inserted": 0, "weaknesses_updated": 0, "rows_examined": rows_examined, "note": "no logs in last 30 days"}

        # UPSERT 風処理: 既存削除して INSERT (UNIQUE 制約で簡潔に)
        # 過去 30 日に登場した (student, subject, topic) のみ更新・他は古いまま残す
        students_processed = len({k[0] for k in agg.keys()})
        rows = list(agg.keys())  # backward-compatible for rows_examined fallback
        inserted = 0; updated = 0
        for (sid, subj, topic), v in agg.items():
            avg_score = (v["score_sum"] / v["score_n"]) if v["score_n"] > 0 else None
            # 🎯 Phase2: つまずき理由内訳 (JSON) と 平均所要時間 (ms)
            reasons = v.get("reasons") or {}
            reason_counts_json = json.dumps(reasons, ensure_ascii=False) if reasons else None
            avg_elapsed = int(round(v["elapsed_sum"] / v["elapsed_n"])) if v.get("elapsed_n") else None
            qa_graded = int(v.get("qa_graded") or 0)
            qa_acc = (v["qa_correct"] / qa_graded) if qa_graded else None
            # 既存 check
            c.execute(
                "SELECT id FROM student_weakness WHERE student_id = ? AND subject = ? AND topic = ?",
                (sid, subj, topic),
            )
            existing = c.fetchone()
            if existing:
                c.execute(
                    "UPDATE student_weakness SET question_count = ?, avg_confidence_score = ?, "
                    "reason_counts = ?, avg_elapsed_ms = ?, qa_accuracy = ?, qa_attempts = ?, "
                    "last_seen_at = ?, aggregated_at = CURRENT_TIMESTAMP "
                    "WHERE student_id = ? AND subject = ? AND topic = ?",
                    (v["count"], avg_score, reason_counts_json, avg_elapsed, qa_acc, qa_graded, v["last"], sid, subj, topic),
                )
                updated += 1
            else:
                c.execute(
                    "INSERT INTO student_weakness (student_id, subject, topic, question_count, "
                    " avg_confidence_score, reason_counts, avg_elapsed_ms, qa_accuracy, qa_attempts, last_seen_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (sid, subj, topic, v["count"], avg_score, reason_counts_json, avg_elapsed, qa_acc, qa_graded, v["last"]),
                )
                inserted += 1
        # ✅ 2026-05-22 P1 fix: 30 日経過の stale row を削除 (古い弱点が worksheet に出続けるのを防ぐ)
        stale_deleted = 0
        try:
            stale_cutoff = (datetime.utcnow() - _td(days=30)).isoformat()
            if _only_sid:
                c.execute("DELETE FROM student_weakness WHERE student_id = ? AND aggregated_at < ?", (_only_sid, stale_cutoff))
            else:
                c.execute("DELETE FROM student_weakness WHERE aggregated_at < ?", (stale_cutoff,))
            stale_deleted = c.rowcount or 0
        except Exception as e:
            log.warning(f"[Weakness] stale row cleanup failed (non-fatal): {e}")
        conn.commit()
        return {
            "students_processed": students_processed,
            "weaknesses_inserted": inserted,
            "weaknesses_updated": updated,
            "rows_examined": rows_examined,
            "stale_rows_deleted": stale_deleted,
        }
    finally:
        conn.close()


