@app.post("/api/admin/stripe/setup-all-prices")
def admin_stripe_setup_all_prices(authorization: Optional[str] = Header(None)):
    """💳 全プランの Stripe Price を 1 度に作成 (or 既存検証)。
    各 Price は lookup_key で永続検索可能 → env 設定不要。
    冪等: 既に lookup_key で見つかれば再作成しない。
    admin Bearer 認証必須。
    """
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="未認証")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY が未設定 (Railway env)")

    s = get_stripe()
    results = []

    for spec in _STRIPE_PLAN_SPECS:
        lk = spec["lookup_key"]
        amount = spec["amount"]
        try:
            # 1. lookup_key で既存検索 (冪等)
            existing = s.Price.list(lookup_keys=[lk], active=True, limit=1)
            if existing and existing.data:
                ex = existing.data[0]
                # 金額の整合確認
                amount_match = (ex.unit_amount == amount)
                results.append({
                    "lookup_key": lk,
                    "status": "existing" if amount_match else "existing_amount_mismatch",
                    "price_id": ex.id,
                    "amount_jpy": ex.unit_amount,
                    "expected_jpy": amount,
                    "amount_match": amount_match,
                    "interval": ex.recurring.get("interval") if ex.recurring else None,
                    "message": (
                        f"既存 Price が一致 ({ex.id}・¥{ex.unit_amount:,}/月)" if amount_match
                        else f"⚠️ 金額不一致: Stripe={ex.unit_amount} 期待={amount}・既存 Price は active=False にして再作成推奨"
                    ),
                })
                continue
        except Exception as e:
            log.warning(f"[Stripe Setup] lookup_key={lk} 検索失敗: {e}")

        # 2. Product を name 一致で再利用 or 新規作成
        product_id = None
        try:
            prods = s.Product.list(active=True, limit=100)
            for p in prods.data:
                if p.name == spec["product_name"]:
                    product_id = p.id
                    break
        except Exception as e:
            log.warning(f"[Stripe Setup] product list 失敗: {e}")
        if not product_id:
            try:
                prod = s.Product.create(
                    name=spec["product_name"],
                    description=spec["description"],
                    metadata=spec["metadata"],
                )
                product_id = prod.id
                log.info(f"[Stripe Setup] product 作成: {spec['product_name']} = {product_id}")
            except Exception as e:
                results.append({
                    "lookup_key": lk,
                    "status": "product_create_failed",
                    "error": str(e),
                })
                continue

        # 3. Price 作成 (lookup_key + recurring monthly + JPY)
        try:
            price = s.Price.create(
                product=product_id,
                unit_amount=amount,
                currency="jpy",
                recurring={"interval": "month"},
                lookup_key=lk,
                transfer_lookup_key=True,  # 同 lookup_key の旧 Price から強制移管
                metadata=spec["metadata"],
            )
            log.info(f"[Stripe Setup] price 作成: lookup_key={lk} amount={amount} id={price.id}")

            # 4. キャッシュ更新 (founder_special / student_addon のみ)
            now = datetime.now(timezone.utc)
            if lk == "founder_special":
                global _FOUNDER_SPECIAL_PRICE_CACHE
                _FOUNDER_SPECIAL_PRICE_CACHE = {"id": price.id, "checked_at": now}
            elif lk == "student_addon":
                global _STUDENT_ADDON_PRICE_CACHE
                _STUDENT_ADDON_PRICE_CACHE = {"id": price.id, "checked_at": now}

            results.append({
                "lookup_key": lk,
                "status": "created",
                "product_id": product_id,
                "price_id": price.id,
                "amount_jpy": amount,
                "expected_jpy": amount,
                "amount_match": True,
                "interval": "month",
                "message": f"✅ 作成完了 ({price.id}・¥{amount:,}/月)",
            })
        except Exception as e:
            results.append({
                "lookup_key": lk,
                "status": "price_create_failed",
                "error": str(e),
            })

    # サマリ
    created = [r for r in results if r["status"] == "created"]
    existing = [r for r in results if r["status"] == "existing"]
    mismatched = [r for r in results if r["status"] == "existing_amount_mismatch"]
    failed = [r for r in results if r["status"] in ("product_create_failed", "price_create_failed")]

    return {
        "ok": len(failed) == 0,
        "summary": {
            "total": len(_STRIPE_PLAN_SPECS),
            "created": len(created),
            "existing_match": len(existing),
            "existing_mismatch": len(mismatched),
            "failed": len(failed),
        },
        "results": results,
        "next_steps": (
            "✅ 全プラン Stripe 反映済 (lookup_key で動的解決)。env 設定は不要。"
            if len(failed) == 0 and len(mismatched) == 0
            else (
                "⚠️ amount mismatch あり: 該当プランの旧 Price を Stripe Dashboard で active=False にしてから再実行してください。"
                if len(mismatched) > 0
                else "❌ 一部失敗: results.error を確認"
            )
        ),
    }


@app.get("/api/admin/stripe/check-prices")
def admin_stripe_check_prices(authorization: Optional[str] = Header(None)):
    """💳 全プランの Stripe 反映状態をチェック (= 読み取りのみ・Price は作成しない)
    塾長が「金額が Stripe に反映されているか」を確認する用。

    2 段検査:
    (A) lookup_key で見つかる Price の amount が PRICE_MAP の期待値と一致するか
    (B) **env (STRIPE_PRICE_*) が指す Price の amount も期待値と一致するか**
        → 2026-05-07 student_addon env が ¥9,800 旧 Price を指していて UI ¥5,000 と
          不一致だった致命事故 (Reviewer A 検出) の再発防止。
    """
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="未認証")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY が未設定")

    s = get_stripe()

    # 各プランの env 値を spec に組み込んでおく (eval 経由で取得)
    _ENV_BY_LOOKUP = {
        "founder_special": STRIPE_PRICE_FOUNDER_SPECIAL,
        "premium": STRIPE_PRICE_PREMIUM,
        "family": STRIPE_PRICE_FAMILY,
        "standard": STRIPE_PRICE_STANDARD,
        "student_addon": STRIPE_PRICE_STUDENT_ADDON,
    }

    results = []
    for spec in _STRIPE_PLAN_SPECS:
        lk = spec["lookup_key"]
        amount = spec["amount"]
        result = {
            "lookup_key": lk,
            "expected_jpy": amount,
        }

        # (A) lookup_key 検索
        try:
            existing = s.Price.list(lookup_keys=[lk], active=True, limit=1)
            if existing and existing.data:
                ex = existing.data[0]
                lk_match = (ex.unit_amount == amount)
                result.update({
                    "stripe_jpy": ex.unit_amount,
                    "match": lk_match,
                    "price_id": ex.id,
                    "interval": ex.recurring.get("interval") if ex.recurring else None,
                    "active": ex.active,
                })
            else:
                result.update({
                    "stripe_jpy": None,
                    "match": False,
                    "price_id": None,
                    "missing": True,
                })
        except Exception as e:
            result.update({
                "match": False,
                "error": f"lookup_key search failed: {e}",
            })

        # (B) env 値の検証 (env が指す Price の amount が期待値と一致するか)
        env_pid = (_ENV_BY_LOOKUP.get(lk) or "").strip()
        if env_pid and not env_pid.endswith("_placeholder"):
            try:
                env_price = s.Price.retrieve(env_pid)
                env_amount = env_price.get("unit_amount")
                env_match = (env_amount == amount)
                result["env"] = {
                    "price_id": env_pid,
                    "stripe_jpy": env_amount,
                    "match": env_match,
                    "lookup_key_on_price": env_price.get("lookup_key"),
                    "active": env_price.get("active"),
                }
                # env が違う Price を指していたら overall match を falsify
                if not env_match:
                    result["match"] = False
                    result["env_mismatch"] = True
            except Exception as e:
                result["env"] = {
                    "price_id": env_pid,
                    "error": str(e),
                    "match": False,
                }
                result["match"] = False
        else:
            # env が placeholder/空 → lookup_key 結果が source of truth
            result["env"] = {
                "price_id": env_pid or None,
                "match": None,  # env 未設定なので評価対象外
                "note": "env 未設定 → lookup_key を source of truth として使う" if not env_pid else "env が placeholder",
            }

        results.append(result)

    all_match = all(r.get("match") for r in results)
    missing = [r for r in results if r.get("missing")]
    mismatched = [r for r in results if r.get("stripe_jpy") is not None and not r.get("match") and not r.get("missing")]
    env_mismatched = [r for r in results if r.get("env_mismatch")]
    # env が「実際に設定されていて lookup_key と金額一致」しているプラン数を数える
    # (未設定で lookup_key fallback の場合は env.match=None なので除外)
    env_set_and_match = [r for r in results if (r.get("env") or {}).get("match") is True]
    env_unset_fallback = [r for r in results if (r.get("env") or {}).get("match") is None and r.get("match") is True]

    if all_match:
        if not env_unset_fallback:
            recommendation = "✅ 全プラン Stripe 反映済 (lookup_key + env 両方一致)"
        else:
            unset_keys = ", ".join(r["lookup_key"] for r in env_unset_fallback)
            recommendation = (
                f"✅ 全プラン Stripe 反映済 (lookup_key 一致 / env: {len(env_set_and_match)} 件設定済 + "
                f"{len(env_unset_fallback)} 件は lookup_key fallback で解決: {unset_keys})"
            )
    else:
        msgs = []
        if missing:
            msgs.append(f"未作成 {len(missing)} 件 → POST /api/admin/stripe/setup-all-prices")
        if env_mismatched:
            msgs.append(f"env が間違った Price を指している {len(env_mismatched)} 件 → Render env を修正")
        if mismatched:
            msgs.append(f"lookup_key 上の Price 金額不一致 {len(mismatched)} 件")
        recommendation = "⚠️ " + " / ".join(msgs)

    return {
        "ok": all_match,
        "all_match": all_match,
        "missing_count": len(missing),
        "mismatched_count": len(mismatched),
        "env_mismatched_count": len(env_mismatched),
        "env_unset_fallback_count": len(env_unset_fallback),
        "env_set_match_count": len(env_set_and_match),
        "results": results,
        "recommendation": recommendation,
    }


# ============================================================================
# 🔧 セルフヒーリング系 admin endpoints (Phase 9)
# 設計原則: monitor が検知できる異常は CEO ダッシュ 1 クリックで解決可能にする
# ============================================================================

@app.post("/api/admin/stripe/reconcile")
def admin_stripe_reconcile(authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """🔄 Stripe ↔ DB 整合性同期 (失敗 webhook 取りこぼし救済)

    Stripe API から subscription を取得し、DB と差分があれば DB を Stripe に合わせて更新する。
    webhook 配信失敗で生じる status ズレを双方向に救済できる (冪等):
      - upgrade: Stripe active なのに DB が trial/past_due → paid に昇格
      - downgrade: Stripe past_due/canceled なのに DB が paid → past_due/canceled に降格
      - stale trial_end: Stripe active 確認済みの paid 行に未来の trial_end が残存 → NULL に
        (monthly webhook の trial_end クリア漏れ fix (2026-06-12) 以前の残留データ救済)
    認証: admin Bearer または X-Cron-Secret (日次 scheduler から呼ぶため)。

    返り値: {reconciled: N, details: [...]}"""
    # 認証: admin Bearer OR CRON_SECRET (scheduler 経由)
    _authed = False
    if authorization and authorization.startswith("Bearer "):
        _tok = authorization[len("Bearer "):].strip()
        if _verify_admin_token(_tok):
            _authed = True
    if not _authed and x_cron_secret and CRON_SECRET and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        _authed = True
    if not _authed:
        raise HTTPException(status_code=401, detail="未認証")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY が未設定")

    s = get_stripe()
    reconciled = []
    orphans = []
    errors = []
    # 生徒ごとの active ai-juku サブ集合 (stale 紐付け自己修復パスで使用)
    _aijuku_subs_by_student = {}
    # auto_paging_iter で 100 件上限を超えても全 active sub を走査 (在籍 200+ でも取りこぼさない)
    try:
        active_subs = list(s.Subscription.list(status="active", limit=100).auto_paging_iter())
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Stripe Subscription.list 失敗: {e}")

    conn = db()
    c = conn.cursor()
    for sub in active_subs:
        try:
            # juku-payment 系 subscription は ai-juku DB に触れない (二重保険)。
            # system タグに加え v1 月謝サブスク (タグ無し・registration_id / source=self-register* のみ)
            # も除外し _is_non_aijuku_invoice とマーカーパリティを取る (2026-06-11 review 推奨)
            _sub_meta = (getattr(sub, "metadata", None) or {})
            if ((_sub_meta.get("system") or "").startswith("juku-payment")
                    or (_sub_meta.get("source") or "").startswith(("self-register", "past-due-invoice"))
                    or _sub_meta.get("registration_id")):
                continue
            customer = sub.customer
            plan = (sub.metadata or {}).get("plan", "")
            email = None
            try:
                cust_obj = s.Customer.retrieve(customer)
                # 🔧 2026-06-20 [email-norm] Stripe の email は大文字混じり得るが、students.email は
                #   小文字正規化で保存 (signup/admin_set とも .lower())。素の email で照合すると
                #   "Parent@Example.com" が DB ヒットせず、実在生徒を誤って orphan 計上し reconcile
                #   から漏らしていた。login 経路 (~9088/9326) と同じく小文字化して突合する。
                email = (cust_obj.email or "").strip().lower() or None
            except Exception:
                pass
            # DB 検索: stripe_customer_id 優先・無ければ email
            c.execute("SELECT id, status, plan, stripe_subscription_id, trial_end FROM students WHERE stripe_customer_id = ?", (customer,))
            row = c.fetchone()
            if not row and email:
                # LOWER(email) で legacy の大文字混じり DB 行にも対応 (param は上で小文字化済)。
                # ORDER BY id LIMIT 1 = 万一 casing 違いの重複行があっても決定的に1件選ぶ (login 経路と同規約)
                c.execute("SELECT id, status, plan, stripe_subscription_id, trial_end FROM students WHERE LOWER(email) = ? ORDER BY id LIMIT 1", (email,))
                row = c.fetchone()
            if not row:
                # Stripe 側に sub があるが DB に該当生徒なし → orphan
                orphans.append({"customer": customer, "email": email, "subscription": sub.id, "plan": plan})
                continue
            sid, status, db_plan = row[0], row[1], row[2]
            _aijuku_subs_by_student.setdefault(sid, []).append({
                "sub_id": sub.id,
                "customer": customer,
                "created": getattr(sub, "created", 0) or 0,
                "stored_sub": row["stripe_subscription_id"],
            })
            if status != "paid":
                # 🛡️ 2026-06-12: trial_end=NULL を伴う (paid 化の共通規約)。この list は
                # status="active" 限定 = Stripe 側で trialing でないことが確認済みなので安全
                # (trial_extended の 21 日 trial 中の生徒がここで paid 化されることはない)。
                c.execute(
                    """UPDATE students SET status='paid', stripe_customer_id=?, stripe_subscription_id=?,
                           plan=?, paid_since=COALESCE(paid_since, CURRENT_TIMESTAMP), trial_end=NULL, cancel_at=NULL, updated_at=CURRENT_TIMESTAMP
                       WHERE id=?""",
                    (customer, sub.id, plan or db_plan, sid),
                )
                conn.commit()
                reconciled.append({"student_id": sid, "email": email, "old_status": status, "new_status": "paid", "plan": plan or db_plan})
            elif db_plan != plan and plan:
                # plan だけ違う → 更新
                c.execute(
                    "UPDATE students SET plan=?, stripe_subscription_id=?, cancel_at=NULL, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                    (plan, sub.id, sid),
                )
                conn.commit()
                reconciled.append({"student_id": sid, "email": email, "plan_change": f"{db_plan} → {plan}"})
            elif row["trial_end"]:
                # 🛡️ 2026-06-12: status='paid' なのに trial_end が残る stale 行の Stripe 検証付き backfill。
                # monthly webhook が paid 化時に trial_end をクリアしなかった fix 前の残留データで、
                # 放置すると cron_trial_reminders の窓に入り契約者へ無課金 trial 用メールが誤配される。
                # この分岐は active sub 確認済み (trialing は list に入らない) の行しか通らないので
                # blind backfill にならない。日次 scheduler 経由で冪等に収束する。
                # (plan ズレと併発時は前の elif が先に走り、翌日のこの分岐で trial_end が消える)
                c.execute("UPDATE students SET trial_end=NULL, updated_at=CURRENT_TIMESTAMP WHERE id=?", (sid,))
                conn.commit()
                reconciled.append({"student_id": sid, "email": email, "stale_trial_end_cleared": str(row["trial_end"])})
        except Exception as e:
            errors.append({"sub_id": sub.id, "error": str(e)})
            try: conn.rollback()
            except Exception: pass

    # 🔗 stale 紐付け自己修復パス (2026-06-11 塾長指示・森澤さん事例): 既に paid で plan も一致する
    # 生徒は上の昇格パスで一切 UPDATE されず、解約済み/juku-payment サブスクへの古い紐付けが残り続ける。
    # 紐付けが死んでいると invoice.payment_failed / subscription.deleted がその生徒に届かず
    # past_due 降格・督促・解約検知が発火しない → stored sub が「その生徒の active ai-juku サブ集合」に
    # 無い場合のみ active サブ (複数なら created 最新) へ張り替える。正当な複数サブ保持者は flap させない。
    relinked = []
    _touched_ids = {r.get("student_id") for r in reconciled}
    for _sid, _subs in _aijuku_subs_by_student.items():
        try:
            if _sid in _touched_ids:
                continue  # 昇格/plan 変更パスが今回すでに正しい紐付けを書いた生徒はスキップ
            _active_ids = {x["sub_id"] for x in _subs}
            _stored = _subs[0]["stored_sub"]
            if _stored in _active_ids:
                continue
            _best = max(_subs, key=lambda x: x.get("created") or 0)
            c.execute(
                "UPDATE students SET stripe_subscription_id=?, stripe_customer_id=?, cancel_at=NULL, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                (_best["sub_id"], _best["customer"], _sid),
            )
            conn.commit()
            relinked.append({"student_id": _sid, "old_subscription": _stored, "new_subscription": _best["sub_id"]})
            log.warning(f"[Reconcile relink] student_id={_sid} stale sub {_stored} → {_best['sub_id']}")
        except Exception as e:
            errors.append({"relink_student": _sid, "error": str(e)})
            try: conn.rollback()
            except Exception: pass

    # 🔻 downgrade pass (2026-05-29 追加): webhook 取りこぼしで「Stripe は past_due/unpaid/canceled
    # なのに DB は paid のまま」の生徒を救済。Stripe を真実として paid → past_due/canceled に降格。
    # ・paid のみ対象 (trial/expired/canceled には触れない)。subscription_id 厳密照合で誤降格を防ぐ。
    # ・unpaid → past_due (webhook と統一・回復経路を生かす。canceled に潰すと paid 復帰できなくなる)
    # ・canceled → canceled。canceled sub は永久蓄積するため created で直近 90 日に限定 (上限取りこぼし回避)
    # ・past_due 化時は past_due_since を打刻 (grace 起点)
    downgraded = []
    now_ts = datetime.now(timezone.utc)
    _downgrade_map = {"past_due": "past_due", "unpaid": "past_due", "canceled": "canceled"}
    for _stripe_st, _db_st in _downgrade_map.items():
        try:
            # list() で materialize し、全ページ取得 (network) を outer try 内に収める
            # → for ループ中の page fetch 例外で関数が中断し conn.close() 漏れになるのを防ぐ
            if _stripe_st == "canceled":
                _cutoff = int((now_ts - timedelta(days=90)).timestamp())
                _iter = list(s.Subscription.list(status="canceled", limit=100, created={"gte": _cutoff}).auto_paging_iter())
            else:
                _iter = list(s.Subscription.list(status=_stripe_st, limit=100).auto_paging_iter())
        except Exception as e:
            errors.append({"downgrade_list": _stripe_st, "error": str(e)})
            continue
        for sub in _iter:
            try:
                _dsub_meta = (getattr(sub, "metadata", None) or {})
                if ((_dsub_meta.get("system") or "").startswith("juku-payment")
                        or (_dsub_meta.get("source") or "").startswith(("self-register", "past-due-invoice"))
                        or _dsub_meta.get("registration_id")):
                    continue
                c.execute("SELECT id, status, name, email FROM students WHERE stripe_subscription_id=?", (sub.id,))
                row = c.fetchone()
                if not row:
                    continue
                sid, cur_status = row[0], row[1]
                if cur_status == "paid":
                    if _db_st == "past_due":
                        c.execute(
                            """UPDATE students SET status='past_due',
                                   past_due_since=COALESCE(past_due_since, CURRENT_TIMESTAMP),
                                   updated_at=CURRENT_TIMESTAMP
                               WHERE id=? AND status='paid'""",
                            (sid,),
                        )
                    else:
                        c.execute(
                            "UPDATE students SET status=?, updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='paid'",
                            (_db_st, sid),
                        )
                    if c.rowcount > 0:
                        conn.commit()
                        downgraded.append({"student_id": sid, "old_status": "paid", "new_status": _db_st, "stripe_status": _stripe_st})
                        log.warning(f"[Reconcile downgrade] student_id={sid} paid→{_db_st} (Stripe {_stripe_st}) sub={sub.id}")
                        if _db_st == "past_due":
                            # 🔔 2026-06-11: 本番 webhook が invoice.payment_failed を購読していない間は
                            # この reconcile が唯一の past_due 降格経路 → サイレント降格だと CEO 監視
                            # (payment_failed_48h) も督促メールも一切発火しない。webhook 経路と同じ
                            # 通知 (stripe_payment_failed event + dunning メール) をここでも発火する。
                            # dunning は helper 側 7日 dedup 済のため日次実行でも連投しない。
                            try:
                                _record_ai_critical_event("stripe_payment_failed", {
                                    "student_id": sid,
                                    "name": row["name"],
                                    "email": row["email"],
                                    "subscription_id": sub.id,
                                    "stripe_status": _stripe_st,
                                    "source": "reconcile_downgrade",
                                })
                            except Exception as _ce:
                                log.error(f"[Reconcile downgrade] critical event record failed for {sid}: {_ce}")
                            try:
                                _send_payment_failed_dunning_email(sid, row["name"], row["email"])
                            except Exception as _de:
                                log.error(f"[Reconcile downgrade] dunning email failed for {sid}: {_de}")
            except Exception as e:
                errors.append({"downgrade_sub_id": getattr(sub, "id", "?"), "error": str(e)})
                try: conn.rollback()
                except Exception: pass
    conn.close()

    return {
        "ok": True,
        "stripe_active_subscriptions": len(active_subs),
        "reconciled": len(reconciled),
        "relinked": len(relinked),
        "downgraded": len(downgraded),
        "orphans": len(orphans),
        "errors": len(errors),
        "details": {"reconciled": reconciled, "relinked": relinked, "downgraded": downgraded, "orphans": orphans, "errors": errors},
        "message": f"✅ 昇格 {len(reconciled)} 件 / 紐付け修復 {len(relinked)} 件 / 降格 {len(downgraded)} 件を Stripe に同期。orphan {len(orphans)} 件は手動確認推奨。",
    }


@app.post("/api/admin/stripe/backfill-payments")
def admin_stripe_backfill_payments(
    payload: dict = None,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """💰 過去の Stripe paid invoice を payments テーブルへ backfill (2026-06-11)

    webhook が invoice.payment_succeeded のみ処理 (本番は invoice.paid しか購読されておらず
    一度も発火しない) だったバグで payments が全期間 0 行 → Stripe API から status=paid の
    invoice を取得して投入する。保存 dedup キーは webhook と同じ invoice:<id> 正規化
    (照合は payment_intent も含む) のため何度実行しても冪等。生徒不一致 invoice は
    INSERT せず unmatched_student で報告のみ (juku-payment 月謝の混入防止と合わせ 3 視点 review 反映)。

    認証: admin Bearer または X-Cron-Secret。
    payload: {dry_run?: true (デフォルト true・明示 false で実 INSERT), days?: 365 (走査範囲)}
    返り値: {ok, dry_run, scanned, inserted, skipped_duplicate, skipped_zero, skipped_juku_payment, unmatched_student, details}
    """
    _authed = False
    if authorization and authorization.startswith("Bearer "):
        _tok = authorization[len("Bearer "):].strip()
        if _verify_admin_token(_tok):
            _authed = True
    if not _authed and x_cron_secret and CRON_SECRET and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        _authed = True
    if not _authed:
        raise HTTPException(status_code=401, detail="未認証")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY が未設定")

    payload = payload or {}
    dry_run = bool(payload.get("dry_run", True))  # 安全側デフォルト: 明示 false の時だけ実 INSERT
    try:
        _days_raw = payload.get("days", 365)
        # `or 365` だと days=0 が 365 に化ける (R2 review LOW) → None のみ default に倒す
        days = max(1, min(int(365 if _days_raw is None else _days_raw), 730))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="days は数値で指定してください")
    _cutoff = int((datetime.now(timezone.utc) - timedelta(days=days)).timestamp())

    s = get_stripe()
    try:
        paid_invoices = list(s.Invoice.list(status="paid", limit=100, created={"gte": _cutoff}).auto_paging_iter())
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Stripe Invoice.list 失敗: {e}")

    conn = db()
    c = conn.cursor()
    inserted, skipped_dup, skipped_zero, skipped_juku, unmatched = [], [], [], [], []
    skipped_refunded = []
    errors = []
    for inv in paid_invoices:
        try:
            inv_id = inv.get("id")
            # juku-payment 月謝の完全除外 (invoice.metadata + 滞納 source + サブスク metadata の 3 経路)
            _skip_reason = _is_non_aijuku_invoice(inv)
            if _skip_reason:
                skipped_juku.append({"invoice": inv_id, "reason": _skip_reason})
                continue
            amount_paid = inv.get("amount_paid", 0) or 0
            if amount_paid <= 0:
                skipped_zero.append(inv_id)
                continue
            inv_pi = inv.get("payment_intent")
            if isinstance(inv_pi, dict):
                inv_pi = inv_pi.get("id")
            # 保存キーは webhook と同じ invoice id 正規化 (CRITICAL-2: 全 API バージョンで同一値に衝突させる)
            store_key = f"invoice:{inv_id}" if inv_id else None
            dedup_keys = [k for k in (store_key, inv_pi) if k]
            if not store_key:
                # 実質起こり得ないが、黙って落とすと scanned と各バケツ合計が合わなくなる
                errors.append({"invoice": inv_id, "error": "invoice id missing"})
                continue
            _ph = ",".join("?" * len(dedup_keys))
            c.execute(f"SELECT 1 FROM payments WHERE stripe_payment_intent IN ({_ph})", tuple(dedup_keys))
            if c.fetchone():
                skipped_dup.append(inv_id)
                continue
            # student_id 解決: subscription → customer → email の順 (webhook と同ロジック + email 救済)
            student_id = None
            matched_by = None
            inv_sub = _invoice_subscription_id(inv)
            inv_cust = inv.get("customer")
            if inv_sub:
                c.execute("SELECT id FROM students WHERE stripe_subscription_id=?", (inv_sub,))
                row = c.fetchone()
                if row:
                    student_id = row["id"]
                    matched_by = "subscription"
            if student_id is None and inv_cust:
                c.execute("SELECT id FROM students WHERE stripe_customer_id=?", (inv_cust,))
                row = c.fetchone()
                if row:
                    student_id = row["id"]
                    matched_by = "customer"
            if student_id is None and inv_sub:
                # email fallback (2026-06-11 ラウンド1 review): 解約→再契約で stripe_customer_id が
                # 新 customer に上書きされた生徒の旧 customer 配下 invoice を救済
                # (reconcile の email fallback と同方針。students.email は UNIQUE)。
                # R2 review MEDIUM: subscription 付き invoice に限定 — マーカー無しの手動 Dashboard
                # invoice (subscription 無し) を email 一致だけで売上計上しない。
                _inv_email = (inv.get("customer_email") or "").strip().lower()
                if _inv_email:
                    c.execute("SELECT id FROM students WHERE LOWER(email)=?", (_inv_email,))
                    row = c.fetchone()
                    if row:
                        student_id = row["id"]
                        matched_by = "email"
            paid_ts = ((inv.get("status_transitions") or {}).get("paid_at")) or inv.get("created")
            paid_at_dt = datetime.fromtimestamp(paid_ts, tz=timezone.utc) if paid_ts else datetime.now(timezone.utc)
            entry = {
                "invoice": inv_id, "student_id": student_id, "amount": amount_paid,
                "paid_at": paid_at_dt.isoformat(), "subscription": inv_sub, "customer": inv_cust,
                "matched_by": matched_by,
            }
            if student_id is None:
                # 生徒不一致は INSERT せず報告のみ (CRITICAL-3: NULL student_id 行を作らない)。
                # 生徒行が後から紐付いた場合は次回実行 (日次 cron) が冪等に投入する。
                unmatched.append(entry)
                continue
            # 返金チェック (R2 review MEDIUM): Stripe は返金しても invoice.status='paid' のままのため、
            # 返金済み invoice を全額 'paid' で復活させない。照会コスト削減のため dedup/juku/$0/未一致を
            # 通過した INSERT 候補のみ charge を 1 回照会。basil 系 payload 等で charge id が取れない
            # 場合は素通し (以後の返金は charge.refunded webhook が反映する)。
            refunded_amt = 0
            _ch_ref = inv.get("charge")
            if isinstance(_ch_ref, dict):
                refunded_amt = _ch_ref.get("amount_refunded", 0) or 0
            elif _ch_ref:
                try:
                    refunded_amt = (s.Charge.retrieve(_ch_ref).get("amount_refunded", 0)) or 0
                except Exception as _che:
                    errors.append({"invoice": inv_id, "error": f"refund check failed: {_che}"})
            if refunded_amt >= amount_paid:
                skipped_refunded.append({"invoice": inv_id, "refunded": refunded_amt})
                continue
            amount_to_record = amount_paid - max(0, refunded_amt)
            entry["amount"] = amount_to_record
            if refunded_amt > 0:
                entry["refunded_deducted"] = refunded_amt
            if not dry_run:
                try:
                    c.execute(
                        f"""INSERT INTO payments (student_id, stripe_payment_intent, amount, status, paid_at)
                            SELECT ?, ?, ?, 'paid', ?
                            WHERE NOT EXISTS (SELECT 1 FROM payments WHERE stripe_payment_intent IN ({_ph}))""",
                        (student_id, store_key, amount_to_record, paid_at_dt, *dedup_keys)
                    )
                    conn.commit()
                    if getattr(c, "rowcount", 0) > 0:
                        inserted.append(entry)
                    else:
                        skipped_dup.append(inv_id)
                except IntegrityError:
                    try: conn.rollback()
                    except Exception: pass
                    skipped_dup.append(inv_id)
            else:
                inserted.append(entry)
        except Exception as e:
            errors.append({"invoice": getattr(inv, "id", "?"), "error": str(e)})
            try: conn.rollback()
            except Exception: pass
    conn.close()

    log.info(
        f"[Stripe backfill-payments] dry_run={dry_run} scanned={len(paid_invoices)} "
        f"inserted={len(inserted)} dup={len(skipped_dup)} zero={len(skipped_zero)} "
        f"juku={len(skipped_juku)} refunded={len(skipped_refunded)} unmatched={len(unmatched)} errors={len(errors)}"
    )
    return {
        "ok": True,
        "dry_run": dry_run,
        "days": days,
        "scanned": len(paid_invoices),
        "inserted": len(inserted),
        "skipped_duplicate": len(skipped_dup),
        "skipped_zero": len(skipped_zero),
        "skipped_juku_payment": len(skipped_juku),
        "skipped_refunded": len(skipped_refunded),
        "unmatched_student": len(unmatched),
        "errors": len(errors),
        "details": {"inserted": inserted, "unmatched_student": unmatched,
                    "skipped_refunded": skipped_refunded, "errors": errors},
        "message": (
            f"{'(dry run) ' if dry_run else ''}走査 {len(paid_invoices)} 件 → "
            f"投入{'予定' if dry_run else ''} {len(inserted)} 件 / 重複 skip {len(skipped_dup)} 件 / "
            f"$0 skip {len(skipped_zero)} 件 / 全額返金 skip {len(skipped_refunded)} 件 / "
            f"生徒未一致 {len(unmatched)} 件"
        ),
    }


# AIコーチング webhook handler (stripe_webhook) が実装済みで、本番運用に必須の購読イベント。
# invoice.paid は「支払済になった」を広く捉えるイベントで payment_succeeded 発火ケースを実質包含する
# ため paid のみ購読する (両方購読すると配信量が倍になるだけ。handler 側は両イベント対応済 +
# invoice 単位 dedup があるのでどちらが届いても安全)。
_REQUIRED_WEBHOOK_EVENTS = (
    "checkout.session.completed",
    "invoice.paid",
    "invoice.payment_failed",
    "customer.subscription.updated",
    "customer.subscription.deleted",
    "charge.refunded",  # 返金の逆仕訳 (2026-06-11 ラウンド1 review: 無いと売上が恒久過大表示)
)


@app.post("/api/admin/stripe/webhook-events-sync")
def admin_stripe_webhook_events_sync(
    payload: dict = None,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🔧 Stripe webhook endpoint の購読イベント自己修復 (2026-06-11)

    監査で本番 webhook endpoint が checkout.session.completed / invoice.paid /
    customer.subscription.deleted の 3 種しか購読しておらず、invoice.payment_failed と
    customer.subscription.updated が一度も届かない (= past_due 降格・督促メール・課金回復の
    webhook 経路が全て不発) ことが判明 → 不足イベントを API で追加する self-healing endpoint。

    ・AIコーチングの webhook URL (path に /api/stripe/webhook を含む) のみ対象。
      juku-payment 側 (/api/stripe-webhook ハイフン区切り・Vercel) は path 不一致で触らない。
    ・Dashboard 作成の endpoint は Stripe 仕様で API 更新不可 → エラー内容と手動手順を返す。
    ・認証: admin Bearer または X-Cron-Secret。dry_run デフォルト true (明示 false で実更新)。
    """
    _authed = False
    if authorization and authorization.startswith("Bearer "):
        _tok = authorization[len("Bearer "):].strip()
        if _verify_admin_token(_tok):
            _authed = True
    if not _authed and x_cron_secret and CRON_SECRET and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        _authed = True
    if not _authed:
        raise HTTPException(status_code=401, detail="未認証")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY が未設定")

    payload = payload or {}
    dry_run = bool(payload.get("dry_run", True))
    s = get_stripe()
    try:
        endpoints = list(s.WebhookEndpoint.list(limit=100).auto_paging_iter())
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Stripe WebhookEndpoint.list 失敗: {e}")

    results = []
    for ep in endpoints:
        ep_id = ep.get("id")
        url = ep.get("url") or ""
        # api_version は juku-payment サブスク判定 (subscription_details の有無) に影響するため可視化
        # (R2 review: 2023-08-16 未満だと subscription_details が無く unmatched 観測が増える)
        entry = {"id": ep_id, "url": url, "status": ep.get("status"), "api_version": ep.get("api_version")}
        if "/api/stripe/webhook" not in url:
            entry["skipped"] = "AIコーチング webhook ではない (juku-payment 等) → 変更しない"
            results.append(entry)
            continue
        current = list(ep.get("enabled_events") or [])
        entry["current_events"] = current
        if "*" in current:
            entry["missing_events"] = []
            entry["note"] = "全イベント購読 (*) のため変更不要"
            results.append(entry)
            continue
        missing = [e for e in _REQUIRED_WEBHOOK_EVENTS if e not in current]
        entry["missing_events"] = missing
        if not missing:
            entry["note"] = "必須イベント購読済・変更不要"
            results.append(entry)
            continue
        target = sorted(set(current) | set(_REQUIRED_WEBHOOK_EVENTS))
        if dry_run:
            entry["would_update_to"] = target
            results.append(entry)
            continue
        try:
            s.WebhookEndpoint.modify(ep_id, enabled_events=target)
            entry["updated"] = True
            entry["added_events"] = missing
            log.info(f"[Stripe webhook-events-sync] endpoint {ep_id} に {len(missing)} イベント追加: {missing}")
        except Exception as e:
            # Dashboard 作成 endpoint は API 更新不可 (Stripe 仕様)。手動手順を案内する。
            entry["error"] = str(e)
            entry["manual_fix"] = (
                "Stripe Dashboard → 開発者 → Webhooks → 該当 endpoint → 「イベントを追加」で "
                + ", ".join(missing) + " を追加してください"
            )
            log.error(f"[Stripe webhook-events-sync] endpoint {ep_id} 更新失敗: {e}")
        results.append(entry)

    return {
        "ok": True,
        "dry_run": dry_run,
        "required_events": list(_REQUIRED_WEBHOOK_EVENTS),
        "endpoints": results,
    }


@app.get("/api/admin/stripe/diagnose-orphan-subs")
def admin_stripe_diagnose_orphan_subs(
    days: int = 30,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🔍 customer.subscription.deleted のうち生徒不一致 (orphan) の解約イベントを Stripe Events から
    特定する read-only 診断 (2026-06-11)。

    背景: 6/8 にどの生徒の stripe_subscription_id とも一致しない subscription.deleted が届いており、
    同一顧客の重複サブスク (二重課金) の疑い → Stripe Events API (保持 30 日) から該当イベントを取得し、
    sub_id / customer / 同一 customer の生徒照合 / 直近 invoice 履歴を返して人手判断を支援する。
    Stripe への書込は一切行わない。認証: admin Bearer または X-Cron-Secret。
    """
    _authed = False
    if authorization and authorization.startswith("Bearer "):
        _tok = authorization[len("Bearer "):].strip()
        if _verify_admin_token(_tok):
            _authed = True
    if not _authed and x_cron_secret and CRON_SECRET and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        _authed = True
    if not _authed:
        raise HTTPException(status_code=401, detail="未認証")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY が未設定")

    days = max(1, min(int(days), 30))  # Stripe Events の保持期間は 30 日
    _cutoff = int((datetime.now(timezone.utc) - timedelta(days=days)).timestamp())
    s = get_stripe()
    try:
        evts = list(s.Event.list(type="customer.subscription.deleted", created={"gte": _cutoff}, limit=100).auto_paging_iter())
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Stripe Event.list 失敗: {e}")

    conn = db()
    c = conn.cursor()
    out = []
    errors = []
    for ev in evts:
        try:
            sub = (ev.get("data") or {}).get("object") or {}
            sub_id = sub.get("id")
            cust = sub.get("customer")
            meta = sub.get("metadata") or {}
            entry = {
                "event_id": ev.get("id"),
                "deleted_at": datetime.fromtimestamp(ev.get("created"), tz=timezone.utc).isoformat() if ev.get("created") else None,
                "subscription_id": sub_id,
                "customer": cust,
                "system_tag": meta.get("system"),
                # 🔁 [upgrade-supersede] (2026-06-12): 月額移行/再申込で webhook が即時解約した旧サブスク (生徒不一致が正常)
                "superseded_by": meta.get("superseded_by"),
                "sub_created": datetime.fromtimestamp(sub.get("created"), tz=timezone.utc).isoformat() if sub.get("created") else None,
            }
            # sub_id 一致の生徒 (居れば正常な解約イベント)
            c.execute("SELECT id, name, status FROM students WHERE stripe_subscription_id=?", (sub_id,))
            m = c.fetchone()
            entry["matched_student"] = {"student_id": m["id"], "name": m["name"], "status": m["status"]} if m else None
            # superseded_by 付きは置換済み旧サブスク (生徒不一致が正常) — orphan (重複サブスク疑い) とは区別して数えない
            entry["superseded"] = bool(meta.get("superseded_by"))
            entry["orphan"] = m is None and not entry["superseded"]
            # customer 一致の生徒 (sub_id 不一致でも同一人物の別サブスク = 重複サブスク疑いの判定材料)
            if cust:
                c.execute("SELECT id, name, status, stripe_subscription_id FROM students WHERE stripe_customer_id=?", (cust,))
                cm = c.fetchone()
                entry["same_customer_student"] = (
                    {"student_id": cm["id"], "name": cm["name"], "status": cm["status"],
                     "current_subscription_id": cm["stripe_subscription_id"]} if cm else None
                )
                # 同一 customer の直近 invoice (二重課金の有無を見る)
                try:
                    _invs = s.Invoice.list(customer=cust, limit=10)
                    entry["recent_invoices"] = [
                        {
                            "id": i.get("id"),
                            "status": i.get("status"),
                            "amount_paid": i.get("amount_paid"),
                            "subscription": _invoice_subscription_id(i),
                            "created": datetime.fromtimestamp(i.get("created"), tz=timezone.utc).isoformat() if i.get("created") else None,
                        }
                        for i in (_invs.get("data") or [])
                    ]
                except Exception as ie:
                    entry["recent_invoices_error"] = str(ie)
            out.append(entry)
        except Exception as e:
            errors.append({"event_id": ev.get("id") if hasattr(ev, "get") else "?", "error": str(e)})
            # Postgres は失敗 statement で txn が abort する → rollback しないと以降の全 event が連鎖失敗
            try: conn.rollback()
            except Exception: pass
    conn.close()

    orphan_count = sum(1 for o in out if o.get("orphan"))
    superseded_count = sum(1 for o in out if o.get("superseded"))
    return {
        "ok": True,
        "days": days,
        "scanned_events": len(evts),
        "orphan_count": orphan_count,
        "superseded_count": superseded_count,
        "events": out,
        "errors": errors,
        "message": f"subscription.deleted {len(evts)} 件中 orphan (生徒不一致) {orphan_count} 件 / 置換済み (superseded) {superseded_count} 件",
    }


@app.get("/api/admin/stripe/diagnose-trialing-leftovers")
def admin_stripe_diagnose_trialing_leftovers(
    notify: int = 0,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🔍 Stripe 上で生きている trialing subscription のうち「生徒の現契約と不一致」な残留を
    列挙する read-only 診断 (2026-06-12)。

    背景 🔁 [upgrade-supersede] (2026-06-12): 32954aa 以前は体験中 (trial_extended) の月額移行で
    旧 trial サブスクが Stripe に残留し、trial 明けに ¥14,500/月 の二重課金が始まった。
    既存の reconcile は Subscription.list(status="active") のみ走査・diagnose-orphan-subs は
    deleted イベントのみ走査のため、「まだ生きている trialing 残留」は課金が始まるまで
    どの機構にも見えなかった (3 視点監査 2026-06-12 で特定した検出の穴)。
    本 endpoint は status="trialing" を全走査し、課金開始 **前** に残留を検出する。

    分類:
      - normal:   sub_id が生徒の stripe_subscription_id と一致 (進行中の trial_extended・正常)
      - leftover: 生徒は特定できるが stored sub と不一致 (月額移行/解約後の残留 →
                  trial 明けに二重課金)。metadata.superseded_by 付きで生存 = 置換時の解約失敗も含む
      - orphan:   どの生徒にも紐づかない trialing サブ (手動作成など・要個別確認)
    notify=1 (日次 scheduler 用): leftover/orphan があれば critical event を記録して塾長に可視化。
    同一の検出集合 (sub_id の digest 一致) は 3 日間再記録しない = 3 日ごとの督促に減速して
    CEO ダッシュの critical event ノイズ化を防ぐ (3視点 review 指摘 2026-06-12)。集合が変われば即記録。
    Stripe への書込は一切行わない。認証: admin Bearer または X-Cron-Secret。
    """
    _authed = False
    if authorization and authorization.startswith("Bearer "):
        _tok = authorization[len("Bearer "):].strip()
        if _verify_admin_token(_tok):
            _authed = True
    if not _authed and x_cron_secret and CRON_SECRET and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        _authed = True
    if not _authed:
        raise HTTPException(status_code=401, detail="未認証")
    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY が未設定")

    s = get_stripe()
    try:
        trialing_subs = list(s.Subscription.list(status="trialing", limit=100).auto_paging_iter())
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Stripe Subscription.list 失敗: {e}")

    conn = db()
    c = conn.cursor()
    normal, leftovers, orphans, errors = [], [], [], []
    for sub in trialing_subs:
        try:
            meta = (getattr(sub, "metadata", None) or {})
            # juku-payment / 旧 v1 月謝系は ai-juku の管轄外 (reconcile と同じ除外規約)
            if ((meta.get("system") or "").startswith("juku-payment")
                    or (meta.get("source") or "").startswith(("self-register", "past-due-invoice"))
                    or meta.get("registration_id")):
                continue
            sub_id = sub.id
            customer = getattr(sub, "customer", None)
            _te_ts = getattr(sub, "trial_end", None)
            entry = {
                "subscription_id": sub_id,
                "customer": customer,
                "trial_end": datetime.fromtimestamp(int(_te_ts), tz=timezone.utc).isoformat() if _te_ts else None,
                "superseded_by": meta.get("superseded_by"),
            }
            # 1) sub_id 一致 = その生徒の現契約 (正常な trial_extended 進行中)
            c.execute("SELECT id, name, status FROM students WHERE stripe_subscription_id=?", (sub_id,))
            row = c.fetchone()
            if row:
                entry["student"] = {"student_id": row["id"], "name": row["name"], "status": row["status"]}
                normal.append(entry)
                continue
            # 2) customer → email (親/子) の順で生徒を探す。見つかれば stored sub 不一致の残留
            # Customer.retrieve は customer 不一致の sub でのみ発火 (最大 trialing 件数分の N+1 だが
            # founder 50 名規模 + 日次 1 回なので Stripe rate limit (100req/s) に対して十分許容)
            row = None
            if customer:
                c.execute("SELECT id, name, status, stripe_subscription_id FROM students WHERE stripe_customer_id=?", (customer,))
                row = c.fetchone()
            if not row and customer:
                _lo_email = None
                try:
                    _lo_email = ((getattr(s.Customer.retrieve(customer), "email", None) or "").strip().lower()) or None
                except Exception:
                    _lo_email = None
                if _lo_email:
                    c.execute(
                        "SELECT id, name, status, stripe_subscription_id FROM students "
                        "WHERE LOWER(email)=? OR LOWER(COALESCE(student_email,''))=?",
                        (_lo_email, _lo_email),
                    )
                    row = c.fetchone()
            if row:
                entry["student"] = {"student_id": row["id"], "name": row["name"], "status": row["status"],
                                    "current_subscription_id": row["stripe_subscription_id"]}
                entry["reason"] = (
                    "supersede_cancel_failed" if meta.get("superseded_by")
                    else f"student_status_{row['status']}_with_mismatched_live_trial"
                )
                leftovers.append(entry)
            else:
                orphans.append(entry)
        except Exception as e:
            errors.append({"sub_id": getattr(sub, "id", "?"), "error": str(e)})
            # Postgres は失敗 statement で txn が abort する → rollback しないと以降が連鎖失敗
            try: conn.rollback()
            except Exception: pass
    conn.close()

    result = {
        "ok": True,
        "scanned_trialing": len(trialing_subs),
        "leftover_count": len(leftovers),
        "orphan_count": len(orphans),
        "normal_count": len(normal),
        "leftovers": leftovers,
        "orphans": orphans,
        "normal": normal,
        "errors": errors,
        "message": (
            f"trialing {len(trialing_subs)} 件中 残留 (leftover) {len(leftovers)} 件 / "
            f"生徒不明 (orphan) {len(orphans)} 件 / 正常 {len(normal)} 件"
        ),
    }
    if notify and (leftovers or orphans):
        # 連日同一内容の積み上げ防止 (3視点 review 指摘 2026-06-12): 検出集合 (sub_id) の digest が
        # 直近 3 日の記録と一致するなら再記録しない。集合が変わったら即記録 (新規残留を遅延させない)。
        _digest = hashlib.sha256(json.dumps(sorted(
            [e["subscription_id"] for e in leftovers] + [e["subscription_id"] for e in orphans]
        )).encode("utf-8")).hexdigest()[:16]
        _dup = False
        try:
            _conn_d = db()
            _c_d = _conn_d.cursor()
            # created_at は DB 既定の "YYYY-MM-DD HH:MM:SS" (UTC) — 同形式の文字列で範囲比較する
            _cutoff_d = (datetime.now(timezone.utc) - timedelta(days=3)).strftime("%Y-%m-%d %H:%M:%S")
            _c_d.execute(
                "SELECT props FROM events WHERE name=? AND session_id='ai_failsafe' AND created_at>=? ORDER BY id DESC LIMIT 1",
                ("trialing_leftover_subscription_detected", _cutoff_d),
            )
            _prev = _c_d.fetchone()
            _conn_d.close()
            if _prev:
                try:
                    _dup = (json.loads(_prev["props"]).get("digest") == _digest)
                except Exception:
                    _dup = False
        except Exception as _de:
            # dedup 照会失敗は記録継続 (重複ノイズより残留の見逃しの方が実害大)
            log.warning(f"[trialing-leftovers] dedup lookup failed (記録は続行): {_de}")
        if _dup:
            log.info(f"[trialing-leftovers] 同一内容を 3 日以内に記録済み (digest={_digest}) — critical event 再記録スキップ")
        else:
            _record_ai_critical_event("trialing_leftover_subscription_detected", {
                "digest": _digest,
                "leftover_count": len(leftovers),
                "orphan_count": len(orphans),
                "subscriptions": (
                    [{"subscription_id": e["subscription_id"], "trial_end": e["trial_end"],
                      "student_id": (e.get("student") or {}).get("student_id"), "reason": e.get("reason")}
                     for e in leftovers]
                    + [{"subscription_id": e["subscription_id"], "trial_end": e["trial_end"],
                        "student_id": None, "reason": "orphan"} for e in orphans]
                ),
                "action_required": "Stripe Dashboard で各 subscription を確認し、残留なら Cancel immediately してください (放置すると trial 明けに二重課金)",
            })
    return result


