# IP rate limit (events table 汚染防御・bot 対策・3視点 review High 修正)
# 1 IP あたり 30 req/min (ある程度緩い・通常ユーザーは LP 1 訪問 = 1 record)
_LP_UTM_RATE: dict = {}  # {ip: [unix_ts, ...]}
_LP_UTM_RATE_LIMIT = 30
_LP_UTM_RATE_WINDOW = 60  # seconds


def _check_lp_utm_rate(ip: str) -> bool:
    """1 IP あたり 30 req/min の rate limit。bot による events table 膨張防御。"""
    import time as _t
    now = _t.time()
    window_start = now - _LP_UTM_RATE_WINDOW
    timestamps = _LP_UTM_RATE.get(ip, [])
    timestamps = [t for t in timestamps if t > window_start]
    if len(timestamps) >= _LP_UTM_RATE_LIMIT:
        return False
    timestamps.append(now)
    _LP_UTM_RATE[ip] = timestamps
    # memory leak 対策: dict が 10000 IP 超えたら全 clear (1 process 想定の簡易対応)
    if len(_LP_UTM_RATE) > 10000:
        _LP_UTM_RATE.clear()
    return True


@app.post("/api/lp/track-utm-visit")
def track_utm_visit(payload: dict, request: Request):
    """📊 LP 訪問時の UTM パラメータを events table に記録 (公開 endpoint・auth 不要)。
    LP 側 JS から fetch で叩く想定。CEO ダッシュ「📊 ChatGPT Store 流入分析」で集計。
    payload: {utm_source, utm_medium, utm_campaign, utm_content?, utm_term?,
              referrer?, session_id?, user_agent_hint?}
    """
    # 🛡️ IP rate limit (3視点 review High 修正・bot 対策)
    client_ip = "unknown"
    try:
        if request.client:
            client_ip = request.client.host or "unknown"
        # X-Forwarded-For 対応 (Railway/Vercel 経由)
        xff = request.headers.get("x-forwarded-for", "")
        if xff:
            client_ip = xff.split(",")[0].strip() or client_ip
    except Exception:
        pass
    if not _check_lp_utm_rate(client_ip):
        raise HTTPException(status_code=429, detail="rate limit exceeded (30 req/min)")

    utm_source = (payload.get("utm_source") or "").strip()[:50]
    utm_medium = (payload.get("utm_medium") or "").strip()[:50]
    utm_campaign = (payload.get("utm_campaign") or "").strip()[:100]
    utm_content = (payload.get("utm_content") or "").strip()[:100]
    utm_term = (payload.get("utm_term") or "").strip()[:100]
    referrer = (payload.get("referrer") or "").strip()[:300]
    session_id = (payload.get("session_id") or "").strip()[:50]

    # validation: utm_source か utm_campaign いずれか必須
    if not utm_source and not utm_campaign:
        raise HTTPException(status_code=400, detail="utm_source か utm_campaign が必要")

    # whitelist: 想定 utm_source のみ受付 (任意 string で events table 汚染防止)
    KNOWN_SOURCES = {"chatgpt_store", "threads", "instagram", "x", "youtube", "google", "direct", "other"}
    if utm_source and utm_source not in KNOWN_SOURCES:
        utm_source = "other"

    try:
        conn = db()
        c = conn.cursor()
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            (
                "lp_utm_visit",
                json.dumps({
                    "utm_source": utm_source,
                    "utm_medium": utm_medium,
                    "utm_campaign": utm_campaign,
                    "utm_content": utm_content,
                    "utm_term": utm_term,
                    "referrer": referrer[:200],
                }, ensure_ascii=False),
                session_id or "anon",
            ),
        )
        conn.commit()
        conn.close()
    except Exception as e:
        log.warning(f"[UTM] track failed: {e}")
        return {"ok": False, "error": str(e)[:200]}
    return {"ok": True, "tracked": True}


@app.get("/api/admin/autopilot/dashboard")
def admin_autopilot_dashboard(authorization: Optional[str] = Header(None)):
    """🤖 AI オートパイロット集約ダッシュ (集客〜収益化 半自動の見える化)
    塾長指示「AI チームで半自動で集客〜収益化」(2026-05-11) の C 機能。

    5 phase (集客 / 接客 / 訴求 / 決済 / 継続 / 改善) のステータス + 過去 7 日 KPI +
    過去 7 日 AI 自動アクション履歴を 1 endpoint で返す。

    AI チーム責任分担:
    - 集客①: Daily SNS 研究員 (project_ai_juku.md)
    - 集客②: ChatGPT Store funnel + Custom GPT 6 体 (feedback_chatgpt_store_funnel.md)
    - 集客③: channel bandit (本日 commit / utm_source × CV)
    - 接客: AI チューター 5 段 fallback (feedback_ai_tutor_sonnet_gemini.md)
    - 訴求: LP variant 多腕バンディット (project_ai_juku_lp_bandit.md) + CTA 強化版
    - 決済: Stripe Price lookup_key fallback + 招待コード
    - 継続①: trial-followups / trial-reminders (silent skip)
    - 継続②: trial-rescue (本日 commit / 体験中失速 AI 個別フォロー)
    - 改善: SNS 投稿型 CV 自動学習 (project_ai_juku_sns_auto_learning.md)
    """
    _verify_admin_required(authorization)

    now = datetime.now(timezone.utc)
    cutoff_7d = (now - timedelta(days=7)).isoformat()
    cutoff_24h = (now - timedelta(hours=24)).isoformat()
    cutoff_30d = (now - timedelta(days=30)).isoformat()

    conn = db()
    c = conn.cursor()
    try:
        # ===== KPI: 過去 7 日 =====
        # visits (lp_view) unique sessions
        try:
            c.execute(
                "SELECT COUNT(DISTINCT session_id) FROM events WHERE name='lp_view' AND created_at > ?",
                (cutoff_7d,)
            )
            row = c.fetchone()
            visits_7d = (row[0] if row else 0) or 0
        except Exception:
            visits_7d = 0

        # 体験申込 (status='trial' で過去 7 日 created)
        try:
            c.execute(
                "SELECT COUNT(*) FROM students WHERE status='trial' AND created_at > ?",
                (cutoff_7d,)
            )
            row = c.fetchone()
            trial_signups_7d = (row[0] if row else 0) or 0
        except Exception:
            trial_signups_7d = 0

        # 有料転換 (status='paid' で過去 7 日 paid_since)
        try:
            c.execute(
                "SELECT COUNT(*) FROM students WHERE status='paid' AND paid_since > ?",
                (cutoff_7d,)
            )
            row = c.fetchone()
            paid_conversions_7d = (row[0] if row else 0) or 0
        except Exception:
            paid_conversions_7d = 0

        # 全体 active paid (MRR の基盤)
        # 🔧 2026-06-16 [mrr-stripe-actual] per-student の sub_id も取得し Stripe 実額で MRR 集計。
        #   plan_counts は後段の plan_breakdown/active_paid_total で使うため従来どおり維持。
        plan_counts = {}
        _paid_rows = []  # [(plan, sub_id), ...]
        try:
            c.execute(
                "SELECT plan, stripe_subscription_id FROM students WHERE status='paid' AND plan IS NOT NULL"
            )
            for r in c.fetchall():
                _p = r["plan"] if hasattr(r, "keys") else r[0]
                try:
                    _sid = r["stripe_subscription_id"] if hasattr(r, "keys") else r[1]
                except Exception:
                    _sid = None
                plan_counts[_p] = plan_counts.get(_p, 0) + 1
                _paid_rows.append((_p, _sid))
        except Exception:
            plan_counts = {}
            _paid_rows = []

        # MRR 計算 ([mrr-stripe-actual] active Stripe サブスク実額・取れない分は _mrr_fee フォールバック。
        #   admin_stats と同一ロジック。founder クーポン顧客別差や ¥12,000 固定近似を解消)
        _mrr_amounts = _stripe_active_sub_amounts()
        mrr = 0
        for _p, _sid in _paid_rows:
            try:
                mrr += _student_mrr_yen(_p or "", _sid, _mrr_amounts)
            except Exception:
                pass

        # churn (過去 30 日 expired)
        try:
            c.execute(
                "SELECT COUNT(*) FROM students WHERE status='expired' AND updated_at > ?",
                (cutoff_30d,)
            )
            row = c.fetchone()
            churn_30d = (row[0] if row else 0) or 0
        except Exception:
            churn_30d = 0

        # 体験 → 有料 転換率
        cv_trial_to_paid = (paid_conversions_7d / trial_signups_7d) if trial_signups_7d > 0 else None
        # LP → 体験 転換率
        cv_visit_to_trial = (trial_signups_7d / visits_7d) if visits_7d > 0 else None

        # ===== AI 自動アクション履歴 (過去 7 日) =====
        action_types = {
            "daily_sns_post": "📣 Daily SNS 投稿生成",
            "trial_rescue": "🚨 体験離脱予兆 AI フォロー",
            "lp_variant_choice": "🎰 LP バンディット選択",
            "ai_fallback_openai": "🛡️ AI チューター fallback 発動",
            "referral_paid_credit": "💸 紹介ループ ¥3,000 OFF 付与",
            "textbook_generated": "📚 教材プール 自動生成",
            "exam_question_generated": "📝 問題プール 自動生成",
            "stripe_payment_failed": "🔴 月次課金 決済失敗 (past_due 降格)",
            "payment_unmatched_invoice": "🔭 生徒未紐付けの入金 (backfill 待ち)",
        }
        actions_summary = []
        try:
            for ev_name, label in action_types.items():
                try:
                    c.execute(
                        "SELECT COUNT(*) FROM events WHERE name=? AND created_at > ?",
                        (ev_name, cutoff_7d)
                    )
                    row = c.fetchone()
                    cnt = (row[0] if row else 0) or 0
                    if cnt > 0:
                        actions_summary.append({"event": ev_name, "label": label, "count_7d": cnt})
                except Exception:
                    pass
            actions_summary.sort(key=lambda x: x["count_7d"], reverse=True)
        except Exception:
            pass

        # ===== 5 phase 自動機能ステータス =====
        # 集客①: Daily SNS が直近 24h で投稿生成済か
        try:
            c.execute(
                "SELECT COUNT(*) FROM events WHERE name='daily_sns_post' AND created_at > ?",
                (cutoff_24h,)
            )
            sns_24h = (c.fetchone()[0] or 0)
        except Exception:
            sns_24h = 0

        # 継続②: trial-rescue が直近 7 日で実行済か
        try:
            c.execute(
                "SELECT COUNT(*) FROM notifications WHERE template='trial_rescue' AND sent_at > ?",
                (cutoff_7d,)
            )
            rescue_7d = (c.fetchone()[0] or 0)
        except Exception:
            rescue_7d = 0

        phases = [
            {
                "phase": "📣 集客", "status": "active" if sns_24h > 0 else "idle",
                "components": [
                    {"name": "Daily SNS 研究員", "status": f"直近 24h: {sns_24h} 件投稿生成"},
                    {"name": "ChatGPT Store funnel", "status": "Custom GPT 6 体 全公開済"},
                    {"name": "集客 channel bandit", "status": "utm_source 別 CV 自動最適化中"},
                ],
            },
            {
                "phase": "📚 接客", "status": "active",
                "components": [
                    {"name": "AI チューター 5 段 fallback", "status": "Sonnet→Gemini→Haiku→Opus→GPT-4o"},
                    {"name": "写真採点 (5 AI 多視点)", "status": "Opus/GPT-4o/Sonnet/Gemini/Haiku 並列"},
                    {"name": "YouTube 教材生成", "status": "Gemini multimodal 駆動"},
                ],
            },
            {
                "phase": "🎯 訴求", "status": "active",
                "components": [
                    {"name": "LP variant 多腕バンディット", "status": "epsilon-greedy 0.2 で 3 variants 自動最適化"},
                    {"name": "Custom GPT CTA 強化 (4 トリガー)", "status": "ChatGPT 内で 7 日無料体験誘導"},
                    {"name": "創設メンバー 50 名 FOMO", "status": "残枠表示 (camouflage 値)"},
                ],
            },
            {
                "phase": "💳 決済", "status": "active",
                "components": [
                    {"name": "Stripe Price lookup_key fallback", "status": "全 5 プラン env 任意化"},
                    {"name": "招待コード方式", "status": "HMAC 署名 + 30 日期限"},
                    {"name": "synthetic-monitor", "status": "5 分おき E2E 監視"},
                ],
            },
            {
                "phase": "📈 継続", "status": "active" if rescue_7d > 0 else "watching",
                "components": [
                    {"name": "trial-reminders (終了3日前)", "status": "毎日 JST 9:00 cron"},
                    {"name": "trial-followups (Day1/3/7)", "status": "silent customer skip 込み"},
                    {"name": "trial-rescue (失速 AI 個別)", "status": f"直近 7 日: {rescue_7d} 件送信"},
                    {"name": "紹介ループ (¥3,000 OFF)", "status": "HMAC code + claim-first UPDATE"},
                ],
            },
            {
                "phase": "🔬 改善", "status": "active",
                "components": [
                    {"name": "SNS 投稿型 CV 自動学習", "status": "過去 30 日 utm_content CV → prompt 注入"},
                    {"name": "監視 AI", "status": "5 分おき monitor + 致命検知"},
                    {"name": "事故 auto-rollback", "status": "致命検知時 GitHub PAT で revert"},
                ],
            },
        ]

        # ===== 戻り値 =====
        return {
            "ok": True,
            "generated_at": now.isoformat(),
            "kpi_7d": {
                "visits": visits_7d,
                "trial_signups": trial_signups_7d,
                "paid_conversions": paid_conversions_7d,
                "cv_visit_to_trial": cv_visit_to_trial,
                "cv_trial_to_paid": cv_trial_to_paid,
            },
            "kpi_overall": {
                "active_paid_total": sum(plan_counts.values()),
                "plan_breakdown": plan_counts,
                "mrr_jpy": mrr,
                "churn_30d": churn_30d,
            },
            "phases": phases,
            "ai_actions_7d": actions_summary,
            "memo": (
                "ai-juku の集客〜収益化を 9 つの AI 自動機能で半自動運用中。"
                "塾長は本ダッシュで AI チームの仕事ぶりを 1 画面で確認可。"
                "詳細は各 phase の専用 UI (CEO ダッシュ内) で深掘り。"
            ),
        }
    finally:
        conn.close()


@app.get("/api/admin/marketing/paid-attribution")
def admin_paid_attribution(days: int = 90, authorization: Optional[str] = Header(None),
                            x_cron_secret: Optional[str] = Header(None)):
    """📊 paid 化した生徒の流入元 attribution (塾長指示 2026-05-19 集客 audit)
    students テーブルの signup_utm_* / signup_lp_variant 列から
    paid 顧客の流入経路を集計。「どの channel/variant/SNS post が paid 化したか」を可視化。

    認証: admin Bearer or X-Cron-Secret (autonomous audit 用)
    クエリ: ?days=90 (default 過去 90 日の paid_since 範囲・最大 365)

    返却:
      - by_source: {utm_source: {paid: n, trial: m, conversion_rate: p}}
      - by_content: {utm_content: {同上}}
      - by_variant: {lp_variant: {同上}}
      - top_paid_sources: 上位 5 流入元
      - data_quality: utm 欠落率
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")
    if days < 1 or days > 365:
        days = 90
    conn = db()
    c = conn.cursor()
    try:
        # 過去 days 日内の signup で paid 化した students + trial のまま
        threshold = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        c.execute(
            """SELECT signup_utm_source, signup_utm_content, signup_utm_campaign, signup_lp_variant,
                      status, plan
               FROM students
               WHERE created_at >= ?""",
            (threshold,)
        )
        rows = c.fetchall()
    except Exception as e:
        log.warning(f"[paid-attribution] query failed: {e}")
        conn.close()
        raise HTTPException(status_code=500, detail=f"query failed: {type(e).__name__}")
    conn.close()
    # 集計
    def _agg_by(key_idx):
        agg = {}
        for r in rows:
            k = r[key_idx] or "(unknown)"
            if k not in agg:
                agg[k] = {"paid": 0, "trial": 0, "past_due": 0, "canceled": 0, "expired": 0, "other": 0}
            status = (r[4] or "other")
            if status == "paid":
                agg[k]["paid"] += 1
            elif status == "trial":
                agg[k]["trial"] += 1
            elif status == "past_due":
                agg[k]["past_due"] += 1
            elif status == "canceled":
                agg[k]["canceled"] += 1
            elif status == "expired":
                agg[k]["expired"] += 1
            else:
                agg[k]["other"] += 1
        # conversion_rate 算出 (paid / (paid + trial + past_due + canceled + expired))
        for k, v in agg.items():
            total = v["paid"] + v["trial"] + v.get("past_due", 0) + v["canceled"] + v["expired"]
            v["total"] = total
            v["conversion_rate"] = round(v["paid"] / total, 3) if total > 0 else 0
        return agg
    by_source = _agg_by(0)
    by_content = _agg_by(1)
    by_campaign = _agg_by(2)
    by_variant = _agg_by(3)
    # top 5 paid sources
    top_paid_sources = sorted(
        [{"source": k, **v} for k, v in by_source.items() if v["paid"] > 0],
        key=lambda x: x["paid"], reverse=True
    )[:5]
    # data quality: utm 欠落率
    total_rows = len(rows)
    missing_source = sum(1 for r in rows if not r[0])
    missing_variant = sum(1 for r in rows if not r[3])
    return {
        "ok": True,
        "days": days,
        "total_signups": total_rows,
        "by_source": by_source,
        "by_content": by_content,
        "by_campaign": by_campaign,
        "by_variant": by_variant,
        "top_paid_sources": top_paid_sources,
        "data_quality": {
            "missing_utm_source": missing_source,
            "missing_utm_source_pct": round(missing_source / total_rows, 3) if total_rows > 0 else 0,
            "missing_lp_variant": missing_variant,
            "missing_lp_variant_pct": round(missing_variant / total_rows, 3) if total_rows > 0 else 0,
            "note": "2026-05-19 以降の signup のみ utm 保存。それ以前は (unknown) で集計される。",
        },
    }


@app.get("/api/admin/marketing/channel-bandit-status")
def admin_channel_bandit_status(days: int = 30, authorization: Optional[str] = Header(None)):
    """📡 集客チャネル別バンディット状態 (utm_source × CV)
    過去 N 日 (default 30) の channel 別 CV を集計し epsilon-greedy weight を返す。
    Daily SNS 研究員の生成 prompt にこの weight に基づくヒントが自動注入される。

    塾長は「どのチャネルが効いているか」「次回投稿の集中先」を可視化できる。
    memory: project_ai_juku_sns_auto_learning.md (utm_content 学習) + project_ai_juku_lp_bandit.md (LP variant bandit)
    """
    _verify_admin_required(authorization)
    if days < 1 or days > 365:
        days = 30
    weights = _compute_channel_bandit_weights(days=days)
    total_views = sum(w["views"] for w in weights.values())
    total_submits = sum(w["submits"] for w in weights.values())
    sorted_channels = sorted(
        [{"channel": ch, **data} for ch, data in weights.items()],
        key=lambda x: x["weight"],
        reverse=True,
    )
    hint = _build_channel_bandit_hint()
    return {
        "ok": True,
        "days": days,
        "total_views": total_views,
        "total_submits": total_submits,
        "overall_cv_rate": (total_submits / total_views) if total_views > 0 else 0.0,
        "epsilon": SNS_CHANNEL_BANDIT_EPSILON,
        "min_views_for_qualified": SNS_CHANNEL_BANDIT_MIN_VIEWS,
        "channels": sorted_channels,
        "prompt_hint_injected": bool(hint),
        "prompt_hint_preview": hint[:200] if hint else "(全体 100 views 未満のため hint 注入なし・均等配分継続)",
        "memo": (
            "Daily SNS 研究員 (毎日 JST 6:00) の生成 prompt に上記 hint が自動注入される。"
            f"epsilon={SNS_CHANNEL_BANDIT_EPSILON*100:.0f}% 探索 / {(1-SNS_CHANNEL_BANDIT_EPSILON)*100:.0f}% 活用。"
            f"各 channel 30 views 以上で qualified 判定・未満は均等配分継続。"
        ),
    }


@app.get("/api/admin/marketing/chatgpt-store-analytics")
def admin_chatgpt_store_analytics(
    days: int = 7,
    authorization: Optional[str] = Header(None),
):
    """📊 ChatGPT Store 流入分析 (CEO ダッシュ用)。
    過去 N 日 (default 7d) の utm_source=chatgpt_store の流入数を campaign 別に集計。
    """
    _verify_admin_required(authorization)
    if days < 1 or days > 365:
        days = 7

    conn = db()
    try:
        c = conn.cursor()
        # SQLite と Postgres で datetime 関数が違うので、both 対応 (近似で 過去 N 日 = N*86400 秒前)
        # events.created_at は TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        # SQLite: datetime('now', '-7 days') / Postgres: NOW() - INTERVAL '7 days'
        # シンプルな共通: WHERE created_at >= ? で ISO 文字列比較 (両 DB OK)
        from datetime import timedelta
        threshold = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        c.execute(
            "SELECT props, created_at FROM events "
            "WHERE name = 'lp_utm_visit' AND created_at >= ? "
            "ORDER BY created_at DESC LIMIT 5000",
            (threshold,),
        )
        rows = c.fetchall()
    finally:
        conn.close()

    by_campaign = {}
    by_source = {}
    by_content = {}
    total = 0
    for r in rows:
        try:
            props = json.loads(r["props"] or "{}")
        except Exception:
            continue
        if props.get("utm_source") != "chatgpt_store":
            # CEO ダッシュは ChatGPT Store のみ表示・他 source は別 endpoint で
            # でも全 source 集計も並べる
            src = props.get("utm_source") or "(unknown)"
            by_source[src] = by_source.get(src, 0) + 1
            total += 1
            continue
        camp = props.get("utm_campaign") or "(none)"
        cont = props.get("utm_content") or "(none)"
        by_campaign[camp] = by_campaign.get(camp, 0) + 1
        by_content[cont] = by_content.get(cont, 0) + 1
        by_source["chatgpt_store"] = by_source.get("chatgpt_store", 0) + 1
        total += 1

    # ChatGPT Store の発火実績 (campaign 別) を Custom GPT 6 体定義と join (未到達でも 0 件で表示)
    specs = _get_custom_gpt_funnel_specs()
    chatgpt_store_breakdown = []
    for s in specs:
        chatgpt_store_breakdown.append({
            "campaign": s["id"],
            "name": s["name"],
            "visits": by_campaign.get(s["id"], 0),
        })
    chatgpt_store_breakdown.sort(key=lambda x: -x["visits"])

    return {
        "ok": True,
        "days": days,
        "total_visits": total,
        "chatgpt_store_total": by_source.get("chatgpt_store", 0),
        "by_source": by_source,
        "chatgpt_store_breakdown": chatgpt_store_breakdown,  # 6 Custom GPT × 流入数
        "top_contents": dict(sorted(by_content.items(), key=lambda x: -x[1])[:10]),
        "memo": "Custom GPT を 6 体公開すると ChatGPT Store 月 5 億ユーザーから流入。0 件期間は公開直後 or Custom GPT が未公開の可能性",
    }


@app.post("/api/admin/cache/force-purge")
def admin_cache_force_purge(authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """🧹 全生徒のブラウザキャッシュを強制パージ。

    DB に CACHE_VERSION を bump して保存。フロントの cache-purge.js が起動時に
    /api/cache-version を叩き、保存値より新しければ caches を全削除 + 強制リロード。
    バージョン文字列は ISO timestamp で生成。
    認証: admin Bearer または X-Cron-Secret (緊急対応で塾長離席中でも実行可・2026-05-06)"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    new_version = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    conn = db()
    c = conn.cursor()
    try:
        # kv_settings テーブルが無ければ作る
        c.execute(
            """CREATE TABLE IF NOT EXISTS kv_settings (
                key TEXT PRIMARY KEY,
                value TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )"""
        )
        # UPSERT
        c.execute("DELETE FROM kv_settings WHERE key = ?", ("cache_version",))
        c.execute("INSERT INTO kv_settings (key, value) VALUES (?, ?)", ("cache_version", new_version))
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        raise HTTPException(status_code=500, detail=f"DB 書込失敗: {e}")
    finally:
        conn.close()

    return {
        "ok": True,
        "cache_version": new_version,
        "message": f"✅ cache_version={new_version} を発行。次回アクセス時に全生徒のブラウザがキャッシュ削除+強制リロードします。",
    }


@app.get("/api/cache-version")
def public_cache_version():
    """全フロントが起動時に呼ぶ。新しい version が来ていたら caches 削除 + reload。"""
    conn = db()
    c = conn.cursor()
    version = ""
    try:
        c.execute("CREATE TABLE IF NOT EXISTS kv_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)")
        c.execute("SELECT value FROM kv_settings WHERE key = ?", ("cache_version",))
        row = c.fetchone()
        if row:
            version = row[0] if not hasattr(row, "keys") else row["value"]
    except Exception:
        try: conn.rollback()
        except Exception: pass
    finally:
        conn.close()
    return {"version": version or "initial"}


@app.post("/api/admin/campaigns/enrollment-waiver/reset")
def admin_enrollment_waiver_reset(payload: dict = None, authorization: Optional[str] = Header(None)):
    """💰 入塾金免除キャンペーンの枠カウンタをリセット (月初リセット用)。
    既存の status='paid' の中で enrollment_waiver_applied=1 だった生徒数 = 消費済み枠。
    本 endpoint は events テーブルに「リセット時刻」を記録し、それ以降の paid 生徒のみを
    「消費済み」としてカウントする方式に切替える。
    optional payload: {"new_limit": 100} で上限も同時に更新可能 (env 上書き)。"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="未認証")

    payload = payload or {}
    new_limit = payload.get("new_limit")
    now = datetime.now(timezone.utc)

    conn = db()
    c = conn.cursor()
    try:
        c.execute("CREATE TABLE IF NOT EXISTS kv_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)")
        c.execute("DELETE FROM kv_settings WHERE key = ?", ("enrollment_waiver_reset_at",))
        c.execute("INSERT INTO kv_settings (key, value) VALUES (?, ?)", ("enrollment_waiver_reset_at", now.isoformat()))
        if new_limit:
            c.execute("DELETE FROM kv_settings WHERE key = ?", ("enrollment_waiver_limit",))
            c.execute("INSERT INTO kv_settings (key, value) VALUES (?, ?)", ("enrollment_waiver_limit", str(int(new_limit))))
        conn.commit()
        # events に記録
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            ("enrollment_waiver_reset", json.dumps({"reset_at": now.isoformat(), "new_limit": new_limit}, ensure_ascii=False), "admin"),
        )
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        raise HTTPException(status_code=500, detail=f"リセット失敗: {e}")
    finally:
        conn.close()

    return {
        "ok": True,
        "reset_at": now.isoformat(),
        "new_limit": new_limit or ENROLLMENT_WAIVER_LIMIT,
        "message": f"✅ 入塾金免除キャンペーンを {now.strftime('%Y-%m-%d %H:%M')} にリセット。以降の paid 生徒で枠を再カウント開始。",
    }


@app.post("/api/admin/exam-questions/purge")
def admin_exam_questions_purge(payload: dict, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """🗑️ 蓄積問題プールの選択削除 (品質悪い問題を一括削除→次 tick で再蓄積)。
    payload: {
      "exam_id": "daigaku" (optional),
      "part_key": "r_long" (optional),
      "eiken_grade": "todai" (optional),
      "model": "test-probe" (optional・特定 model のみ削除),
      "older_than_days": 30 (optional, 指定日数より古いものだけ削除)
    }
    引数なしの場合は安全のため 422 (誤爆防止)。

    認証:
    - admin Bearer (従来): どの filter でも実行可
    - x-cron-secret: 安全のため **model filter が指定されている時のみ許可** (test probe / 旧 model の cleanup 用途)。
      理由: model は内部識別子なので CRON_SECRET 経由でも bulk wipe 事故が起きにくい。"""
    authed_admin = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed_admin = True
    # 🎯 2026-05-13 塾長指示「test probe row 削除」: model filter 指定時のみ CRON_SECRET 許可
    authed_cron_model = False
    if (not authed_admin) and payload.get("model") and CRON_SECRET and x_cron_secret \
            and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed_cron_model = True
    if not (authed_admin or authed_cron_model):
        raise HTTPException(status_code=401, detail="未認証")
    if not isinstance(payload, dict) or not payload:
        raise HTTPException(status_code=422, detail="filter parameter が必須 (exam_id/part_key/eiken_grade/model/older_than_days のいずれか)")

    where = []
    params = []
    if payload.get("exam_id"):
        where.append("exam_id = ?")
        params.append(payload["exam_id"])
    if payload.get("part_key"):
        where.append("part_key = ?")
        params.append(payload["part_key"])
    if payload.get("eiken_grade"):
        where.append("eiken_grade = ?")
        params.append(payload["eiken_grade"])
    if payload.get("model"):
        where.append("model = ?")
        params.append(payload["model"])
    older_than = payload.get("older_than_days")
    if older_than:
        cutoff = datetime.now(timezone.utc) - timedelta(days=int(older_than))
        where.append("created_at < ?")
        params.append(cutoff.isoformat())
    if not where:
        raise HTTPException(status_code=422, detail="少なくとも 1 つの filter が必要")
    # 🛡 cron-secret 経由は model filter 必須 (admin Bearer はこの制約なし)
    if authed_cron_model and not payload.get("model"):
        raise HTTPException(status_code=403, detail="cron-secret 経由の purge は model filter 必須")

    where_sql = " WHERE " + " AND ".join(where)
    conn = db()
    c = conn.cursor()
    deleted = 0
    try:
        # まず削除対象数をカウント (返却用)
        c.execute(f"SELECT COUNT(*) FROM exam_questions{where_sql}", tuple(params))
        row = c.fetchone()
        deleted = int(row[0] if row else 0)
        # DELETE
        c.execute(f"DELETE FROM exam_questions{where_sql}", tuple(params))
        conn.commit()
        # events に記録
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            ("exam_questions_purge", json.dumps({"filter": payload, "deleted": deleted}, ensure_ascii=False), "admin"),
        )
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        raise HTTPException(status_code=500, detail=f"削除失敗: {e}")
    finally:
        conn.close()

    return {
        "ok": True,
        "deleted": deleted,
        "filter": payload,
        "message": f"✅ {deleted} 問を削除。次の tick (interval scheduler) で薄い part から自動再蓄積されます。",
    }


@app.post("/api/admin/exam-questions/delete-by-id")
def admin_exam_questions_delete_by_id(
    payload: dict,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🎯 単一 id 指定で exam_questions 1 record を狙い撃ち削除。
    payload: {"id": 16767}
    認証: admin Bearer または x-cron-secret (単一 id 限定なので CRON_SECRET 経由でも安全)。
    用途: 旧 batch の致命データ corruption (stem 空 / answer=None 等) を 1 record 単位で削除。
    purge endpoint は filter で複数 record 一括削除する設計のため、単一狙い撃ちには適さない。
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if (not authed) and CRON_SECRET and x_cron_secret \
            and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    qid_raw = payload.get("id") if isinstance(payload, dict) else None
    try:
        qid = int(qid_raw)
    except Exception:
        raise HTTPException(status_code=422, detail="id (positive int) が必須")
    if qid <= 0:
        raise HTTPException(status_code=422, detail="id は positive int が必須")

    conn = db()
    c = conn.cursor()
    info = None
    try:
        c.execute(
            "SELECT id, exam_id, part_key, eiken_grade FROM exam_questions WHERE id = ?",
            (qid,),
        )
        row = c.fetchone()
        if not row:
            return {"ok": True, "deleted": 0, "id": qid, "message": f"id={qid} は既に存在しません (no-op)"}
        # row → dict 抽出 (sqlite Row / psycopg dict_row 両対応)
        if hasattr(row, "keys") and "id" in row.keys():
            info = {
                "id": row["id"],
                "exam_id": row["exam_id"],
                "part_key": row["part_key"],
                "eiken_grade": row["eiken_grade"],
            }
        else:
            info = {"id": row[0], "exam_id": row[1], "part_key": row[2], "eiken_grade": row[3]}
        c.execute("DELETE FROM exam_questions WHERE id = ?", (qid,))
        conn.commit()
        # events 監査ログ
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("exam_questions_delete_by_id", json.dumps(info, ensure_ascii=False), "admin"),
            )
            conn.commit()
        except Exception as e:
            log.warning(f"[ExamQ:DeleteById] events 記録失敗 (削除は成功): {e}")
    except HTTPException:
        raise
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        raise HTTPException(status_code=500, detail=f"削除失敗: {e}")
    finally:
        conn.close()

    return {"ok": True, "deleted": 1, "removed": info}


@app.post("/api/admin/exam-questions/burst-seed")
async def admin_exam_questions_burst_seed(payload: dict = None, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """🚀 ROTATION 枠を目標 N 問まで一括生成 (初期投入・特定科目の即時増量用)。

    payload (任意):
      {"target_per_part": 30, "max_total": 3000, "concurrency": 5,
       "parts": [["rikei","phys_kyotsu","kyotsu_rikei"], ["rikei","chem_kyotsu","kyotsu_rikei"]]}
    省略時のデフォルト: target=30, max_total=3000, concurrency=5

    動作:
    - EXAM_QUESTION_ROTATION 全枠 (parts 指定時はその区分のみ) を読み、現在 count < 実効目標 の枠を抽出
    - 実効目標 = max(target_per_part, 区分別 OVERRIDE)。物理/化学(共テ)は OVERRIDE=60 まで充填
    - 不足分の合計 (cap max_total) を asyncio で並列生成
    - DAILY_MAX 制約はバイパス (CEO 判断・1回限りの一括投入)
    - 完了時に詳細サマリ返却

    🔬 例 (物理・化学の共テ問題だけ今すぐ60問まで増やす):
      curl -X POST .../api/admin/exam-questions/burst-seed -H 'X-Cron-Secret: $CRON_SECRET' \
        -d '{"parts":[["rikei","phys_kyotsu","kyotsu_rikei"],["rikei","chem_kyotsu","kyotsu_rikei"],["rikei","phys_basic","kyotsu_rikei"],["rikei","chem_basic","kyotsu_rikei"]]}'

    レスポンス:
    {ok, target_per_part, scanned_parts, parts_under_target, generated, failed, duration_sec, details: [...]}
    """
    # 認証 (admin Bearer or x-cron-secret)
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")
    if not ANTHROPIC_API_KEY:
        raise HTTPException(status_code=503, detail="ANTHROPIC_API_KEY 未設定")

    payload = payload or {}
    target = int(payload.get("target_per_part", 30))    # CEO 課金許可済 → デフォを TARGET_POOL=30 に
    max_total = int(payload.get("max_total", 3000))     # 全枠 30問満杯まで届く上限
    concurrency = max(1, min(int(payload.get("concurrency", 5)), 8))  # 1-8 並列 (5 デフォ・速度優先)
    # 🔬 任意 parts フィルタ: [[exam,part,grade], ...] 指定時はその区分のみ生成 (例: 物理/化学だけ即時投入)。
    parts_filter = payload.get("parts")
    parts_set = None
    if isinstance(parts_filter, list) and parts_filter:
        parts_set = set()
        for it in parts_filter:
            if isinstance(it, (list, tuple)) and len(it) == 3:
                parts_set.add((it[0], it[1], it[2]))

    # 各区分の実効目標 = max(payload target, 区分別 OVERRIDE)。物理/化学(共テ)は OVERRIDE=60 まで充填する。
    def _eff_target(e, p, g):
        return max(target, _target_pool_for(e, p, g))

    counts = _exam_pool_counts()
    # 不足枠を抽出 (count < 実効目標)
    # 🛡 EXAM_QUESTION_AUTO_GENERATE_SKIP に含まれる枠は AI 課金回避のため burst-seed 経由生成しない
    needs = []
    for (exam_id, part_key, grade), n in counts.items():
        if (exam_id, part_key, grade) in EXAM_QUESTION_AUTO_GENERATE_SKIP:
            continue
        if parts_set is not None and (exam_id, part_key, grade) not in parts_set:
            continue
        deficit = max(0, _eff_target(exam_id, part_key, grade) - n)
        if deficit > 0:
            for _ in range(deficit):
                needs.append((exam_id, part_key, grade))
    parts_under_target = sum(
        1 for (e, p, g), n in counts.items()
        if (e, p, g) not in EXAM_QUESTION_AUTO_GENERATE_SKIP
        and (parts_set is None or (e, p, g) in parts_set)
        and n < _eff_target(e, p, g)
    )
    # max_total キャップ
    if len(needs) > max_total:
        needs = needs[:max_total]

    if not needs:
        return {
            "ok": True,
            "target_per_part": target,
            "scanned_parts": len(counts),
            "parts_under_target": 0,
            "generated": 0,
            "failed": 0,
            "duration_sec": 0,
            "message": f"全 {len(counts)} 枠が target={target} に到達済み。生成不要。",
        }

    started = datetime.now(timezone.utc)
    log.info(f"[BurstSeed] starting: target={target}, max_total={max_total}, concurrency={concurrency}, queue={len(needs)}")

    # 並列実行用 semaphore
    sem = asyncio.Semaphore(concurrency)
    generated = []
    failed = []
    lock = asyncio.Lock()

    async def gen_one(exam_id, part_key, grade):
        async with sem:
            loop = asyncio.get_event_loop()
            q = await loop.run_in_executor(None, _generate_exam_question, exam_id, part_key, grade)
            if q:
                await loop.run_in_executor(None, _save_exam_question, exam_id, part_key, q, grade)
                async with lock:
                    generated.append({"exam": exam_id, "part": part_key, "grade": grade})
            else:
                async with lock:
                    failed.append({"exam": exam_id, "part": part_key, "grade": grade})

    try:
        # 全タスクを並列で起動 (concurrency=3 で sem 制御)
        await asyncio.wait_for(
            asyncio.gather(*[gen_one(*n) for n in needs], return_exceptions=True),
            timeout=3600,  # 1時間タイムアウト (大量蓄積モード対応・generated 数は途中まででも保存される)
        )
    except asyncio.TimeoutError:
        log.warning("[BurstSeed] timeout reached at 10min")

    duration = (datetime.now(timezone.utc) - started).total_seconds()

    # events ログ
    try:
        conn = db()
        c = conn.cursor()
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            ("exam_questions_burst_seed", json.dumps({
                "target": target, "max_total": max_total, "concurrency": concurrency,
                "queued": len(needs), "generated": len(generated), "failed": len(failed),
                "duration_sec": int(duration),
            }, ensure_ascii=False), "admin"),
        )
        conn.commit()
        conn.close()
    except Exception as e:
        log.warning(f"[BurstSeed] event log failed: {e}")

    log.info(f"[BurstSeed] done: generated={len(generated)} failed={len(failed)} duration={int(duration)}s")
    # 概算コスト (Sonnet 4.6 $3/$15 per 1M tokens, ~3500 tokens output avg per question = $0.053)
    est_cost_usd = round(len(generated) * 0.06, 2)
    return {
        "ok": True,
        "target_per_part": target,
        "scanned_parts": len(counts),
        "parts_under_target": parts_under_target,
        "queued": len(needs),
        "generated": len(generated),
        "failed": len(failed),
        "duration_sec": int(duration),
        "estimated_cost_usd": est_cost_usd,
        "message": f"✅ {len(generated)} 問生成 (失敗 {len(failed)}・所要 {int(duration)}秒・推定 ${est_cost_usd}≈¥{int(est_cost_usd * 150)})",
    }


def _mirror_questions_to_supabase(mirror_url: str, ok_questions: list, valid_rotation: set) -> dict:
    """Supabase staging に exam_questions を mirror INSERT (staging-first flow 用)。
    env SUPABASE_MIRROR_URL 設定時のみ呼ばれる。失敗時は警告のみ・本番 import を止めない。
    memory: feedback_supabase_staging.md (Phase 1・C 採用) の自動 mirror 化。
    psycopg3 仕様: `?` ではなく `%s` placeholder・dict は Jsonb wrap 必須。"""
    if not mirror_url:
        return {"ok": False, "reason": "SUPABASE_MIRROR_URL not set"}
    # 🛡️ 防御: mirror_url に Railway 本番 host 含有なら refuse (3 視点 review data Agent 推奨)
    # mirror_url を誤って Railway URL に設定した場合に本番 DB を mirror 上書き / TRUNCATE する事故防止
    _railway_markers = ['railway.app', 'rlwy.net', 'railway.internal', 'proxy.rlwy.net']
    if any(m in mirror_url for m in _railway_markers):
        return {"ok": False, "reason": f"mirror_url contains Railway production marker; refusing to mirror to prevent accidental TRUNCATE/overwrite of Railway production DB"}
    # Supabase 想定 host のみ allow (誤設定検知)
    if 'supabase.com' not in mirror_url and 'supabase.co' not in mirror_url:
        log.warning(f"[ExamQ:Mirror] mirror_url does not contain 'supabase.com'/'supabase.co' — proceeding but verify it's the intended staging DB")
    try:
        import psycopg as _psycopg
        from psycopg.types.json import Jsonb as _Jsonb
    except ImportError:
        return {"ok": False, "reason": "psycopg not installed"}
    mirror_inserted = 0
    mirror_failed = 0
    try:
        # ✅ 2026-06-20 [exam-import-batch-commit] txn-abort cascade に対する安全性の根拠:
        #   この接続は autocommit=True。psycopg3 の autocommit では各 execute が独立した
        #   暗黙トランザクションとして即時 commit され、囲うトランザクションが存在しない。
        #   よって 1 行 INSERT が失敗しても「current transaction is aborted」状態は発生せず、
        #   後続行は無影響 → except で rollback 不要 (mirror_failed カウントのみで安全)。
        #   ⚠️ もし将来この connect から autocommit=True を外すなら、本番 import 側
        #   (_exam_questions_import_core) と同じ per-row SAVEPOINT 隔離を必ず入れること。
        with _psycopg.connect(mirror_url, connect_timeout=10, autocommit=True) as conn:
            for q in ok_questions:
                exam_id = q.get("exam_id")
                part_key = q.get("part_key")
                eiken_grade = q.get("eiken_grade")
                question_data = q.get("question_data")
                model = q.get("model") or "claude-max-plan"
                if not exam_id or not part_key or not question_data:
                    continue
                if (exam_id, part_key, eiken_grade) not in valid_rotation:
                    continue
                try:
                    with conn.cursor() as cur:
                        cur.execute(
                            "INSERT INTO exam_questions (exam_id, part_key, eiken_grade, question_data, model) VALUES (%s, %s, %s, %s, %s)",
                            (
                                exam_id, part_key, eiken_grade,
                                _Jsonb(question_data) if isinstance(question_data, (dict, list)) else question_data,
                                model,
                            ),
                        )
                    mirror_inserted += 1
                except Exception:
                    mirror_failed += 1
        return {"ok": True, "mirrored": mirror_inserted, "mirror_failed": mirror_failed}
    except Exception as e:
        return {"ok": False, "reason": str(e)[:200]}


def _exam_questions_import_core(questions: list, skip_full: bool = False) -> dict:
    """exam_questions 一括インサートのコアロジック (admin endpoint と AI チームワークフロー両方から再利用)。

    入力 validation は呼び出し側で行うこと (questions が list で空ではないことを保証)。
    重複 import の防御は呼び出し側責任 (memory: feedback_seed_import_no_loop.md)。

    Supabase mirror (Phase 1・staging-first flow): env SUPABASE_MIRROR_URL が設定されていれば、
    Railway 本番 INSERT 後に同 questions を Supabase にも自動 mirror INSERT する。失敗時は警告のみ・
    本番 import を止めない。memory: feedback_supabase_staging.md
    """
    counts = _exam_pool_counts() if skip_full else {}
    valid_rotation = {(e, p, g) for (e, p, g) in EXAM_QUESTION_ROTATION}

    inserted = 0
    skipped = 0
    failed = []
    conn = db()
    c = conn.cursor()

    # 🔧 2026-06-20 [exam-import-dedup] 重複取込ガード: 同一 (exam_id,part_key,eiken_grade) かつ
    #   question_data が完全一致の行は skip する。過去の手動 re-import で約2000件の重複が蓄積した
    #   ため (dedup-20260620 でクリーンアップ済)。既存 pool の content hash を batch が触る (exam_id,
    #   part_key) ぶんだけ前ロードし、batch 内の重複も seen_hashes で弾く。md5 は SQLite に無いので
    #   Python 側で計算 (両 backend 共通・既存行の question_data 文字列を hash して一致判定)。
    def _content_hash(qd):
        s = qd if isinstance(qd, str) else json.dumps(qd, ensure_ascii=False)
        return hashlib.md5(s.encode("utf-8")).hexdigest()
    existing_hashes = set()
    _pairs = sorted({(q.get("exam_id"), q.get("part_key")) for q in questions
                     if q.get("exam_id") and q.get("part_key")})
    if _pairs:
        _cond = " OR ".join(["(exam_id=? AND part_key=?)"] * len(_pairs))
        _params = tuple(v for pr in _pairs for v in pr)
        try:
            c.execute("SELECT exam_id, part_key, COALESCE(eiken_grade,''), question_data "
                      f"FROM exam_questions WHERE {_cond}", _params)
            for _r in c.fetchall():
                existing_hashes.add((_r[0], _r[1], (_r[2] or ""), _content_hash(_r[3])))
        except Exception as _e:
            log.warning(f"[ExamQ:Import] dedup preload skipped (guard off): {type(_e).__name__}: {_e}")
            existing_hashes = set()
        else:
            log.info(f"[ExamQ:Import] dedup preload: {len(_pairs)} pools, {len(existing_hashes)} existing hashes")
    seen_hashes = set()
    skipped_dup = 0
    inserted_idx = set()  # 実際に primary へ INSERT した行 index (mirror を挿入済のみに限定)

    # 🔧 2026-06-20 [exam-import-batch-commit] N 行ごと commit + 行ごと SAVEPOINT 隔離。
    #   ad8b296 の per-row commit は正しいが Railway PG では 1 行 1 fsync で大量 re-seed が
    #   timeout に近づく。SAVEPOINT で各行を隔離すれば 1 行失敗は ROLLBACK TO SAVEPOINT で
    #   その行だけ捨てられ、同一 batch 内の既存成功行も Postgres の txn-abort cascade も巻き
    #   込まない (= per-row commit と同じ floor を維持したまま fsync 回数を 1/N に削減)。
    #   ⚠️ SQLite footgun: 既定 isolation_level="" は DML 前に暗黙 BEGIN を打ち、手動
    #   SAVEPOINT/COMMIT と競合する。この接続だけ manual mode (isolation_level=None) に切替え、
    #   BEGIN/SAVEPOINT/COMMIT を明示制御することで PG と同一コードパスを通す
    #   (→ 下のローカル SQLite 機能テストが本番 PG と同じ savepoint ロジックを検証できる)。
    if not USE_POSTGRES:
        try:
            conn._conn.isolation_level = None  # Python sqlite3 を手動トランザクションモードへ
        except Exception:
            pass

    def _begin_txn():
        # SQLite manual mode では SAVEPOINT を「ネスト」させる (= RELEASE で即 commit させない)
        # ために明示 BEGIN が要る。Postgres(psycopg3 非autocommit) は最初の execute で txn を
        # 自動 BEGIN するため何もしない (明示 BEGIN は psycopg3 では不要/警告対象)。
        if not USE_POSTGRES:
            c.execute("BEGIN")

    # ⚠️ DALL-E 同期生成 (数秒/枚) がループ内にある時に batch commit すると、未 commit の
    #   先行行が DALL-E HTTP 呼び出しの間ずっと「idle in transaction」になり、Railway PG の
    #   idle_in_transaction_session_timeout に当たって batch ごと失われ得る。DALL-E 有効時は
    #   per-row commit (batch_n=1) に落とし、遅い呼び出しを跨いで txn を開いたままにしない
    #   (DALL-E 無効=既定の大量 re-seed 経路でのみ batch commit の fsync 削減を効かせる)。
    batch_n = 1 if EXAM_IMPORT_AUTO_DALLE else EXAM_IMPORT_COMMIT_BATCH
    since_commit = 0  # 直近 commit 以降の未 commit 成功行数
    batch_keys = []   # 直近 commit 以降に skip_full で counts++ したキー (batch破棄時に巻き戻す)

    def _discard_open_batch():
        # 未 commit の現 batch (since_commit 件) を捨てた時、inserted と skip_full の counts を
        # 実DB状態 (batch分は未耐久) に整合させ、txn を開き直す。Postgres の abort 状態も解除。
        nonlocal since_commit, inserted, batch_keys
        try: conn.rollback()
        except Exception: pass
        inserted -= since_commit
        if skip_full:
            for k in batch_keys:
                counts[k] = max(0, counts.get(k, 0) - 1)
        since_commit = 0
        batch_keys = []
        try: _begin_txn()
        except Exception: pass

    def _commit_batch():
        # 現 batch を耐久化。commit 自体が失敗したら batch を破棄して整合 (例外は伝播させない)。
        nonlocal since_commit, batch_keys
        try:
            conn.commit()
        except Exception as ce:
            log.warning(f"[ExamQ:Import] batch commit 失敗→当該batch破棄: {type(ce).__name__}: {ce}")
            _discard_open_batch()
            return
        since_commit = 0
        batch_keys = []
        try: _begin_txn()
        except Exception: pass

    try:
        _begin_txn()
        for i, q in enumerate(questions):
            sp_open = False  # この行で SAVEPOINT を張ったか (except での復旧分岐に使う)
            try:
                exam_id = q.get("exam_id")
                part_key = q.get("part_key")
                eiken_grade = q.get("eiken_grade")
                question_data = q.get("question_data")
                model = q.get("model") or "claude-max-plan"

                if not exam_id or not part_key or not question_data:
                    failed.append({"i": i, "reason": "missing required fields"})
                    continue
                if (exam_id, part_key, eiken_grade) not in valid_rotation:
                    failed.append({"i": i, "reason": f"invalid rotation: {exam_id}/{part_key}/{eiken_grade}"})
                    continue
                if skip_full and counts.get((exam_id, part_key, eiken_grade), 0) >= _target_pool_for(exam_id, part_key, eiken_grade):
                    skipped += 1
                    continue

                # 🔧 2026-06-20 [exam-import-dedup] 既存 pool or 同一 batch 内と content 完全一致なら skip
                #   (DALL-E mutation 前の生 question_data で hash → 同一ソースの re-import を弾く)。
                #   ★hash 計算は SAVEPOINT より前。非JSON 等で例外を投げると batch ごと巻き戻るため、
                #   hash 不能なら dedup を諦めて通常 INSERT 経路へ流す (= その行は SAVEPOINT 内で失敗し
                #   単独 ROLLBACK・他の成功行を巻き込まない)。
                try:
                    _hkey = (exam_id, part_key, (eiken_grade or ""), _content_hash(question_data))
                except Exception:
                    _hkey = None
                if _hkey is not None and (_hkey in existing_hashes or _hkey in seen_hashes):
                    skipped_dup += 1
                    continue

                # 🎨 2026-05-23 塾長指示「DALL-E 図解付き問題プール生成」:
                # 致命 1 fix: 同期 DALL-E call は Railway timeout (60-300s) 超過リスクのため env gate (default OFF)
                # default OFF: figure_description のみ DB 保存 → 別 endpoint /api/admin/exam-questions/generate-pending-figures で後追い生成
                # ON 時: 1 batch max 10 figure まで (それ超は figure_description のみ保存・後追い処理)
                if EXAM_IMPORT_AUTO_DALLE and isinstance(question_data, dict):
                    fig_desc = question_data.get("figure_description")
                    if fig_desc and not question_data.get("figure_b64") and inserted < EXAM_IMPORT_DALLE_MAX_PER_BATCH:
                        try:
                            subj_hint = question_data.get("subject_hint") or question_data.get("subject") or ""
                            topic_hint = question_data.get("topic_hint") or question_data.get("topic") or question_data.get("passage_title") or ""
                            fig = _generate_figure_b64_safe(fig_desc, subj_hint, topic_hint)
                            if fig:
                                question_data["figure_b64"] = fig["figure_b64"]
                                question_data["figure_revised_prompt"] = fig["figure_revised_prompt"]
                                question_data["figure_source"] = fig["figure_source"]
                                log.info(f"[ExamQ:Import] DALL-E figure embedded for {exam_id}/{part_key} (b64 len={len(fig['figure_b64'])})")
                        except Exception as fe:
                            log.warning(f"[ExamQ:Import] DALL-E figure generation skipped: {type(fe).__name__}: {fe}")
                            # 致命にしない (figure なしでも問題は使える)

                # 🔧 2026-06-20 [exam-import-batch-commit] 1 行を SAVEPOINT で隔離して INSERT。
                #   失敗時は ROLLBACK TO SAVEPOINT でその行だけ捨て、同一 batch 内の既存成功行も
                #   Postgres の txn-abort cascade も巻き込まない。commit は N 行ごと (下) なので
                #   fsync 回数は 1/N に減るが、「失敗行が成功行を巻き込まない」floor は不変。
                c.execute("SAVEPOINT exam_import_sp")
                sp_open = True
                c.execute(
                    "INSERT INTO exam_questions (exam_id, part_key, eiken_grade, question_data, model) VALUES (?, ?, ?, ?, ?)",
                    (exam_id, part_key, eiken_grade,
                     json.dumps(question_data, ensure_ascii=False) if not isinstance(question_data, str) else question_data,
                     model),
                )
                c.execute("RELEASE SAVEPOINT exam_import_sp")
                sp_open = False
                inserted += 1
                since_commit += 1
                if _hkey is not None:
                    seen_hashes.add(_hkey)  # 以降の同一 content 行 (batch 内重複) を弾く
                inserted_idx.add(i)         # mirror 対象 = 実際に挿入した行のみ
                if skip_full:
                    _k = (exam_id, part_key, eiken_grade)
                    counts[_k] = counts.get(_k, 0) + 1
                    batch_keys.append(_k)
                # N 行たまったら commit (= 1 回の fsync で N 行を耐久化)。_commit_batch は commit
                # 失敗時も当該 batch を破棄して inserted/counts を整合し、txn を開き直す。
                if since_commit >= batch_n:
                    _commit_batch()
            except Exception as e:
                failed.append({"i": i, "reason": f"{type(e).__name__}: {e}"})
                recovered = False
                if sp_open:
                    # 通常: 失敗行だけ ROLLBACK TO SAVEPOINT で捨て、batch の既存成功行は残す。
                    # 直近 commit 以降の成功行 (since_commit 件) は savepoint より外なので残る。
                    # (Postgres の abort 状態もこれで解除され、後続行を処理続行できる)。
                    try:
                        c.execute("ROLLBACK TO SAVEPOINT exam_import_sp")
                        c.execute("RELEASE SAVEPOINT exam_import_sp")
                        recovered = True
                    except Exception:
                        recovered = False
                if not recovered:
                    # SAVEPOINT 自体が失敗 or savepoint 復旧不能 = txn が壊れている可能性。
                    # 現 batch を丸ごと破棄して inserted/counts を整合し、txn を開き直す。
                    _discard_open_batch()
        _commit_batch()  # 端数 (batch_n 未満) の成功行を耐久化 (commit 失敗時も整合)
    finally:
        conn.close()

    log.info(f"[ExamQ:Import] inserted={inserted} skipped={skipped} failed={len(failed)}")

    # 🪞 Supabase staging mirror (Phase 1・自動 mirror 化)
    mirror_result = None
    mirror_url = os.getenv("SUPABASE_MIRROR_URL", "").strip()
    if mirror_url and inserted > 0:
        # 🔧 2026-06-20 [exam-import-dedup] mirror は「実際に primary へ INSERT した行」のみ対象に。
        #   旧実装 (failed 以外=全部) は dup-skip / skip_full の未挿入行まで Supabase へ mirror し、
        #   primary に無い行を staging に増やしていた (mirror 結果が inserted と不一致)。
        ok_questions = [q for i, q in enumerate(questions) if i in inserted_idx]
        try:
            mirror_result = _mirror_questions_to_supabase(mirror_url, ok_questions, valid_rotation)
            log.info(f"[ExamQ:Mirror→Supabase] {mirror_result}")
        except Exception as e:
            mirror_result = {"ok": False, "reason": str(e)[:200]}
            log.warning(f"[ExamQ:Mirror→Supabase] non-fatal exception: {e}")

    return {
        "ok": True,
        "received": len(questions),
        "inserted": inserted,
        "skipped_full": skipped,
        "skipped_dup": skipped_dup,  # 既存/batch内と完全一致で弾いた重複数 (取込ガード)
        "failed": len(failed),
        "failed_details": failed[:20],
        "mirror": mirror_result,  # Supabase mirror result (None if SUPABASE_MIRROR_URL not set)
        "message": f"✅ {inserted}問 import (skip {skipped}・重複skip {skipped_dup}・失敗 {len(failed)})",
    }


@app.post("/api/admin/exam-questions/import")
def admin_exam_questions_import(payload: dict, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """🆓 Claude Max プラン経由で生成した問題 JSON を一括インサート ($0 運用用)。

    payload:
      {
        "questions": [
          {"exam_id": "toefl", "part_key": "r_passage1", "eiken_grade": null,
           "question_data": {...}, "model": "claude-max-plan"}
        ],
        "skip_full": true  // 任意・true なら TARGET_POOL 到達 part を skip
      }

    認証: admin Bearer or x-cron-secret"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    questions = payload.get("questions") or []
    if not isinstance(questions, list) or not questions:
        raise HTTPException(status_code=400, detail="questions が空 or 配列ではありません")
    # 🔧 2026-06-20 [exam-import-batch-commit] timeout backstop: savepoint batching でも INSERT は
    #   行数に線形なので、病的に巨大な 1 リクエストは分割させる (既定 5000・env で調整可)。
    if len(questions) > EXAM_IMPORT_MAX_ROWS:
        raise HTTPException(
            status_code=413,
            detail=f"questions が多すぎます ({len(questions)}件 > 上限{EXAM_IMPORT_MAX_ROWS}件)。"
                   f"分割して送信してください (env EXAM_IMPORT_MAX_ROWS で上限変更可)",
        )

    skip_full = bool(payload.get("skip_full", False))
    return _exam_questions_import_core(questions, skip_full)


@app.post("/api/admin/exam-questions/replace-explanation")
def admin_exam_questions_replace_explanation(
    payload: dict,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🛡️ 塾長指示 2026-05-27「自習レベル解説への差し替え + archive 必須 + rollback 可能」:
    既存 exam_questions レコードの question_data を新しい高品質版に差し替える。

    payload:
      {
        "batch_id": "20260527_kyodai_phys_lv5",  // group identifier for rollback
        "reason": "Level 5 自習解説に差し替え",
        "replacements": [
          {"id": 12345, "new_question_data": {...}, "new_model": "claude-max-plan"},
          ...
        ]
      }

    動作:
    1. 各 id の元 question_data を exam_questions_archive に保存
    2. exam_questions.question_data を新版に UPDATE
    3. 差し替え件数 + archive id リストを返却 (rollback 時に使用)

    認証: admin Bearer or x-cron-secret"""
    import hmac as _hmac
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and _hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    replacements = payload.get("replacements") or []
    if not isinstance(replacements, list) or not replacements:
        raise HTTPException(status_code=400, detail="replacements が空")

    batch_id = str(payload.get("batch_id") or "").strip()[:128] or f"batch_{int(time.time())}"
    reason = str(payload.get("reason") or "")[:500]

    archived = 0
    updated = 0
    failed = []
    archive_ids = []

    conn = db()
    try:
        c = conn.cursor()
        # 🛡️ 同時実行の race 防止 (Postgres advisory lock)
        try:
            if USE_POSTGRES:
                c.execute("SELECT pg_advisory_xact_lock(8675310)")
        except Exception:
            pass

        for rep in replacements:
            qid = rep.get("id")
            new_qd = rep.get("new_question_data")
            if not qid or not isinstance(new_qd, (dict, str)):
                failed.append({"id": qid, "reason": "invalid input"})
                continue

            # 既存レコード取得
            c.execute("SELECT id, exam_id, part_key, eiken_grade, question_data, model, created_at FROM exam_questions WHERE id = ?", (qid,))
            row = c.fetchone()
            if not row:
                failed.append({"id": qid, "reason": "not found"})
                continue
            # row → dict (Postgres/SQLite 両対応)
            if isinstance(row, dict):
                r = row
            else:
                r = {"id": row[0], "exam_id": row[1], "part_key": row[2], "eiken_grade": row[3],
                     "question_data": row[4], "model": row[5], "created_at": row[6]}

            # archive に保存
            c.execute(
                "INSERT INTO exam_questions_archive "
                "(original_id, exam_id, part_key, eiken_grade, question_data, original_model, original_created_at, replacement_batch_id, replacement_reason) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (r["id"], r["exam_id"], r["part_key"], r["eiken_grade"], r["question_data"],
                 r["model"], r["created_at"], batch_id, reason)
            )
            # archive id 取得 (Postgres は RETURNING、SQLite は lastrowid)
            try:
                if USE_POSTGRES:
                    c.execute("SELECT currval(pg_get_serial_sequence('exam_questions_archive','id'))")
                    arch_id = c.fetchone()
                    arch_id = arch_id[0] if not isinstance(arch_id, dict) else arch_id.get("currval")
                else:
                    arch_id = c.lastrowid
            except Exception:
                arch_id = None
            if arch_id:
                archive_ids.append(arch_id)
            archived += 1

            # exam_questions を UPDATE
            new_qd_json = new_qd if isinstance(new_qd, str) else json.dumps(new_qd, ensure_ascii=False)
            new_model = rep.get("new_model") or r.get("model") or "claude-max-plan"
            c.execute(
                "UPDATE exam_questions SET question_data = ?, model = ? WHERE id = ?",
                (new_qd_json, new_model, qid)
            )
            updated += 1

        conn.commit()
    finally:
        conn.close()

    return {
        "ok": True,
        "batch_id": batch_id,
        "archived": archived,
        "updated": updated,
        "failed_count": len(failed),
        "failed": failed,
        "archive_ids": archive_ids,
    }


@app.post("/api/admin/exam-questions/rollback-batch")
def admin_exam_questions_rollback_batch(
    payload: dict,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🛡️ 塾長指示 2026-05-27: 差し替えた batch を 1-click rollback する。

    payload: {"batch_id": "20260527_kyodai_phys_lv5"}

    動作:
    1. archive から該当 batch_id のレコードを SELECT
    2. それぞれ exam_questions の question_data を archive の値に戻す
    3. archive レコードに rollback_at を記録 (履歴は残す)
    """
    import hmac as _hmac
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and _hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    batch_id = str(payload.get("batch_id") or "").strip()
    if not batch_id:
        raise HTTPException(status_code=400, detail="batch_id 必須")

    restored = 0
    conn = db()
    try:
        c = conn.cursor()
        try:
            if USE_POSTGRES:
                c.execute("SELECT pg_advisory_xact_lock(8675311)")
        except Exception:
            pass
        # 未 rollback の archive を取得
        c.execute(
            "SELECT id, original_id, question_data, original_model FROM exam_questions_archive "
            "WHERE replacement_batch_id = ? AND rollback_at IS NULL",
            (batch_id,)
        )
        rows = c.fetchall()
        for row in rows:
            if isinstance(row, dict):
                arch_id = row.get("id")
                orig_id = row.get("original_id")
                orig_qd = row.get("question_data")
                orig_model = row.get("original_model")
            else:
                arch_id, orig_id, orig_qd, orig_model = row[0], row[1], row[2], row[3]
            c.execute(
                "UPDATE exam_questions SET question_data = ?, model = ? WHERE id = ?",
                (orig_qd, orig_model or "claude-max-plan", orig_id)
            )
            c.execute(
                "UPDATE exam_questions_archive SET rollback_at = CURRENT_TIMESTAMP WHERE id = ?",
                (arch_id,)
            )
            restored += 1
        conn.commit()
    finally:
        conn.close()

    return {"ok": True, "batch_id": batch_id, "restored": restored}


@app.get("/api/admin/exam-questions/replacement-batches")
def admin_exam_questions_replacement_batches(
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
    limit: int = 50,
):
    """🛡️ 塾長指示 2026-05-27: 差し替え batch 一覧 (ceo ダッシュ表示用)。
    rollback 可否 + 各 batch の件数を返す。"""
    import hmac as _hmac
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and _hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    limit = max(1, min(int(limit or 50), 200))
    conn = db()
    try:
        c = conn.cursor()
        c.execute(
            "SELECT replacement_batch_id, "
            "COUNT(*) AS total_count, "
            "SUM(CASE WHEN rollback_at IS NULL THEN 1 ELSE 0 END) AS active_count, "
            "MAX(replaced_at) AS replaced_at, "
            "MAX(replacement_reason) AS reason "
            "FROM exam_questions_archive "
            "WHERE replacement_batch_id IS NOT NULL "
            "GROUP BY replacement_batch_id "
            "ORDER BY MAX(replaced_at) DESC "
            "LIMIT ?",
            (limit,)
        )
        rows = c.fetchall()
        batches = []
        for row in rows:
            if isinstance(row, dict):
                batches.append({
                    "batch_id": row.get("replacement_batch_id"),
                    "total": row.get("total_count"),
                    "active": row.get("active_count"),
                    "replaced_at": str(row.get("replaced_at") or ""),
                    "reason": row.get("reason") or "",
                    "can_rollback": (row.get("active_count") or 0) > 0,
                })
            else:
                batches.append({
                    "batch_id": row[0],
                    "total": row[1],
                    "active": row[2],
                    "replaced_at": str(row[3] or ""),
                    "reason": row[4] or "",
                    "can_rollback": (row[2] or 0) > 0,
                })
    finally:
        conn.close()
    return {"ok": True, "batches": batches}


@app.post("/api/admin/exam-questions/mirror-all-to-supabase")
def admin_mirror_all_to_supabase(
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
    truncate_first: bool = False,
):
    """🪞 Railway exam_questions 全件を Supabase staging に一括 mirror INSERT。
    Phase 1 staging-first flow 採用後の **初回補完** + **緊急切替先準備** 用。
    env SUPABASE_MIRROR_URL 必須・admin Bearer or x-cron-secret 認証。
    実行時間目安: 16,000+ records で 30-60 分・per-row INSERT で transaction abort 回避。

    query parameter:
      truncate_first=true で実行前に Supabase 側 exam_questions を TRUNCATE。
      再実行時の重複爆発防止 (3 視点 review 指摘で追加・2026-05-20)。
      ⚠️ destructive 操作なので明示的 OPT-IN のみ。

    memory: feedback_supabase_staging.md (Phase A 補完手段)"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")
    mirror_url = os.getenv("SUPABASE_MIRROR_URL", "").strip()
    if not mirror_url:
        raise HTTPException(status_code=503, detail="SUPABASE_MIRROR_URL env not set")
    # Railway 本番から SELECT *
    questions: list = []
    try:
        conn = db()
        try:
            cur = conn.execute(
                "SELECT exam_id, part_key, eiken_grade, question_data, model FROM exam_questions ORDER BY id"
            )
            for row in cur.fetchall():
                # row order: exam_id, part_key, eiken_grade, question_data, model
                qd = row[3]
                if isinstance(qd, str):
                    try:
                        qd = json.loads(qd)
                    except Exception:
                        pass  # raw string のままで mirror
                questions.append({
                    "exam_id": row[0],
                    "part_key": row[1],
                    "eiken_grade": row[2],
                    "question_data": qd,
                    "model": row[4] or "claude-max-plan",
                })
        finally:
            conn.close()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Railway SELECT failed: {str(e)[:200]}")
    if not questions:
        return {"ok": True, "total_railway": 0, "mirrored": 0, "message": "Railway 側に exam_questions が無い"}
    # 🛡️ 重複爆発防止 (truncate_first=true で OPT-IN)
    # ⚠️ CRITICAL: TRUNCATE は Railway 本番 URL に誤実行すると本番 16,000+ wipe 致命
    # → _mirror_questions_to_supabase と同じ Railway URL reject check を TRUNCATE 直前にも実行
    truncated = 0
    if truncate_first:
        # 🛡️ 同 helper と同じ防御ガード (3 視点 review data Agent 致命指摘 fix・2026-05-20)
        _railway_markers_truncate = ['railway.app', 'rlwy.net', 'railway.internal', 'proxy.rlwy.net']
        if any(m in mirror_url for m in _railway_markers_truncate):
            raise HTTPException(
                status_code=400,
                detail=f"SUPABASE_MIRROR_URL contains Railway production marker; refusing TRUNCATE to prevent accidental wipe of Railway production DB",
            )
        if 'supabase.com' not in mirror_url and 'supabase.co' not in mirror_url:
            raise HTTPException(
                status_code=400,
                detail=f"SUPABASE_MIRROR_URL does not contain 'supabase.com'/'supabase.co'; refusing destructive TRUNCATE on unknown host",
            )
        try:
            import psycopg as _psycopg
            with _psycopg.connect(mirror_url, connect_timeout=10, autocommit=True) as conn:
                with conn.cursor() as cur:
                    cur.execute("SELECT count(*) FROM exam_questions")
                    truncated = cur.fetchone()[0]
                    cur.execute("TRUNCATE exam_questions RESTART IDENTITY")
            log.info(f"[ExamQ:MirrorAll] TRUNCATE done (deleted {truncated} prior rows)")
        except HTTPException:
            raise
        except Exception as e:
            log.error(f"[ExamQ:MirrorAll] TRUNCATE failed: {e}")
            raise HTTPException(status_code=500, detail=f"truncate failed: {str(e)[:200]}")
    # Supabase に mirror
    valid_rotation = {(e, p, g) for (e, p, g) in EXAM_QUESTION_ROTATION}
    log.info(f"[ExamQ:MirrorAll] starting Supabase mirror of {len(questions)} questions (truncated_first={truncate_first})")
    result = _mirror_questions_to_supabase(mirror_url, questions, valid_rotation)
    return {
        "ok": result.get("ok", False),
        "total_railway": len(questions),
        "truncated_first": truncate_first,
        "truncated_rows": truncated,
        **result,
    }


