@app.post("/api/admin/login-as-student")
def admin_login_as_student(payload: dict, authorization: Optional[str] = Header(None)):
    """🔐 塾長が生徒として直接ログインする (magic link 不要の admin 迂回)。
    payload: {"id": 6} または {"email": "..."}
    成功時: 30日有効の session token + student info を返す。塾長は localStorage に
    保存して mypage / index にアクセスできる。
    監査ログ: 全 impersonation を log + events に記録。"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="セッション期限切れ")

    sid_arg = payload.get("id")
    email_arg = (payload.get("email") or "").strip().lower()
    conn = db()
    c = conn.cursor()
    try:
        if sid_arg:
            c.execute("SELECT id, name, email, grade, status, plan FROM students WHERE id=?", (int(sid_arg),))
        elif email_arg:
            c.execute("SELECT id, name, email, grade, status, plan FROM students WHERE LOWER(email)=? LIMIT 1", (email_arg,))
        else:
            raise HTTPException(status_code=400, detail="id or email required")
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="student not found")
        sid = int(row["id"])
        # 監査ログ
        log.warning(f"[AdminImpersonation] admin -> student id={sid} email={row['email']}")
        try:
            c.execute(
                "INSERT INTO events (name, props, created_at) VALUES (?, ?, ?)",
                ("admin_impersonation", json.dumps({"student_id": sid, "email": row["email"]}, ensure_ascii=False), datetime.now(timezone.utc)),
            )
            conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass

        # 🔐 なりすまし専用 token_type。session を要求する全 API では session 同様に通り
        #   (_verify_session_token)、かつ _get_current_student の在籍ステータスゲートを回避する
        #   (canceled/expired/trial切れの生徒でも塾長が入室確認できる)。発行は本 admin 経路のみ。
        session_token = _sign_session_token(sid, token_type="impersonation")
        import time as _t
        return {
            "ok": True,
            "token": session_token,
            "expires_at": int(_t.time()) + SESSION_TTL_SECONDS,
            "student": {
                "id": sid,
                "name": row["name"],
                "email": row["email"],
                "grade": row["grade"],  # 🧒 中学生モード判定用 (2026-06-04): 代行ログインでも中学生モードを正しく表示
                "status": row["status"],
                "plan": row["plan"],
            },
        }
    finally:
        conn.close()


@app.post("/api/admin/send-report")
def admin_send_report(payload: dict, authorization: Optional[str] = Header(None)):
    """管理者がモニタリングメールアドレスに任意レポートを送信。"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="セッション期限切れ")
    subject = payload.get("subject", "レポート")
    body_html = payload.get("body_html", "")
    if not body_html:
        raise HTTPException(status_code=400, detail="body_html required")
    result = _send_monitor_email(subject, body_html)
    return {"ok": result.get("sent", False), "error": result.get("error")}


@app.post("/api/admin/students/reactivate")
def admin_students_reactivate(payload: dict, authorization: Optional[str] = Header(None),
                              x_cron_secret: Optional[str] = Header(None)):
    """canceled / expired student を任意の status に再アクティベート。
    塾長自身のテスト用アカウント (status=canceled) を復活させて magic link を
    届くようにする用途 (2026-05-03 塾長指示)。
    payload: {"id": 6, "status": "paid", "plan": "founder_special"}
    認証 (2026-06-07 拡張): admin Bearer (塾長セッション) or X-Cron-Secret (Claude 運用)。
    cron-secret は trial 復活のみ許可。paid 付与 (課金実体の無い entitlement) は admin Bearer 必須。"""
    is_admin_bearer = bool(
        authorization and authorization.startswith("Bearer ")
        and _verify_admin_token(authorization[len("Bearer "):].strip())
    )
    is_cron = bool(CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET))
    if not (is_admin_bearer or is_cron):
        raise HTTPException(status_code=401, detail="未認証")

    sid = int(payload.get("id") or 0)
    new_status = (payload.get("status") or "paid").strip()
    new_plan = (payload.get("plan") or "").strip()  # 空 = 既存 plan を保持 (founder_special を勝手に付けない)
    if not sid:
        raise HTTPException(status_code=400, detail="id required")
    if new_status not in ("paid", "trial"):
        raise HTTPException(status_code=400, detail="status must be 'paid' or 'trial'")
    # 🛡 cron-secret では paid 付与不可 (entitlement 偽造防止)。admin Bearer のみ paid 可。
    if new_status == "paid" and not is_admin_bearer:
        raise HTTPException(status_code=403, detail="paid 復活は管理者ログインが必要です (cron-secret は trial のみ)")

    conn = db()
    c = conn.cursor()
    try:
        c.execute("SELECT id, email, status, plan FROM students WHERE id=?", (sid,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail=f"student id={sid} not found")
        before = {"status": row["status"], "plan": row["plan"]}
        # plan 変更は admin Bearer のみ。cron-secret は status 復活のみで plan は既存維持
        # (trial+founder_special で AI予算20倍などの entitlement 偽造を防止)。未指定は既存保持。
        eff_plan = (new_plan or row["plan"]) if is_admin_bearer else row["plan"]
        if new_status == "paid":
            c.execute(
                "UPDATE students SET status='paid', plan=?, paid_since=COALESCE(paid_since, ?), trial_end=NULL WHERE id=?",
                (eff_plan, datetime.now(timezone.utc), sid),
            )
        else:
            new_trial_end = datetime.now(timezone.utc) + timedelta(days=30)
            c.execute(
                "UPDATE students SET status='trial', plan=?, trial_end=? WHERE id=?",
                (eff_plan, new_trial_end, sid),
            )
        conn.commit()
        c.execute("SELECT id, name, email, status, plan, trial_end, paid_since FROM students WHERE id=?", (sid,))
        after_row = c.fetchone()
        actor = "admin" if is_admin_bearer else "cron"
        log.info(f"[admin/reactivate] id={sid} {before} -> status={new_status} plan={eff_plan} actor={actor}")
        # 🔍 監査 events (billing status 変更 → actor + before/after を残す)
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("student_reactivated", json.dumps({
                    "student_id": sid, "before": before,
                    "after_status": new_status, "plan": eff_plan, "actor": actor,
                }, ensure_ascii=False), actor),
            )
            conn.commit()
        except Exception:
            pass
        return {
            "ok": True,
            "id": sid,
            "before": before,
            "after": {
                "status": after_row["status"],
                "plan": after_row["plan"],
                "trial_end": str(after_row["trial_end"]) if after_row["trial_end"] else None,
                "paid_since": str(after_row["paid_since"]) if after_row["paid_since"] else None,
            },
        }
    finally:
        conn.close()


@app.post("/api/admin/students/purge-test")
def admin_students_purge_test(payload: dict, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """テスト用ダミー生徒レコードを削除する admin endpoint。
    payload:
      {"ids": [5, 6, 7]}                       # ID 指定削除
      {"name_contains": ["検証", "再確認"]}    # 名前部分一致で削除 (複数 OR)
      {"dry_run": true}                        # 削除せず該当件数だけ返す
    認証: admin Bearer or x-cron-secret"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    ids = payload.get("ids") or []
    name_contains = payload.get("name_contains") or []
    dry_run = bool(payload.get("dry_run", False))
    if not ids and not name_contains:
        raise HTTPException(status_code=400, detail="ids または name_contains のいずれか必須")

    conn = db()
    c = conn.cursor()
    matched = []
    try:
        # ID 指定
        if ids:
            placeholders = ",".join(["?"] * len(ids))
            c.execute(f"SELECT id, name, status FROM students WHERE id IN ({placeholders})", tuple(ids))
            for r in c.fetchall():
                matched.append({"id": r["id"], "name": r["name"], "status": r["status"], "via": "id"})
        # 名前部分一致 (複数 OR)
        if name_contains:
            for kw in name_contains:
                c.execute("SELECT id, name, status FROM students WHERE name LIKE ?", (f"%{kw}%",))
                for r in c.fetchall():
                    if not any(m["id"] == r["id"] for m in matched):
                        matched.append({"id": r["id"], "name": r["name"], "status": r["status"], "via": f"name~{kw}"})

        deleted = 0
        if not dry_run and matched:
            ids_to_delete = [m["id"] for m in matched]
            placeholders = ",".join(["?"] * len(ids_to_delete))
            # 外部キー違反防止: 関連テーブルを先に削除
            try:
                c.execute(f"DELETE FROM otp_codes WHERE student_id IN ({placeholders})", tuple(ids_to_delete))
            except Exception as e:
                log.warning(f"[Students:PurgeTest] otp_codes cleanup failed: {e}")
            try:
                c.execute(f"DELETE FROM payments WHERE student_id IN ({placeholders})", tuple(ids_to_delete))
            except Exception as e:
                log.warning(f"[Students:PurgeTest] payments cleanup failed: {e}")
            try:
                c.execute(f"DELETE FROM usage_monthly WHERE student_id IN ({placeholders})", tuple(ids_to_delete))
            except Exception as e:
                log.warning(f"[Students:PurgeTest] usage_monthly cleanup failed: {e}")
            # students 本体削除
            c.execute(f"DELETE FROM students WHERE id IN ({placeholders})", tuple(ids_to_delete))
            # _Cursor に rowcount 属性が無いため matched 数を deleted とみなす
            deleted = len(ids_to_delete)
            conn.commit()
    finally:
        conn.close()

    log.info(f"[Students:PurgeTest] dry_run={dry_run} matched={len(matched)} deleted={deleted}")
    return {
        "ok": True,
        "matched": len(matched),
        "deleted": deleted,
        "dry_run": dry_run,
        "items": matched[:50],
        "message": f"{'(dry run) ' if dry_run else ''}該当 {len(matched)} 件、削除 {deleted} 件",
    }


class StudentDeleteRequest(BaseModel):
    confirm_email: Optional[str] = None  # 安全装置: student.email と完全一致必須 (同名衝突防止)
    confirm_name: Optional[str] = None  # 後方互換 (email 未設定の生徒向け fallback)
    dry_run: Optional[bool] = False
    cancel_stripe: Optional[bool] = False  # Stripe 解約も同時実行する場合 true
    # 🛡️ 2026-05-13 追加: ai-juku DB 削除のみで Stripe 解約しない (外部システム継続用)
    # 例: 塾の月謝として juku-payment 側で課金継続中・ai-juku 側に誤登録された行のみ削除
    force_skip_stripe: Optional[bool] = False


@app.post("/api/admin/students/{student_id}/delete")
def admin_student_delete(student_id: int, payload: StudentDeleteRequest,
                          authorization: Optional[str] = Header(None),
                          x_cron_secret: Optional[str] = Header(None)):
    """顧客データ完全削除 (admin only)。生徒本体 + 全関連データを cascade delete。
    安全装置: payload.confirm_name が student.name と完全一致する場合のみ実行。
    Stripe 有効サブスクがある場合、payload.cancel_stripe=true でない限り 409 で拒否。
    events テーブルに削除前スナップショット audit log を残す。

    認証: admin Bearer または X-Cron-Secret (2026-05-13 追加・塾長離席中 Claude 経由緊急対応用)
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
        else:
            raise HTTPException(status_code=401, detail="未認証")
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    conn = db()
    c = conn.cursor()
    try:
        c.execute("SELECT id, name, email, status, plan, course, stripe_subscription_id, stripe_customer_id, created_at FROM students WHERE id=?", (student_id,))
        student = c.fetchone()
        if not student:
            raise HTTPException(status_code=404, detail="生徒が見つかりません")

        # 安全装置: email 完全一致必須 (同名衝突防止)。email 未設定の生徒のみ name fallback 可。
        if not payload.dry_run:
            student_email = (student["email"] or "").strip().lower()
            student_name = (student["name"] or "").strip()
            if student_email:
                provided_email = (payload.confirm_email or "").strip().lower()
                if not provided_email or provided_email != student_email:
                    raise HTTPException(status_code=400, detail="確認のためメールアドレスを正確に入力してください")
            else:
                # email 未設定 → name fallback
                provided_name = (payload.confirm_name or "").strip()
                if not provided_name or provided_name != student_name:
                    raise HTTPException(status_code=400, detail="確認のため生徒名を正確に入力してください (この生徒は email 未設定のため名前で確認)")

        # 🛡️ Stripe サブスク取扱い (2026-05-13 force_skip_stripe 追加):
        # - cancel_stripe=true       → ai-juku で Stripe 解約 + DB 削除 (通常の退会)
        # - force_skip_stripe=true   → DB のみ削除・Stripe は外部システム (juku-payment 等) で継続
        # - 上記いずれも未指定       → 409 (安全装置・誤削除防止)
        sub_id = student["stripe_subscription_id"]
        if sub_id and not payload.dry_run:
            if not payload.cancel_stripe and not payload.force_skip_stripe:
                raise HTTPException(
                    status_code=409,
                    detail="Stripe 有効サブスクがあります。Stripe 解約も同時実行する場合は cancel_stripe=true、外部システムで課金継続する場合は force_skip_stripe=true を付けて再送してください"
                )
            if payload.force_skip_stripe:
                log.warning(f"[StudentDelete] force_skip_stripe=true: ai-juku DB のみ削除・Stripe sub {sub_id} は継続 (student_id={student_id})")
        if sub_id and not payload.dry_run and payload.cancel_stripe and not payload.force_skip_stripe:
            _stripe = get_stripe()
            if not _stripe:
                raise HTTPException(status_code=503, detail="Stripe が構成されていません")
            try:
                _stripe.Subscription.delete(sub_id)
                log.info(f"[StudentDelete] stripe sub canceled: student={student_id} sub={sub_id}")
            except Exception as e:
                err_msg = str(e).lower()
                # 既解約・存在しないサブスクは正常扱いで進める (Stripe ポータルで既に解約済みケース)
                if any(s in err_msg for s in ("no such subscription", "resource_missing", "already canceled", "already_canceled")):
                    log.info(f"[StudentDelete] stripe sub already gone (treated as success): student={student_id} sub={sub_id}")
                else:
                    log.error(f"[StudentDelete] stripe cancel failed: {type(e).__name__}: {e}")
                    raise HTTPException(status_code=502, detail=f"Stripe 解約失敗: {e}")

        # 関連データの件数集計 (preview 用 + audit)
        related_counts = {}
        related_tables = [
            ("study_logs", "student_id"),
            ("study_plans", "student_id"),
            ("homework_assignments", "student_id"),
            ("exam_results", "student_id"),
            ("curricula", "student_id"),
            ("notifications", "student_id"),
            ("otp_codes", "student_id"),
            ("usage_monthly", "student_id"),
            ("mock_exam_sessions", "student_id"),
            ("vocab_progress", "student_id"),
            ("payments", "student_id"),
            ("ai_tutor_messages", "student_id"),
        ]
        for tbl, col in related_tables:
            try:
                c.execute(f"SELECT COUNT(*) AS n FROM {tbl} WHERE {col}=?", (student_id,))
                row = c.fetchone()
                related_counts[tbl] = int(row["n"]) if row else 0
            except Exception as _e:
                related_counts[tbl] = -1  # テーブル不在等
        # messages (sender or recipient)
        try:
            c.execute(
                "SELECT COUNT(*) AS n FROM messages WHERE (sender_type='student' AND sender_id=?) OR (recipient_type='student' AND recipient_id=?)",
                (student_id, student_id)
            )
            row = c.fetchone()
            related_counts["messages"] = int(row["n"]) if row else 0
        except Exception:
            related_counts["messages"] = -1
        # referrals (referrer or referred)
        try:
            c.execute("SELECT COUNT(*) AS n FROM referrals WHERE referrer_id=? OR referred_id=?", (student_id, student_id))
            row = c.fetchone()
            related_counts["referrals"] = int(row["n"]) if row else 0
        except Exception:
            related_counts["referrals"] = -1
        # course_applications
        try:
            c.execute("SELECT COUNT(*) AS n FROM course_applications WHERE student_id=?", (student_id,))
            row = c.fetchone()
            related_counts["course_applications"] = int(row["n"]) if row else 0
        except Exception:
            related_counts["course_applications"] = -1

        snapshot = {
            "id": student["id"], "name": student["name"], "email": student["email"],
            "status": student["status"], "plan": student["plan"], "course": student["course"],
            "created_at": str(student["created_at"]) if student["created_at"] else None,
            "stripe_customer_id": student["stripe_customer_id"],
            "stripe_subscription_id": student["stripe_subscription_id"],
            "related_counts": related_counts,
        }

        if payload.dry_run:
            return {"ok": True, "dry_run": True, "snapshot": snapshot, "message": "削除されません (dry_run)"}

        # 監査ログ: 削除前スナップショット
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("admin_student_deleted", json.dumps(snapshot, ensure_ascii=False), "admin")
            )
        except Exception as _e:
            log.warning(f"[StudentDelete] audit log failed: {_e}")

        # cascade delete - FK 依存順に
        delete_tables = [
            ("study_logs", "DELETE FROM study_logs WHERE student_id=?"),
            ("study_plans", "DELETE FROM study_plans WHERE student_id=?"),
            ("homework_assignments", "DELETE FROM homework_assignments WHERE student_id=?"),
            ("exam_results", "DELETE FROM exam_results WHERE student_id=?"),
            ("curricula", "DELETE FROM curricula WHERE student_id=?"),
            ("notifications", "DELETE FROM notifications WHERE student_id=?"),
            ("otp_codes", "DELETE FROM otp_codes WHERE student_id=?"),
            ("usage_monthly", "DELETE FROM usage_monthly WHERE student_id=?"),
            ("mock_exam_sessions", "DELETE FROM mock_exam_sessions WHERE student_id=?"),
            ("vocab_progress", "DELETE FROM vocab_progress WHERE student_id=?"),
            ("ai_tutor_messages", "DELETE FROM ai_tutor_messages WHERE student_id=?"),
            ("payments", "DELETE FROM payments WHERE student_id=?"),
        ]
        deleted_counts = {}
        for tbl, sql in delete_tables:
            try:
                c.execute(sql, (student_id,))
                deleted_counts[tbl] = related_counts.get(tbl, 0)
            except Exception as e:
                log.warning(f"[StudentDelete] {tbl} cleanup failed: {e}")
                deleted_counts[tbl] = -1
        # messages: 双方向
        try:
            c.execute(
                "DELETE FROM messages WHERE (sender_type='student' AND sender_id=?) OR (recipient_type='student' AND recipient_id=?)",
                (student_id, student_id)
            )
            deleted_counts["messages"] = related_counts.get("messages", 0)
        except Exception as e:
            log.warning(f"[StudentDelete] messages cleanup failed: {e}")
            deleted_counts["messages"] = -1
        # course_applications: 監査保存のため student_id を NULL にして履歴は残す
        # 🛡️ 2026-05-19 fix (defense in depth): email も anonymize して再申込時の重複 hit を防止
        # 小川碧斗事例: 削除後の再申込で「メールアドレス登録済み」現象。
        # POST /api/course-applications 側の student_id IS NOT NULL 条件追加と併せて二重防御。
        try:
            c.execute(
                "UPDATE course_applications SET student_id=NULL, email = 'deleted-' || id || '@deleted.invalid' WHERE student_id=?",
                (student_id,)
            )
            deleted_counts["course_applications_anonymized"] = related_counts.get("course_applications", 0)
        except Exception as e:
            log.warning(f"[StudentDelete] course_applications anonymize failed: {e}")
        # referrals: 監査保存のため referrer_id/referred_id を NULL にして履歴は残す
        try:
            c.execute("UPDATE referrals SET referrer_id=NULL WHERE referrer_id=?", (student_id,))
            c.execute("UPDATE referrals SET referred_id=NULL WHERE referred_id=?", (student_id,))
            deleted_counts["referrals_anonymized"] = related_counts.get("referrals", 0)
        except Exception as e:
            log.warning(f"[StudentDelete] referrals anonymize failed: {e}")
        # students 本体削除
        c.execute("DELETE FROM students WHERE id=?", (student_id,))
        conn.commit()
        log.info(f"[StudentDelete] student={student_id} name={student['name']} email={student['email']} deleted={deleted_counts}")
        return {
            "ok": True, "dry_run": False,
            "deleted": deleted_counts,
            "snapshot": snapshot,
            "message": f"生徒「{student['name']}」を削除しました",
        }
    finally:
        conn.close()


@app.post("/api/admin/students/{student_id}/create-invoice")
def admin_create_invoice_for_student(
    student_id: int,
    payload: dict,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🧾 個別生徒に Stripe 請求書 (Invoice) を発行 + 自動メール送信 (admin only)。

    塾長指示 (2026-05-24): CEO ダッシュ「生徒詳細」モーダルから 1 クリックで
    任意金額・任意品目の請求書 を発行できるようにする。模試代・教材代・追加補講代
    などの個別 spot 請求 を想定。

    payload: {
      "amount_jpy": int (必須・100-1000000 範囲・安全上限 100 万円),
      "item_name": str (必須・1-200 文字・例「5月分模試代」),
      "memo": str (任意・250 文字以下・請求書 description に追記),
      "days_until_due": int (任意・default 7・1-90 範囲)
    }

    動作:
    1. 認証 (admin Bearer or X-Cron-Secret)
    2. STRIPE_SECRET_KEY 必須・テスト/本番 mode は env で決定
    3. student 存在確認 (email 必須)
    4. stripe_customer_id 取得 → 無ければ Stripe customer を auto-create + DB UPDATE
    5. InvoiceItem 作成 → Invoice 作成 (collection_method=send_invoice) → finalize → send_invoice
    6. events.admin_invoice_issued に audit 記録
    7. invoice URL (hosted_invoice_url + invoice_pdf) を返却

    認証: admin Bearer または X-Cron-Secret"""
    # auth
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    if not STRIPE_SECRET_KEY:
        raise HTTPException(status_code=503, detail="STRIPE_SECRET_KEY 未設定")

    # payload validation
    if not isinstance(payload, dict):
        raise HTTPException(status_code=422, detail="payload (object) が必要")
    try:
        amount = int(payload.get("amount_jpy"))
    except Exception:
        raise HTTPException(status_code=422, detail="amount_jpy (positive int) が必要")
    if amount < 100 or amount > 1_000_000:
        raise HTTPException(status_code=422, detail="amount_jpy は 100 〜 1,000,000 円の範囲")
    item_name = (payload.get("item_name") or "").strip()
    if not item_name:
        raise HTTPException(status_code=422, detail="item_name (品目名) が必要")
    if len(item_name) > 200:
        item_name = item_name[:200]
    memo = (payload.get("memo") or "").strip()[:250]
    try:
        days_until_due = int(payload.get("days_until_due") or 7)
    except Exception:
        days_until_due = 7
    days_until_due = max(1, min(days_until_due, 90))

    conn = db()
    c = conn.cursor()
    try:
        c.execute("SELECT id, name, email, stripe_customer_id, status FROM students WHERE id=?", (student_id,))
        st = c.fetchone()
        if not st:
            raise HTTPException(status_code=404, detail="生徒が見つかりません")
        student_email = (st["email"] or "").strip()
        if not student_email:
            raise HTTPException(status_code=400, detail="生徒に email が登録されていないため Stripe 請求書を送れません。")
        student_name = (st["name"] or "").strip()
        customer_id = st["stripe_customer_id"]

        s = get_stripe()

        # 🛡 mode 判定 (test/livemode 混同事故予防)
        stripe_mode = "test" if STRIPE_SECRET_KEY.startswith("sk_test_") else "live"

        # 🛡 error message sanitizer (Stripe SDK exception に sk_ key prefix が混じる稀ケースを除去)
        import re as _re
        def _sanitize_err(msg: str) -> str:
            return _re.sub(r"sk_(test|live)_[A-Za-z0-9]+", "sk_[REDACTED]", str(msg))[:200]

        # 🛡 idempotency_key 共通 prefix (秒粒度・同 student の同秒 retry を 1 回にまとめる)
        import time as _time
        _idem_ts = int(_time.time())
        _idem_prefix = f"si_{student_id}_{_idem_ts}"

        # Stripe customer auto-create (なければ・metadata.student_id で重複検索を試行)
        if not customer_id:
            try:
                # 重複防止: 過去に同 student_id で作成済の customer を search
                found = None
                try:
                    search_res = s.Customer.search(
                        query=f"metadata['student_id']:'{student_id}'",
                        limit=1,
                    )
                    if search_res.data:
                        found = search_res.data[0]
                except Exception as _se:
                    # search 失敗は致命でない (古い API version で未対応の場合あり) → 通常 create に fallback
                    log.info(f"[admin/create-invoice] Customer.search skipped: {type(_se).__name__}")
                if found:
                    customer_id = found.id
                    log.info(f"[admin/create-invoice] Stripe customer 重複検出 (再利用): {customer_id}")
                else:
                    cust = s.Customer.create(
                        email=student_email,
                        name=student_name or None,
                        metadata={"student_id": str(student_id), "source": "admin_spot_invoice"},
                        idempotency_key=f"{_idem_prefix}_cust",
                    )
                    customer_id = cust.id
                    log.info(f"[admin/create-invoice] Stripe customer auto-created: {customer_id} for student_id={student_id}")
                # DB 反映 (Stripe 側に customer 確実に存在するため commit 安全)
                c.execute("UPDATE students SET stripe_customer_id=? WHERE id=?", (customer_id, student_id))
                conn.commit()
            except Exception as e:
                log.error(f"[admin/create-invoice] Stripe customer create/search failed: {type(e).__name__}: {e}")
                raise HTTPException(status_code=500, detail=f"Stripe customer 作成失敗: {type(e).__name__}: {_sanitize_err(e)}")

        # InvoiceItem → Invoice → finalize → send
        # 🛡 二重請求リスク対策: pending_invoice_items_behavior="exclude" + InvoiceItem を明示紐付け
        try:
            inv_item = s.InvoiceItem.create(
                customer=customer_id,
                amount=amount,
                currency="jpy",
                description=item_name,
                metadata={"student_id": str(student_id), "source": "admin_spot_invoice"},
                idempotency_key=f"{_idem_prefix}_item",
            )
            inv = s.Invoice.create(
                customer=customer_id,
                collection_method="send_invoice",
                days_until_due=days_until_due,
                description=(memo or item_name)[:1000],
                metadata={
                    "student_id": str(student_id),
                    "item_name": item_name,
                    "source": "admin_spot_invoice",
                },
                auto_advance=False,           # finalize を明示的に呼ぶ
                pending_invoice_items_behavior="exclude",  # 既存 pending item の混入防止
                idempotency_key=f"{_idem_prefix}_inv",
            )
            # InvoiceItem を本 Invoice に明示紐付け (exclude で除外された分を取込)
            try:
                s.InvoiceItem.modify(inv_item.id, invoice=inv.id)
            except Exception as _me:
                # modify 失敗時は警告のみ (Stripe ロジック上 InvoiceItem が orphan 化するが finalize 前なら影響軽微)
                log.warning(f"[admin/create-invoice] InvoiceItem.modify(invoice) 失敗: {type(_me).__name__}: {_me}")
            finalized = s.Invoice.finalize_invoice(inv.id)
            sent = s.Invoice.send_invoice(finalized.id)
        except Exception as e:
            log.error(f"[admin/create-invoice] Stripe invoice create/send failed: {type(e).__name__}: {e}")
            raise HTTPException(status_code=500, detail=f"Stripe 請求書発行失敗: {type(e).__name__}: {_sanitize_err(e)}")

        # 🛡 sent.status check (送信成功検証・"open" であれば正常)
        sent_status = getattr(sent, "status", None)
        auto_mail_ok = (sent_status == "open")
        if not auto_mail_ok:
            log.warning(f"[admin/create-invoice] sent.status={sent_status} (expected 'open') — email 自動送信失敗の可能性")

        # events 監査ログ
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("admin_invoice_issued", json.dumps({
                    "student_id": student_id,
                    "email": student_email,
                    "stripe_customer_id": customer_id,
                    "invoice_id": sent.id,
                    "invoice_number": getattr(sent, "number", None),
                    "amount_jpy": amount,
                    "item_name": item_name,
                    "days_until_due": days_until_due,
                    "hosted_invoice_url": getattr(sent, "hosted_invoice_url", None),
                }, ensure_ascii=False), "admin"),
            )
            conn.commit()
        except Exception as e:
            log.warning(f"[admin/create-invoice] events 記録失敗 (請求書発行は成功): {e}")

        return {
            "ok": True,
            "invoice_id": sent.id,
            "invoice_number": getattr(sent, "number", None),
            "amount_jpy": amount,
            "currency": "jpy",
            "status": sent_status,
            "hosted_invoice_url": getattr(sent, "hosted_invoice_url", None),
            "invoice_pdf": getattr(sent, "invoice_pdf", None),
            "days_until_due": days_until_due,
            "customer_id": customer_id,
            "auto_email_sent": auto_mail_ok,
            "stripe_mode": stripe_mode,  # "test" or "live" — UI で 🧪 TEST MODE バッジ表示用
            "message": (
                f"✅ 請求書 #{getattr(sent, 'number', sent.id)} を発行・{student_email} へ自動送信しました"
                if auto_mail_ok
                else f"⚠ 請求書 #{getattr(sent, 'number', sent.id)} は作成しましたが、自動メール送信に失敗した可能性があります (status={sent_status})。Stripe Dashboard > Settings > Emails を確認してください。"
            ),
        }
    except HTTPException:
        raise
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        log.error(f"[admin/create-invoice] unexpected: {type(e).__name__}: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"内部エラー: {type(e).__name__}")
    finally:
        conn.close()


@app.post("/api/admin/students/{student_id}/waive-enrollment-fee")
def admin_waive_enrollment_fee(
    student_id: int,
    payload: dict = None,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🆓 個別生徒の入塾金 (¥10,000) を免除する (admin only)。

    塾長指示 (2026-05-29): CEO ダッシュ「生徒詳細」から 1 クリックで任意の生徒の
    入塾金を免除できるようにする。これまでは ①先着キャンペーン枠 ②紹介された側 のみ
    自動免除で、塾長が任意指定する手段が無かった。

    動作:
    1. 認証 (admin Bearer or X-Cron-Secret)
    2. student 存在確認
    3. DB: enrollment_fee_waived=1 + enrollment_waiver_applied_at をセット (冪等)
    4. Stripe (customer_id があれば): 保留中 InvoiceItem のうち
       metadata.type=='enrollment_fee' または description に「入塾金」を含むものを削除
       (= 体験→有料転換時の初回請求から入塾金を外す)。**他の課金品目は絶対に触らない**。
    5. アクティブ subscription の metadata needs_enrollment_fee=0 を defensive にセット
    6. events.admin_enrollment_fee_waived に audit 記録

    返却: {ok, already_waived, db_updated, stripe_items_deleted, stripe_mode, message}
    認証: admin Bearer または X-Cron-Secret"""
    # auth
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            "SELECT id, name, email, stripe_customer_id, enrollment_fee_waived FROM students WHERE id=?",
            (student_id,),
        )
        st = c.fetchone()
        if not st:
            raise HTTPException(status_code=404, detail="生徒が見つかりません")
        try:
            already_waived = bool(st["enrollment_fee_waived"]) if "enrollment_fee_waived" in st.keys() else False
        except Exception:
            already_waived = False
        customer_id = st["stripe_customer_id"]
        student_name = (st["name"] or "").strip()

        # 1) DB フラグ (冪等: 既に免除でも applied_at が NULL なら埋める)
        c.execute(
            "UPDATE students SET enrollment_fee_waived = 1, "
            "enrollment_waiver_applied_at = COALESCE(enrollment_waiver_applied_at, CURRENT_TIMESTAMP) "
            "WHERE id = ?",
            (student_id,),
        )
        conn.commit()
        db_updated = True

        # 2) Stripe 保留入塾金 InvoiceItem 削除 (安全: enrollment_fee 限定)
        stripe_items_deleted = 0
        stripe_subs_updated = 0
        stripe_mode = None
        stripe_error = None
        if STRIPE_SECRET_KEY and customer_id:
            stripe_mode = "test" if STRIPE_SECRET_KEY.startswith("sk_test_") else "live"
            try:
                s = get_stripe()
                # 保留中 (まだ Invoice に乗っていない) InvoiceItem を列挙
                try:
                    items = s.InvoiceItem.list(customer=customer_id, pending=True, limit=100)
                    item_list = items.data if hasattr(items, "data") else items.get("data", [])
                except Exception:
                    # pending param 非対応の古い API 向け fallback (全件取得して未請求のみ)
                    items = s.InvoiceItem.list(customer=customer_id, limit=100)
                    item_list = [it for it in (items.data if hasattr(items, "data") else items.get("data", []))
                                 if not getattr(it, "invoice", None)]
                for it in item_list:
                    meta = getattr(it, "metadata", None) or {}
                    itype = (meta.get("type") if hasattr(meta, "get") else None) or ""
                    isource = (meta.get("source") if hasattr(meta, "get") else None) or ""
                    desc = getattr(it, "description", "") or ""
                    # ★ enrollment_fee 限定で削除 (他の spot 請求・模試代等は絶対に消さない)
                    #   ① metadata.type=='enrollment_fee' を最優先 (確実)
                    #   ② 旧 item で type 欠落の場合のみ description 厳密一致で救済。ただし
                    #      admin_spot_invoice (塾長の任意命名請求) は description に「入塾金」を
                    #      含んでも絶対に対象外 (誤削除防止・review A MAJOR-1)
                    is_enrollment = (
                        itype == "enrollment_fee"
                        or (isource != "admin_spot_invoice" and desc == "入塾金（システム登録費用・初回のみ）")
                    )
                    if is_enrollment:
                        try:
                            s.InvoiceItem.delete(it.id)
                            stripe_items_deleted += 1
                            log.info(f"[waive-enrollment] deleted InvoiceItem {it.id} student={student_id}")
                        except Exception as _de:
                            log.warning(f"[waive-enrollment] InvoiceItem.delete 失敗 {getattr(it,'id','?')}: {type(_de).__name__}")
                # defensive: active/trialing subscription の metadata を needs_enrollment_fee=0 に
                try:
                    subs = s.Subscription.list(customer=customer_id, status="all", limit=10)
                    sub_list = subs.data if hasattr(subs, "data") else subs.get("data", [])
                    for sub in sub_list:
                        if getattr(sub, "status", "") in ("trialing", "active", "past_due"):
                            try:
                                s.Subscription.modify(sub.id, metadata={"needs_enrollment_fee": "0"})
                                stripe_subs_updated += 1
                            except Exception:
                                pass
                except Exception:
                    pass
            except Exception as e:
                import re as _re
                stripe_error = _re.sub(r"sk_(test|live)_[A-Za-z0-9]+", "sk_[REDACTED]", str(e))[:160]
                log.error(f"[waive-enrollment] Stripe 処理失敗 student={student_id}: {type(e).__name__}: {stripe_error}")

        # 3) audit
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("admin_enrollment_fee_waived", json.dumps({
                    "student_id": student_id,
                    "student_name": student_name,
                    "already_waived": already_waived,
                    "stripe_items_deleted": stripe_items_deleted,
                    "stripe_subs_updated": stripe_subs_updated,
                    "stripe_mode": stripe_mode,
                }, ensure_ascii=False), "admin"),
            )
            conn.commit()
        except Exception as e:
            log.warning(f"[waive-enrollment] events 記録失敗 (免除自体は成功): {e}")

        # 🛡️ review A MAJOR-2: Stripe 失敗時は DB は免除済みでも保留入塾金が残り次回課金される
        #   恐れがあるため、強い警告 + ok=False で塾長に再実行/手動確認を促す。
        if stripe_error:
            msg = (
                f"⚠️ {student_name or ('生徒 #'+str(student_id))} の DB 免除フラグは立てましたが、"
                f"Stripe への反映に失敗しました。Stripe に入塾金 ¥10,000 の保留請求が残っている可能性があります。"
                f"このボタンを再実行するか、Stripe ダッシュボードで該当顧客の保留請求を確認してください。"
                f"（詳細: {stripe_error}）"
            )
            return {
                "ok": False,
                "student_id": student_id,
                "already_waived": already_waived,
                "db_updated": db_updated,
                "stripe_items_deleted": stripe_items_deleted,
                "stripe_subs_updated": stripe_subs_updated,
                "stripe_mode": stripe_mode,
                "stripe_error": stripe_error,
                "message": msg,
            }

        msg = f"✅ {student_name or ('生徒 #'+str(student_id))} の入塾金を免除しました"
        if stripe_items_deleted > 0:
            msg += f" (Stripe 保留請求 {stripe_items_deleted} 件を削除)"
        elif STRIPE_SECRET_KEY and customer_id:
            msg += "（Stripe に保留中の入塾金請求は見つかりませんでした＝既に免除済み/未作成）"
        elif not customer_id:
            msg += "（Stripe 顧客未作成のため DB フラグのみ。今後の請求で入塾金は加算されません）"

        return {
            "ok": True,
            "student_id": student_id,
            "already_waived": already_waived,
            "db_updated": db_updated,
            "stripe_items_deleted": stripe_items_deleted,
            "stripe_subs_updated": stripe_subs_updated,
            "stripe_mode": stripe_mode,
            "stripe_error": stripe_error,
            "message": msg,
        }
    except HTTPException:
        raise
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        log.error(f"[waive-enrollment] unexpected: {type(e).__name__}: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"内部エラー: {type(e).__name__}")
    finally:
        conn.close()


@app.post("/api/admin/textbooks/purge")
def admin_textbook_pool_purge(payload: dict, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """textbook_pool の特定レコードを削除する admin endpoint。
    payload (いずれか必須):
      {"source": "claude_max_seed_batch01"}  # source 完全一致で削除
      {"id": 123}                              # ID 指定削除
      {"subject": "数学ⅠA", "topic": "2次関数"}  # subject + topic 一致削除
    認証: admin Bearer or x-cron-secret"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    source = payload.get("source")
    rec_id = payload.get("id")
    subject = payload.get("subject")
    topic = payload.get("topic")

    where = []
    params = []
    if source:
        where.append("source = ?")
        params.append(source)
    if rec_id:
        where.append("id = ?")
        params.append(int(rec_id))
    if subject:
        where.append("subject = ?")
        params.append(subject)
    if topic:
        where.append("topic = ?")
        params.append(topic)
    if not where:
        raise HTTPException(status_code=400, detail="削除条件が空です (source/id/subject/topic のいずれか必須)")

    where_sql = " WHERE " + " AND ".join(where)
    conn = db()
    c = conn.cursor()
    try:
        c.execute(f"SELECT COUNT(*) AS n FROM textbook_pool{where_sql}", tuple(params))
        row = c.fetchone()
        will_delete = row["n"] if row else 0
        c.execute(f"DELETE FROM textbook_pool{where_sql}", tuple(params))
        conn.commit()
    finally:
        conn.close()

    log.info(f"[TextbookPool:Purge] deleted={will_delete} where={where_sql} params={params}")
    return {"ok": True, "deleted": will_delete, "where": where_sql, "message": f"✅ {will_delete} 教材を削除しました"}


@app.get("/api/admin/textbooks/list")
def admin_textbook_pool_list(authorization: Optional[str] = Header(None)):
    """admin: textbook_pool 一覧 (CEO ダッシュ表示用)"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="セッション期限切れ")
    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            """SELECT id, subject, topic, level, length, type, title, tags, status, source, created_at
               FROM textbook_pool ORDER BY created_at DESC LIMIT 200"""
        )
        rows = [dict(r) for r in c.fetchall()]
        c.execute("SELECT COUNT(*) AS n FROM textbook_pool")
        total_row = c.fetchone()
        total = total_row["n"] if total_row else 0
    finally:
        conn.close()
    for r in rows:
        if r.get("created_at"):
            r["created_at"] = str(r["created_at"])
        r["tags"] = (r.get("tags") or "").split(",") if r.get("tags") else []
    return {"ok": True, "total": total, "items": rows}


@app.post("/api/admin/exam-questions/generate")
def admin_exam_questions_generate(payload: dict, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """指定パート (or ローテ全件) の問題を生成。手動トリガー。
    payload: {"exam_id": "eiken", "part_key": "r_q1", "eiken_grade": "gp1", "count": 1}
    省略時はローテーション全件 (quota 使用)"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    exam_id = payload.get("exam_id")
    part_key = payload.get("part_key")
    eiken_grade = payload.get("eiken_grade")
    count = int(payload.get("count") or 0)

    if exam_id and part_key:
        # 特定 part に N 問
        n = max(1, min(count or 1, 10))
        generated = []
        for _ in range(n):
            q = _generate_exam_question(exam_id, part_key, eiken_grade)
            if q:
                _save_exam_question(exam_id, part_key, q, eiken_grade)
                generated.append({"exam": exam_id, "part": part_key, "grade": eiken_grade})
        return {"generated": len(generated), "details": generated}
    else:
        # ローテ全件 (quota 使用)
        return _run_exam_questions_generation(quota=count or EXAM_QUESTIONS_DAILY_QUOTA)


