@app.get("/api/admin/exam-questions/pool-status")
def admin_exam_questions_pool_status(
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """全 part の pool 蓄積数を返す (CEO ダッシュボード用)。
    認証: admin Bearer または X-Cron-Secret (audit script 経由)。
    🛟 2026-05-17 audit limit=50 cap 問題発覚で CRON_SECRET 経路を追加 (塾長指示
    「pool チェック」で正確な count が必要なため)。"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")
    counts = _exam_pool_counts()
    # 🌐 手動取込シードの「取込済み/未取込」判定用: model='manual'/'manual2' の行数を (exam,part,grade) 別に集計。
    #   ceo のシード取込ボタンが AI生成分と区別して取込済みを表示するのに使う。
    #   manual = 共テ理科147問など初期手作りシード / manual2 = 隙間時間ドリル単元別増量シード (2026-06-17)。
    #   別 model で分けることで既存ボタンのカウントを汚さず、各ボタンが自分の取込分だけを判定できる。
    manual_counts = {}
    manual2_counts = {}
    _mc = None
    try:
        _mc = db(); _mcur = _mc.cursor()
        _mcur.execute("SELECT exam_id, part_key, eiken_grade, model, COUNT(*) AS n FROM exam_questions WHERE model IN ('manual', 'manual2') GROUP BY exam_id, part_key, eiken_grade, model")
        for _r in _mcur.fetchall():
            _key = (_r["exam_id"], _r["part_key"], _r["eiken_grade"])
            if _r["model"] == "manual2":
                manual2_counts[_key] = int(_r["n"])
            else:
                manual_counts[_key] = int(_r["n"])
    except Exception as _e:
        log.warning(f"[pool-status] manual count query failed: {_e}")
    finally:
        if _mc is not None:
            try: _mc.close()
            except Exception: pass
    # 🎯 増量シードの「本当に取込まれたか」判定用: 各増量シード固有の inner-id 接頭辞を持つ
    #   manual2 行数を数える。バッジが「同part既存batchの数」で早とちり✅化する問題(2026-06-18 塾長
    #   報告)の根治。接頭辞は増量seedのみが使う coined token なので、同partに既存manual2があっても
    #   その増量分の実在数だけを正確に拾える。data-idprefix を持つ ceo ボタンがこれで判定する。
    seed_prefix_counts = {}
    _sp = None
    try:
        _sp = db(); _spcur = _sp.cursor()
        _spcur.execute(
            "SELECT "
            "SUM(CASE WHEN question_data LIKE '%mexp%' THEN 1 ELSE 0 END) AS mexp, "
            "SUM(CASE WHEN question_data LIKE '%rexp%' THEN 1 ELSE 0 END) AS rexp, "
            "SUM(CASE WHEN question_data LIKE '%sexp%' THEN 1 ELSE 0 END) AS sexp, "
            "SUM(CASE WHEN question_data LIKE '%kexp%' THEN 1 ELSE 0 END) AS kexp, "
            "SUM(CASE WHEN question_data LIKE '%gexp%' THEN 1 ELSE 0 END) AS gexp, "
            "SUM(CASE WHEN question_data LIKE '%m3x%' THEN 1 ELSE 0 END) AS m3x "
            "FROM exam_questions WHERE model = 'manual2'"
        )
        _spr = _spcur.fetchone()
        if _spr is not None:
            for _pf in ("mexp", "rexp", "sexp", "kexp", "gexp", "m3x"):
                try:
                    _v = _spr[_pf]
                except Exception:
                    _v = None
                try:
                    seed_prefix_counts[_pf] = int(_v or 0)
                except Exception:
                    seed_prefix_counts[_pf] = 0
    except Exception as _e:
        log.warning(f"[pool-status] seed prefix count query failed: {_e}")
    finally:
        if _sp is not None:
            try: _sp.close()
            except Exception: pass
    JST = timezone(timedelta(hours=9))
    today_count = _exam_generated_today()
    parts = []
    by_exam = {}
    total = 0
    full_pool = 0
    low_pool = 0
    for (exam_id, part_key, eiken_grade), n in counts.items():
        total += n
        _tgt = _target_pool_for(exam_id, part_key, eiken_grade)
        is_full = n >= _tgt
        is_low = n < EXAM_QUESTIONS_MIN_POOL
        if is_full: full_pool += 1
        if is_low: low_pool += 1
        parts.append({
            "exam": exam_id,
            "part": part_key,
            "grade": eiken_grade,
            "count": n,
            "target": _tgt,
            "manual": manual_counts.get((exam_id, part_key, eiken_grade), 0),  # 手作りシード取込分
            "manual2": manual2_counts.get((exam_id, part_key, eiken_grade), 0),  # 単元別増量シード取込分
            "is_full": is_full,
            "is_low": is_low,
        })
        by_exam[exam_id] = by_exam.get(exam_id, 0) + n
    parts.sort(key=lambda p: (p["count"], p["exam"], p["part"]))
    return {
        "rotation_size": len(EXAM_QUESTION_ROTATION),
        "total_questions": total,
        "by_exam": by_exam,
        "full_pool_parts": full_pool,
        "low_pool_parts": low_pool,
        "in_flight_refills": len(_REFILL_INFLIGHT),
        "today_generated": today_count,
        "seed_prefix_counts": seed_prefix_counts,  # 増量シード固有ID接頭辞の実在大問数 (バッジ判定用)
        "config": {
            "interval_hours": EXAM_QUESTIONS_INTERVAL_HOURS,
            "per_tick": EXAM_QUESTIONS_PER_TICK,
            "target_pool": EXAM_QUESTIONS_TARGET_POOL,
            "min_pool": EXAM_QUESTIONS_MIN_POOL,
            "daily_max": EXAM_QUESTIONS_DAILY_MAX,
            "model": EXAM_QUESTIONS_MODEL,
        },
        "parts": parts,
    }


# ============================================================================
# 📰 CNN / Japan Times / BBC 記事から英語読解問題を生成 (実英文記事モード)
# ============================================================================
# 著作権配慮: 記事本文を丸ごと取り込まずに、RSS フィードのタイトル + 短い summary
# (RSS が公開している抜粋・通常 1-3 文) を seed として AI に類題本文を生成させる。
# 元記事の URL は出題と一緒に表示し、生徒が原典で読み比べできるようにする。

NEWS_FEEDS = {
    "cnn":           {"url": "http://rss.cnn.com/rss/cnn_topstories.rss",      "name": "CNN Top Stories",      "level": "B2-C1"},
    "cnn_world":     {"url": "http://rss.cnn.com/rss/cnn_world.rss",           "name": "CNN World",            "level": "B2-C1"},
    "japan_times":   {"url": "https://www.japantimes.co.jp/feed/topstories/",  "name": "The Japan Times",      "level": "B2"},
    "japan_times_news": {"url": "https://www.japantimes.co.jp/news/feed/",     "name": "Japan Times News",     "level": "B2"},
    "bbc":           {"url": "http://feeds.bbci.co.uk/news/rss.xml",           "name": "BBC News",             "level": "B2"},
    "bbc_world":     {"url": "http://feeds.bbci.co.uk/news/world/rss.xml",     "name": "BBC World",            "level": "B2"},
    "nyt":           {"url": "https://rss.nytimes.com/services/xml/rss/nyt/HomePage.xml", "name": "The New York Times", "level": "C1"},
    "guardian":      {"url": "https://www.theguardian.com/world/rss",          "name": "The Guardian",         "level": "B2-C1"},
    "reuters_world": {"url": "https://feeds.reuters.com/reuters/worldNews",    "name": "Reuters World",        "level": "B2"},
    "nhk_world":     {"url": "https://www3.nhk.or.jp/nhkworld/en/news/feed/",  "name": "NHK World",            "level": "B1-B2"},
}


@app.get("/api/admin/db-diag")
def admin_db_diag(authorization: Optional[str] = Header(None), q: Optional[str] = None):
    """🕐 [db-diag] 本番DBのセッションタイムゾーンと trial_end の生値を返す診断 (admin専用・読取専用)。
    trial_end を naive 列に aware iso 保存している TZ ズレ (active 生徒の誤expired化) を本番で確認するため。
    q を渡すと名前/メール一致の生徒、無指定なら trial/expired の直近を返す。書込は一切行わない。"""
    if not authorization or not authorization.startswith("Bearer ") or not _verify_admin_token(authorization[len("Bearer "):].strip()):
        raise HTTPException(status_code=401, detail="未認証")

    def _fv(row):
        if row is None:
            return None
        try:
            return list(row.values())[0]
        except Exception:
            try:
                return row[0]
            except Exception:
                return str(row)

    out = {"use_postgres": USE_POSTGRES, "now_utc": datetime.now(timezone.utc).isoformat()}
    conn = db()
    c = conn.cursor()
    try:
        if USE_POSTGRES:
            try:
                c.execute("SHOW timezone")
                out["timezone"] = _fv(c.fetchone())
            except Exception as _e:
                out["timezone_error"] = f"{type(_e).__name__}: {_e}"
        else:
            out["timezone"] = "sqlite (ローカル開発・本番はPostgres)"
        try:
            c.execute("SELECT CURRENT_TIMESTAMP AS now_db")
            out["now_db"] = str(_fv(c.fetchone()))
        except Exception as _e:
            out["now_db_error"] = f"{type(_e).__name__}: {_e}"
        try:
            if q and q.strip():
                _like = f"%{q.strip()}%"
                c.execute(
                    "SELECT id, name, status, trial_end FROM students "
                    "WHERE name LIKE ? OR LOWER(COALESCE(email,'')) LIKE LOWER(?) OR LOWER(COALESCE(student_email,'')) LIKE LOWER(?) "
                    "ORDER BY id DESC LIMIT 10",
                    (_like, _like, _like),
                )
            else:
                c.execute(
                    "SELECT id, name, status, trial_end FROM students "
                    "WHERE status IN ('trial','expired') ORDER BY id DESC LIMIT 10"
                )
            out["trial_end_samples"] = [
                {"id": r["id"], "name": r["name"], "status": r["status"], "trial_end_raw": str(r["trial_end"])}
                for r in c.fetchall()
            ]
        except Exception as _e:
            out["samples_error"] = f"{type(_e).__name__}: {_e}"
    finally:
        conn.close()
    return out


def _fetch_news_feed(feed_key: str, limit: int = 5) -> list[dict]:
    """RSS フィードを取得して [{title, link, summary, published}] のリストを返す。
    XML パースは標準ライブラリのみで実装 (xml.etree.ElementTree)。"""
    feed = NEWS_FEEDS.get(feed_key)
    if not feed:
        return []
    try:
        import xml.etree.ElementTree as ET
        req = urllib.request.Request(feed["url"], headers={"User-Agent": "Mozilla/5.0 (compatible; AIJukuBot/1.0)"})
        with urllib.request.urlopen(req, timeout=15) as resp:
            xml_bytes = resp.read()
        root = ET.fromstring(xml_bytes)
        # RSS 2.0: channel/item, Atom: feed/entry — 両方サポート
        items = []
        # try RSS first
        for item in root.findall(".//item")[:limit]:
            title = (item.findtext("title") or "").strip()
            link = (item.findtext("link") or "").strip()
            summary = (item.findtext("description") or item.findtext("{http://purl.org/rss/1.0/modules/content/}encoded") or "").strip()
            published = (item.findtext("pubDate") or item.findtext("{http://purl.org/dc/elements/1.1/}date") or "").strip()
            if title and link:
                # HTML タグを単純除去 (RSS の description には HTML が混じることが多い)
                import re
                summary_text = re.sub(r"<[^>]+>", "", summary)[:600]
                items.append({"title": title, "link": link, "summary": summary_text, "published": published})
        # try Atom if no RSS items
        if not items:
            ns = {"atom": "http://www.w3.org/2005/Atom"}
            for entry in root.findall("atom:entry", ns)[:limit]:
                title = (entry.findtext("atom:title", default="", namespaces=ns) or "").strip()
                link_el = entry.find("atom:link", ns)
                link = (link_el.get("href") if link_el is not None else "").strip()
                summary = (entry.findtext("atom:summary", default="", namespaces=ns) or entry.findtext("atom:content", default="", namespaces=ns) or "").strip()
                published = (entry.findtext("atom:published", default="", namespaces=ns) or "").strip()
                if title and link:
                    import re
                    summary_text = re.sub(r"<[^>]+>", "", summary)[:600]
                    items.append({"title": title, "link": link, "summary": summary_text, "published": published})
        return items
    except Exception as e:
        log.error(f"[News] Failed to fetch {feed_key}: {type(e).__name__}: {e}")
        return []


def _generate_news_reading_question(article: dict, feed_name: str, level: str = "B2") -> Optional[dict]:
    """ニュース記事の見出し+短い要約を seed に、AI で読解問題を生成。
    元記事の文章は引用せず、AI が独自に「同じテーマで同じ語彙レベルの 250-350 語の本文」を執筆。
    元 URL は参考リンクとして出題に併記。"""
    if not ANTHROPIC_API_KEY:
        return None

    system = f"""あなたは英語学習教材の編集者です。{feed_name} で報じられた話題をもとに、英語読解問題を作成してください。

【絶対遵守】
- 元記事の文章を引用しない (著作権)。AI が独自に同じテーマ・同じ語彙レベル・250-350 語で本文を執筆する。
- 本文の文体は一般的なニュース英語 ({feed_name} 風・客観的・第三者視点)
- CEFR {level} レベル相当の語彙・文法に統制する
- 設問は内容理解・推論・語彙の意味推定をバランス良く 5問 (4択)
- 解説は日本語で、正解の根拠 + 他選択肢の誤り + 関連語彙/文法を丁寧に
- 「📰 元記事を読んでみよう」として元記事 URL を末尾に併記する案内文を included_link_message に入れる
- 出力は純粋なJSONのみ"""

    user = f"""【seed 情報 (これを参考に AI が独自に本文を書く)】
ニュースソース: {feed_name}
見出し: {article.get('title')}
要約 (RSS): {article.get('summary', '')[:400]}

【あなたへの指示】
1. 上記の話題と同じテーマを扱う、独自の英語ニュース記事 (250-350 語) を書いてください。元記事の文を引用しない。
2. 5問の理解問題 (4択) を作成。
3. CEFR {level} レベルに統制。

【出力形式】純粋なJSONのみ:
{{
  "passage": "AI が書いた独自の英語本文 (250-350 語)",
  "audio_script": "",
  "prompt": "",
  "source_title": {json.dumps(article.get('title', ''))},
  "source_url": {json.dumps(article.get('link', ''))},
  "source_feed": {json.dumps(feed_name)},
  "level": "{level}",
  "included_link_message": "📰 元記事 ({feed_name}) を読み比べてみよう: ...",
  "questions": [
    {{
      "id": "q1",
      "type": "multiple_choice",
      "stem": "問題文",
      "choices": ["A", "B", "C", "D"],
      "answer": "正解 (0始まり)",
      "explanation": "解説 (日本語、3行以上)"
    }}
  ]
}}"""

    try:
        # AI never-fail: _call_anthropic_safe 経由で Tier 4 (Gemini) まで自動 fallback
        data = _call_anthropic_safe(
            {
                "model": EXAM_QUESTIONS_MODEL,
                "max_tokens": 4000,
                "system": system,
                "messages": [{"role": "user", "content": user}],
            },
            kind="news_reading_question",
        )
        text = data["content"][0]["text"].strip()
        if text.startswith("```"):
            text = text.split("```", 2)[1]
            if text.startswith("json"):
                text = text[4:]
            text = text.strip().rstrip("`").strip()
        return json.loads(text)
    except Exception as e:
        log.error(f"[News] Generation failed: {type(e).__name__}: {e}")
        return None


