@app.post("/api/admin/ai/test-gemini")
def admin_test_gemini(model: Optional[str] = None, strict: int = 0,
                       authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """Gemini Tier 4 fallback の動作確認 endpoint。
    admin Bearer or x-cron-secret 認証。Gemini で 1 回 generate して
    {ok, model, sample, latency_ms} を返す。
    クエリ:
      - model=gemini-2.5-pro 等で任意モデル指定 (省略時は GEMINI_MODEL = Pro)
      - strict=1 で Pro→Flash 二段 fallback を bypass し、Pro が失敗したら raw error を返す
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    if not GEMINI_API_KEY:
        return {
            "ok": False,
            "configured": False,
            "error": "GEMINI_API_KEY が Railway env に未設定。https://aistudio.google.com/app/apikey で発行してください。",
        }

    target_model = model or GEMINI_MODEL

    # strict=1: 二段 fallback bypass で raw error を取得 (デバッグ用)
    if strict:
        t0 = time.time()
        try:
            import google.generativeai as genai
            genai.configure(api_key=GEMINI_API_KEY)
            gen_model = genai.GenerativeModel(
                model_name=target_model,
                system_instruction="あなたは丁寧な日本語アシスタントです。",
                generation_config={"max_output_tokens": 200, "temperature": 0.7},
                safety_settings=[
                    {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_ONLY_HIGH"},
                    {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_ONLY_HIGH"},
                    {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_ONLY_HIGH"},
                    {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_ONLY_HIGH"},
                ],
            )
            chat = gen_model.start_chat()
            resp = chat.send_message("「AI never-fail テスト成功」とだけ短く返答してください。")
            return {
                "ok": True,
                "configured": True,
                "model": target_model,
                "provider": "gemini",
                "strict": True,
                "sample": (resp.text or "")[:200],
                "latency_ms": int((time.time() - t0) * 1000),
            }
        except Exception as e:
            return {
                "ok": False,
                "configured": True,
                "strict": True,
                "model_attempted": target_model,
                "error_type": type(e).__name__,
                "error": str(e)[:1500],
                "latency_ms": int((time.time() - t0) * 1000),
            }

    t0 = time.time()
    try:
        data = _call_gemini(
            {
                "model": target_model,
                "max_tokens": 200,
                "system": "あなたは丁寧な日本語アシスタントです。",
                "messages": [{"role": "user", "content": "「AI never-fail テスト成功」とだけ短く返答してください。"}],
            },
            kind="test_gemini",
        )
        text = (data.get("content") or [{}])[0].get("text", "") if data.get("content") else ""
        return {
            "ok": True,
            "configured": True,
            "model": data.get("_actual_model"),
            "provider": data.get("_provider"),
            "sample": text[:200],
            "latency_ms": int((time.time() - t0) * 1000),
            "usage": data.get("usage", {}),
        }
    except Exception as e:
        return {
            "ok": False,
            "configured": True,
            "error": f"{type(e).__name__}: {str(e)[:300]}",
            "latency_ms": int((time.time() - t0) * 1000),
        }


@app.post("/api/admin/ai/test-anthropic")
def admin_test_anthropic(model: Optional[str] = None,
                          authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """🔬 Anthropic API 疎通確認 (2026-05-13 追加)
    塾長指示「3 AI 中 0 のみ応答」事故の原因究明用。Anthropic 専用 test endpoint が
    存在しなかったため、Anthropic の生死 / credit / quota 状況を確認する手段がなかった。

    admin Bearer or x-cron-secret 認証。
    Anthropic API を直接 (fallback chain 経由せず) 叩いて raw error を返す。
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    if not ANTHROPIC_API_KEY:
        return {"ok": False, "configured": False,
                "error": "ANTHROPIC_API_KEY が未設定"}

    target_model = model or "claude-haiku-4-5"  # cost 最小で疎通確認
    t0 = time.time()
    body = {
        "model": target_model,
        "max_tokens": 50,
        "messages": [{"role": "user", "content": "Say only the word: OK"}],
    }
    try:
        req = urllib.request.Request(
            "https://api.anthropic.com/v1/messages",
            data=json.dumps(body).encode("utf-8"),
            headers={
                "x-api-key": ANTHROPIC_API_KEY,
                "anthropic-version": "2023-06-01",
                "Content-Type": "application/json",
            },
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            text = (data.get("content") or [{}])[0].get("text", "")
            usage = data.get("usage", {})
            return {
                "ok": True,
                "configured": True,
                "model": target_model,
                "sample": text[:100],
                "usage": usage,
                "latency_ms": int((time.time() - t0) * 1000),
            }
    except urllib.error.HTTPError as e:
        err_body = e.read().decode("utf-8", errors="ignore")
        return {
            "ok": False, "configured": True, "model": target_model,
            "http_status": e.code,
            "error": err_body[:500],
            "credit_low": "credit balance is too low" in err_body.lower() or "credit_balance" in err_body.lower(),
            "rate_limited": e.code == 429 or "rate" in err_body.lower(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
    except Exception as e:
        return {
            "ok": False, "configured": True, "model": target_model,
            "error": f"{type(e).__name__}: {str(e)[:300]}",
            "latency_ms": int((time.time() - t0) * 1000),
        }


@app.get("/api/admin/anthropic/credit-status")
def admin_anthropic_credit_status(authorization: Optional[str] = Header(None),
                                    x_cron_secret: Optional[str] = Header(None)):
    """💸 Anthropic credit 残量予測 (2026-05-13 塾長指示)
    補充記録 (anthropic_credit_recharge) - 累計使用 (anthropic_usage_log) = 推定残額
    直近 7 日の日平均使用 → 残額 / 日平均 = 残日数

    認証: admin Bearer または X-Cron-Secret"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    from datetime import timedelta as _td
    conn = db()
    try:
        c = conn.cursor()

        # 累計補充
        c.execute("SELECT COALESCE(SUM(amount_usd), 0) FROM anthropic_credit_recharge")
        row = c.fetchone()
        try:
            total_recharged = float(row[0] or 0)
        except (TypeError, KeyError, IndexError):
            try:
                total_recharged = float(list(row.values())[0] or 0)
            except Exception:
                total_recharged = 0.0

        # 累計使用
        c.execute("SELECT COALESCE(SUM(cost_usd), 0) FROM anthropic_usage_log")
        row = c.fetchone()
        try:
            total_used = float(row[0] or 0)
        except (TypeError, KeyError, IndexError):
            try:
                total_used = float(list(row.values())[0] or 0)
            except Exception:
                total_used = 0.0

        # 直近 7 日の日平均使用
        cutoff_7d = datetime.utcnow() - _td(days=7)
        c.execute("SELECT COALESCE(SUM(cost_usd), 0) FROM anthropic_usage_log WHERE created_at >= ?", (cutoff_7d,))
        row = c.fetchone()
        try:
            last_7d_used = float(row[0] or 0)
        except (TypeError, KeyError, IndexError):
            try:
                last_7d_used = float(list(row.values())[0] or 0)
            except Exception:
                last_7d_used = 0.0
        avg_daily_used = last_7d_used / 7.0

        remaining = max(0.0, total_recharged - total_used)
        days_remaining = (remaining / avg_daily_used) if avg_daily_used > 0.001 else None

        # 状態判定 (色分け用)
        # データ不足 (補充記録なし) → unknown / 残日数 < 3 → critical / < 7 → warning / その他 → ok
        if total_recharged <= 0:
            status_level = "unknown"
        elif days_remaining is None:
            status_level = "ok"  # 使用記録ないがチャージ済
        elif days_remaining < 3:
            status_level = "critical"
        elif days_remaining < 7:
            status_level = "warning"
        else:
            status_level = "ok"

        # 直近補充記録
        c.execute(
            "SELECT amount_usd, note, recorded_at FROM anthropic_credit_recharge "
            "ORDER BY recorded_at DESC LIMIT 5"
        )
        recharges = []
        for r in c.fetchall():
            try:
                amt = r["amount_usd"]; note = r["note"]; ts = r["recorded_at"]
            except (TypeError, KeyError, IndexError):
                amt, note, ts = r[0], r[1], r[2]
            recharges.append({"amount_usd": float(amt or 0), "note": note or "", "recorded_at": str(ts) if ts else None})

        return {
            "ok": True,
            "total_recharged_usd": round(total_recharged, 2),
            "total_used_usd": round(total_used, 4),
            "remaining_usd": round(remaining, 2),
            "last_7d_used_usd": round(last_7d_used, 4),
            "avg_daily_used_usd": round(avg_daily_used, 4),
            "days_remaining": (round(days_remaining, 1) if days_remaining is not None else None),
            "status_level": status_level,  # unknown / ok / warning / critical
            "recharges": recharges,
        }
    finally:
        conn.close()


@app.post("/api/admin/anthropic/credit-recharge")
def admin_anthropic_credit_recharge(payload: dict,
                                      authorization: Optional[str] = Header(None),
                                      x_cron_secret: Optional[str] = Header(None)):
    """💰 Anthropic credit 補充記録 (塾長が Anthropic console で補充した時に手動記録)
    payload: {"amount_usd": 50.0, "note": "Tier 1 初回補充"}"""
    authed = False
    recorded_by = "x-cron-secret"
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
            recorded_by = "admin"
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    try:
        amount = float(payload.get("amount_usd") or 0)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="amount_usd 不正")
    if amount <= 0 or amount > 10000:
        raise HTTPException(status_code=400, detail="amount_usd は 0 < x <= 10000 の範囲で")
    note = (payload.get("note") or "")[:300]

    conn = db()
    try:
        c = conn.cursor()
        c.execute(
            "INSERT INTO anthropic_credit_recharge (amount_usd, note, recorded_by) VALUES (?, ?, ?)",
            (amount, note, recorded_by),
        )
        conn.commit()
        return {"ok": True, "amount_usd": amount, "note": note, "recorded_by": recorded_by}
    finally:
        conn.close()


@app.post("/api/admin/anthropic/credit-set-balance")
def admin_anthropic_credit_set_balance(payload: dict,
                                         authorization: Optional[str] = Header(None),
                                         x_cron_secret: Optional[str] = Header(None)):
    """📥 Anthropic console で表示されている現在の残高を CEO ダッシュに直接同期する。
    2026-05-15 塾長指示「$48.70 残ってるのに CEO で 0 になる」: 補充履歴を後付けで
    入れる代わりに「現在残高 $X を sync」だけで一発合わせ込みできるショートカット。

    payload: {"balance_usd": 48.70, "note": "Console 残高同期 (UTC 2026-05-15)"}

    実装ロジック:
      desired_balance = payload.balance_usd
      current_used    = SUM(anthropic_usage_log.cost_usd)
      current_recharge = SUM(anthropic_credit_recharge.amount_usd)
      delta = desired_balance + current_used - current_recharge
      → anthropic_credit_recharge に 1 行 INSERT (note="balance-sync $X")
      → 結果: total_recharged - total_used = desired_balance になる

    認証: admin Bearer or X-Cron-Secret"""
    authed = False
    recorded_by = "x-cron-secret"
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
            recorded_by = "admin"
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    try:
        balance = float(payload.get("balance_usd"))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="balance_usd 不正")
    if balance < 0 or balance > 10000:
        raise HTTPException(status_code=400, detail="balance_usd は 0 <= x <= 10000 の範囲で")
    # user note は 120 chars に切って diagnostic 情報 (balance/delta/prev) と合わせて
    # トータル 300 chars 以内に収まるよう保証 (truncate WARN fix)
    note = (payload.get("note") or "Console 残高同期")[:120]

    conn = db()
    try:
        c = conn.cursor()
        # 現在の合計使用と合計補充を取得 (credit-status と同じロジック)
        c.execute("SELECT COALESCE(SUM(cost_usd), 0) FROM anthropic_usage_log")
        row = c.fetchone()
        try:
            total_used = float(row[0] or 0)
        except (TypeError, KeyError, IndexError):
            try: total_used = float(list(row.values())[0] or 0)
            except Exception: total_used = 0.0

        c.execute("SELECT COALESCE(SUM(amount_usd), 0) FROM anthropic_credit_recharge")
        row = c.fetchone()
        try:
            total_recharged = float(row[0] or 0)
        except (TypeError, KeyError, IndexError):
            try: total_recharged = float(list(row.values())[0] or 0)
            except Exception: total_recharged = 0.0

        delta = balance + total_used - total_recharged
        # delta が大きく負 (実残高 < 現在残高表示) なら警告 fields を返すが INSERT 自体は実行
        # (anthropic_credit_recharge は cumulative 履歴・負の値も OK で「補正」として記録)
        sync_note = f"{note} → balance=${balance:.2f} delta=${delta:.4f} (prev_recharged=${total_recharged:.2f} used=${total_used:.4f})"
        c.execute(
            "INSERT INTO anthropic_credit_recharge (amount_usd, note, recorded_by) VALUES (?, ?, ?)",
            (delta, sync_note[:300], recorded_by),
        )
        conn.commit()

        return {
            "ok": True,
            "balance_usd": round(balance, 2),
            "delta_inserted_usd": round(delta, 4),
            "prev_total_recharged_usd": round(total_recharged, 2),
            "prev_total_used_usd": round(total_used, 4),
            "new_total_recharged_usd": round(total_recharged + delta, 2),
            "remaining_now_usd": round(balance, 2),
            "recorded_by": recorded_by,
        }
    finally:
        conn.close()


@app.post("/api/admin/ai/test-anthropic-pdf")
def admin_test_anthropic_pdf(authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """🔬 Anthropic PDF 入力疎通確認 (2026-05-13 追加)
    PDF 専用テスト。最小 PDF (1 page・空白) を Anthropic に送り、PDF 処理機能が
    動作しているか確認する。塾長スクショの「PDF + 3 AI 全失敗」事故原因切分け用。
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    if not ANTHROPIC_API_KEY:
        return {"ok": False, "configured": False}

    # 最小 valid PDF (1 page・"hello" テキストのみ・~500 bytes)
    # PDF 1.4 minimum spec の base64 encoded blob
    minimal_pdf_b64 = (
        "JVBERi0xLjQKJeLjz9MKMyAwIG9iaiA8PCAvVHlwZSAvUGFnZSAvUGFyZW50IDIgMCBSIC9SZX"
        "NvdXJjZXMgPDwgL0ZvbnQgPDwgL0YxIDQgMCBSID4+ID4+IC9NZWRpYUJveCBbMCAwIDYxMiA3"
        "OTJdIC9Db250ZW50cyA1IDAgUiA+PiBlbmRvYmoKNCAwIG9iaiA8PCAvVHlwZSAvRm9udCAvU3"
        "VidHlwZSAvVHlwZTEgL0Jhc2VGb250IC9IZWx2ZXRpY2EgPj4gZW5kb2JqCjUgMCBvYmogPDwg"
        "L0xlbmd0aCA0NCA+PiBzdHJlYW0KQlQKL0YxIDI0IFRmCjUwIDcwMCBUZAooaGVsbG8pIFRqCk"
        "VUCmVuZHN0cmVhbQplbmRvYmoKMSAwIG9iaiA8PCAvVHlwZSAvQ2F0YWxvZyAvUGFnZXMgMiAw"
        "IFIgPj4gZW5kb2JqCjIgMCBvYmogPDwgL1R5cGUgL1BhZ2VzIC9LaWRzIFsgMyAwIFIgXSAvQ2"
        "91bnQgMSA+PiBlbmRvYmoKeHJlZgowIDYKMDAwMDAwMDAwMCA2NTUzNSBmCjAwMDAwMDAzNTcg"
        "MDAwMDAgbgowMDAwMDAwNDAyIDAwMDAwIG4KMDAwMDAwMDAwOSAwMDAwMCBuCjAwMDAwMDAxMj"
        "ggMDAwMDAgbgowMDAwMDAwMTkzIDAwMDAwIG4KdHJhaWxlciA8PCAvU2l6ZSA2IC9Sb290IDEg"
        "MCBSID4+CnN0YXJ0eHJlZgo0NTYKJSVFT0YK"
    )
    t0 = time.time()
    body = {
        "model": "claude-haiku-4-5",
        "max_tokens": 100,
        "messages": [{
            "role": "user",
            "content": [
                {"type": "document", "source": {"type": "base64", "media_type": "application/pdf", "data": minimal_pdf_b64}},
                {"type": "text", "text": "Read this PDF and tell me what word is on it. One word only."},
            ],
        }],
    }
    try:
        req = urllib.request.Request(
            "https://api.anthropic.com/v1/messages",
            data=json.dumps(body).encode("utf-8"),
            headers={"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=60) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            text = (data.get("content") or [{}])[0].get("text", "")
            return {
                "ok": True, "configured": True,
                "pdf_works": "hello" in text.lower(),
                "sample": text[:200],
                "latency_ms": int((time.time() - t0) * 1000),
            }
    except urllib.error.HTTPError as e:
        err_body = e.read().decode("utf-8", errors="ignore")
        return {
            "ok": False, "http_status": e.code,
            "error": err_body[:500],
            "diagnosis": "PDF サポートが PR 単位で利用不可・または beta 必須" if "document" in err_body.lower() or "pdf" in err_body.lower() else "Anthropic API 一般エラー (詳細は error)",
            "latency_ms": int((time.time() - t0) * 1000),
        }
    except Exception as e:
        return {"ok": False, "error": f"{type(e).__name__}: {str(e)[:300]}",
                "latency_ms": int((time.time() - t0) * 1000)}


@app.post("/api/admin/ai/test-openai-image")
def admin_test_openai_image(
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🔧 2026-05-23 DALL-E 3 diagnostic: raw OpenAI Image API error を返す debug endpoint。
    auth: admin Bearer or x-cron-secret。
    direct OpenAI API call で raw error body を返却 (本番 endpoint で 500 になる原因特定用)。"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    if not OPENAI_API_KEY:
        return {"ok": False, "configured": False, "error": "OPENAI_API_KEY not set"}

    import urllib.request as _ur
    import urllib.error as _ue
    # 🔧 2026-05-23 dall-e-3 廃止対応: gpt-image-1 (新 model) + quality=medium (低/中/高/auto に変更)
    body = {
        "model": "gpt-image-1",
        "prompt": "A simple test diagram for educational use: a triangle with labeled vertices A, B, C on white background.",
        "n": 1,
        "size": "1024x1024",
        "quality": "medium",
    }
    req = _ur.Request(
        "https://api.openai.com/v1/images/generations",
        data=json.dumps(body).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {OPENAI_API_KEY}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with _ur.urlopen(req, timeout=60) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        items = data.get("data") or []
        first = items[0] if items else {}
        return {
            "ok": True,
            "raw_keys": list(data.keys()),
            "items_count": len(items),
            "first_url_prefix": (first.get("url") or "")[:80],
            "first_b64_prefix": (first.get("b64_json") or "")[:80],
            "revised_prompt": first.get("revised_prompt"),
        }
    except _ue.HTTPError as e:
        # OpenAI から 4xx/5xx 返却 → raw error body を返す
        body_text = ""
        try:
            body_text = e.read().decode("utf-8")[:1000]
        except Exception:
            pass
        # 🛡️ 2026-05-23 security audit P3: API key prefix 漏洩防止 (4 文字のみ・accidental log/transcript 共有耐性)
        return {
            "ok": False, "http_status": e.code, "raw_error_body": body_text,
            "openai_key_prefix": OPENAI_API_KEY[:4] + "***",
            "request_body_sent": body,
        }
    except Exception as e:
        return {
            "ok": False, "exception": f"{type(e).__name__}: {str(e)[:500]}",
            "openai_key_prefix": OPENAI_API_KEY[:4] + "***",
        }


@app.post("/api/admin/ai/test-openai")
def admin_test_openai(model: Optional[str] = None,
                       authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """OpenAI Tier 5 fallback の動作確認 endpoint (2026-05-10 塾長指示)。
    admin Bearer or x-cron-secret 認証。OpenAI で 1 回 generate して
    {ok, model, sample, latency_ms} を返す。
    クエリ:
      - model=gpt-5 等で任意モデル指定 (省略時は OPENAI_MODEL = gpt-4o-mini)
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    if not OPENAI_API_KEY:
        return {
            "ok": False,
            "configured": False,
            "error": "OPENAI_API_KEY が Railway env に未設定。https://platform.openai.com/api-keys で発行してください。",
        }

    target_model = model or OPENAI_MODEL

    t0 = time.time()
    try:
        data = _call_openai(
            {
                "model": target_model,
                "max_tokens": 200,
                "system": "あなたは丁寧な日本語アシスタントです。",
                "messages": [{"role": "user", "content": "「AI never-fail テスト成功」とだけ短く返答してください。"}],
            },
            kind="test_openai",
        )
        text = (data.get("content") or [{}])[0].get("text", "") if data.get("content") else ""
        return {
            "ok": True,
            "configured": True,
            "model": data.get("_actual_model"),
            "provider": data.get("_provider"),
            "sample": text[:200],
            "latency_ms": int((time.time() - t0) * 1000),
            "usage": data.get("usage", {}),
        }
    except Exception as e:
        return {
            "ok": False,
            "configured": True,
            "error": f"{type(e).__name__}: {str(e)[:300]}",
            "latency_ms": int((time.time() - t0) * 1000),
        }


