@app.post("/api/admin/monitor/domain-check-now")
def admin_domain_check_now(authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """ドメイン状態 RDAP チェックを即時実行 (手動)。clientHold 等の異常検知時はアラートメール送信。
    interval 制限を bypass するが、rdap.org への DoS 防止のため 60 秒の手動 throttle あり。
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")
    # 手動 throttle: 60 秒に 1 回まで (rdap.org への配慮)
    now_ts = time.time()
    last_manual = _DOMAIN_MONITOR_LAST_CHECK.get("manual_ts", 0.0)
    if now_ts - last_manual < DOMAIN_MONITOR_MANUAL_THROTTLE_SEC:
        wait_sec = int(DOMAIN_MONITOR_MANUAL_THROTTLE_SEC - (now_ts - last_manual))
        return {"ran": False, "reason": "manual_throttle", "wait_seconds": wait_sec}
    _DOMAIN_MONITOR_LAST_CHECK["manual_ts"] = now_ts
    # interval ガード (kv_settings 永続) を bypass: kv 値を 0 に戻す
    _kv_set("domain_monitor_last_check_ts", "0")
    _DOMAIN_MONITOR_LAST_CHECK["ts"] = 0.0
    return _maybe_run_domain_status_check()


@app.post("/api/admin/monitor/whois-reminder-test")
def admin_whois_reminder_test(authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """Whois 認証年次リマインダーを今すぐテスト送信 (手動)。
    日付ガードと「今年送信済」ガードを bypass する。
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")
    # ガード bypass: anniversary - 30 日前の朝として振る舞う
    try:
        anni_m, anni_d = [int(x) for x in DOMAIN_REGISTRATION_ANNIVERSARY.split("-")]
    except Exception:
        anni_m, anni_d = 5, 6
    fake_date = datetime(datetime.now(JST_TZ_DOMAIN).year, anni_m, anni_d, 8, 0, 0, tzinfo=JST_TZ_DOMAIN) - timedelta(days=30)
    # 今年の dedup キーを消す
    year_key = str(fake_date.year)
    try:
        conn = db()
        c = conn.cursor()
        for db_target in [30, 7]:
            c.execute("DELETE FROM kv_settings WHERE key = ?", (f"whois_renewal_reminder_sent_{year_key}_minus_{db_target}d",))
        # 旧 key も互換で消去
        c.execute("DELETE FROM kv_settings WHERE key = ?", ("whois_renewal_reminder_last_year",))
        conn.commit()
        conn.close()
    except Exception:
        pass
    return _maybe_run_whois_renewal_reminder(fake_date)


# =====================================================================
# 💴 juku-payment クラウド sync (2026-05-07 追加)
# 月謝アプリ (~/ai-juku-system/payment/) の overrides を Railway Postgres
# (kv_settings table) に保存し、携帯/PC 間でデータ共有を実現する。
#
# 認証: 既存の admin Bearer token を流用 (新規認証フロー不要)
# 競合解決: シンプルな last-write-wins (= 最後の POST が勝つ)
#   塾長 1 人運用なので multi-writer 競合は実質発生しない。
# =====================================================================

JUKU_PAYMENT_KV_KEY = "juku_payment_overrides_v1"


@app.get("/api/juku-payment/overrides")
def juku_payment_get_overrides(authorization: Optional[str] = Header(None)):
    """juku-payment overrides (= payments / emails / payerNames / mailSent / status) を取得。
    Bearer token 認証必須 (admin)。"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Bearer token が必要です")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="管理者トークンが無効です")
    val = _kv_get(JUKU_PAYMENT_KV_KEY)
    # updated_at も取りたいので生 SQL (psycopg dict_row でも sqlite Row でも動くよう条件分岐)
    updated_at = None
    try:
        conn = db()
        c = conn.cursor()
        c.execute("CREATE TABLE IF NOT EXISTS kv_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)")
        c.execute("SELECT updated_at FROM kv_settings WHERE key = ?", (JUKU_PAYMENT_KV_KEY,))
        row = c.fetchone()
        conn.close()
        if row is not None:
            # Reviewer A HIGH: psycopg dict_row では row[0] が KeyError(0) になる致命パターン → name で取る
            ua = None
            try:
                ua = row["updated_at"]
            except (KeyError, IndexError, TypeError):
                # sqlite Row 互換 fallback
                try: ua = row[0]
                except Exception: ua = None
            if ua is not None:
                updated_at = ua.isoformat() if hasattr(ua, "isoformat") else str(ua)
    except Exception as e:
        log.warning(f"[JukuPay:get] updated_at fetch failed: {e}")
    return {
        "ok": True,
        "value": val,                      # JSON 文字列 (= STATE.overrides の JSON.stringify)
        "updated_at": updated_at,          # ISO 8601
        "exists": val is not None,
    }


@app.post("/api/juku-payment/overrides")
def juku_payment_set_overrides(payload: dict, authorization: Optional[str] = Header(None)):
    """juku-payment overrides を保存。
    payload: { "value": JSON 文字列 }"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Bearer token が必要です")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="管理者トークンが無効です")
    val = payload.get("value")
    if val is None:
        raise HTTPException(status_code=400, detail="value (JSON 文字列) が必要です")
    if not isinstance(val, str):
        # JSON object で送られた場合は str に変換
        try:
            val = json.dumps(val, ensure_ascii=False)
        except Exception:
            raise HTTPException(status_code=400, detail="value を JSON 化できません")
    # サイズ上限 (= 暴走/誤送信ガード): 5MB
    if len(val.encode("utf-8")) > 5 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="value が大きすぎます (上限 5MB)")
    ok = _kv_set(JUKU_PAYMENT_KV_KEY, val)
    if not ok:
        raise HTTPException(status_code=500, detail="保存に失敗しました")
    # 更新時刻を返す
    updated_at = datetime.now(timezone.utc).isoformat()
    return {"ok": True, "updated_at": updated_at, "size_bytes": len(val.encode("utf-8"))}


@app.get("/api/auth/me")
def auth_me(authorization: Optional[str] = Header(None)):
    """現在のセッションを検証して生徒情報を返す。全ページのアクセスガードに使う。
    + last_login_at を 4 時間以上前なら更新 (継続利用を「最終ログイン」に反映するため)"""
    student = _get_current_student(authorization)
    if not student:
        # 🚪 [login-allow-inactive] 2026-06-19 (方針A): トークンが有効な本人なら、体験切れ/未契約でも
        #   200 を返す (entitled=false)。auth-guard はこれを見てログインへ飛ばさず継続登録(upgrade.html)へ
        #   誘導する。有料 API は _get_current_student (厳格) のままなので無料開放にはならない。
        _tok = authorization[len("Bearer "):].strip() if (authorization and authorization.startswith("Bearer ")) else None
        _claims = _verify_session_token(_tok) if _tok else None
        if not _claims:
            raise HTTPException(status_code=401, detail="Unauthorized")
        _conn = db(); _c = _conn.cursor()
        try:
            _c.execute("SELECT id, name, email, grade, status, trial_end, course FROM students WHERE id = ?", (_claims["student_id"],))
            _row = _c.fetchone()
        finally:
            _conn.close()
        if not _row:
            raise HTTPException(status_code=401, detail="Unauthorized")
        return {"ok": True, "student": {
            "id": _row["id"], "name": _row["name"], "email": _row["email"],
            "grade": _row["grade"], "status": _row["status"], "course": _row["course"],
            "entitled": False, "access_status": _row["status"],
        }}
    # last_login_at リフレッシュ: 4 時間に 1 回まで (DB 書込抑制)
    try:
        last_login_raw = student.get("last_login_at")
        should_refresh = True
        if last_login_raw:
            try:
                if isinstance(last_login_raw, str):
                    last = datetime.fromisoformat(last_login_raw.replace("Z", "+00:00"))
                else:
                    last = last_login_raw
                if last.tzinfo is None: last = last.replace(tzinfo=timezone.utc)
                if (datetime.now(timezone.utc) - last).total_seconds() < 4 * 3600:
                    should_refresh = False
            except Exception:
                pass
        if should_refresh:
            conn = db()
            c = conn.cursor()
            try:
                c.execute("UPDATE students SET last_login_at = CURRENT_TIMESTAMP WHERE id = ?", (student["id"],))
                conn.commit()
            finally:
                conn.close()
    except Exception as _e:
        log.warning(f"[auth_me] last_login_at refresh skipped: {_e}")
    # 🚪 [cancel-period-end] (2026-06-12): 解約予約 (cancel_at_period_end) の期間末時刻を mypage に渡す。
    # _get_current_student の共通 SELECT (全 API の hot path) には列を足さず、ページロード時の auth/me
    # でのみ 1 クエリ追加で取得。tz-naive (PG の TIMESTAMP は naive で返る・書込は常に UTC) は UTC を
    # 付与して ISO で返し、ブラウザ側 new Date() の JST 解釈ずれ (日付が前後する) を防ぐ。
    # 旧 DB (列未追加) で SELECT が失敗しても auth/me 自体は落とさない (magic-link の fallback と同思想)。
    student["cancel_at"] = None
    try:
        conn = db()
        try:
            c = conn.cursor()
            c.execute("SELECT cancel_at FROM students WHERE id = ?", (student["id"],))
            _ca_row = c.fetchone()
        finally:
            conn.close()
        _ca_val = _ca_row["cancel_at"] if _ca_row else None
        if _ca_val:
            if isinstance(_ca_val, str):
                _ca_dt = datetime.fromisoformat(_ca_val.replace("Z", "+00:00"))
            else:
                _ca_dt = _ca_val
            if _ca_dt.tzinfo is None:
                _ca_dt = _ca_dt.replace(tzinfo=timezone.utc)
            student["cancel_at"] = _ca_dt.isoformat()
    except Exception as _cae:
        log.warning(f"[auth_me] cancel_at fetch skipped: {_cae}")
    student["entitled"] = True  # 🚪 [login-allow-inactive] active 本人。auth-guard は entitled で分岐。
    return {"ok": True, "student": student}


# ==========================================================================
# 紹介ループ API (mypage で生徒が自分の紹介URLを取得 / 紹介状況を確認)
# ==========================================================================
@app.get("/api/referral/my-link")
def referral_my_link(authorization: Optional[str] = Header(None)):
    """ログイン中の生徒の紹介URL + 集計を返す。
    - link: 共有用URL (LP に ?ref= 付き)
    - invited: 紹介で申込された数
    - paid: 紹介経由で paid 化した数 (=¥3,000 OFF クーポン獲得回数)
    - reward_yen: 累計獲得割引額 (paid 数 × 3000)
    """
    student = _get_current_student(authorization, allow_canceled=True)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    sid = student["id"]
    code = _generate_referral_code(sid)
    link = f"{BASE_URL}/?ref={code}"

    conn = db()
    c = conn.cursor()
    try:
        c.execute("SELECT COUNT(*) AS n FROM referrals WHERE referrer_id=?", (sid,))
        invited = c.fetchone()["n"]
        c.execute("SELECT COUNT(*) AS n FROM referrals WHERE referrer_id=? AND referred_paid_at IS NOT NULL", (sid,))
        paid = c.fetchone()["n"]
    finally:
        conn.close()

    return {
        "ok": True,
        "link": link,
        "code": code,
        "invited": invited,
        "paid": paid,
        "reward_yen": paid * 3000,
        "reward_per_referral_yen": 3000,
    }


@app.get("/api/referral/verify")
def referral_verify(request: Request, code: str = ""):
    """LP 側で ?ref=XXX を検証する公開 endpoint。表示文言を変える時のみ呼ぶ (UI 装飾用)。
    認証不要だが、有効なコードかどうかだけを返す (referrer の個人情報は返さない)。
    Anti-enum: 1 IP あたり 5分で 30回まで (oracle attack 抑制)。"""
    _check_rate_limit_ip(request, bucket="referral_verify", limit=30, window=300)
    code = (code or "").strip()
    if not code:
        return {"valid": False}
    rid = _verify_referral_code(code)
    if not rid:
        return {"valid": False}
    return {"valid": True}


@app.get("/api/admin/referrals")
def admin_referrals_summary(authorization: Optional[str] = Header(None)):
    """CEOダッシュ用: 紹介経路サマリ。
    - total: 総紹介申込数
    - paid: 成立 (被紹介者が paid 化) した数
    - pending: 紹介申込済だが未成立
    - top_referrers: 上位5名 (紹介者ごとの招待数)
    - reward_total_yen: 紹介者に支払った累計クーポン金額
    """
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="セッション期限切れ")

    conn = db()
    c = conn.cursor()
    try:
        c.execute("SELECT COUNT(*) AS n FROM referrals")
        total = c.fetchone()["n"]
        c.execute("SELECT COUNT(*) AS n FROM referrals WHERE referred_paid_at IS NOT NULL")
        paid = c.fetchone()["n"]
        c.execute("SELECT COUNT(*) AS n FROM referrals WHERE coupon_applied_at IS NOT NULL")
        rewarded = c.fetchone()["n"]
        c.execute(
            """SELECT r.referrer_id, s.name, s.email, COUNT(*) AS invited,
                      SUM(CASE WHEN r.referred_paid_at IS NOT NULL THEN 1 ELSE 0 END) AS converted
               FROM referrals r
               LEFT JOIN students s ON s.id = r.referrer_id
               GROUP BY r.referrer_id, s.name, s.email
               ORDER BY invited DESC LIMIT 5"""
        )
        top = []
        for row in c.fetchall():
            top.append({
                "referrer_id": row["referrer_id"],
                "name": row["name"] or "",
                "email": row["email"] or "",
                "invited": row["invited"],
                "converted": row["converted"] or 0,
            })
    finally:
        conn.close()
    return {
        "total": total,
        "paid": paid,
        "rewarded": rewarded,
        "pending": max(0, total - paid),
        "reward_total_yen": rewarded * 3000,
        "top_referrers": top,
    }


def _get_waiver_count() -> int:
    """これまでキャンペーンで入塾金免除を受けた生徒数を返す。
    enrollment_waiver_applied_at IS NOT NULL で絞ることで、
    キャンペーン開始前の既存 paid 顧客 (waived=0 のまま) や
    手動で waived=1 にした旧データを除外する。"""
    conn = db()
    c = conn.cursor()
    c.execute(
        "SELECT COUNT(*) AS n FROM students "
        "WHERE enrollment_fee_waived = 1 AND enrollment_waiver_applied_at IS NOT NULL"
    )
    row = c.fetchone()
    conn.close()
    return int(row["n"]) if row else 0


def _is_waiver_eligible() -> bool:
    """現時点で入塾金免除キャンペーンの枠が残っているか。"""
    if not ENROLLMENT_WAIVER_CAMPAIGN_ENABLED:
        return False
    return _get_waiver_count() < ENROLLMENT_WAIVER_LIMIT


@app.get("/api/campaigns/enrollment-waiver/status")
def waiver_status():
    """入塾金免除キャンペーンの残枠を返す (公開エンドポイント)。
    LP/checkout のバナー表示に使用。"""
    used = _get_waiver_count()
    remaining = max(0, ENROLLMENT_WAIVER_LIMIT - used)
    return {
        "enabled": ENROLLMENT_WAIVER_CAMPAIGN_ENABLED,
        "limit": ENROLLMENT_WAIVER_LIMIT,
        "used": used,
        "remaining": remaining,
        "is_active": ENROLLMENT_WAIVER_CAMPAIGN_ENABLED and remaining > 0,
        "discount_amount": ENROLLMENT_FEE,
    }


@app.get("/api/usage/me")
def usage_me(authorization: Optional[str] = Header(None)):
    """ログイン中の生徒の今月の使用回数 + プラン上限 + AI 質問累計を返す。
    フロントの「残り○回」表示・アップグレード誘導 + 「AI質問数」スタッツ表示に使用。"""
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    # 実効プラン (status='trial' は希望プランを無視して一律 trial — _effective_quota_plan 参照)。
    # レスポンスの "plan" もこの実効値を返す: 体験中の生徒に希望プラン名 (創設メンバー等) と
    # 無制限表示を誤って見せず、mypage の利用状況パネルがトライアル表示+残回数で一貫する。
    plan = _effective_quota_plan(student)
    # 国公立難関大学コース = premium 同等 → 全機能無制限 (塾長指示)
    _u_course = student.get("course")
    if _u_course == "kokuritsu_nankan":
        quotas = PLAN_QUOTAS.get("premium", PLAN_QUOTAS["trial"])
    else:
        quotas = PLAN_QUOTAS.get(plan, PLAN_QUOTAS["trial"])
    used = _get_all_monthly_usage(int(student["id"]))
    out = {}
    for feature in QUOTA_FEATURES:
        limit = quotas.get(feature)
        used_count = used.get(feature, 0)
        out[feature] = {
            "limit": limit,
            "used": used_count,
            "remaining": (None if limit is None else max(0, limit - used_count)),
        }
    # AI 質問累計 (events テーブルから取得・端末跨ぎでも正確)
    # NOTE: events.session_id は "123" と "student:123" 両形式が混在 (legacy 不整合)
    ai_total = 0
    ai_today = 0
    try:
        conn = db()
        c = conn.cursor()
        sid_str = str(student['id'])
        sid_prefixed = f"student:{sid_str}"
        c.execute(
            "SELECT COUNT(*) AS n FROM events WHERE session_id IN (?, ?) AND name LIKE 'ai_call_%'",
            (sid_str, sid_prefixed)
        )
        ai_total = c.fetchone()["n"]
        # 今日 (JST) のカウント
        now_jst = datetime.now(timezone.utc) + timedelta(hours=9)
        today_start_jst = now_jst.replace(hour=0, minute=0, second=0, microsecond=0)
        today_start_utc = today_start_jst - timedelta(hours=9)
        c.execute(
            "SELECT COUNT(*) AS n FROM events WHERE session_id IN (?, ?) AND name LIKE 'ai_call_%' AND created_at >= ?",
            (sid_str, sid_prefixed, today_start_utc.isoformat())
        )
        ai_today = c.fetchone()["n"]
        conn.close()
    except Exception as _e:
        log.warning(f"[usage_me] ai_call count failed: {_e}")
    return {
        "ok": True,
        "plan": plan,
        "year_month": _jst_year_month(),
        "usage": out,
        "ai_questions": {"total": ai_total, "today": ai_today},
    }


@app.post("/api/trial/signup")
def trial_signup(payload: TrialSignup, request: Request):
    # レート制限 (4番手 監査 2026-04-30): 1 IP あたり 5分で 3 申込まで。
    # Resend 経由で welcome email を送るため、無制限だと
    # (1) Resend abuse 判定で送信ブロック、(2) DB に dummy student を量産される。
    # 🛡️ 2026-05-21: 同 Wi-Fi の家族・兄弟同時申込み + 入力ミス再試行による偶発抵触を
    # 軽減するため 3→5 に緩和 (限度の妥当性は週次で events.rate_limit_hit を確認)。
    _check_rate_limit_ip(request, bucket="trial_signup", limit=5, window=300)

    # 入力検証: TrialSignup の field_validator (フルネーム必須・XSS 対策) は通過済み。
    # メール小文字化 + grade/goal/plan の長さ制限 (XSS 対策の二重防御)
    email_norm = (payload.email or "").lower().strip()
    if not email_norm:
        raise HTTPException(status_code=400, detail="Email required")
    student_email_norm = (payload.student_email or "").lower().strip()
    grade = (payload.grade or "")[:50]
    goal = (payload.goal or "")[:500]
    plan = (payload.plan or "hybrid")[:50]
    # 📊 集客 attribution (2026-05-19): フロントから送信された utm を最大長 cap 付きで保存
    utm_source = (payload.utm_source or "")[:50] or None
    utm_content = (payload.utm_content or "")[:100] or None
    utm_campaign = (payload.utm_campaign or "")[:100] or None
    lp_variant = (payload.lp_variant or "")[:50] or None
    referrer = (payload.referrer or "")[:500] or None

    now = datetime.now(timezone.utc)
    trial_end = now + timedelta(days=FOUNDER_TRIAL_DAYS)  # 14 日間の完全無料体験 (2026-05-19 拡張)
    conn = db()
    c = conn.cursor()

    # 🛡️ 2026-06-12 security MEDIUM fix: student_email が「他生徒の親 email / 子メール」と
    # 一致する申込を拒否。放置すると攻撃者が既存生徒の保護者・子のアドレスを自分の
    # student_email に設定し、magic-link 再発行を繰り返して攻撃者アカウントの OTP メールを
    # その相手へ送り付けられる (メール爆撃 + 攻撃者アカウントへの誤ログイン誘導)。
    # さらに重複したまま保存すると、ログイン検索 (親メール優先 ORDER BY → id 昇順) は常に
    # 既存側の生徒を選ぶため、このアドレスでのログインがサイレントに壊れる
    # (admin_set_student_email 側の同種チェックと整合)。
    # 自分自身の行 (再申込で email_norm が一致する行) は除外 — 同一生徒の再申込で自分の
    # 既存 student_email を再入力しても誤って拒否しない。
    # NOTE: この 400 は「登録済みアドレスか」の列挙オラクルになり得るが、trial_signup の
    # rate limit (5回/5分/IP) で抑制済み + 爆撃実害の防止を優先 (列挙対策より被害が大きい)。
    if student_email_norm and student_email_norm != email_norm:
        c.execute(
            "SELECT 1 FROM students WHERE LOWER(email) != ? "
            "AND (LOWER(email) = ? OR LOWER(COALESCE(student_email, '')) = ?) LIMIT 1",
            (email_norm, student_email_norm, student_email_norm),
        )
        if c.fetchone():
            conn.close()
            raise HTTPException(
                status_code=400,
                detail="この生徒用メールアドレスは使用できません。別のアドレスを指定するか、空欄でお申し込みください（ログイン用リンクは保護者用メールに届きます）。",
            )

    is_existing = False
    try:
        c.execute(
            """INSERT INTO students (name, email, student_email, grade, goal, plan, status, trial_start, trial_end,
                signup_utm_source, signup_utm_content, signup_utm_campaign, signup_lp_variant, signup_referrer)
               VALUES (?, ?, ?, ?, ?, ?, 'trial', ?, ?, ?, ?, ?, ?, ?)
               RETURNING id""",
            (payload.name, email_norm, student_email_norm, grade, goal,
             plan, now.isoformat(), trial_end.isoformat(),
             utm_source, utm_content, utm_campaign, lp_variant, referrer)
        )
        returned = c.fetchone()
        student_id = returned["id"] if returned else None
        conn.commit()
        # 🛡️ 2026-06-12 security review: 新規行の student_email はこの申込で初めて設定された
        # = 未確認 (student_email_verified は DEFAULT 0)。welcome は magicv リンクで送る。
        student_email_newly_set = bool(student_email_norm)
    except IntegrityError:
        # 既存メール: 同一 email の student_id を返す。
        # paid ユーザーは plan/status を変更しない (誤って ¥14,500 → trial 降格させない)。
        # trial 期限切れ/canceled は trial を再延長 (リカバリ申込として扱う)。
        conn.rollback()
        is_existing = True
        student_email_newly_set = False
        c.execute("SELECT id, status, trial_end, student_email FROM students WHERE LOWER(email) = ? LIMIT 1", (email_norm,))
        row = c.fetchone()
        student_id = row["id"] if row else None
        if not student_id:
            conn.close()
            raise HTTPException(status_code=400, detail="Email conflict")
        # 既存行の student_email が空で、今回の申込が新値を持つ場合のみ「新規設定」扱い
        # (下の UPDATE は CASE で空の時だけ埋める。既存値がある再申込では上書きも再送もしない —
        #  これが無いと同一親メールの再 POST のたびに任意の student_email へ welcome を
        #  送れてしまう: security review 2026-06-11 の反復送信ベクター)。
        _prior_child_email = ((row["student_email"] if "student_email" in row.keys() else "") or "").strip()
        try:
            existing_status = row["status"] if row else None
            prev_trial_end = row["trial_end"] if row else None
            # 🚫 無限トライアル抑制 (2026-05-29): 直前 trial 終了から COOLDOWN 日未満の再申込では
            # 新しい 14 日体験を付与しない。expired→即再申込 を繰り返して永久に無料で使う抜け道を遮断する。
            # ・paid / past_due は一切変更しない (paid を trial 降格させない / 決済失敗者に無料体験を与えない)
            # ・canceled (旧 paid の出戻り) は win-back として常に許可
            # ・再エンゲージメント funnel のフォローメールは有料 checkout へ誘導しているため funnel は阻害しない
            TRIAL_REGRANT_COOLDOWN_DAYS = 60
            allow_regrant = False
            if existing_status == "canceled":
                allow_regrant = True
            elif existing_status in ("trial", "expired", None, ""):
                if not prev_trial_end:
                    allow_regrant = True
                else:
                    try:
                        if isinstance(prev_trial_end, str):
                            _pte = datetime.fromisoformat(prev_trial_end.replace("Z", "+00:00"))
                        else:
                            _pte = prev_trial_end
                        if _pte.tzinfo is None:
                            _pte = _pte.replace(tzinfo=timezone.utc)
                        if (now - _pte) >= timedelta(days=TRIAL_REGRANT_COOLDOWN_DAYS):
                            allow_regrant = True
                    except Exception:
                        allow_regrant = True  # parse 失敗時は安全側 (ユーザー体験優先) で従来通り許可
            if existing_status not in ("paid", "past_due"):
                if allow_regrant:
                    # 既存生徒の student_email も更新 (空白のままなら新値で上書き、既存値があれば保持)
                    c.execute(
                        """UPDATE students SET status='trial', trial_start=?, trial_end=?,
                           student_email = CASE WHEN COALESCE(student_email, '') = '' THEN ? ELSE student_email END,
                           updated_at=CURRENT_TIMESTAMP
                           WHERE id=?""",
                        (now.isoformat(), trial_end.isoformat(), student_email_norm, student_id)
                    )
                    conn.commit()
                    log.info(f"[Signup] Re-activated trial for existing student {student_id} ({email_norm}) prev_status={existing_status}")
                else:
                    # クールダウン中: 体験は再付与せず status/データ据え置き。student_email だけ補完。
                    c.execute(
                        """UPDATE students SET
                           student_email = CASE WHEN COALESCE(student_email, '') = '' THEN ? ELSE student_email END,
                           updated_at=CURRENT_TIMESTAMP
                           WHERE id=?""",
                        (student_email_norm, student_id)
                    )
                    conn.commit()
                    log.info(f"[Signup] Trial re-grant SKIPPED (cooldown {TRIAL_REGRANT_COOLDOWN_DAYS}d) student {student_id} ({email_norm}) prev_status={existing_status} prev_trial_end={prev_trial_end}")
                # 上の UPDATE (CASE) で空欄→新値が実際に保存されたケースのみ welcome 対象
                if student_email_norm and not _prior_child_email:
                    student_email_newly_set = True
        except Exception as _e:
            log.warning(f"[Signup] re-activation update failed for student {student_id}: {_e}")
    conn.close()

    log.info(f"Trial signup: {email_norm} -> student_id={student_id} existing={is_existing}")

    # 紹介ループ: ?ref= が指定されていて、新規申込 (=既存ユーザーでない) なら referrals に記録。
    # 既存ユーザーの再申込時は記録しない (再活性化は紹介報酬対象外)。
    # Anti-fraud: 同一 referrer から大量招待 = 自己アカウント生成攻撃を防ぐため、
    # 直近24h で同じ referrer による招待が10件超なら拒否 (小規模塾なので本数で十分)。
    ref_code = (payload.ref or "").strip()
    if ref_code and student_id and not is_existing:
        try:
            referrer_id = _verify_referral_code(ref_code)
            if not referrer_id:
                log.warning(f"[Referral] invalid ref code: code={ref_code[:20]} student={student_id}")
            elif referrer_id == student_id:
                log.warning(f"[Referral] self-referral blocked: student={student_id}")
            else:
                _conn = db(); _c = _conn.cursor()
                try:
                    # Anti-fraud 1: referrer の直近24h招待数チェック
                    yesterday = (datetime.now(timezone.utc) - timedelta(hours=24)).isoformat()
                    _c.execute(
                        "SELECT COUNT(*) AS n FROM referrals WHERE referrer_id=? AND created_at > ?",
                        (referrer_id, yesterday)
                    )
                    recent_count = _c.fetchone()["n"]
                    # Anti-fraud 2: 同じ email ドメイン (個人 gmail 等) の自己招待を抑制
                    # 同一 referrer × 同一被招待 email ドメイン (gmail/yahoo 等の汎用以外) で2件以上は拒否
                    domain = email_norm.split("@")[-1] if "@" in email_norm else ""
                    is_carrier_or_generic = domain in (
                        "gmail.com", "yahoo.co.jp", "yahoo.com", "icloud.com", "outlook.com",
                        "hotmail.com", "live.com", "ezweb.ne.jp", "docomo.ne.jp", "softbank.ne.jp",
                        "i.softbank.jp", "au.com", "ymobile.ne.jp"
                    )
                    domain_dup_count = 0
                    if domain and not is_carrier_or_generic:
                        _c.execute(
                            """SELECT COUNT(*) AS n FROM referrals r
                               JOIN students s ON s.id = r.referred_id
                               WHERE r.referrer_id=? AND LOWER(s.email) LIKE ?""",
                            (referrer_id, f"%@{domain}")
                        )
                        domain_dup_count = _c.fetchone()["n"]

                    if recent_count >= 10:
                        log.warning(f"[Referral] referrer {referrer_id} rate-limited (24h count={recent_count})")
                    elif domain_dup_count >= 2:
                        log.warning(f"[Referral] referrer {referrer_id} suspicious same-domain ({domain}) count={domain_dup_count}")
                    else:
                        try:
                            _c.execute(
                                """INSERT INTO referrals (referrer_id, referred_id, code) VALUES (?, ?, ?)""",
                                (referrer_id, student_id, ref_code)
                            )
                            _conn.commit()
                            log.info(f"[Referral] new: referrer={referrer_id} referred={student_id}")
                        except IntegrityError:
                            _conn.rollback()
                            log.info(f"[Referral] already linked for student {student_id}")
                finally:
                    _conn.close()
        except Exception as e:
            log.warning(f"[Referral] tracking failed: {type(e).__name__}: {e}")

    # 🔥 致命傷修正 (2026-04-29): 申込直後に magic link 招待メールを送信
    # これが無いと顧客はログイン経路を知らず、ダッシュ未利用 = 価値ゼロ。
    # 失敗しても signup 自体は成功させる (顧客は admin から再送信で救済可能)。
    # 🔥 2026-05-01: 生徒メール (任意) が指定されていれば、両方に送信 (子供の端末でログイン可能に)
    email_sent = False
    email_error = None
    student_email_sent = False
    if student_id:
        try:
            # [otp-keep-old-codes] 重複申込時も旧 OTP は無効化しない (届いている古いコードでも
            #   ログイン可能に・整理は _create_otp の上限 GC のみ)。
            # 1時間有効な短命 magic link token (4番手 監査 2026-04-30)
            session_token = _create_magic_link_token(student_id)
            magic_url = f"{BASE_URL}/auth.html?t={session_token}"
            otp_code = _create_otp(student_id)
            result = _send_magic_link_with_retry(
                email_norm,
                payload.name or "",
                magic_url,
                otp_code=otp_code,
                is_welcome=True,
            )
            email_sent = bool(result.get("sent"))
            if not email_sent:
                email_error = (result or {}).get("error", "send_failed")
                log.error(f"[Signup] Welcome email failed for student {student_id} ({email_norm}): {email_error}")
            # 生徒メール (任意) にも送信 (失敗しても親メールが届いていれば OK 扱い)
            # 🛡️ 2026-06-12 security review: 「この申込で新規に保存された」場合のみ送信
            # (student_email_newly_set)。既存値ありの再 POST では送らない — 同一親メールの
            # 再申込連打を任意アドレスへの送信装置にさせない。
            # リンクは親と共通の magic_url ではなく magicv トークン (子メール宛にのみ届く):
            # クリック = アドレス到達の証明として /api/auth/verify が student_email_verified=1
            # を立て、以後の magic-link 再発行が子にも届くようになる (未確認のままなら親のみ)。
            if student_email_newly_set and student_email_norm and student_email_norm != email_norm:
                try:
                    child_token = _create_student_email_verify_token(student_id, student_email_norm)
                    child_magic_url = f"{BASE_URL}/auth.html?t={child_token}"
                    student_result = _send_magic_link_with_retry(
                        student_email_norm,
                        payload.name or "",
                        child_magic_url,
                        otp_code=otp_code,
                        is_welcome=True,
                        is_child_verify=True,
                    )
                    student_email_sent = bool(student_result.get("sent"))
                    log.info(f"[Signup] Student-email send for {student_id}: sent={student_email_sent} ({student_email_norm})")
                except Exception as se:
                    log.warning(f"[Signup] Student-email send exception for {student_id}: {se}")
                # 📋 audit (security review ③): 自己登録による student_email 設定を events に記録
                # (admin 設定時の student_email_set と同名 event・actor で区別。CEO ダッシュの
                #  未確認バッジと合わせて「誰がいつ設定した子メールか」を追跡可能にする)
                try:
                    conn_a = db(); c_a = conn_a.cursor()
                    c_a.execute(
                        "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                        ("student_email_set", json.dumps({
                            "student_id": student_id,
                            "new_domain": (student_email_norm.split("@")[-1] if "@" in student_email_norm else None),
                            "actor": "self_signup",
                            "verified": False,
                        }, ensure_ascii=False), f"student:{student_id}")
                    )
                    conn_a.commit(); conn_a.close()
                except Exception as _ae:
                    log.warning(f"[Signup] student_email_set event record failed: {_ae}")
        except Exception as e:
            email_error = f"{type(e).__name__}: {e}"
            log.error(f"[Signup] Welcome email exception for student {student_id} ({email_norm}): {email_error}")

    # 監視: events に signup_email_status を記録 (CEO ダッシュ監視・自動 nudge 用)
    try:
        conn2 = db(); cc = conn2.cursor()
        cc.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            (
                "signup_email_status",
                json.dumps({"student_id": student_id, "email_sent": email_sent, "error": email_error[:200] if email_error else None}, ensure_ascii=False),
                f"student:{student_id}",
            ),
        )
        conn2.commit(); conn2.close()
    except Exception as _e:
        log.warning(f"[Signup] failed to record signup_email_status event: {_e}")

    return {
        "ok": True,
        "student_id": student_id,
        "trial_end": trial_end.isoformat(),
        "email_sent": email_sent,  # フロント (checkout-success.html) で「メール届かなかった場合は…」案内に使う
        "student_email_sent": student_email_sent,  # 生徒メール (任意) への送信成否
    }

# ==========================================================================
# Routes: Stripe Checkout
# ==========================================================================
@app.post("/api/stripe/trial-checkout")
def create_trial_checkout(payload: dict):
    """14日間 完全無料 体験 (GW 集中体験戦略)。Stripe 決済は発生しない。
    創設メンバー50名枠は本契約 (paid) のみでカウント。体験は無制限に受付。
    2026-05-07: 通塾生プラン (student_addon) は invite_code 検証必須化 (Reviewer A CRITICAL #1)
    2026-05-19: enable_card_for_extension=True で Stripe Subscription (21 日 trial) ルートを追加。
       クレカ事前登録 → trial 期間 +7 日 (合計 21 日) → 自動課金 paid 化を opt-in で実現。
       未 opt-in は従来通り完全無料 14 日体験 (free=True 即時 success)。
    """
    email = (payload.get("email") or "").strip()
    name = (payload.get("name") or "").strip()
    student_id = payload.get("student_id")
    invite_code = (payload.get("invite_code") or "").strip()
    plan_hint = (payload.get("plan") or "").strip()  # フロントが送ってくれる場合のヒント
    enable_card_extension = bool(payload.get("enable_card_for_extension", False))  # 🎁 2026-05-19 +7 日延長 opt-in
    if not email:
        raise HTTPException(status_code=400, detail="email required")

    # 通塾生プラン (student_addon) は招待コード必須 + 検証
    # フロントの guard はバイパス可能 (DevTools) なので server side で必ず検証
    if plan_hint == "student_addon" or invite_code:
        if not invite_code:
            raise HTTPException(status_code=400, detail="通塾生プランをご利用には塾長から発行された招待コードが必要です。")
        try:
            inv = _verify_invite_token(invite_code)
        except HTTPException:
            raise
        except Exception as e:
            log.warning(f"[trial-checkout] invite verify failed: {e}")
            raise HTTPException(status_code=401, detail="招待コードが無効または期限切れです。塾長にご確認ください。")
        # invite token の email と payload.email の一致を検証 (他人の招待を流用させない)
        token_email = (inv.get("email") or "").strip().lower()
        payload_email = email.strip().lower()
        if token_email and token_email != payload_email:
            log.warning(f"[trial-checkout] invite email mismatch: token={token_email} payload={payload_email}")
            raise HTTPException(status_code=401, detail="招待コードと入力されたメールアドレスが一致しません。塾長にご確認ください。")
        log.info(f"[trial-checkout] invite verified: email={payload_email}")

    # 🎁 2026-05-19 +7 日延長 opt-in: Stripe Subscription with trial_period_days=21
    # クレカ事前登録 → 21 日無料 → 終了後自動課金 (founder_special ¥14,500/月)
    # ユーザーは Stripe customer portal でいつでも解約可能 (課金前にキャンセル可)
    EXTENDED_TRIAL_DAYS = FOUNDER_TRIAL_DAYS + 7  # 14 + 7 = 21 日
    if enable_card_extension and STRIPE_SECRET_KEY:
        try:
            s = get_stripe()
            # founder_special price 取得 (lookup_key or env から)
            founder_price_id = _lookup_plan_price_id("founder_special")
            if not founder_price_id:
                log.warning("[trial-checkout +7d] founder_special price not configured, falling back to free trial")
                # フォールバック: 通常の無料体験
            else:
                session = s.checkout.Session.create(
                    mode="subscription",
                    payment_method_types=["card"],
                    line_items=[{"price": founder_price_id, "quantity": 1}],
                    subscription_data={
                        "trial_period_days": EXTENDED_TRIAL_DAYS,  # 21 日無料
                        "metadata": {
                            "purchase_type": "trial_extended",
                            "student_id": str(student_id or ""),
                            "name": name,
                            "trial_days": str(EXTENDED_TRIAL_DAYS),
                        },
                        # trial 終了直前にメール通知を Stripe からも送る (二重防御)
                        "trial_settings": {"end_behavior": {"missing_payment_method": "cancel"}},
                    },
                    customer_email=email,
                    success_url=f"{BASE_URL}/checkout-success.html?session_id={{CHECKOUT_SESSION_ID}}&extended=1&purchase=trial_extended",
                    cancel_url=f"{BASE_URL}/checkout-cancel.html",
                    metadata={
                        "purchase_type": "trial_extended",
                        "student_id": str(student_id or ""),
                        "name": name,
                    },
                    # 解約しやすさを担保 (顧客自身が Stripe Portal で解約可)
                    allow_promotion_codes=False,
                )
                log.info(f"[trial-checkout +7d] Stripe subscription session created: id={session.id}, email={email}, trial_days={EXTENDED_TRIAL_DAYS}")
                return {
                    "extended": True,
                    "checkout_url": session.url,
                    "session_id": session.id,
                    "trial_days": EXTENDED_TRIAL_DAYS,
                    "note": "クレジットカード登録後、21 日間 完全無料。trial 終了 24 時間前に Stripe からメール通知あり。",
                }
        except Exception as e:
            log.error(f"[trial-checkout +7d] Stripe session creation failed: {type(e).__name__}: {e}")
            # フォールバック: 通常の無料体験に降格 (ユーザー体験継続性確保)

    # 完全無料体験: Stripe をスキップして即時 success ページへ (デフォルト経路)
    if FOUNDER_TRIAL_PRICE == 0:
        return {
            "free": True,
            "checkout_url": f"{BASE_URL}/checkout-success.html?session_id=free_trial&student_id={student_id or ''}&purchase=trial",
            "amount": 0,
            "trial_days": FOUNDER_TRIAL_DAYS,
        }

    # 以下、有償体験に戻す場合のフォールバック (現状は使用されない)
    conn_fc = db()
    c_fc = conn_fc.cursor()
    try:
        c_fc.execute(
            # past_due (決済失敗の猶予中) も枠を占有しているとみなす (回復見込みのため枠を空けない・2026-05-29)
            "SELECT COUNT(*) FROM students WHERE status IN ('paid','past_due') AND plan IS NOT NULL AND plan != 'student_addon'"
        )
        taken = c_fc.fetchone()[0]
    except Exception:
        taken = 0
    conn_fc.close()
    if taken >= FOUNDER_LIMIT and not student_id:
        raise HTTPException(
            status_code=403,
            detail=f"創設メンバー{FOUNDER_LIMIT}名の募集は終了しました。次期募集をお待ちください。"
        )

    if not STRIPE_SECRET_KEY:
        return {
            "mock": True,
            "checkout_url": f"{BASE_URL}/checkout-success.html?session_id=mock_trial&purchase=trial",
            "amount": FOUNDER_TRIAL_PRICE,
        }

    s = get_stripe()
    session = s.checkout.Session.create(
        mode="payment",
        payment_method_types=["card"],
        line_items=[{
            "price_data": {
                "currency": "jpy",
                "product_data": {
                    "name": f"AIコーチング - {FOUNDER_TRIAL_DAYS}日間体験",
                    "description": f"AIチューター・教材生成・学習分析をフル活用できる{FOUNDER_TRIAL_DAYS}日間。"
                },
                "unit_amount": FOUNDER_TRIAL_PRICE,
            },
            "quantity": 1,
        }],
        customer_email=email,
        success_url=f"{BASE_URL}/checkout-success.html?session_id={{CHECKOUT_SESSION_ID}}&purchase=trial",
        cancel_url=f"{BASE_URL}/checkout-cancel.html",
        metadata={
            "purchase_type": "trial",
            "student_id": str(student_id or ""),
            "name": name,
        }
    )
    return {
        "checkout_url": session.url,
        "session_id": session.id,
        "amount": FOUNDER_TRIAL_PRICE,
    }


def _mask_email_for_display(addr: str) -> str:
    """メールアドレスをマスク表示用に変換 (pa***@example.com)。
    checkout 応答で平文の親メールを返すと「子メール → 親メール」の無認証開示オラクルに
    なるため、API 応答には必ずマスク済みを載せる (2026-06-12 review 指摘)。"""
    try:
        local, _, domain = (addr or "").partition("@")
        if not local or not domain:
            return ""
        keep = 2 if len(local) >= 3 else 1
        return local[:keep] + "***@" + domain
    except Exception:
        return ""


@app.post("/api/stripe/checkout")
def create_checkout_session(payload: CheckoutRequest, request: Request):
    """
    新プラン構造でのチェックアウト:
    - 創設メンバープラン (founder_special): 永年¥14,500/月 (50名限定・全機能無制限)
    - 通常プラン (premium/family): 月額サブスク
    - 通塾生プラン (student_addon): ¥5,000/月・**招待コード必須** (HMAC トークン)
    - 体験は別途 /api/stripe/trial-checkout で 14日間 完全無料 (Stripe を経由しない)
    """
    # 🛡️ 2026-06-12 review 指摘: この endpoint は未認証なのに rate limit が無く、
    # 400/200 の応答差で登録済みアドレス (親+子) を無制限列挙できた。verify-code と同水準に制限。
    _check_rate_limit_ip(request, bucket="checkout", limit=10, window=60)

    price_info = PRICE_MAP.get(payload.plan)
    if not price_info:
        raise HTTPException(status_code=400, detail=f"Invalid plan: {payload.plan}")
    price_id, amount, plan_name, max_students = price_info

    # 子メール → 親メール差し替えの追跡 (応答の billing_email_switched と invite 照合で使用)
    _input_email_lower = (payload.email or "").strip().lower()
    _billing_email_switched = False

    # 🔧 2026-05-07: name 空で来た場合 (upgrade.html 継続登録) は email から既存生徒を lookup
    # → trial 中に登録した name を DB から復元 (顧客 wrmama10 が [object Object] 報告した
    # 致命バグの根本対策)
    # 🔑 2026-06-12: 子メール (student_email) でも照合する。login.html/auth.html の体験期限切れ
    #   導線は生徒が入力したアドレス (子メールあり得る) を upgrade.html に prefill するが、
    #   旧 lookup は親 email のみ対象で 400 になっていた (2026-06-11 review 指摘)。
    #   verify-code / magic-link と完全に同一の条件・順序で照合し、ログインと checkout が
    #   同じ生徒を選ぶことを保証する (親メール一致を優先)。
    payload_name = (payload.name or "").strip()
    if not payload_name:
        try:
            _email_lower = (payload.email or "").strip().lower()
            _conn_lookup = db()
            _c_lookup = _conn_lookup.cursor()
            _c_lookup.execute(
                "SELECT id, name, email FROM students "
                "WHERE LOWER(email) = ? OR LOWER(COALESCE(student_email, '')) = ? "
                "ORDER BY CASE WHEN LOWER(email) = ? THEN 0 ELSE 1 END, id LIMIT 1",
                (_email_lower, _email_lower, _email_lower),
            )
            _row_lookup = _c_lookup.fetchone()
            _conn_lookup.close()
            if _row_lookup and _row_lookup["name"]:
                payload_name = (_row_lookup["name"] or "").strip()
                # student_id も埋めておく (後続の re-checkout 判定や履歴継承で使う)
                if not payload.student_id and _row_lookup["id"]:
                    payload.student_id = _row_lookup["id"]
                # 子メール一致だった場合は親メール (students.email) に差し替えて Stripe に渡す。
                # 領収書・督促メールは契約者 (保護者) に届けるべきで、子メールを Stripe の
                # customer email にすると invoice reconcile 等の email fallback (LOWER(email)
                # = 親メール前提) からも外れるため。webhook 紐付け自体は metadata.student_id で行う。
                _parent_email = (_row_lookup["email"] or "").strip()
                if _parent_email and _parent_email.lower() != _email_lower:
                    payload.__dict__["email"] = _parent_email
                    _billing_email_switched = True
                    log.info(f"[Checkout] student_email matched: billing email switched to parent (student_id={payload.student_id})")
                # 2026-05-07: PII reduction (Round 2 audit) — name を log に出さない
                log.info(f"[Checkout] name lookup ok: email={payload.email} student_id={payload.student_id} (name resolved from DB)")
            else:
                # 既存生徒が見つからない (新規ユーザが name 抜きで来た / typo で照合失敗) → 親切なエラー
                raise HTTPException(
                    status_code=400,
                    detail="ご登録情報が見つかりませんでした。ご登録済みのメールアドレス (保護者の方のアドレス、またはお子さま用アドレス) でお試しください。新規の方は LP (新規登録) からお手続きをお願いいたします。"
                )
        except HTTPException:
            raise
        except Exception as _e_lookup:
            log.warning(f"[Checkout] name lookup failed: {_e_lookup}")
            raise HTTPException(status_code=400, detail="お名前の自動取得に失敗しました。お手数ですが新規登録画面からお手続きください。")
    # 後続コードが payload.name を参照するので上書き
    if payload_name != payload.name:
        try:
            payload.__dict__["name"] = payload_name  # pydantic v2 でも書き換え可能
        except Exception:
            pass

    # 🏫 通塾生プラン: 招待コード (HMAC トークン) 必須検証
    # 塾長指示 2026-05-06: 通塾生は塾長発行の招待コード経由でのみ契約可能
    # memory: feedback_student_invite_link.md (招待リンク方式は実装済み)
    # 例外: 既存の paid 生徒 (再チェックアウト・プラン変更) は invite_code 不要
    _is_existing_paid_student = False
    if payload.plan == "student_addon" and payload.student_id:
        try:
            _conn_pc = db()
            _c_pc = _conn_pc.cursor()
            # 🔑 2026-06-12: 子メール (student_email) 一致も許可 — name 入力ありで lookup を
            # 通らず子メールのまま来る経路 (checkout.js 等) でも既存 paid 判定が成立するように
            _c_pc.execute(
                "SELECT status FROM students WHERE id = ? AND (LOWER(email) = ? OR LOWER(COALESCE(student_email, '')) = ?)",
                (payload.student_id, (payload.email or "").lower().strip(), (payload.email or "").lower().strip()),
            )
            _row_pc = _c_pc.fetchone()
            if _row_pc and _row_pc["status"] == "paid":
                _is_existing_paid_student = True
                log.info(f"[Checkout] student_addon re-checkout for existing paid student_id={payload.student_id} (invite_code skipped)")
            _conn_pc.close()
        except Exception as _e_pc:
            log.warning(f"[Checkout] existing paid check failed: {_e_pc}")
    if payload.plan == "student_addon" and not _is_existing_paid_student:
        if not payload.invite_code:
            raise HTTPException(
                status_code=400,
                detail="通塾生プランは招待コードが必要です。塾長から発行された招待コードを入力してください。"
            )
        invite_check = _verify_invite_token(payload.invite_code.strip())
        if not invite_check.get("valid"):
            reason = invite_check.get("reason", "invalid")
            log.warning(f"[Checkout] student_addon invite_code rejected: reason={reason} email={payload.email}")
            err_msg = {
                "expired": "招待コードの有効期限が切れています。塾長に再発行を依頼してください。",
                "signature_mismatch": "招待コードが無効です (署名検証失敗)。",
                "malformed": "招待コードの形式が不正です。",
                "server_misconfigured": "サーバー設定エラー。塾長にお問い合わせください。",
            }.get(reason, "招待コードが無効です。")
            raise HTTPException(status_code=403, detail=err_msg)
        # invite token の email と payload.email の一致を検証 (他人の招待を流用させない)
        # 🔑 2026-06-12: 差し替え前の元入力アドレスとの一致も許可。招待が子メール宛に発行され、
        # 生徒が子メールを入力した場合、lookup の親メール差し替え後に照合すると「入力した
        # まさにそのアドレスで申し込め」という自己矛盾 403 ループになるため (review 指摘)。
        invite_email = (invite_check.get("email") or "").strip().lower()
        payload_email = (payload.email or "").strip().lower()
        if invite_email and payload_email and invite_email != payload_email and invite_email != _input_email_lower:
            log.warning(f"[Checkout] student_addon invite_code email mismatch: invite={invite_email} payload={payload_email}")
            raise HTTPException(
                status_code=403,
                detail=f"招待コードに紐づくメールアドレスと入力されたメールアドレスが一致しません。招待コードの発行元 {invite_email} でお申込みください。"
            )
        # invite token の kind を確認 (必ず student_addon)
        if invite_check.get("kind") != "student_addon":
            raise HTTPException(status_code=403, detail="招待コードの種類が不正です。")
        log.info(f"[Checkout] student_addon invite verified: email={payload_email}")
    # 🛡️ 全プラン共通 fallback: env が空/placeholder なら lookup_key で動的解決
    # 2026-05-10 改修: 元々 founder_special のみ fallback だったが、premium/family/standard/student_addon も
    #   env 抜けで Stripe 400 になる致命リスクがあったため、塾長指示で全プラン同等の堅牢性に統一
    #   (memory: feedback_stripe_price_env_design.md)
    if not price_id or price_id.endswith("_placeholder"):
        price_id = _lookup_plan_price_id(payload.plan)
        if not price_id:
            raise HTTPException(
                status_code=503,
                detail=f"「{plan_name}」の Stripe Price が未設定です。管理者に通知済 (admin endpoint で setup してください)。"
            )

    # 創設メンバー枠チェック: LP で「50名限定」と約束しているため、既存 paid 生徒が
    # FOUNDER_LIMIT に達している場合はここで停止する。これがないと URL 直打ちで
    # 101名目以降の決済が通ってしまい、マーケ上の約束を破ることになる。
    # ただし、既存 paid 生徒の更新（再課金・プラン変更）は許可する。
    if not payload.student_id:
        conn_fc = db()
        c_fc = conn_fc.cursor()
        try:
            c_fc.execute(
                # past_due (決済失敗の猶予中) も枠を占有しているとみなす (2026-05-29)
                "SELECT COUNT(*) FROM students WHERE status IN ('paid','past_due') AND plan IS NOT NULL AND plan != '' AND plan != 'student_addon'"
            )
            paid_count = c_fc.fetchone()[0]
        except Exception as e:
            log.error(f"Founder check query failed: {e}")
            paid_count = 0
        conn_fc.close()
        if paid_count >= FOUNDER_LIMIT:
            raise HTTPException(
                status_code=403,
                detail=f"創設メンバー{FOUNDER_LIMIT}名の募集は終了しました。次期募集をお待ちください。"
            )

    # student_id が指定されている場合、email との一致を検証する。
    # これをしないと連番IDで他生徒の stripe_customer_id を上書きでき、課金を奪える。
    # 🔑 2026-06-12: 子メール (student_email) 一致も許可 — ログイン (magic-link/verify-code) と
    #   同じ照合面。子メールはログインに使える = 当該生徒のアカウントに到達できるアドレスのため、
    #   ここだけ弾いても防御にならない。子メール一致で通過した場合は Stripe へ親メールで渡す
    #   (領収書/督促の宛先・invoice reconcile の email fallback との一貫性)。
    if payload.student_id:
        conn_ck = db()
        c_ck = conn_ck.cursor()
        c_ck.execute("SELECT email, student_email FROM students WHERE id = ?", (payload.student_id,))
        _row_ck = c_ck.fetchone()
        conn_ck.close()
        if not _row_ck:
            raise HTTPException(status_code=404, detail="Student not found")
        _ck_parent = (_row_ck["email"] or "").strip().lower()
        _ck_child = (_row_ck["student_email"] or "").strip().lower()
        _ck_payload = (payload.email or "").strip().lower()
        if _ck_payload != _ck_parent and (not _ck_child or _ck_payload != _ck_child):
            raise HTTPException(status_code=403, detail="student_id/email mismatch")
        if _ck_payload != _ck_parent and _ck_parent:
            payload.__dict__["email"] = (_row_ck["email"] or "").strip()
            _billing_email_switched = True
            log.info(f"[Checkout] student_email matched at id-check: billing email switched to parent (student_id={payload.student_id})")

    if not STRIPE_SECRET_KEY:
        # Mock mode: return fake checkout URL（API key未設定時のデモ用）
        return {
            "mock": True,
            "checkout_url": f"{BASE_URL}/checkout-success.html?session_id=mock_{payload.plan}&purchase={'student_addon' if payload.plan == 'student_addon' else 'monthly'}",
            "plan": payload.plan,
            "plan_name": plan_name,
            "amount": amount,
            "max_students": max_students,
            "enrollment_fee": ENROLLMENT_FEE if payload.plan not in ENROLLMENT_FEE_EXEMPT else 0,
            "trial_fee": FOUNDER_TRIAL_PRICE if payload.plan != "student_addon" else 0,
            # 子メール入力 → 親メール差し替え後の請求先 (マスク済・フロント表示用)
            "billing_email": _mask_email_for_display(str(payload.email or "")),
            "billing_email_switched": _billing_email_switched,
            "note": "Stripe API key未設定。ENVに STRIPE_SECRET_KEY を設定すると実際の決済画面に誘導されます。"
        }

    s = get_stripe()

    # 塾生アドオン: 入塾金なし・トライアルなしの単純サブスク
    if payload.plan == "student_addon":
        session = s.checkout.Session.create(
            mode="subscription",
            payment_method_types=["card"],
            line_items=[{"price": price_id, "quantity": 1}],
            customer_email=payload.email,
            success_url=f"{BASE_URL}/checkout-success.html?session_id={{CHECKOUT_SESSION_ID}}&purchase=student_addon",
            cancel_url=f"{BASE_URL}/checkout-cancel.html",
            allow_promotion_codes=True,
            subscription_data={
                # purchase_type: webhook の分岐は else (monthly 系 catch-all) のままで不変だが、
                # ログ/分析で student_addon が monthly に混ざらないよう明示 (他プランと同じ規約)
                "metadata": {"plan": payload.plan, "student_id": str(payload.student_id or ""), "type": "student_addon", "purchase_type": "student_addon"}
            },
            metadata={"plan": payload.plan, "student_id": str(payload.student_id or ""), "type": "student_addon", "purchase_type": "student_addon"}
        )
        return {
            "checkout_url": session.url,
            "session_id": session.id,
            "plan_name": plan_name,
            "monthly_fee": amount,
            "enrollment_fee": 0,
            # 子メール入力 → 親メール差し替え後の請求先 (マスク済。Stripe checkout には平文で prefill される)
            "billing_email": _mask_email_for_display(str(payload.email or "")),
            "billing_email_switched": _billing_email_switched,
        }

    # 継続本契約: 月額サブスク。トライアル無し（即時課金）。
    # 体験期間は別途 /api/stripe/trial-checkout で 14日間 完全無料 (Stripe 不経由)。
    # 入塾金はWebhook (checkout.session.completed) で InvoiceItem として
    # 顧客に作成 → 初回請求書に自動的に乗る。
    # 先着100名キャンペーン枠が残っていれば入塾金免除フラグを立てる
    waiver_eligible = (
        payload.plan not in ENROLLMENT_FEE_EXEMPT
        and _is_waiver_eligible()
    )
    needs_enrollment_fee = (payload.plan not in ENROLLMENT_FEE_EXEMPT) and not waiver_eligible
    # 🛡️ 2026-05-29: 個別免除フラグ (CEO ダッシュ「🆓 入塾金免除」ボタン) を尊重。
    #   campaign 枠とは独立に、DB で enrollment_fee_waived=1 の生徒は入塾金を必ず免除する。
    #   これが無いと「免除ボタンを押したのに本契約 checkout で ¥10,000 課金」の silent fail になる。
    #   enrollment_waiver_applied は "0" のまま (campaign カウンタを二重消費しない) で needs_enrollment_fee だけ落とす。
    if needs_enrollment_fee and (payload.student_id or payload.email):
        _conn_w = None
        try:
            _conn_w = db(); _c_w = _conn_w.cursor()
            if payload.student_id:
                _c_w.execute("SELECT enrollment_fee_waived FROM students WHERE id=?", (payload.student_id,))
            else:
                # email は大文字小文字を無視して照合 (免除の取りこぼし防止・他箇所と統一)
                _c_w.execute("SELECT enrollment_fee_waived FROM students WHERE LOWER(email)=LOWER(?)", (payload.email,))
            _rw = _c_w.fetchone()
            if _rw and ("enrollment_fee_waived" in _rw.keys()) and _rw["enrollment_fee_waived"]:
                needs_enrollment_fee = False
                log.info(f"[Checkout] 個別免除フラグ適用: 入塾金スキップ student_id={payload.student_id} email={payload.email}")
        except Exception as _we:
            log.warning(f"[Checkout] manual waiver lookup failed: {type(_we).__name__}: {_we}")
        finally:
            if _conn_w is not None:
                try: _conn_w.close()
                except Exception: pass
    subscription_data = {
        "metadata": {
            "plan": payload.plan,
            "student_id": str(payload.student_id or ""),
            "name": (payload.name or "")[:200],  # 2026-05-07: Reviewer C 指摘・webhook 側で name lost を防ぐ
            "max_students": str(max_students),
            "founder": "1",
            "needs_enrollment_fee": "1" if needs_enrollment_fee else "0",
            "enrollment_waiver_applied": "1" if waiver_eligible else "0",
            "purchase_type": "monthly",
        }
    }

    session_kwargs = {
        "mode": "subscription",
        "payment_method_types": ["card"],
        "line_items": [{"price": price_id, "quantity": 1}],
        "customer_email": payload.email,
        "success_url": f"{BASE_URL}/checkout-success.html?session_id={{CHECKOUT_SESSION_ID}}&purchase=monthly",
        "cancel_url": f"{BASE_URL}/checkout-cancel.html",
        "subscription_data": subscription_data,
        "metadata": {
            "plan": payload.plan,
            "plan_name": plan_name,
            "student_id": str(payload.student_id or ""),
            "name": (payload.name or "")[:200],  # 2026-05-07: webhook で「（新規）」表示防止
            "max_students": str(max_students),
            "purchase_type": "monthly",
            "needs_enrollment_fee": "1" if needs_enrollment_fee else "0",
            "enrollment_waiver_applied": "1" if waiver_eligible else "0",
        }
    }

    try:
        session = s.checkout.Session.create(**session_kwargs)
    except Exception as e:
        log.error(f"Stripe checkout.Session.create failed for plan={payload.plan}: {type(e).__name__}: {e}")
        raise HTTPException(status_code=400, detail=f"Stripe error: {type(e).__name__}: {str(e)[:500]}")

    return {
        "checkout_url": session.url,
        "session_id": session.id,
        "plan_name": plan_name,
        "monthly_fee": amount,
        "trial_fee": FOUNDER_TRIAL_PRICE,
        "enrollment_fee": ENROLLMENT_FEE if payload.plan not in ENROLLMENT_FEE_EXEMPT else 0,
        "max_students": max_students,
        # 子メール入力 → 親メール差し替え後の請求先 (マスク済。Stripe checkout には平文で prefill される)
        "billing_email": _mask_email_for_display(str(payload.email or "")),
        "billing_email_switched": _billing_email_switched,
    }


@app.get("/api/plans")
def list_plans():
    """フロントエンドがプラン一覧を動的取得する用"""
    return {
        "plans": {
            k: {"price": v[1], "name": v[2], "max_students": v[3]}
            for k, v in PRICE_MAP.items()
            if k in ("founder1", "standard", "premium", "family", "student_addon")
        },
        "enrollment_fee": ENROLLMENT_FEE,
        "trial_fee": FOUNDER_TRIAL_PRICE,
        "trial_duration_days": FOUNDER_TRIAL_DAYS,
    }

def _calculate_dynamic_fake_taken(real_paid: int) -> int:
    """カモフラージュ申込数を動的計算 (FOMO 加速設計)。
    要素:
      - BASE (デフォルト26): ローンチ初日の最低カモフラージュ
      - MULTIPLIER (デフォルト2.0): 実申込1名あたりの追加偽申込
      - DAILY_GROWTH (デフォルト0.5): 1日あたりの自然増 (週で +3.5)
    最終的に MIN_REMAINING で下限保護 (残0=売り止め印象を防ぐ)。"""
    import time
    days_since_launch = max(0, (time.time() - SERVICE_LAUNCH_TS) / 86400)
    natural_growth = int(days_since_launch * FOUNDER_PUBLIC_FAKE_DAILY_GROWTH)
    fomo_boost = int(real_paid * FOUNDER_PUBLIC_FAKE_MULTIPLIER)
    return real_paid + FOUNDER_PUBLIC_FAKE_BASE + fomo_boost + natural_growth


@app.get("/api/founders/count")
def founders_count(public: bool = False):
    """創設メンバーの残り枠をカウント。
    status='paid' の全プラン（新規: founder_special/standard/premium/family/student_addon,
    旧: ai/hybrid/intensive）を対象。トライアル中も status='paid' が立つため、
    実際に枠を占有している全員をカウントする。

    public=1 (顧客向け): 動的計算カモフラージュ値を返す (FOMO設計)。
      実申込が増えるほど + 経過日数が増えるほど 残枠表示が縮小する。
      env で BASE/MULTIPLIER/DAILY_GROWTH/MIN_REMAINING を調整可能。
    public未指定 (内部用): 実数値を返す (CEOダッシュボード用)。"""
    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            # past_due (決済失敗の猶予中) も枠を占有しているとみなす (2026-05-29)
            "SELECT COUNT(*) FROM students WHERE status IN ('paid','past_due') AND plan IS NOT NULL AND plan != '' AND plan != 'student_addon'"
        )
        paid = c.fetchone()[0]
    except Exception as e:
        log.error(f"founders_count query failed: {e}")
        paid = 0
    conn.close()
    real_remaining = max(0, FOUNDER_LIMIT - paid)
    if public:
        # 動的カモフラージュ計算
        public_taken = _calculate_dynamic_fake_taken(paid)
        # 最低 MIN_REMAINING 名は残す (「残0」=完売印象を防ぐ)
        public_remaining = max(FOUNDER_PUBLIC_MIN_REMAINING, FOUNDER_LIMIT - public_taken)
        public_taken = FOUNDER_LIMIT - public_remaining
        return {"limit": FOUNDER_LIMIT, "taken": public_taken, "remaining": public_remaining}
    return {"limit": FOUNDER_LIMIT, "taken": paid, "remaining": real_remaining}

# ==========================================================================
# 紹介ループ Stripe coupon 発行ヘルパー (race-safe + deferred 対応)
# ==========================================================================
def _process_referral_coupon_for_referred(c, conn, s, referred_id: int):
    """被紹介者が paid 化した時に呼ばれる。
    referrer の status と stripe_customer_id を確認し、
    paid なら即時 coupon 発行、未 paid なら referred_paid_at だけ記録 (deferred)。
    Race-safe: atomic UPDATE で claim-first → 失敗 (=他 worker 処理済) なら何もしない。"""
    # 該当 referral レコードを取得
    c.execute(
        "SELECT id, referrer_id, coupon_applied_at, referred_paid_at FROM referrals WHERE referred_id=?",
        (referred_id,)
    )
    ref_row = c.fetchone()
    if not ref_row:
        return  # 紹介リンク無し

    # 既に処理済みなら何もしない
    if ref_row["coupon_applied_at"]:
        return

    # referred_paid_at をまず claim (race-safe: WHERE referred_paid_at IS NULL)
    c.execute(
        "UPDATE referrals SET referred_paid_at=CURRENT_TIMESTAMP WHERE id=? AND referred_paid_at IS NULL",
        (ref_row["id"],)
    )
    rowcount = c.rowcount if hasattr(c, "rowcount") else 0
    conn.commit()
    if rowcount == 0 and ref_row["referred_paid_at"]:
        # 他 worker が既に処理済 → 進めない
        return

    # referrer の状態確認
    c.execute(
        "SELECT id, status, stripe_customer_id FROM students WHERE id=?",
        (ref_row["referrer_id"],)
    )
    referrer_row = c.fetchone()
    if not referrer_row:
        log.warning(f"[Referral] referrer {ref_row['referrer_id']} not found")
        return

    if referrer_row["status"] != "paid" or not referrer_row["stripe_customer_id"]:
        log.info(f"[Referral] referrer {ref_row['referrer_id']} not paid yet → coupon deferred")
        return

    # coupon 発行 (claim-first で coupon_applied_at を入れて他 worker をブロック)
    _issue_referral_coupon(c, conn, s, ref_row["id"], referrer_row["stripe_customer_id"], ref_row["referrer_id"])


def _process_deferred_referral_coupons(c, conn, s, paid_student_id: int):
    """生徒が paid 化した時に呼ばれる。
    この生徒が紹介者になっている referrals のうち deferred (referred_paid_at IS NOT NULL かつ coupon_applied_at IS NULL)
    を見つけて coupon 発行する。"""
    c.execute(
        """SELECT id FROM referrals
           WHERE referrer_id=? AND referred_paid_at IS NOT NULL AND coupon_applied_at IS NULL""",
        (paid_student_id,)
    )
    rows = list(c.fetchall())
    if not rows:
        return
    c.execute("SELECT stripe_customer_id FROM students WHERE id=? AND status='paid'", (paid_student_id,))
    customer_row = c.fetchone()
    if not customer_row or not customer_row["stripe_customer_id"]:
        return
    customer_id = customer_row["stripe_customer_id"]
    log.info(f"[Referral] processing {len(rows)} deferred coupon(s) for paid_student_id={paid_student_id}")
    for r in rows:
        _issue_referral_coupon(c, conn, s, r["id"], customer_id, paid_student_id)


def _issue_referral_coupon(c, conn, s, referral_row_id: int, customer_id: str, referrer_id: int):
    """Stripe coupon 発行 + active sub に適用 + referrals 更新。Race-safe (claim-first)。"""
    # claim-first: coupon_applied_at をプレースホルダ '__pending__' で先に書き込み
    pending_marker = "__pending__"
    c.execute(
        """UPDATE referrals SET coupon_id=? WHERE id=? AND coupon_applied_at IS NULL""",
        (pending_marker, referral_row_id)
    )
    rowcount = c.rowcount if hasattr(c, "rowcount") else 0
    conn.commit()
    if rowcount == 0:
        # 他 worker が先に処理した
        return

    coupon_id_created = None
    try:
        cp = s.Coupon.create(
            amount_off=3000, currency="jpy", duration="once",
            max_redemptions=1, name="紹介報酬 ¥3,000 OFF"
        )
        coupon_id_created = cp.id
        subs = s.Subscription.list(customer=customer_id, status="active", limit=1)
        if subs.data:
            s.Subscription.modify(subs.data[0].id, coupon=coupon_id_created)
            log.info(f"✅ Referral coupon applied: referrer={referrer_id} coupon={coupon_id_created}")
        else:
            log.warning(f"[Referral] referrer {referrer_id} has no active subscription; coupon created but not applied")
    except Exception as ce:
        log.error(f"[Referral] coupon create/apply failed: {type(ce).__name__}: {ce}")
        # __pending__ をクリアして再リトライ可能にする
        c.execute("UPDATE referrals SET coupon_id=NULL WHERE id=? AND coupon_id=?", (referral_row_id, pending_marker))
        conn.commit()
        return

    # 確定: coupon_applied_at + coupon_id を入れる
    c.execute(
        "UPDATE referrals SET coupon_applied_at=CURRENT_TIMESTAMP, coupon_id=? WHERE id=?",
        (coupon_id_created, referral_row_id)
    )
    conn.commit()


def _is_non_aijuku_invoice(invoice: dict) -> Optional[str]:
    """ai-juku の売上として記録してはいけない invoice なら理由文字列、対象なら None。
    同一 Stripe アカウントを juku-payment (月謝・Vercel webhook 管轄) と共有しているため
    3 視点 review (2026-06-11) で発見された 4 つのすり抜け経路を全て塞ぐ:
    ① invoice.metadata.system=juku-payment* (既存チェック)
    ② 滞納月謝請求 api/past-due-invoice.py は metadata.source=past-due-invoice-v1 のみで system 無し
    ③ 旧 mode=subscription 月謝サブスクの system タグは subscription metadata にあり
       invoice.metadata へ伝播しない (acacia: subscription_details.metadata /
       basil: parent.subscription_details.metadata — Vercel 側 api/stripe-webhook.py と同じ対処)
    ④ v1 月謝サブスク (2026-05-03〜05-13) は system タグ自体が無い → registration_id /
       source=self-register-v1 を juku-payment マーカーとして照合"""
    # 3 層 (invoice 直下 / acacia: subscription_details / basil: parent.subscription_details) を
    # 同一基準で照合する。④ は 2026-06-11 ラウンド1 review (MEDIUM) で追加:
    # 旧 v1 自己登録月謝サブスク (2026-05-03〜05-13 作成) は system タグが無く
    # registration_id + source=self-register-v1 しか持たない → Vercel 側
    # api/stripe-webhook.py の registration_id 一次マーカー判定とパリティを取る
    # (ai-juku サブスクの metadata は plan/purchase_type 系のみで registration_id を持たない)。
    _layers = (
        ("metadata", invoice.get("metadata") or {}),
        ("subscription_details.metadata", (invoice.get("subscription_details") or {}).get("metadata") or {}),
        ("parent.subscription_details.metadata", (((invoice.get("parent") or {}).get("subscription_details") or {}).get("metadata") or {})),
    )
    for _layer_name, _m in _layers:
        if (_m.get("system") or "").startswith("juku-payment"):
            return f"{_layer_name}.system=juku-payment"
        if (_m.get("source") or "").startswith("past-due-invoice"):
            return f"{_layer_name}.source=past-due-invoice (滞納月謝)"
        if (_m.get("source") or "").startswith("self-register"):
            return f"{_layer_name}.source=self-register (旧v1月謝サブスク)"
        if _m.get("registration_id"):
            return f"{_layer_name}.registration_id あり (juku-payment 月謝)"
    return None


def _invoice_subscription_id(invoice: dict) -> Optional[str]:
    """invoice payload から subscription id を API バージョン互換で取り出す。
    旧 API (〜2024 acacia): invoice.subscription / 新 API (2025-03-31 basil〜):
    invoice.parent.subscription_details.subscription に移動したため両対応。
    webhook payload のバージョンは Dashboard の endpoint 設定依存で手元から確定できない (2026-06-11)。"""
    sub = invoice.get("subscription")
    if isinstance(sub, dict):  # expand されている場合は id を取る
        sub = sub.get("id")
    if sub:
        return sub
    _parent = invoice.get("parent") or {}
    _sub_details = _parent.get("subscription_details") or {}
    sub = _sub_details.get("subscription")
    if isinstance(sub, dict):
        sub = sub.get("id")
    return sub or None


def _cancel_superseded_subscription(stripe_client, old_sub_id, new_sub_id, student_id, context: str):
    """新 subscription への置換で不要になった旧 subscription を Stripe 上で即時解約する。

    🔁 [upgrade-supersede] (2026-06-12): trial_extended (カード登録 21 日体験) 中に月額移行すると
    checkout は新 subscription を作るが、旧 trial サブスクは Stripe に残ったまま trial 明けに
    active 化して ¥14,500/月 の二重課金が始まる。trial_extended の再申込でも同型の孤児が生まれる。
    DB の stripe_subscription_id を新サブスクで上書き・commit した **後** に呼ぶこと —
    subscription.deleted webhook は sub_id 厳密一致なので、置換済みの生徒が誤って canceled 化される
    ことはない。解約前に metadata.superseded_by を付け、deleted webhook の orphan 警告
    (重複サブスク疑い) と /api/admin/stripe/diagnose-orphan-subs の誤検知を防ぐ。
    """
    if not old_sub_id or not new_sub_id or old_sub_id == new_sub_id:
        return  # 置換が成立していない (旧サブスク無し / webhook 再配送で同一 sub) — 何もしない
    try:
        try:
            stripe_client.Subscription.modify(old_sub_id, metadata={"superseded_by": new_sub_id, "superseded_context": context})
        except Exception as _me:
            # タグ付け失敗は致命ではない (orphan 警告のノイズより旧サブスク取り残しの実害が大きい) — 解約は続行
            log.info(f"[{context}] superseded tag failed for {old_sub_id} (解約は続行): {type(_me).__name__}: {_me}")
        stripe_client.Subscription.delete(old_sub_id)
        log.info(f"[{context}] 旧 subscription {old_sub_id} を即時解約 (置換先 {new_sub_id}, student_id={student_id})")
    except Exception as e:
        _msg = str(e).lower()
        if type(e).__name__ == "InvalidRequestError" and any(
            _t in _msg for _t in (
                "no such subscription", "resource_missing",
                "already canceled", "already_canceled",
                "has been canceled", "canceled subscription",
            )
        ):
            log.info(f"[{context}] 旧 subscription {old_sub_id} は既に解約済み")
            return
        # 放置すると旧サブスクの課金開始時に二重課金が始まる — 手動対応必須の critical event として記録
        log.error(
            f"[{context}] FAILED to cancel superseded subscription {old_sub_id} "
            f"(student_id={student_id}, new={new_sub_id}): {type(e).__name__}: {e}"
        )
        _record_ai_critical_event("superseded_subscription_cancel_failed", {
            "student_id": student_id,
            "old_subscription": old_sub_id,
            "new_subscription": new_sub_id,
            "context": context,
            "error": str(e)[:200],
            "action_required": (
                f"Stripe Dashboard で旧 subscription {old_sub_id} を手動解約してください "
                f"(student_id={student_id}・新契約 {new_sub_id} は有効・放置すると課金開始時に二重課金)"
            ),
        })


# ==========================================================================
# Routes: Stripe Webhook
# ==========================================================================
@app.post("/api/stripe/webhook")
async def stripe_webhook(request: Request, stripe_signature: str = Header(None)):
    if not STRIPE_WEBHOOK_SECRET:
        log.warning("Stripe webhook called but STRIPE_WEBHOOK_SECRET not set")
        return {"received": True, "mock": True}

    payload = await request.body()
    s = get_stripe()
    try:
        event = s.Webhook.construct_event(payload, stripe_signature, STRIPE_WEBHOOK_SECRET)
    except Exception as e:
        log.error(f"Webhook signature error: {e}")
        raise HTTPException(status_code=400, detail="Invalid signature")

    # 冪等性ガード: Stripe は webhook を再送するため、同じ event.id が2回処理されると
    # InvoiceItem の二重作成などで多重課金に直結する。processed_events に UNIQUE 制約で
    # 先勝ちINSERTし、既に入っていれば即座に return。
    event_id = event.get("id")
    if event_id:
        conn = db()
        c = conn.cursor()
        try:
            c.execute(
                "INSERT INTO processed_events (event_id, event_type) VALUES (?, ?)",
                (event_id, event.get("type", "")),
            )
            conn.commit()
        except IntegrityError:
            conn.rollback()
            conn.close()
            log.info(f"Stripe webhook duplicate ignored: id={event_id}, type={event.get('type')}")
            return {"received": True, "duplicate": True}
        conn.close()

    log.info(f"Stripe webhook: {event['type']} id={event_id}")

    if event["type"] == "checkout.session.completed":
        session = event["data"]["object"]
        meta = session.get("metadata", {}) or {}
        # 🚨 2026-05-13: AIコーチングと juku-payment 月謝の完全分離 (二重保険)
        # juku-payment 系イベント (system=juku-payment-monthly) は ai-juku DB に一切触らずに skip
        # commit 308d8c4 の VALID_PLAN_KEYS check に加え、metadata.system で明示的に分岐する
        _meta_system = (meta.get("system") or "").strip()
        if _meta_system.startswith("juku-payment"):
            log.info(f"[Stripe webhook] Skipping juku-payment event (system={_meta_system}) - handled by Vercel /payment/api/stripe-webhook")
            return JSONResponse({"received": True, "skipped_reason": "juku-payment system tag"}, status_code=200)
        purchase_type = meta.get("purchase_type", "monthly")  # 既定は月額（旧互換）
        plan = meta.get("plan")
        student_id = meta.get("student_id")
        max_students = meta.get("max_students", "1")
        name_from_meta = meta.get("name", "")
        conn = db()
        c = conn.cursor()
        customer = session.get("customer")
        subscription = session.get("subscription")
        # 2026-05-07: email を必ず lowercase に正規化 (Round 2 audit 検出・致命バグ修正)
        # 旧コード: WHERE email=? が Stripe から来た "Parent@Example.com" で MISS → 新規 INSERT
        # → 既存 trial student の history が孤立する致命バグ。
        # students テーブルは trial/signup で email_norm (lowercase) で保存している (line 10979)。
        _email_raw = session.get("customer_details", {}).get("email") or session.get("customer_email")
        email = (_email_raw or "").strip().lower() or None

        if purchase_type == "trial":
            # 完全無料 14日体験: status='trial', trial_start=now, trial_end=now+14d
            # Stripe 決済不要。自動課金は発生しない。
            now = datetime.now(timezone.utc)
            trial_end = now + timedelta(days=FOUNDER_TRIAL_DAYS)
            if student_id and student_id != "":
                c.execute(
                    """UPDATE students SET status='trial', stripe_customer_id=?,
                           trial_start=?, trial_end=?, updated_at=CURRENT_TIMESTAMP
                       WHERE id=?""",
                    (customer, now.isoformat(), trial_end.isoformat(), student_id)
                )
            elif email:
                c.execute("SELECT id FROM students WHERE LOWER(email) = ? ORDER BY id LIMIT 1", (email,))
                row = c.fetchone()
                if row:
                    c.execute(
                        """UPDATE students SET status='trial', stripe_customer_id=?,
                               trial_start=?, trial_end=?, updated_at=CURRENT_TIMESTAMP
                           WHERE id=?""",
                        (customer, now.isoformat(), trial_end.isoformat(), row[0])
                    )
                else:
                    c.execute(
                        """INSERT INTO students (name, email, status, stripe_customer_id, trial_start, trial_end)
                           VALUES (?, ?, 'trial', ?, ?, ?)""",
                        (name_from_meta or "（新規）", email, customer, now.isoformat(), trial_end.isoformat())
                    )
            conn.commit()

        elif purchase_type == "trial_extended":
            # 🎁 2026-05-19 集客 funnel #4: +7 日延長 trial (Stripe Subscription 21 日)
            # ユーザーがクレカ登録 → Stripe Subscription with trial_period_days=21 開始
            # webhook で受け取った subscription_id を保存・trial_end を 21 日後に更新
            # その後の trial 終了は customer.subscription.updated (status: trialing→active) で paid 化
            now = datetime.now(timezone.utc)
            EXTENDED_TRIAL_DAYS = FOUNDER_TRIAL_DAYS + 7  # 14 + 7 = 21
            trial_end = now + timedelta(days=EXTENDED_TRIAL_DAYS)
            log.info(f"[Stripe webhook trial_extended] student_id={student_id}, email={email}, customer={customer}, subscription={subscription}")
            target_id = None
            _old_sub_te = None  # 🔁 [upgrade-supersede] 再申込時の旧 subscription (置換成立後に即時解約)
            # 🛡 R3-B fix (2026-05-19): student_id は metadata 経由でユーザー制御可能 (LP form の hidden field 経由)
            # 他人の student_id を渡されると IDOR で被害者の subscription_id/status を上書きする攻撃が可能。
            # → student_id を指定された場合も email 一致を必ず検証してから採用 (email は Stripe verified)
            if student_id and student_id != "" and email:
                try:
                    c.execute("SELECT id, stripe_subscription_id FROM students WHERE id=? AND LOWER(email)=?", (student_id, email))
                    _vrow = c.fetchone()
                    if _vrow:
                        target_id = _vrow["id"]
                        _old_sub_te = _vrow["stripe_subscription_id"]
                    else:
                        log.warning(f"[Stripe webhook trial_extended] student_id={student_id} does NOT match email={email}; falling back to email lookup (possible IDOR attempt)")
                except Exception as _ve:
                    log.warning(f"[Stripe webhook trial_extended] student_id ownership check failed: {_ve}")
            if target_id is None and email:
                c.execute("SELECT id, stripe_subscription_id FROM students WHERE LOWER(email) = ? ORDER BY id LIMIT 1", (email,))
                row = c.fetchone()
                if row:
                    target_id = row["id"]
                    _old_sub_te = row["stripe_subscription_id"]
            if target_id:
                # 🛡 既存 student を UPDATE (trial_signup endpoint で既に INSERT 済の想定)
                # plan='founder_special' (現在の +7 日延長 default プラン・将来 plan metadata 受け取りで切替可)
                # 🛡 [cancel-consistency] (2026-06-12): status='canceled' の行は trial に書き戻さない。
                # checkout 完了〜webhook 到達の間に /api/billing/cancel-trial が呼ばれると、sub_id 未保存の
                # ため純 trial 経路で DB は canceled になるが Stripe subscription は生きている。ここで無条件に
                # trial へ復活させると「解約したはずの生徒に 21 日後、自動課金が始まる」ため、canceled は
                # 維持して subscription を即時解約する (解約が生徒の最終意思)。
                c.execute(
                    """UPDATE students SET status='trial', stripe_customer_id=?, stripe_subscription_id=?,
                           trial_start=?, trial_end=?, plan='founder_special', cancel_at=NULL, updated_at=CURRENT_TIMESTAMP
                       WHERE id=? AND status != 'canceled'""",
                    (customer, subscription, now.isoformat(), trial_end.isoformat(), target_id)
                )
                _te_updated = c.rowcount
                conn.commit()
                if _te_updated > 0:
                    log.info(f"[Stripe webhook trial_extended] updated student {target_id}, trial_end={trial_end.isoformat()}")
                    # 🔁 [upgrade-supersede] trial_extended 再申込: 旧 subscription を残すと
                    # 旧側の trial 明けに二重課金が始まるため、置換が成立した時点で即時解約
                    _cancel_superseded_subscription(s, _old_sub_te, subscription, target_id, "trial_extended-recheckout-supersede")
                elif subscription:
                    # [cancel-consistency] 解約先行 (canceled) または行消失 → 作成済み subscription を孤立した
                    # まま放置すると課金が始まるため即時解約する。
                    log.warning(
                        f"[Stripe webhook trial_extended] student {target_id} is canceled (or gone) — "
                        f"canceling fresh subscription {subscription} to prevent billing"
                    )
                    try:
                        _stripe_te = get_stripe()
                        _stripe_te.Subscription.delete(subscription)
                        log.info(f"[Stripe webhook trial_extended] subscription {subscription} canceled (post-cancel race resolved)")
                    except Exception as _ce:
                        _ce_msg = str(_ce).lower()
                        if type(_ce).__name__ == "InvalidRequestError" and any(
                            _s in _ce_msg for _s in (
                                "no such subscription", "resource_missing",
                                "already canceled", "already_canceled",
                                "has been canceled", "canceled subscription",
                            )
                        ):
                            log.info(f"[Stripe webhook trial_extended] subscription {subscription} already gone")
                        else:
                            # 解約済み生徒への課金が始まってしまうため、手動対応必須の critical event として記録
                            log.error(
                                f"[Stripe webhook trial_extended] FAILED to cancel subscription {subscription} "
                                f"for canceled student {target_id}: {type(_ce).__name__}: {_ce}"
                            )
                            _record_ai_critical_event("trial_extended_cancel_race_unresolved", {
                                "student_id": target_id,
                                "subscription": subscription,
                                "customer": customer,
                                "error": str(_ce)[:200],
                                "action_required": "Stripe Dashboard で subscription を手動解約してください (生徒は解約済み・放置すると 21 日後に課金開始)",
                            })
            else:
                # 想定外: trial_signup endpoint で先に INSERT されているはずだが、何らかの理由で
                # 見つからない場合 → 新規 INSERT で fallback (audit log で警告)
                c.execute(
                    """INSERT INTO students (name, email, status, stripe_customer_id, stripe_subscription_id,
                           trial_start, trial_end, plan)
                       VALUES (?, ?, 'trial', ?, ?, ?, ?, 'founder_special')""",
                    (name_from_meta or "（新規）", email, customer, subscription, now.isoformat(), trial_end.isoformat())
                )
                conn.commit()
                log.warning(f"[Stripe webhook trial_extended] target student not found, inserted new (email={email})")

        else:  # purchase_type == "monthly" (旧互換含む)
            # 月額サブスク登録: status='paid'、入塾金 InvoiceItem 作成
            # 🛡️ 2026-05-13 塾長指摘 fix:
            # ai-juku 申込フォーム経由以外 (Stripe Payment Link 直接決済・juku-payment 月謝等) で
            # 来た webhook は plan metadata が無い → 旧実装は「（新規）」+ plan=null で INSERT してしまい
            # 「塾の月謝が ai-juku MRR に混入」する致命傷だった。
            # 修正: 有効 plan key (founder_special/founder1/premium/family/standard/student_addon) でない場合、
            #       student_id 既存ならそのまま UPDATE (signup flow からの再決済を許容)、
            #       新規 INSERT は skip して warning ログ + critical event 記録 (audit 用)。
            _VALID_PLAN_KEYS = {"founder_special", "founder1", "premium", "family", "standard", "student_addon"}
            plan_valid = bool(plan) and plan in _VALID_PLAN_KEYS

            # 🔁 [upgrade-supersede] (2026-06-12): 上書き前に旧 subscription を捕捉する。
            # trial_extended (カード登録 21 日体験) 中の月額移行では checkout が新 subscription を
            # 作るため、旧 trial サブスクを Stripe 上で解約しないと残留し、trial 明けに active 化して
            # ¥14,500/月 の二重課金が始まる。commit 後に _cancel_superseded_subscription で即時解約。
            _old_sub_monthly = None
            _supersede_student_id = None

            if student_id and student_id != "":
                # 既存 ID 指定: ai-juku 申込フォーム経由なので plan が空でも UPDATE 続行 (後方互換)
                # 🛡️ 2026-06-12: trial_end=NULL を追加 (admin set-status paid / subscription.updated
                # active の paid 化と同じ規約)。monthly checkout はトライアル無し即時課金なので
                # クリアは無条件に正しい。体験中の月額移行で trial_end が残ると status='paid' +
                # 未来 trial_end の行になり、cron_trial_reminders の窓 (trial_end が 24-48h 先) に
                # 必ず一度入って、契約者に無課金 trial 用「自動課金は発生しません」メールが
                # 誤配される (3ffa446 の 3視点 review root cause 指摘)。
                try:
                    c.execute("SELECT stripe_subscription_id FROM students WHERE id=?", (student_id,))
                    _r_old = c.fetchone()
                    if _r_old:
                        _old_sub_monthly = _r_old["stripe_subscription_id"]
                        _supersede_student_id = student_id
                except Exception as _oe:
                    # 捕捉失敗でも paid 化は止めない (旧サブスク残留は reconcile/orphan 監視が後追い検出)
                    log.warning(f"[Stripe webhook monthly] old subscription lookup failed (student_id={student_id}): {_oe}")
                c.execute(
                    """UPDATE students SET status='paid', stripe_customer_id=?, stripe_subscription_id=?,
                           paid_since=CURRENT_TIMESTAMP, plan=?, trial_end=NULL, cancel_at=NULL, updated_at=CURRENT_TIMESTAMP
                       WHERE id=?""",
                    (customer, subscription, plan, student_id)
                )
            elif email:
                c.execute("SELECT id, stripe_subscription_id FROM students WHERE LOWER(email) = ? ORDER BY id LIMIT 1", (email,))
                row = c.fetchone()
                if row:
                    _old_sub_monthly = row["stripe_subscription_id"]
                    _supersede_student_id = row["id"]
                    # 既存 email: trial → paid 化等の正常 case (trial_end=NULL は上の ID 指定 UPDATE と同理由)
                    c.execute(
                        """UPDATE students SET status='paid', stripe_customer_id=?, stripe_subscription_id=?,
                               paid_since=CURRENT_TIMESTAMP, plan=?, trial_end=NULL, cancel_at=NULL, updated_at=CURRENT_TIMESTAMP
                           WHERE id=?""",
                        (customer, subscription, plan, row["id"])
                    )
                else:
                    # 新規 email: ai-juku で初登場の顧客
                    # plan が ai-juku の有効 key でない場合は INSERT skip (juku-payment 月謝など外部経路の混入を防ぐ)
                    if plan_valid:
                        c.execute(
                            """INSERT INTO students (name, email, plan, status, stripe_customer_id, stripe_subscription_id, paid_since)
                               VALUES (?, ?, ?, 'paid', ?, ?, CURRENT_TIMESTAMP)""",
                            (name_from_meta or "（新規）", email, plan, customer, subscription)
                        )
                    else:
                        log.warning(
                            f"[Stripe webhook] Skipping INSERT: plan='{plan}' is not in ai-juku VALID_PLAN_KEYS "
                            f"(likely external system like juku-payment 月謝). email={email} customer={customer}"
                        )
                        try:
                            _record_ai_critical_event("stripe_webhook_skipped_unknown_plan", {
                                "email": email,
                                "customer": customer,
                                "subscription": subscription,
                                "plan_received": plan,
                                "reason": "plan not in VALID_PLAN_KEYS - likely juku-payment 月謝 or external Payment Link",
                            })
                        except Exception:
                            pass
            conn.commit()

            # 🔁 [upgrade-supersede] DB が新 subscription を指した後に旧サブスクを即時解約する
            # (subscription.deleted webhook は sub_id 厳密一致 → 置換済みの生徒は canceled 化されない)
            _cancel_superseded_subscription(s, _old_sub_monthly, subscription, _supersede_student_id, "monthly-checkout-supersede")

            # 入塾金 InvoiceItem (月額のみ・先着100名キャンペーン適用時はスキップ)
            # Race condition 対策: webhook 処理時に再度枠チェック (atomic)。
            # checkout時に枠ありと判定されても、webhook処理時には100名超過している可能性があるため。
            session_waiver_flag = meta.get("enrollment_waiver_applied") == "1"
            apply_waiver_now = False
            if session_waiver_flag and customer:
                # 現在の適用済み数を再カウントして上限内か判定
                current_count = _get_waiver_count()
                if current_count < ENROLLMENT_WAIVER_LIMIT:
                    apply_waiver_now = True
                else:
                    log.warning(
                        f"⚠️ Enrollment waiver requested but limit reached "
                        f"(used={current_count}/{ENROLLMENT_WAIVER_LIMIT}). "
                        f"Falling back to standard enrollment fee. customer={customer}"
                    )

            if (meta.get("needs_enrollment_fee") == "1" or (session_waiver_flag and not apply_waiver_now)) and customer:
                try:
                    s.InvoiceItem.create(
                        customer=customer, amount=ENROLLMENT_FEE, currency="jpy",
                        description="入塾金（システム登録費用・初回のみ）",
                        metadata={"plan": plan, "type": "enrollment_fee"},
                    )
                    log.info(f"✅ Enrollment fee InvoiceItem created: customer={customer}")
                except Exception as e:
                    log.error(f"Failed to create enrollment fee InvoiceItem: {type(e).__name__}: {e}")
            elif apply_waiver_now:
                # キャンペーン適用確定 → DB に免除フラグ + 適用日時を記録
                try:
                    if student_id and student_id != "":
                        c.execute(
                            "UPDATE students SET enrollment_fee_waived = 1, "
                            "enrollment_waiver_applied_at = CURRENT_TIMESTAMP "
                            "WHERE id = ? AND enrollment_waiver_applied_at IS NULL",
                            (student_id,),
                        )
                    elif email:
                        c.execute(
                            "UPDATE students SET enrollment_fee_waived = 1, "
                            "enrollment_waiver_applied_at = CURRENT_TIMESTAMP "
                            "WHERE LOWER(email) = ? AND enrollment_waiver_applied_at IS NULL",
                            (email,),
                        )
                    conn.commit()
                    log.info(f"✅ Enrollment fee WAIVED (campaign): customer={customer} student_id={student_id} email={email}")
                except Exception as e:
                    log.error(f"Failed to mark enrollment_fee_waived: {type(e).__name__}: {e}")

            # 紹介ループ報酬: paid 化した生徒の紹介者に ¥3,000 OFF クーポン自動付与。
            # Race condition 対策: atomic UPDATE で coupon_applied_at を先に確保 (claim-first)、
            #   失敗 (=他 worker が先に処理済み) なら何もしない。
            # Deferred 対策: referrer がまだ paid でない時は coupon_id をブランクのまま referred_paid_at だけ記録 →
            #   referrer 自身が paid 化する時 (= この同じ webhook が referrer side で発火) に
            #   _process_deferred_referral_coupons() で再発行。
            try:
                resolved_referred_id = None
                if student_id and student_id != "":
                    resolved_referred_id = int(student_id)
                elif email:
                    c.execute("SELECT id FROM students WHERE LOWER(email) = ? ORDER BY id LIMIT 1", (email,))
                    _row = c.fetchone()
                    if _row:
                        resolved_referred_id = _row["id"] if hasattr(_row, "keys") else _row[0]

                if resolved_referred_id:
                    _process_referral_coupon_for_referred(c, conn, s, resolved_referred_id)

                # 紹介者自身の paid 転換: deferred になっていたクーポンを再処理
                referrer_paid_id = resolved_referred_id  # この生徒が referrer として持つ deferred を処理
                if referrer_paid_id:
                    _process_deferred_referral_coupons(c, conn, s, referrer_paid_id)
            except Exception as e:
                log.error(f"[Referral] reward processing failed: {type(e).__name__}: {e}")

        # Welcome email (どちらのタイプも共通: ログインコード+リンク送信)
        # 429 / 一時エラー対応: _send_magic_link_with_retry を使用 (trial_signup と DRY 統一)
        try:
            if student_id and student_id != "":
                c.execute("SELECT id, name, email, student_email FROM students WHERE id=?", (student_id,))
            elif email:
                c.execute("SELECT id, name, email, student_email FROM students WHERE LOWER(email) = ? ORDER BY id LIMIT 1", (email,))
            else:
                c.execute("SELECT id, name, email, student_email FROM students WHERE 1=0")
            s_row = c.fetchone()
            if s_row and s_row["email"]:
                # [otp-keep-old-codes] 旧 OTP は無効化しない (整理は上限 GC のみ)
                # 1時間有効な短命 magic link token (4番手 監査 2026-04-30)
                _token = _create_magic_link_token(s_row["id"])
                _magic_url = f"{BASE_URL}/auth.html?t={_token}"
                _otp_code = _create_otp(s_row["id"])
                # 🛡️ 2026-06-12: 受信者 cap (爆撃対策) は bypass — Stripe 決済完了がトリガーの
                # 送信なので攻撃者が任意アドレス宛に乱発できず、支払い直後の顧客への
                # ログイン案内が直前の再送連打などでスキップされる事故の方が実害が大きい。
                _wresult = _send_magic_link_with_retry(s_row["email"], s_row["name"] or "", _magic_url, otp_code=_otp_code, is_welcome=True,
                                                        bypass_recipient_cap=True)
                # 🔑 2026-06-12: 子メール (student_email) にも同じリンク/コードを併送。
                # 子メールで checkout した生徒は領収書も welcome も親宛のみで「自分の受信箱に
                # 何も届かない」誤報告になるため (request_magic_link の親+子デュアル送信と対称)。
                _child_sent = None
                _child_blocked = False
                try:
                    _child_email = ((s_row["student_email"] if "student_email" in s_row.keys() else "") or "").strip()
                    if _child_email and _child_email.lower() != (s_row["email"] or "").lower():
                        # 他生徒の親 email と衝突するレガシーデータは送信しない (誤配防止・magic-link 側と同方針)
                        c.execute("SELECT 1 FROM students WHERE LOWER(email) = ? LIMIT 1", (_child_email.lower(),))
                        if c.fetchone():
                            _child_blocked = True
                            log.warning(f"[Webhook] welcome 子メール送信 skip (他生徒の親emailと衝突) student_id={s_row['id']}")
                        else:
                            # cap bypass は親と同じ理屈 (決済トリガーで乱発不可・直前の再送連打で
                            # スキップされると「子の受信箱に何も来ない」が再発するため)。
                            # max_attempts=1: 子宛は副本のため、Resend 障害時に webhook の同期
                            # ブロッキングを親 (~33s) からさらに倍増させない (review MEDIUM)。
                            # 🛡️ 2026-06-12 UX review H2: 子宛は親と共通の magic トークンではなく
                            #   magicv (確認付き) トークンを使う。子がこのリンクをタップすると
                            #   student_email_verified=1 が立ち、以後の magic-link 再発行が子にも届く。
                            #   親の magic リンク併用だとクリックしても確認が立たず、次回再ログインで
                            #   「子に届かない」が再発するため (signup の子 welcome と同方針)。
                            _child_token = _create_student_email_verify_token(s_row["id"], _child_email)
                            _child_magic_url = f"{BASE_URL}/auth.html?t={_child_token}"
                            _child_result = _send_magic_link_with_retry(_child_email, s_row["name"] or "", _child_magic_url, otp_code=_otp_code, is_welcome=True,
                                                                        max_attempts=1, bypass_recipient_cap=True, is_child_verify=True) or {}
                            _child_sent = bool(_child_result.get("sent"))
                except Exception as _ce:
                    log.warning(f"[Webhook] welcome 子メール送信 failed: {_ce}")
                # 監視: signup_email_status と統一フォーマットで記録
                try:
                    _conn_e = db()
                    _cc_e = _conn_e.cursor()
                    _cc_e.execute(
                        "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                        (
                            "welcome_email_status",
                            json.dumps({
                                "student_id": s_row["id"],
                                "email_sent": bool(_wresult.get("sent")),
                                "error": (_wresult.get("error") or "")[:200] if not _wresult.get("sent") else None,
                                "student_email_sent": _child_sent,
                                "student_email_blocked": _child_blocked or None,
                                "source": "stripe_webhook",
                            }, ensure_ascii=False),
                            f"student:{s_row['id']}",
                        ),
                    )
                    _conn_e.commit()
                    _conn_e.close()
                except Exception as _ee:
                    log.warning(f"[Webhook] welcome_email_status event failed: {_ee}")
        except Exception as e:
            log.error(f"Failed to send welcome magic link: {type(e).__name__}: {e}")

        conn.close()
        log.info(f"✅ Checkout completed: type={purchase_type}, plan={plan}, customer={customer}")

    elif event["type"] in ("invoice.payment_succeeded", "invoice.paid"):
        # 🔴 2026-06-11 CRITICAL fix: 本番の Stripe webhook endpoint は invoice.paid のみ購読されており
        # invoice.payment_succeeded は全期間 0 件 (processed_events で実証) → この分岐が一度も発火せず
        # payments テーブルが 0 行のままだった。届くイベント (invoice.paid) でも同じ処理を発火させる。
        # 両イベントが届く環境では event_id が異なり processed_events では dedup できないため、
        # invoice 単位の dedup キー (payment_intent / invoice id) で二重 INSERT を防ぐ。
        invoice = event["data"]["object"]
        # 🚨 2026-05-13 + 2026-06-11 強化: AIコーチングと juku-payment 月謝の完全分離。
        # invoice.metadata だけでなく滞納月謝 (metadata.source) とサブスク metadata
        # (subscription_details / parent.subscription_details) も照合 (3 視点 review CRITICAL-1)
        _skip_reason = _is_non_aijuku_invoice(invoice)
        if _skip_reason:
            log.info(f"[Stripe webhook] Skipping non-ai-juku invoice ({_skip_reason}) - handled by Vercel webhook")
            return JSONResponse({"received": True, "skipped_reason": _skip_reason}, status_code=200)
        conn = db()
        try:
            c = conn.cursor()
            _inv_id = invoice.get("id")
            _inv_pi = invoice.get("payment_intent")
            if isinstance(_inv_pi, dict):
                _inv_pi = _inv_pi.get("id")
            _inv_sub_id = _invoice_subscription_id(invoice)
            _inv_customer = invoice.get("customer")
            _amount_paid = invoice.get("amount_paid", 0) or 0
            # 保存する dedup キーは全 API バージョンで存在する invoice id に正規化 (3 視点 review CRITICAL-2:
            # basil 系 payload は payment_intent が無く、backfill (acacia) と保存キーが食い違うと二重挿入する)。
            # NOT EXISTS の照合リストには payment_intent も含めて旧形式の行とも衝突検知できるようにする。
            _store_key = f"invoice:{_inv_id}" if _inv_id else None
            _dedup_keys = [k for k in (_store_key, _inv_pi) if k]
            # student_id 解決: subscription 優先・無ければ customer で照合
            _pay_student_id = None
            if _inv_sub_id:
                c.execute("SELECT id FROM students WHERE stripe_subscription_id=?", (_inv_sub_id,))
                _ps = c.fetchone()
                if _ps:
                    _pay_student_id = _ps["id"]
            if _pay_student_id is None and _inv_customer:
                c.execute("SELECT id FROM students WHERE stripe_customer_id=?", (_inv_customer,))
                _ps = c.fetchone()
                if _ps:
                    _pay_student_id = _ps["id"]
            if _amount_paid > 0 and _store_key and _pay_student_id is not None:
                try:
                    # paid_at は Stripe 側の支払確定時刻を採用 (webhook 再送・遅延配信でもズレない)。
                    # 注: invoice.paid は paid_out_of_band (Dashboard 手動消込・振込) でも発火するが、
                    # それも実売上として意図的に記録する。
                    _paid_ts = ((invoice.get("status_transitions") or {}).get("paid_at")) or invoice.get("created")
                    _paid_at_dt = datetime.fromtimestamp(_paid_ts, tz=timezone.utc) if _paid_ts else datetime.now(timezone.utc)
                    _ph = ",".join("?" * len(_dedup_keys))
                    c.execute(
                        f"""INSERT INTO payments (student_id, stripe_payment_intent, amount, status, paid_at)
                            SELECT ?, ?, ?, 'paid', ?
                            WHERE NOT EXISTS (SELECT 1 FROM payments WHERE stripe_payment_intent IN ({_ph}))""",
                        (_pay_student_id, _store_key, _amount_paid, _paid_at_dt, *_dedup_keys)
                    )
                    # payments 記録を先に確定 (回復 UPDATE 失敗で入金記録まで巻き戻らないよう txn 分離)
                    conn.commit()
                    if getattr(c, "rowcount", 0) > 0:
                        log.info(f"[Stripe webhook {event['type']}] payment recorded: student_id={_pay_student_id} amount={_amount_paid} invoice={_inv_id}")
                    else:
                        log.info(f"[Stripe webhook {event['type']}] duplicate payment skipped (invoice={_inv_id})")
                except IntegrityError:
                    # UNIQUE index (idx_payments_stripe_pi) との競合 = 並行配信での二重 INSERT → 無視で OK
                    try: conn.rollback()
                    except Exception: pass
                    log.info(f"[Stripe webhook {event['type']}] duplicate payment blocked by unique index (invoice={_inv_id})")
                except Exception as _pay_e:
                    log.error(f"[Stripe webhook {event['type']}] payments INSERT failed: {_pay_e}")
                    try: conn.rollback()
                    except Exception: pass
            elif _amount_paid > 0 and _pay_student_id is None:
                # 生徒不一致の有料 invoice は INSERT しない (3 視点 review CRITICAL-3: NULL student_id 行は
                # 削除 cascade に乗らず再リンク経路も無い)。checkout 完了前の初回 invoice 競合も含め、
                # 生徒行が揃った後の日次 backfill (stripe-backfill-payments) が冪等に拾い直す。
                log.warning(
                    f"[Stripe webhook {event['type']}] paid invoice with no matching student — skipped. "
                    f"35日以内は日次 backfill が拾い直す / 35日超は手動 backfill (days=365) が必要 "
                    f"(invoice={_inv_id} sub={_inv_sub_id} customer={_inv_customer} amount={_amount_paid})"
                )
                try:
                    # 🔭 取りこぼし観測 (2026-06-11 ラウンド1 review): scheduler 停止等で backfill が
                    # 走らない場合に CEO 失敗 feed で気付けるよう events に記録 (対処= backfill 実行)。
                    _record_ai_critical_event("payment_unmatched_invoice", {
                        "invoice": _inv_id,
                        "subscription_id": _inv_sub_id,
                        "customer": _inv_customer,
                        "amount": _amount_paid,
                        "source": "webhook_invoice_paid",
                    })
                except Exception as _ue:
                    log.error(f"[Stripe webhook {event['type']}] unmatched observation event failed: {_ue}")
            elif _amount_paid <= 0:
                # $0 invoice (trial 期間・100% クーポン) は入金ではないため記録しない (payment_failed 分岐と同基準)
                log.info(f"[Stripe webhook {event['type']}] skip $0 invoice (invoice={_inv_id} sub={_inv_sub_id})")
            # 🔁 2026-05-29 課金回復: 過去に決済失敗で past_due 化した生徒が、
            # リトライ成功 (invoice.paid / invoice.payment_succeeded) したら自動で paid に戻す (二重保険)。
            # 主経路は customer.subscription.updated (status active) だが、webhook 順序や
            # 取りこぼしに備えてこちらでも回復させる。canceled/expired には触れない。
            # trial_end=NULL は主経路 (subscription.updated active) と同じ規約 (2026-06-12) —
            # paid 行に未来の trial_end が残ると cron_trial_reminders で誤テンプレ送信になる。
            if _inv_sub_id:
                try:
                    c.execute(
                        """UPDATE students SET status='paid',
                               paid_since=COALESCE(paid_since, CURRENT_TIMESTAMP),
                               trial_end=NULL,
                               past_due_since=NULL,
                               updated_at=CURRENT_TIMESTAMP
                           WHERE stripe_subscription_id=? AND status='past_due'""",
                        (_inv_sub_id,)
                    )
                    conn.commit()
                    if c.rowcount > 0:
                        log.info(f"[Stripe webhook {event['type']}] past_due→paid recovered: sub={_inv_sub_id} ({c.rowcount} students)")
                except Exception as _rec_e:
                    log.error(f"[Stripe webhook {event['type']}] recovery update failed: {_rec_e}")
                    try: conn.rollback()
                    except Exception: pass
        finally:
            # 生徒解決 SELECT が try 外にあった旧構造は例外時に conn リーク + HTTP 500 を起こし得た
            # (2026-06-11 ラウンド1 review LOW) → 分岐全体を try/finally で閉じる
            try: conn.close()
            except Exception: pass

    elif event["type"] == "charge.refunded":
        # 💸 2026-06-11 (ラウンド1 review): 返金の逆仕訳。payments が売上集計 (revenue-timeline /
        # 30日売上 / mrr_yen) の真実になったため、返金を反映しないと売上が恒久的に過大表示になる。
        # ai-juku 判定は「payments に該当行が存在するか」で行う: juku-payment の charge は
        # payments に行が無いので自然に no-op (別系統の metadata 判定を再実装しない)。
        # amount_refunded は cumulative なので同イベントが何度届いても冪等。
        charge = event["data"]["object"]
        _ch_inv = charge.get("invoice")
        if isinstance(_ch_inv, dict):
            _ch_inv = _ch_inv.get("id")
        _ch_pi = charge.get("payment_intent")
        if isinstance(_ch_pi, dict):
            _ch_pi = _ch_pi.get("id")
        _refund_keys = [k for k in (f"invoice:{_ch_inv}" if _ch_inv else None, _ch_pi) if k]
        _amount_refunded = charge.get("amount_refunded", 0) or 0
        _ch_amount = charge.get("amount", 0) or 0
        if _refund_keys and _amount_refunded > 0:
            conn = db()
            try:
                c = conn.cursor()
                _ph = ",".join("?" * len(_refund_keys))
                if charge.get("refunded") or (_ch_amount and _amount_refunded >= _ch_amount):
                    # 全額返金: status='refunded' に倒す (売上 SUM は status='paid' のみなので自然に除外)
                    c.execute(
                        f"UPDATE payments SET status='refunded' WHERE stripe_payment_intent IN ({_ph})",
                        tuple(_refund_keys),
                    )
                else:
                    # 一部返金: 残額に更新 (status は 'paid' のまま)。全額返金済 ('refunded') 行には触れない。
                    # AND amount > ? で「残額が減る方向」にのみ更新 (R2 review: out-of-order 配信で
                    # 古い小さい amount_refunded が後から届いても巻き戻さない・冪等)
                    _new_amount = _ch_amount - _amount_refunded
                    c.execute(
                        f"UPDATE payments SET amount=? WHERE stripe_payment_intent IN ({_ph}) AND status='paid' AND amount > ?",
                        (_new_amount, *_refund_keys, _new_amount),
                    )
                conn.commit()
                if getattr(c, "rowcount", 0) > 0:
                    log.info(f"[Stripe webhook charge.refunded] 返金反映: keys={_refund_keys} refunded={_amount_refunded}/{_ch_amount}")
                else:
                    log.info(f"[Stripe webhook charge.refunded] payments に該当行なし (juku-payment / 未記録) → no-op (keys={_refund_keys})")
            except Exception as _rf_e:
                log.error(f"[Stripe webhook charge.refunded] 反映失敗: {_rf_e}")
                try: conn.rollback()
                except Exception: pass
            finally:
                try: conn.close()
                except Exception: pass

    elif event["type"] == "invoice.payment_failed":
        # 🔴 2026-05-29 MAJOR fix: 月次サブスクの決済失敗を検知して status='past_due' に降格。
        # これが無いと「カード期限切れ・残高不足で実際は入金停止なのに DB は paid のまま」
        # となり MRR と実入金が乖離する。
        # ・降格対象は **paid のみ** (trial は除外: trial_extended の初回課金失敗で「転換寸前の体験生」を
        #   誤ロックしないため。trial 終了は trial_end / expire scheduler が担当)
        # ・塾長指示「猶予期間あり」: past_due は grace 期間中アクセス維持 (access gate)、past_due_since を打刻
        # ・$0 invoice (trial/100%クーポン) は amount_due=0 で skip
        # ・リトライ成功時は invoice.payment_succeeded / subscription.updated(active) で自動 paid 回復
        # ・CEO へ critical event 記録 + 生徒へカード更新案内メール (dedup)
        invoice = event["data"]["object"]
        _skip_reason = _is_non_aijuku_invoice(invoice)
        if _skip_reason:
            log.info(f"[Stripe webhook] Skipping non-ai-juku invoice.payment_failed ({_skip_reason}) - handled by Vercel webhook")
            return JSONResponse({"received": True, "skipped_reason": _skip_reason}, status_code=200)
        _fail_sub_id = _invoice_subscription_id(invoice)
        _fail_customer = invoice.get("customer")
        _amount_due = invoice.get("amount_due", 0)
        _attempt = invoice.get("attempt_count", 0)
        # $0 invoice は実課金でないため降格しない (trial 期間の $0 invoice 等)
        if not _amount_due or _amount_due <= 0:
            log.info(f"[Stripe webhook invoice.payment_failed] skip $0 invoice (sub={_fail_sub_id})")
            return {"received": True, "skipped_reason": "zero amount invoice"}
        conn = db()
        c = conn.cursor()
        matched_rows = []
        try:
            # subscription_id 優先で照合 (最も正確)。無ければ customer_id で fallback。降格対象は paid のみ。
            if _fail_sub_id:
                c.execute(
                    "SELECT id, name, email, plan, status FROM students WHERE stripe_subscription_id=? AND status='paid'",
                    (_fail_sub_id,)
                )
                matched_rows = list(c.fetchall())
            if not matched_rows and _fail_customer:
                c.execute(
                    "SELECT id, name, email, plan, status FROM students WHERE stripe_customer_id=? AND status='paid'",
                    (_fail_customer,)
                )
                matched_rows = list(c.fetchall())
            for _mr in matched_rows:
                _sid = _mr["id"]
                # past_due_since は COALESCE で初回失敗時刻を保持 (grace の起点・リトライ毎にリセットしない)
                c.execute(
                    """UPDATE students SET status='past_due',
                           past_due_since=COALESCE(past_due_since, CURRENT_TIMESTAMP),
                           updated_at=CURRENT_TIMESTAMP
                       WHERE id=? AND status='paid'""",
                    (_sid,)
                )
            conn.commit()
        except Exception as _fe:
            log.error(f"[Stripe webhook invoice.payment_failed] update failed: {_fe}")
            try: conn.rollback()
            except Exception: pass
        conn.close()
        if matched_rows:
            for _mr in matched_rows:
                log.error(
                    f"🔴 [Stripe webhook invoice.payment_failed] paid→past_due: "
                    f"student_id={_mr['id']} email={_mr['email']} plan={_mr['plan']} "
                    f"prev_status={_mr['status']} amount_due={_amount_due} attempt={_attempt} sub={_fail_sub_id}"
                )
                _record_ai_critical_event("stripe_payment_failed", {
                    "student_id": _mr["id"],
                    "name": _mr["name"],
                    "email": _mr["email"],
                    "plan": _mr["plan"],
                    "prev_status": _mr["status"],
                    "amount_due": _amount_due,
                    "attempt_count": _attempt,
                    "subscription": _fail_sub_id,
                    "customer": _fail_customer,
                })
                # 💳 生徒へカード更新案内メール (dedup: 7日以内に送信済みなら再送しない)
                try:
                    _send_payment_failed_dunning_email(_mr["id"], _mr["name"], _mr["email"])
                except Exception as _de:
                    log.error(f"[Stripe webhook invoice.payment_failed] dunning email failed for {_mr['id']}: {_de}")
        else:
            log.warning(
                f"[Stripe webhook invoice.payment_failed] no matching paid/trial student "
                f"(sub={_fail_sub_id} customer={_fail_customer} amount_due={_amount_due})"
            )

    elif event["type"] in ("payment_intent.succeeded", "payment_intent.payment_failed", "setup_intent.succeeded"):
        # 🚨 2026-05-13: AIコーチングは subscription/invoice ベースなので PaymentIntent / SetupIntent はすべて juku-payment 系として skip
        # (もし将来 ai-juku でも PaymentIntent 直接利用する場合は metadata.system を明示的に区別すること)
        obj = event["data"]["object"]
        _meta = obj.get("metadata", {}) or {}
        _sys = (_meta.get("system") or "").strip()
        if _sys.startswith("juku-payment"):
            log.info(f"[Stripe webhook] {event['type']} from juku-payment (system={_sys}) - handled by Vercel webhook")
        else:
            log.info(f"[Stripe webhook] {event['type']} from unknown source (system={_sys or 'none'}) - skip")
        return JSONResponse({"received": True, "skipped_reason": "PaymentIntent/SetupIntent not handled by ai-juku"}, status_code=200)

    elif event["type"] in ("customer.subscription.deleted", "customer.subscription.canceled"):
        sub = event["data"]["object"]
        # 🚨 2026-05-13: AIコーチングと juku-payment 月謝の完全分離 (二重保険)
        # juku-payment は setup mode で subscription を持たない設計だが、
        # 将来 Stripe Dashboard 等で手動 subscription が作られた場合に ai-juku DB 誤更新を防ぐ
        _sub_meta = sub.get("metadata", {}) or {}
        if (_sub_meta.get("system") or "").startswith("juku-payment"):
            log.info(f"[Stripe webhook] Skipping juku-payment subscription event (system={_sub_meta.get('system')})")
            return JSONResponse({"received": True, "skipped_reason": "juku-payment system tag"}, status_code=200)
        conn = db()
        c = conn.cursor()
        # cancel_at=NULL [cancel-period-end]: 期間末解約の完了 (または即時解約) で予約状態を解消。
        # 残すと再契約時 (新サブスク紐付け前の表示) に「解約予約済み」が誤表示される。
        # 🧹 [cancel-consistency] (2026-06-12): canceled 遷移時に stripe_subscription_id も NULL クリア。
        # 死んだ sub_id が残留すると、trial 再付与 (win-back/admin) 後に card_registered 誤表示 /
        # cancel-trial の Stripe 502 (UI から解約不能) / expire-trials cron 除外 (永久に失効しない) /
        # 課金前通知の誤送信を引き起こす (trial_extended 文言分岐レビューで発覚)。
        # past_due_since も canceled 遷移で解消 (05604ea の不変条件と同じ。monthly checkout の paid 化は
        # past_due_since をクリアしないため、stale な猶予起点が再契約後の決済失敗で即失効を招く)。
        c.execute("UPDATE students SET status='canceled', cancel_at=NULL, stripe_subscription_id=NULL, past_due_since=NULL, updated_at=CURRENT_TIMESTAMP WHERE stripe_subscription_id=?",
                  (sub.get("id"),))
        _del_matched = c.rowcount
        _dup_cleared = False
        if _del_matched == 0:
            # [cancel-consistency] updated(canceled) ハンドラが先に sub_id を NULL クリア済みだと
            # ここは 0 件一致になる。その場合は処理済みイベントの重複なので警告を出さない (誤報抑制)。
            try:
                c.execute("SELECT 1 FROM students WHERE stripe_customer_id=? AND status='canceled' LIMIT 1",
                          (sub.get("customer"),))
                _dup_cleared = bool(c.fetchone())
            except Exception:
                pass
        conn.commit()
        conn.close()
        if _del_matched == 0:
            if _dup_cleared:
                log.info(
                    f"[Stripe webhook {event['type']}] sub={sub.get('id')} customer={sub.get('customer')} "
                    f"は処理済み (canceled & sub_id クリア済み) — 重複イベントとして無視"
                )
            elif (_sub_meta.get("superseded_by") or "").strip():
                # 🔁 [upgrade-supersede] 月額移行/再申込で置換され webhook 側から即時解約した旧サブスク。
                # DB は新 sub_id を指しているため不一致が正常 — orphan 警告 (要確認) を出さない。
                log.info(
                    f"[Stripe webhook {event['type']}] sub={sub.get('id')} は置換済み旧サブスクの解約 "
                    f"(superseded_by={_sub_meta.get('superseded_by')}) — 正常"
                )
            else:
                # 🔍 2026-06-11: どの生徒の stripe_subscription_id にも一致しない解約イベントを可視化。
                # 同一顧客の重複サブスク (二重課金) や手動作成サブスクの解約を見逃さないための観測ログ。
                log.warning(
                    f"[Stripe webhook {event['type']}] no matching student for sub={sub.get('id')} "
                    f"customer={sub.get('customer')} — 重複サブスク/手動サブスクの可能性。Stripe Dashboard で要確認"
                )

    elif event["type"] == "customer.subscription.updated":
        # 🎁 2026-05-19: +7 日 trial → paid 化検知 (集客 funnel #4)
        # 🔴 2026-05-29 MAJOR fix: Subscription の status 遷移を双方向で DB に同期する。
        #   - 'active'  : trial 終了 or past_due 回復 → status='paid'
        #   - 'past_due'/'unpaid' : 月次決済失敗 → status='past_due' (access gate が拒否) + CEO 通知
        #   - 'canceled': 解約 → status='canceled' (deleted ハンドラの二重保険)
        # purchase_type='trial_extended' 経路で作成された Subscription が 21 日経過して自動課金成功した case を含む
        sub = event["data"]["object"]
        _sub_meta = sub.get("metadata", {}) or {}
        if (_sub_meta.get("system") or "").startswith("juku-payment"):
            return JSONResponse({"received": True, "skipped_reason": "juku-payment system tag"}, status_code=200)
        sub_id = sub.get("id")
        sub_status = sub.get("status")  # 'trialing', 'active', 'past_due', 'unpaid', 'canceled'
        # 🚪 [cancel-period-end] (2026-06-12): cancel_at_period_end / cancel_at を students.cancel_at に常時同期。
        # 自社の /api/billing/cancel-trial (paid/past_due は期間末解約に変更) だけでなく、Stripe Customer
        # Portal での「期間末解約の予約」や「予約の取消 (契約再開)」もこの updated イベントで届くため、
        # イベントの値を真実として毎回書く (予約が無ければ NULL に戻る = 自己修復)。
        # status の canceled 化は従来どおり deleted ハンドラ / 下の canceled 分岐が担当し、ここでは触らない。
        try:
            _cap_flag = bool(sub.get("cancel_at_period_end"))
            _cap_ts = sub.get("cancel_at") or (sub.get("current_period_end") if _cap_flag else None)
            _cap_iso = None
            if _cap_ts:
                _cap_iso = datetime.fromtimestamp(int(_cap_ts), tz=timezone.utc).isoformat()
            _conn_cap = db()
            try:
                _c_cap = _conn_cap.cursor()
                _c_cap.execute(
                    "UPDATE students SET cancel_at=?, updated_at=CURRENT_TIMESTAMP WHERE stripe_subscription_id=?",
                    (_cap_iso, sub_id)
                )
                if _c_cap.rowcount > 0 and _cap_iso:
                    log.info(f"[Stripe webhook subscription.updated] cancel_at sync: sub={sub_id} cancel_at={_cap_iso}")
                _conn_cap.commit()
            finally:
                _conn_cap.close()
        except Exception as _cape:
            log.error(f"[Stripe webhook subscription.updated] cancel_at sync failed for sub={sub_id}: {_cape}")
        if sub_status == "active":
            # trial → paid (自動課金成功) もしくは past_due → paid (リトライ成功で回復)。past_due_since もクリア。
            # 🔴 2026-06-12: 'expired' も回復対象に追加。expire-trials cron が本 webhook より先に走る /
            # 配送遅延・失敗すると、カード登録済み生徒 (trial_extended) が expired に落ち
            # 「Stripe は課金継続・アクセスは失効」のまま固定されていた。active 受信時点で paid に自己回復させる。
            conn = db()
            c = conn.cursor()
            try:
                c.execute(
                    """UPDATE students SET status='paid',
                           paid_since=COALESCE(paid_since, CURRENT_TIMESTAMP),
                           trial_end=NULL,
                           past_due_since=NULL,
                           updated_at=CURRENT_TIMESTAMP
                       WHERE stripe_subscription_id=? AND status IN ('trial','past_due','expired')""",
                    (sub_id,)
                )
                affected = c.rowcount
                conn.commit()
                if affected > 0:
                    log.info(f"[Stripe webhook subscription.updated] →paid (trial/past_due/expired解消): sub={sub_id} ({affected} students)")
            except Exception as e:
                log.error(f"[Stripe webhook subscription.updated active] failed: {e}")
                try: conn.rollback()
                except Exception: pass
            conn.close()
        elif sub_status in ("past_due", "unpaid"):
            # 月次決済失敗で Stripe が past_due/unpaid に遷移 → DB も past_due に降格。
            # **paid のみ対象** (trial は除外: trial_extended 初回課金失敗での誤ロック防止。canceled/expired にも触れない)。
            # 塾長指示「猶予期間あり」: past_due_since を打刻し grace 期間中はアクセス維持。
            conn = db()
            c = conn.cursor()
            notify_rows = []
            try:
                c.execute(
                    "SELECT id, name, email, plan, status FROM students WHERE stripe_subscription_id=? AND status='paid'",
                    (sub_id,)
                )
                notify_rows = list(c.fetchall())
                for _nr in notify_rows:
                    c.execute(
                        """UPDATE students SET status='past_due',
                               past_due_since=COALESCE(past_due_since, CURRENT_TIMESTAMP),
                               updated_at=CURRENT_TIMESTAMP
                           WHERE id=? AND status='paid'""",
                        (_nr["id"],)
                    )
                conn.commit()
            except Exception as e:
                log.error(f"[Stripe webhook subscription.updated past_due] failed: {e}")
                try: conn.rollback()
                except Exception: pass
            conn.close()
            for _nr in notify_rows:
                log.error(
                    f"🔴 [Stripe webhook subscription.updated] {sub_status}: "
                    f"student_id={_nr['id']} email={_nr['email']} plan={_nr['plan']} "
                    f"prev_status={_nr['status']} sub={sub_id}"
                )
                _record_ai_critical_event("stripe_payment_failed", {
                    "student_id": _nr["id"],
                    "name": _nr["name"],
                    "email": _nr["email"],
                    "plan": _nr["plan"],
                    "prev_status": _nr["status"],
                    "subscription": sub_id,
                    "source": f"subscription.updated:{sub_status}",
                })
                try:
                    _send_payment_failed_dunning_email(_nr["id"], _nr["name"], _nr["email"])
                except Exception as _de:
                    log.error(f"[Stripe webhook subscription.updated past_due] dunning email failed for {_nr['id']}: {_de}")
        elif sub_status == "canceled":
            # subscription.deleted ハンドラの二重保険 (updated でも canceled が来うる)
            conn = db()
            c = conn.cursor()
            try:
                # 🧹 [cancel-consistency] (2026-06-12): deleted ハンドラ同様、canceled 遷移時に sub_id も
                # NULL クリア (死んだ sub_id 残留による card_registered 誤表示 / cancel-trial 502 /
                # expire-trials cron 除外を防ぐ)。past_due_since も同時解消 (canceled 遷移の不変条件)。
                c.execute(
                    "UPDATE students SET status='canceled', cancel_at=NULL, stripe_subscription_id=NULL, past_due_since=NULL, updated_at=CURRENT_TIMESTAMP WHERE stripe_subscription_id=? AND status IN ('paid','trial','past_due')",
                    (sub_id,)
                )
                if c.rowcount > 0:
                    log.info(f"[Stripe webhook subscription.updated] →canceled: sub={sub_id} ({c.rowcount} students)")
                conn.commit()
            except Exception as e:
                log.error(f"[Stripe webhook subscription.updated canceled] failed: {e}")
                try: conn.rollback()
                except Exception: pass
            conn.close()

    return {"received": True}

