def _line_build_todo_text(student) -> str:
    """「やること」コマンドの返信本文。mypage「コーチの今日の一手」と同じデータ源
    (宿題ドリル → 弱点 → 今日の学習記録) をサーバ側だけで集約する (AI 課金ゼロ・決定論)。
    復習カード (忘却曲線) は client localStorage のみのため含めない。"""
    sid = student["id"]
    conn = db()
    try:
        c = conn.cursor()
        c.execute(
            "SELECT d.title, d.unit FROM grammar_drill_assignments a "
            "JOIN grammar_drills d ON d.id = a.drill_id "
            "WHERE a.student_id = ? AND a.status = 'open' "
            "ORDER BY a.assigned_at LIMIT 3",
            (sid,),
        )
        drills = list(c.fetchall())
        c.execute(
            "SELECT COUNT(*) AS n FROM grammar_drill_assignments WHERE student_id = ? AND status = 'open'",
            (sid,),
        )
        drill_total = c.fetchone()["n"] or 0
        c.execute(
            "SELECT subject, topic FROM student_weakness "
            "WHERE student_id = ? AND question_count > 0 "
            "ORDER BY question_count DESC LIMIT 1",
            (sid,),
        )
        weak = c.fetchone()
        c.execute(
            "SELECT COALESCE(SUM(minutes), 0) AS m FROM study_logs WHERE student_id = ? AND studied_date = ?",
            (sid, _today_jst().isoformat()),
        )
        today_min = c.fetchone()["m"] or 0
    finally:
        conn.close()

    name = (student["name"] or "").strip() or "生徒"
    lines = [f"📋 {name}さんの今日のやること", ""]
    if drill_total > 0:
        lines.append(f"📚 塾長からの宿題ドリル: {drill_total}件")
        for d in drills:
            lines.append(f"・{d['title']} ({d['unit']})")
        if drill_total > len(drills):
            lines.append(f"…ほか {drill_total - len(drills)} 件")
    else:
        lines.append("📚 未完了の宿題ドリルはありません 👏")
    if weak:
        lines.append(f"🎯 苦手の復習: {(weak['topic'] or weak['subject'])[:30]}")
    if today_min > 0:
        lines.append(f"⏱ 今日の学習記録: {today_min}分")
    else:
        lines.append("⏱ 今日の学習記録: まだ0分 — まず1つ取り組んでみよう")
    lines += ["", "▶ マイページで取り組む", f"{BASE_URL}/mypage.html"]
    return "\n".join(lines)


def _line_handle_question(student, content: str, reply_token: str):
    """「質問 <内容>」を塾長への問い合わせ (messages) として保存 + email 通知。
    CEO ダッシュ「受信した申込問い合わせ」(sender_type='student' AND recipient_type='admin')
    に表示され、既存の 返信 / AI 返信案 ボタンがそのまま使える。"""
    body = _sanitize_text(content, 5000)
    if not body:
        _line_reply_text(reply_token, _LINE_QUESTION_USAGE)
        return
    sid = student["id"]
    name = (student["name"] or "").strip() or "生徒"
    subject = f"📱 LINE質問: {name}さん"
    conn = db()
    try:
        c = conn.cursor()
        # 連投ガード: LINE 経由は未認証面のため、生徒あたり 10 件/時で打ち止め (爆撃・誤連打対策)
        _cutoff_h = (datetime.now(timezone.utc) - timedelta(hours=1)).strftime("%Y-%m-%d %H:%M:%S")
        c.execute(
            "SELECT COUNT(*) AS n FROM messages WHERE sender_type='student' AND sender_id=? "
            "AND sent_via='line' AND created_at >= ?",
            (sid, _cutoff_h),
        )
        if (c.fetchone()["n"] or 0) >= 10:
            _line_reply_text(reply_token, "⚠️ 短時間に送れる質問の上限に達しました。しばらくしてからお試しください。")
            return
        # 冪等ガード: message イベントは webhookEventId dedup の対象外 (連携コード再送考慮) のため、
        # LINE の再配送で同一質問が二重登録されないよう 同一生徒・同一本文 5 分以内は INSERT しない
        _cutoff_m = (datetime.now(timezone.utc) - timedelta(minutes=5)).strftime("%Y-%m-%d %H:%M:%S")
        c.execute(
            "SELECT id FROM messages WHERE sender_type='student' AND sender_id=? AND sent_via='line' "
            "AND body=? AND created_at >= ? LIMIT 1",
            (sid, body, _cutoff_m),
        )
        if c.fetchone():
            _line_reply_text(reply_token, "✅ 質問を塾長に届けました！\n返信は LINE またはメールでお知らせします。")
            return
        c.execute(
            "INSERT INTO messages (sender_type, sender_id, recipient_type, recipient_id, broadcast_filter, subject, body, sent_via, email_status) "
            "VALUES (?,?,?,?,?,?,?,?,?)",
            ("student", sid, "admin", None, None, subject, body, "line", None),
        )
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("student_message_sent",
                 json.dumps({"student_id": sid, "name": name, "source": "line",
                             "subject": subject[:120]}, ensure_ascii=False),
                 str(sid)),
            )
        except Exception:
            pass
        conn.commit()
        log.info(f"[LINE question] student={sid} → messages 登録 (len={len(body)})")
    finally:
        conn.close()
    # 塾長 email 通知 (student_send_message と同パターン・失敗しても質問自体は保存済み)
    if DAILY_SNS_TO_EMAIL and RESEND_API_KEY and FROM_EMAIL:
        try:
            import urllib.request as _ur
            email_body = (
                f"{name}さん (生徒ID:{sid}) から LINE 経由で質問が届きました。\n\n{body}\n\n"
                f"CEO ダッシュ「📨 メッセージ配信」 → 履歴 で内容確認 + 返信できます。"
            )
            req = _ur.Request(
                "https://api.resend.com/emails",
                data=json.dumps({
                    "from": FROM_EMAIL,
                    "to": [DAILY_SNS_TO_EMAIL],
                    "subject": f"📱 [LINE質問] {name}さん",
                    "text": email_body,
                }).encode("utf-8"),
                headers={"Authorization": f"Bearer {RESEND_API_KEY}", "Content-Type": "application/json", "User-Agent": "ai-juku-system/1.0"},
                method="POST",
            )
            _ur.urlopen(req, timeout=10).read()
        except Exception as _e:
            log.warning(f"[LINE question] email notify failed: {_e}")
    _line_reply_text(reply_token, "✅ 質問を塾長に届けました！\n返信は LINE またはメールでお知らせします。")


@app.post("/api/line/webhook")
async def line_webhook(request: Request, x_line_signature: str = Header(None)):
    """LINE Messaging API webhook。署名検証後、各イベントを非同期ハンドラに投げて即 200 を返す
    (LINE は 3 秒以内の応答を要求)。follow=連携案内 / message=連携コード照合 / image=AI 解答 (Phase C)。"""
    body = await request.body()
    # 🔒 fail-closed: SECRET 未設定なら受信拒否 (偽イベントの無認証投入を防ぐ)。
    #   本番は Messaging API チャネルの SECRET 設定済み前提。webhook URL を LINE Console に
    #   登録する際に SECRET も必ず設定すること (ACCESS_TOKEN とペア)。
    if not LINE_CHANNEL_SECRET:
        log.error("[LINE webhook] LINE_CHANNEL_SECRET 未設定のため受信拒否 (fail-closed)")
        raise HTTPException(status_code=503, detail="LINE webhook not configured")
    hash_ = hmac.new(LINE_CHANNEL_SECRET.encode("utf-8"), body, hashlib.sha256).digest()
    # bytes 同士で比較: compare_digest(str, str) は非 ASCII ヘッダで TypeError → 500 になるため
    #   (攻撃者制御の x-line-signature に対し 400 を維持する既存バグ修理)。
    try:
        sig_bytes = (x_line_signature or "").encode("utf-8")
    except Exception:
        sig_bytes = b""
    if not sig_bytes or not hmac.compare_digest(base64.b64encode(hash_), sig_bytes):
        raise HTTPException(status_code=400, detail="Invalid signature")
    try:
        data = json.loads(body)
    except Exception:
        return {"ok": True}
    import asyncio as _aio
    for event in data.get("events", []):
        try:
            _t = _aio.create_task(_handle_line_event(event))
            _LINE_BG_TASKS.add(_t)
            _t.add_done_callback(_LINE_BG_TASKS.discard)
        except Exception as e:
            log.warning(f"[LINE webhook] dispatch failed: {e}")
    return {"ok": True}


async def _handle_line_event(event: dict):
    """LINE webhook イベントの非同期ハンドラ。冪等性 + follow + message(連携コード) を処理。
    image = AIチューター写真解答は Phase C で _handle_line_image を追加して分岐する。"""
    try:
        etype = event.get("type")
        source = event.get("source") or {}
        user_id = source.get("userId")
        reply_token = event.get("replyToken")
        # 冪等性: follow 等の副作用は二重実行を避ける。ただし message(連携コード) は bind が冪等で、
        #   かつ初回処理が一時失敗した際の LINE 再送で連携を取りこぼさないよう、seen スキップ対象外にする。
        event_id = event.get("webhookEventId")
        if etype != "message" and event_id and _line_event_seen(event_id):
            return

        if etype == "follow":
            # bot からの follow 自動返信は送らない (2026-06-11 塾長指示「1+2」)。
            #   新規友だちの大半はマーケ流入の見込み客で、「連携コード」案内は混乱の元。
            #   あいさつは OA Manager の「あいさつメッセージ」(塾長作成・有効) に一本化し、
            #   生徒への連携手順は mypage の「LINE連携」UI 側で案内する。
            return

        if etype == "message":
            msg = event.get("message") or {}
            if msg.get("type") == "text":
                text = (msg.get("text") or "").strip()
                # 連携コード照合は正規化版で行う (コピペの前後空白・改行・ゼロ幅スペース・全角を吸収)。
                # コマンド (やること/質問) や有人チャット判定は元の text を使う。
                code_text = _normalize_link_code(text)
                # 先に消費せず peek → 別生徒に紐付く LINE なら有効コードを burn せず案内 (リトライ余地を残す)
                peek_sid = _peek_line_link_token(code_text) if code_text else None
                if peek_sid and user_id:
                    if _line_user_taken_by_other(user_id, peek_sid):
                        log.warning(f"[LINE bind] taken: userId(...{user_id[-6:]}) は別生徒に紐付き済 (要求 sid={peek_sid})")
                        _line_reply_text(reply_token, "⚠️ このLINEは既に別の生徒アカウントに連携済みです。\nお心当たりがなければ塾までご連絡ください。")
                        return
                    sid = _consume_line_link_token(code_text)  # ここで初めて atomic single-use 消費
                    if sid:
                        result = _bind_line_user(sid, user_id)
                        if result == "ok":
                            log.info(f"[LINE bind] student_id={sid} linked (userId ...{user_id[-6:]})")
                            _line_reply_text(reply_token, "✅ LINE連携が完了しました！\n今後はログインコードやお知らせがLINEに届きます。")
                        else:
                            log.warning(f"[LINE bind] taken(race): student_id={sid} userId(...{user_id[-6:]})")
                            _line_reply_text(reply_token, "⚠️ このLINEは既に別の生徒アカウントに連携済みです。\nお心当たりがなければ塾までご連絡ください。")
                    else:
                        _line_reply_text(reply_token, "⚠️ 連携コードが無効または期限切れです。マイページで新しいコードを発行してください。")
                elif code_text and not peek_sid and _LINE_CODE_LIKE.fullmatch(code_text):
                    # コードらしき文字列だが実際に無効 (期限切れ/タイプミス/使用済) → ここだけ案内を返す。
                    #   peek_sid 有効 + user_id 欠落 (グループ/ルーム投稿等 bind 不可能な経路) は誤案内せず沈黙。
                    # 🔍 [line-link-diag] (2026-06-12): 「発行直後なのに期限切れ」報告の原因特定のため
                    #   理由 (not_found/used/expired) をログに残す (コード全文は短命 secret のため先頭のみ)。
                    _diag = _line_link_token_status(code_text)
                    if user_id and _diag.get("reason") in ("used", "not_found") and _line_student_by_user(user_id):
                        # 既に連携済みの LINE からの (使用済み/古い) コード再送 — 初回処理で reply だけ
                        # 失われたケースを「期限切れ」と誤案内せず、連携完了を伝える。
                        log.info(f"[LINE link] code from already-linked user (...{str(user_id)[-6:]}): reason={_diag.get('reason')}")
                        _line_reply_text(reply_token, "✅ このLINEはすでに連携済みです。\n「やること」と送ると今日のまとめが届きます。")
                    else:
                        log.warning(
                            f"[LINE link] invalid code-like rejected: reason={_diag.get('reason')} "
                            f"prefix={code_text[:6]}… len={len(code_text)} server_now={_diag.get('server_now')} "
                            f"expires_at={_diag.get('expires_at_parsed')}"
                        )
                        _line_reply_text(reply_token, "⚠️ 連携コードが無効または期限切れです。マイページで新しいコードを発行してください。")
                elif text and user_id and _LINE_CMD_TODO.fullmatch(text):
                    # 🤝 [line-phase1] やること確認: 固定文字列の完全一致のみ反応 (リッチメニュー対応)
                    _cmd_row = _line_student_by_user(user_id)
                    if _cmd_row:
                        _line_reply_text(reply_token, _line_build_todo_text(_cmd_row))
                    else:
                        _line_reply_text(reply_token, _LINE_NOT_LINKED_GUIDE)
                elif text and user_id and _LINE_CMD_QUESTION.match(text):
                    # 🤝 [line-phase1] 質問転送: 「質問」単独 or 「質問 <内容>」(区切り必須) のみ反応
                    _cmd_row = _line_student_by_user(user_id)
                    if _cmd_row:
                        _line_handle_question(_cmd_row, _LINE_CMD_QUESTION.sub("", text, count=1), reply_token)
                    else:
                        _line_reply_text(reply_token, _LINE_NOT_LINKED_GUIDE)
                # それ以外の通常トーク (挨拶・質問・チャット) には bot は沈黙する。
                #   チャット:オン の有人対応・応答メッセージ運用と干渉しないため (2026-06-11 塾長指示)。
            return
    except Exception as e:
        log.error(f"[LINE event] handler error: {type(e).__name__}: {e}")


@app.post("/api/line/link-code")
def line_link_code(authorization: Optional[str] = Header(None)):
    """ログイン中の生徒が自分の LINE 連携コードを発行する (mypage の「LINE連携」ボタン)。
    本人性: session_token で認証された生徒のみ → 自分の student_id にしか紐付かない。"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="ログインが必要です")
    claims = _verify_session_token(authorization[len("Bearer "):].strip())
    if not claims or not claims.get("student_id"):
        raise HTTPException(status_code=401, detail="セッションの有効期限が切れています")
    sid = int(claims["student_id"])
    code = _create_line_link_token(sid)  # [line-link-noexpiry] 期限なし (single-use のみ)
    return {
        "ok": True,
        "code": code,
        "expires_in_min": None,  # 無期限 (後方互換のためキーは残す)
        "add_friend_url": LINE_ADD_FRIEND_URL,
        "instructions": "①公式LINEを友だち追加 → ②このコードをトークに送信、で連携完了です（期限なし・1回で完了）。",
    }


@app.get("/api/admin/line/link-token-status")
def admin_line_link_token_status(token: str, authorization: Optional[str] = Header(None),
                                 x_cron_secret: Optional[str] = Header(None)):
    """🔍 [line-link-diag] 連携コードの状態診断 (read-only)。「発行直後なのに期限切れ」等の
    トラブル時に、コードが not_found (別環境/別DB) / used (二重処理) / expired (時刻ズレ) /
    valid のどれかを即特定する。認証: admin Bearer または X-Cron-Secret。"""
    _authed = False
    if authorization and authorization.startswith("Bearer "):
        _tok = authorization[len("Bearer "):].strip()
        if _verify_admin_token(_tok):
            _authed = True
    if not _authed and x_cron_secret and CRON_SECRET and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        _authed = True
    if not _authed:
        raise HTTPException(status_code=401, detail="未認証")
    return {"ok": True, **_line_link_token_status((token or "").strip())}


@app.post("/api/admin/students/issue-line-link")
def admin_issue_line_link(payload: dict, authorization: Optional[str] = Header(None),
                          x_cron_secret: Optional[str] = Header(None)):
    """🔗 管理者が任意の生徒の LINE 連携コードを発行する (ログインできない生徒の救済)。
    認証: admin Bearer または X-Cron-Secret。検索は issue-otp-direct と同じ (id/email/name_query)。
    本人性: 発行されたコードは「本人の LINE から送信」されて初めて紐付くため、コードを知る塾長
    が発行しても、生徒本人の LINE userId にしか紐付かない (なりすまし不可)。"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
        else:
            raise HTTPException(status_code=401, detail="セッション期限切れ")
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    sid_arg = payload.get("student_id") or payload.get("id")
    email_arg = (payload.get("email") or "").strip().lower()
    name_query = (payload.get("name_query") or "").strip()
    conn = db()
    c = conn.cursor()
    try:
        row = None
        if sid_arg:
            c.execute("SELECT id, name, email, line_user_id FROM students WHERE id = ? LIMIT 1", (int(sid_arg),))
            row = c.fetchone()
        elif email_arg:
            # 🔑 2026-06-12 review 指摘: issue-otp-direct と同様、子メール (student_email) でも
            #   検索可能に (magic-link / verify-code と同一条件・親メール優先)。
            c.execute(
                "SELECT id, name, email, line_user_id FROM students "
                "WHERE LOWER(email) = ? OR LOWER(COALESCE(student_email, '')) = ? "
                "ORDER BY CASE WHEN LOWER(email) = ? THEN 0 ELSE 1 END, id LIMIT 1",
                (email_arg, email_arg, email_arg),
            )
            row = c.fetchone()
        elif name_query:
            like = f"%{name_query}%"
            c.execute("SELECT id, name, email, line_user_id FROM students WHERE name LIKE ? ORDER BY id DESC LIMIT 10", (like,))
            cands = c.fetchall()
            if not cands:
                raise HTTPException(status_code=404, detail=f"name_query '{name_query}' に一致する生徒なし")
            if len(cands) > 1:
                return {"ok": False, "needs_disambiguation": True,
                        "candidates": [{"id": r["id"], "name": r["name"], "email": r["email"]} for r in cands],
                        "message": f"{len(cands)} 件ヒット。student_id を指定してください。"}
            row = cands[0]
        else:
            raise HTTPException(status_code=400, detail="student_id / email / name_query のいずれか必須")
        if not row:
            raise HTTPException(status_code=404, detail="生徒が見つかりません")
        sid = int(row["id"])
        already = bool(row["line_user_id"]) if ("line_user_id" in row.keys()) else False
        code = _create_line_link_token(sid)  # [line-link-noexpiry] 期限なし (single-use のみ)
        return {
            "ok": True,
            "code": code,
            "already_linked": already,
            "add_friend_url": LINE_ADD_FRIEND_URL,
            "student": {"id": sid, "name": row["name"], "email": row["email"]},
            "instructions": "この連携コードを生徒に伝え、①公式LINEを友だち追加 → ②コードをトークに送信、で連携完了です（期限なし・1回で完了）。",
        }
    finally:
        conn.close()

