# =====================================================================
# 🚨 体験中・離脱予兆者への AI 個別フォロー (2026-05-11)
# 塾長指示「AI チームで半自動で集客〜収益化」の継続 phase 強化。
# 既存 trial-followups (体験「終了後」フォロー) と orthogonal:
# - trial-followups: status='expired' 対象・定型 3 段ドリップ
# - trial-rescue: status='trial' 対象・離脱予兆検知 + AI 個別メッセージ
# memory: feedback_silent_customer_skip.md (last_login_at IS NULL skip) +
#         feedback_cron_dedup_required.md (notifications dedup 必須)
# =====================================================================

def _detect_at_risk_trial_students(now: datetime) -> list:
    """体験中で「失速サイン」を出している生徒を検出。
    条件:
    - status='trial' AND trial_end > now (体験継続中)
    - 体験開始 (trial_start) 2-7 日経過 (登録直後の様子見期間を除外、終了直前は既存 trial-reminders 担当)
    - last_login_at IS NOT NULL (silent customer は skip・memory: feedback_silent_customer_skip.md)
    - last_login_at < now - 48h (ログイン履歴あるが 2 日以上アクセスなし = 失速)
    - 過去 7 日間に template='trial_rescue' で success=1 の notification なし (dedup)

    returns: list of student dict {id, name, email, grade, goal, plan, trial_start, trial_end, last_login_at, days_since_login}
    """
    cutoff_recent = (now - timedelta(hours=48)).isoformat()
    cutoff_dedup = (now - timedelta(days=7)).isoformat()
    early_cutoff = (now - timedelta(days=2)).isoformat()  # trial_start <= 2日前 (登録直後を除外)
    late_cutoff = (now - timedelta(days=7)).isoformat()   # trial_start >= 7日前 (古すぎを除外)

    conn = db()
    c = conn.cursor()
    try:
        c.execute(
            """SELECT s.id, s.name, s.email, s.grade, s.goal, s.plan,
                      s.trial_start, s.trial_end, s.last_login_at
               FROM students s
               WHERE s.status = 'trial'
                 AND s.email IS NOT NULL
                 AND s.trial_end > ?
                 AND s.last_login_at IS NOT NULL
                 AND s.last_login_at < ?
                 AND s.trial_start IS NOT NULL
                 AND s.trial_start <= ?
                 AND s.trial_start >= ?
                 AND (s.course IS NULL OR s.course != 'kokuritsu_nankan')
               LIMIT 200""",
            (now.isoformat(), cutoff_recent, early_cutoff, late_cutoff)
        )
        candidates = list(c.fetchall())

        # dedup check (7日以内に trial_rescue 成功送信あれば skip)
        result = []
        for row in candidates:
            sid = row["id"] if hasattr(row, "keys") else row[0]
            c.execute(
                """SELECT id FROM notifications
                   WHERE student_id = ? AND template = 'trial_rescue'
                     AND success = 1 AND sent_at > ?
                   LIMIT 1""",
                (sid, cutoff_dedup)
            )
            if c.fetchone():
                continue
            # last_login からの経過時間 (hours) 計算
            try:
                ll = row["last_login_at"]
                if isinstance(ll, str):
                    ll = datetime.fromisoformat(ll.replace("Z", "+00:00"))
                if ll.tzinfo is None:
                    ll = ll.replace(tzinfo=timezone.utc)
                hours_since_login = int((now - ll).total_seconds() / 3600)
            except Exception:
                hours_since_login = -1
            result.append({
                "id": sid,
                "name": row["name"] if hasattr(row, "keys") else row[1],
                "email": row["email"] if hasattr(row, "keys") else row[2],
                "grade": row["grade"] if hasattr(row, "keys") else row[3],
                "goal": row["goal"] if hasattr(row, "keys") else row[4],
                "plan": row["plan"] if hasattr(row, "keys") else row[5],
                "trial_start": str(row["trial_start"] if hasattr(row, "keys") else row[6]),
                "trial_end": str(row["trial_end"] if hasattr(row, "keys") else row[7]),
                "last_login_at": str(row["last_login_at"] if hasattr(row, "keys") else row[8]),
                "hours_since_login": hours_since_login,
            })
        return result
    finally:
        conn.close()


def _generate_personalized_followup(student: dict) -> dict:
    """生徒の情報から個別 follow-up メッセージを AI 生成。
    Claude Sonnet 4.6 経由 (_call_ai_safe task_type='trial_rescue' で Gemini fallback 完備)。
    安全な fallback: AI 失敗時は定型文を返す (silent fail させない・必ず何か送る)。

    returns: {subject: str, body: str, model: str, _fallback: bool}
    """
    name = (student.get("name") or "").strip() or "あなた"
    grade = (student.get("grade") or "").strip()
    goal = (student.get("goal") or "").strip()
    hours = student.get("hours_since_login") or 0
    days_since = max(1, hours // 24)

    # AI 生成試行
    if ANTHROPIC_API_KEY or GEMINI_API_KEY or OPENAI_API_KEY:
        try:
            system = (
                "あなたは AI AIコーチングの塾長です。体験中の生徒が失速しています。"
                "親身で温かい、押し付けがましくない follow-up メッセージを書いてください。"
                "ai-juku の AI チューター・学習計画・5 AI 多視点添削の活用を自然に促してください。"
                "教師名 (関正生・富田・林修等) は一切出さないこと。"
            )
            grade_info = f"学年: {grade}" if grade else ""
            goal_info = f"志望: {goal}" if goal else ""
            user_msg = f"""{name}さんへの follow-up メッセージを生成してください。

【状況】
- 体験中・あと数日で終了
- 最後のログインから {days_since} 日経過
{grade_info}
{goal_info}

【出力形式】純粋な JSON のみ:
{{
  "subject": "件名 (30 字以内・絵文字 1 個 OK)",
  "body": "本文 (180-280 字・改行は \\n・名前 {name} で呼びかけ・最後に「マイページからすぐ再開できます」で締める)"
}}"""
            data = _call_ai_safe(
                {
                    "model": "claude-sonnet-4-6-20251022",
                    "max_tokens": 800,  # 日本語多バイト + JSON wrapper の truncate リスク回避 (3視点 review 推奨)
                    "system": system,
                    "messages": [{"role": "user", "content": user_msg}],
                },
                task_type="trial_rescue",
            )
            content_text = data["content"][0]["text"].strip()
            if content_text.startswith("```"):
                content_text = content_text.split("```", 2)[1]
                if content_text.startswith("json"):
                    content_text = content_text[4:]
                content_text = content_text.strip()
                if content_text.endswith("```"):
                    content_text = content_text[:-3].strip()
            parsed = json.loads(content_text)
            subject = (parsed.get("subject") or "").strip()
            body = (parsed.get("body") or "").strip()
            if subject and body and len(body) >= 50:
                return {
                    "subject": subject,
                    "body": body,
                    "model": data.get("_actual_model") or "claude-sonnet-4-6",
                    "_fallback": False,
                }
            log.warning(f"[TrialRescue] AI returned empty/short content for student {student.get('id')}")
        except Exception as e:
            log.warning(f"[TrialRescue] AI generation failed for student {student.get('id')}: {type(e).__name__}: {e}")

    # Fallback (silent fail させず定型文を必ず送る)
    return {
        "subject": f"{name}さんへ — 体験を再開しませんか? 🎓",
        "body": (
            f"{name}さん、こんにちは。AI AIコーチングの塾長です。\n\n"
            f"前回のログインから {days_since} 日経ちました。体験はあと数日で終わりますが、まだ AI チューターや学習計画を試していない場合はぜひ。"
            f"分からない問題は深夜でも AI が即解説します。\n\n"
            f"マイページからすぐ再開できます。"
        ),
        "model": "fallback_static",
        "_fallback": True,
    }


def _send_trial_rescue_email(to_email: str, student_name: str, subject: str, body: str, login_url: str) -> dict:
    """trial-rescue 個別メール送信 (Resend 経由)"""
    import html as _html
    if not RESEND_API_KEY:
        log.warning(f"[DEV-MODE] Trial rescue email skipped for {to_email}")
        return {"sent": False, "dev_mode": True}
    safe_name = _html.escape(student_name or "")
    body_html = _html.escape(body).replace("\n", "<br>")
    html_body = f"""<!DOCTYPE html>
<html><body style="font-family:-apple-system,sans-serif;line-height:1.7;color:#333;max-width:560px;margin:0 auto;padding:2rem;">
<h1 style="font-size:1.3rem;color:#6366f1;">🎓 AIコーチング</h1>
<p style="white-space:pre-line;font-size:0.98rem;">{body_html}</p>
<p style="text-align:center;margin:2rem 0;">
  <a href="{login_url}" style="display:inline-block;padding:1rem 2rem;background:linear-gradient(135deg,#6366f1,#ec4899);color:#fff;text-decoration:none;border-radius:8px;font-weight:700;">
    🎓 マイページで体験を再開する
  </a>
</p>
<hr style="margin:2rem 0;border:none;border-top:1px solid #eee;">
<p style="font-size:0.8rem;color:#999;">お問い合わせ: <a href="mailto:info@trillion-ai-juku.com" style="color:#6366f1;">info@trillion-ai-juku.com</a></p>
</body></html>"""
    try:
        import urllib.request
        req = urllib.request.Request(
            "https://api.resend.com/emails",
            data=json.dumps({
                "from": FROM_EMAIL,
                "to": [to_email],
                "subject": subject,
                "html": html_body,
            }).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {RESEND_API_KEY}",
                "Content-Type": "application/json",
                "User-Agent": "ai-juku-system/1.0",
            },
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            result = json.loads(resp.read().decode())
            return {"sent": True, "resend_id": result.get("id")}
    except Exception as e:
        log.error(f"[TrialRescue] Email failed for {to_email}: {type(e).__name__}: {e}")
        return {"sent": False, "error": str(e)}


@app.post("/api/admin/marketing/trial-rescue-now")
def admin_trial_rescue_now(
    payload: dict = None,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🚨 体験中・離脱予兆者への AI 個別フォロー (admin Bearer or x-cron-secret)
    塾長が CEO ダッシュから手動 trigger 可、cron からも呼ばれる兼用 endpoint。

    対象: 体験中 (status='trial') + ログイン履歴あり + 48h+ 未アクセス + 体験開始 2-7 日経過
    AI (Claude Sonnet 4.6) が個別メッセージ生成 → in-app messages + email
    dedup: notifications template='trial_rescue' + success=1 + 7d 内

    body (任意): {"dry_run": bool}
    """
    # auth
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    payload = payload or {}
    dry_run = bool(payload.get("dry_run", False))

    now = datetime.now(timezone.utc)
    at_risk = _detect_at_risk_trial_students(now)
    log.info(f"[TrialRescue] Detected {len(at_risk)} at-risk students (dry_run={dry_run})")

    import urllib.parse as _urlparse
    sent = 0
    fallback_count = 0
    failed = 0
    preview = []
    conn = db()
    c = conn.cursor()
    try:
        for stu in at_risk:
            sid = stu["id"]
            email = stu["email"]
            name = stu["name"] or ""

            if dry_run:
                preview.append({
                    "student_id": sid,
                    "email": email,
                    "hours_since_login": stu["hours_since_login"],
                    "trial_end": stu["trial_end"],
                })
                continue

            # AI 個別メッセージ生成
            msg = _generate_personalized_followup(stu)
            subject = msg["subject"]
            body = msg["body"]
            if msg.get("_fallback"):
                fallback_count += 1

            # in-app messages テーブルに INSERT (生徒が次回ログイン時に表示)
            try:
                c.execute(
                    """INSERT INTO messages (sender_type, sender_id, recipient_type, recipient_id,
                                              subject, body, sent_via, email_status)
                       VALUES ('admin', NULL, 'student', ?, ?, ?, 'in_app_and_email', 'pending')""",
                    (sid, subject, body)
                )
            except Exception as e:
                log.warning(f"[TrialRescue] in-app message insert failed for {sid}: {e}")

            # メール送信
            login_url = f"{BASE_URL}/auth.html?email={_urlparse.quote(email, safe='')}"
            result = _send_trial_rescue_email(email, name, subject, body, login_url)

            # notifications 記録 (dedup 用 + 監査)
            try:
                c.execute(
                    """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                       VALUES (?, 'email', 'trial_rescue', ?, ?, ?)""",
                    (sid, json.dumps({
                        "subject": subject,
                        "hours_since_login": stu["hours_since_login"],
                        "model": msg.get("model", ""),
                        "fallback": msg.get("_fallback", False),
                    }, ensure_ascii=False),
                    1 if result.get("sent") else 0,
                    result.get("error", "") if not result.get("sent") else "")
                )
            except Exception as e:
                log.warning(f"[TrialRescue] notification record failed for {sid}: {e}")

            if result.get("sent"):
                sent += 1
            else:
                failed += 1
        conn.commit()
    finally:
        conn.close()

    return {
        "ok": True,
        "scanned_at": now.isoformat(),
        "at_risk_count": len(at_risk),
        "sent": sent,
        "ai_fallback_count": fallback_count,
        "failed": failed,
        "dry_run": dry_run,
        "preview": preview[:50] if dry_run else [],
        "memo": (
            f"AI 個別メッセージ {sent} 件送信完了 (fallback {fallback_count} 件)。"
            "失速サイン (48h+ 未ログイン + 体験 2-7 日経過) を検知し AI が個別メッセージで再エンゲージ。"
        ),
    }


@app.post("/api/cron/trial-followups")
def cron_trial_followups(x_cron_secret: str = Header(None), dry_run: bool = False):
    """体験終了後フォローアップ: Day1 / Day3 / Day7 の3段階ドリップメール。
    expire-trials の後に毎日実行。notifications テーブルで重複防止。"""
    if not CRON_SECRET:
        raise HTTPException(status_code=503, detail="Cron not configured")
    if not x_cron_secret or not hmac.compare_digest(x_cron_secret, CRON_SECRET):
        raise HTTPException(status_code=401, detail="Unauthorized")

    import urllib.parse as _urlparse
    conn = db()
    c = conn.cursor()
    try:
        now = datetime.now(timezone.utc)

        # 継続意思のない (= 一度もログインしていない) 顧客はスキップ (塾長指示 2026-05-06)
        # 💳 2026-06-12: カード登録済み (stripe_subscription_id あり) の expired も除外。
        # webhook 遅延等の異常系で expired に落ちたカード生徒は Stripe 上は課金継続中でありうるため、
        # 「自動課金は一切発生しません」という本ドリップの文面が誤案内になる
        # (彼らの paid 回復は subscription.updated active ハンドラが担当)。
        c.execute(
            "SELECT id, name, email, trial_end, last_login_at FROM students WHERE status='expired' AND email IS NOT NULL AND trial_end IS NOT NULL AND (course IS NULL OR course != 'kokuritsu_nankan')"
            " AND (stripe_subscription_id IS NULL OR stripe_subscription_id = '')"
        )
        expired_students = list(c.fetchall())

        sent = 0
        skipped = 0
        skipped_silent = 0
        skipped_silent_ids = []
        preview = []
        for row in expired_students:
            # サイレント顧客スキップ: 一度もログインしていない = 継続の連絡がない顧客 (塾長指示 2026-05-06)
            try:
                _last_login = row["last_login_at"]
            except (KeyError, IndexError):
                _last_login = None
            if not _last_login:
                skipped_silent += 1
                skipped_silent_ids.append(row["id"])
                continue
            try:
                te = row["trial_end"]
                if isinstance(te, str):
                    te = datetime.fromisoformat(te.replace("Z", "+00:00"))
                if te.tzinfo is None:
                    te = te.replace(tzinfo=timezone.utc)
                days_since = int((now - te).total_seconds() / 86400)
            except Exception:
                continue

            # >= 範囲で判定: cron が1日欠落しても取りこぼさない (dedup で二重送信防止)
            if days_since < 0:
                continue
            elif days_since <= 2:
                step = 1
            elif days_since <= 5:
                step = 3
            elif days_since <= 10:
                step = 7
            else:
                continue

            template_key = f"trial_followup_day{step}"
            c.execute(
                "SELECT id FROM notifications WHERE student_id=? AND template=? AND success=1 LIMIT 1",
                (row["id"], template_key)
            )
            if c.fetchone():
                skipped += 1
                continue

            if dry_run:
                preview.append({"student_id": row["id"], "email": row["email"], "days_since": days_since, "step": step})
                continue

            upgrade_url = f"{BASE_URL}/upgrade.html?email={_urlparse.quote(row['email'], safe='')}"
            result = _send_trial_followup_email(row["email"], row["name"] or "", step, upgrade_url)
            c.execute(
                """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                   VALUES (?, 'email', ?, ?, ?, ?)""",
                (row["id"], template_key, json.dumps({"days_since": days_since, "step": step}),
                 1 if result.get("sent") else 0, result.get("error", ""))
            )
            if result.get("sent"):
                sent += 1
        conn.commit()
        # events に audit log (CEO ダッシュ可視化用)
        if skipped_silent > 0 and not dry_run:
            try:
                c.execute(
                    "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                    ("trial_followup_silent_skipped",
                     json.dumps({"count": skipped_silent, "student_ids": skipped_silent_ids[:50], "reason": "last_login_at IS NULL"}, ensure_ascii=False),
                     "cron")
                )
                conn.commit()
            except Exception as _e:
                log.warning(f"[trial-followups] silent skip audit failed: {_e}")
        return {"sent": sent, "skipped": skipped, "skipped_silent": skipped_silent, "candidates": len(expired_students), "preview": preview if dry_run else None}
    finally:
        conn.close()


@app.post("/api/admin/students/extend-trial")
def admin_extend_trial(payload: dict, authorization: Optional[str] = Header(None)):
    """CEOダッシュボードから1クリックで体験延長。expired/trial → trial + 7日延長。"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="セッション期限切れ")

    try:
        sid = int(payload.get("id") or 0)
        extra_days = int(payload.get("days") or 7)
    except (ValueError, TypeError):
        raise HTTPException(status_code=400, detail="id and days must be integers")
    if not sid:
        raise HTTPException(status_code=400, detail="id required")
    if extra_days < 1 or extra_days > 30:
        raise HTTPException(status_code=400, detail="days must be 1-30")

    conn = db()
    c = conn.cursor()
    try:
        c.execute("SELECT id, email, name, status, trial_end FROM students WHERE id=?", (sid,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail=f"student id={sid} not found")
        if row["status"] not in ("expired", "trial"):
            raise HTTPException(status_code=400, detail=f"status={row['status']} は体験延長対象外です (expired/trial のみ)")

        new_trial_end = datetime.now(timezone.utc) + timedelta(days=extra_days)
        c.execute(
            "UPDATE students SET status='trial', trial_end=?, updated_at=CURRENT_TIMESTAMP WHERE id=?",
            (new_trial_end, sid)
        )
        # 旧 followup 通知をクリア → 再 expire 時に新しいドリップが送れるようにする
        c.execute(
            "DELETE FROM notifications WHERE student_id=? AND template LIKE 'trial_followup_%'",
            (sid,)
        )
        conn.commit()
        log.info(f"[admin/extend-trial] id={sid} extended {extra_days} days, new trial_end={new_trial_end}")
        return {
            "ok": True,
            "id": sid,
            "name": row["name"],
            "email": row["email"],
            "previous_status": row["status"],
            "new_trial_end": new_trial_end.isoformat(),
            "extended_days": extra_days,
        }
    finally:
        conn.close()


@app.post("/api/admin/students/send-followup")
def admin_send_followup(payload: dict, authorization: Optional[str] = Header(None)):
    """CEOダッシュボードから手動フォローアップメール送信。24h cooldown 付き。"""
    import urllib.parse as _urlparse
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="セッション期限切れ")

    try:
        sid = int(payload.get("id") or 0)
    except (ValueError, TypeError):
        raise HTTPException(status_code=400, detail="id must be integer")
    if not sid:
        raise HTTPException(status_code=400, detail="id required")

    conn = db()
    c = conn.cursor()
    try:
        c.execute("SELECT id, email, name, status, trial_end FROM students WHERE id=?", (sid,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail=f"student id={sid} not found")
        if not row["email"]:
            raise HTTPException(status_code=400, detail="メールアドレスが登録されていません")

        # 24h cooldown: 直近24時間以内に手動送信済みならブロック
        cooldown_since = (datetime.now(timezone.utc) - timedelta(hours=24)).isoformat()
        c.execute(
            "SELECT id FROM notifications WHERE student_id=? AND template='trial_followup_manual' AND success=1 AND created_at > ? LIMIT 1",
            (sid, cooldown_since)
        )
        if c.fetchone():
            raise HTTPException(status_code=429, detail="24時間以内にフォローアップ済みです。時間を置いてお試しください。")

        # trial_end からの経過日数で適切なテンプレートを自動選択
        days_since_expiry = 1
        try:
            te = row["trial_end"]
            if te:
                if isinstance(te, str):
                    te = datetime.fromisoformat(te.replace("Z", "+00:00"))
                if te.tzinfo is None:
                    te = te.replace(tzinfo=timezone.utc)
                days_since_expiry = max(1, int((datetime.now(timezone.utc) - te).total_seconds() / 86400))
        except Exception:
            pass

        upgrade_url = f"{BASE_URL}/upgrade.html?email={_urlparse.quote(row['email'], safe='')}"
        result = _send_trial_followup_email(row["email"], row["name"] or "", days_since_expiry, upgrade_url)
        if not result.get("sent"):
            c.execute(
                """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                   VALUES (?, 'email', 'trial_followup_manual', ?, 0, ?)""",
                (sid, json.dumps({"triggered_by": "ceo_dashboard", "days_since": days_since_expiry}), result.get("error", ""))
            )
            conn.commit()
            raise HTTPException(status_code=502, detail=f"メール送信失敗: {result.get('error', '不明')}")

        c.execute(
            """INSERT INTO notifications (student_id, channel, template, payload, success, error)
               VALUES (?, 'email', 'trial_followup_manual', ?, 1, '')""",
            (sid, json.dumps({"triggered_by": "ceo_dashboard", "days_since": days_since_expiry}))
        )
        conn.commit()
        return {"ok": True, "sent": True, "email": row["email"]}
    finally:
        conn.close()


@app.post("/api/cron/trial-reminders")
def cron_trial_reminders(x_cron_secret: str = Header(None), dry_run: bool = False):
    """毎日1回外部cronから呼び出し。trial_end が 1-2 日先の生徒にリマインダー送信。
    notifications テーブルで重複送信防止。
    クレカ登録済み trial (status='trial' かつ stripe_subscription_id あり = trial_extended 経路)
    は体験終了後に自動課金が始まるため、無課金 trial と別テンプレ (trial_ending_card) で
    課金開始の事実と解約方法を通知する (2026-06-12 checkout-success 文言分岐 review)。"""
    if not CRON_SECRET:
        raise HTTPException(status_code=503, detail="Cron not configured")
    if not x_cron_secret or not hmac.compare_digest(x_cron_secret, CRON_SECRET):
        raise HTTPException(status_code=401, detail="Unauthorized")

    conn = db()
    c = conn.cursor()
    now = datetime.now(timezone.utc)
    t_start = now + timedelta(hours=24)   # 24時間後以降
    t_end = now + timedelta(hours=48)     # 48時間以内
    # 送信対象は status='trial' のみ (無課金 trial も trial_extended も 'trial')。
    # 'paid' は本来この窓に入らない規約 (paid 化は trial_end=NULL を伴う・2026-06-12 fix) だが、
    # fix 前の stale 行 (paid なのに未来 trial_end) を検出・audit するため SELECT には残し、
    # ループ冒頭で skip する — paid 行に正しいテンプレは存在しない (無課金用も card 用も虚偽になる)。
    # 継続意思のない (= 一度もログインしていない) 顧客はスキップ (塾長指示 2026-05-06)
    # ただしクレカ登録済み (_card_registered) は例外 — ループ内コメント参照 (2026-06-12)
    c.execute(
        """SELECT id, name, email, trial_end, status, last_login_at, course, stripe_subscription_id
           FROM students
           WHERE status IN ('trial','paid') AND email IS NOT NULL
             AND trial_end IS NOT NULL
             AND trial_end > ? AND trial_end <= ?""",
        (t_start.isoformat(), t_end.isoformat())
    )
    candidates = list(c.fetchall())

    sent = 0
    sent_card = 0
    skipped = 0
    skipped_silent = 0
    skipped_silent_ids = []
    skipped_course = 0
    skipped_course_ids = []
    skipped_paid_stale = 0
    skipped_paid_stale_ids = []
    silent_card_notified = 0
    silent_card_ids = []
    preview = []
    for row in candidates:
        # 国公立難関大学コース ('kokuritsu_nankan') は塾の通塾生 = SaaS 体験課金 funnel の対象外。
        # 体験終了リマインド (継続登録の案内) を送らない (塾長指示 2026-06-04・早川真央さん事例)。
        try:
            _course = row["course"]
        except (KeyError, IndexError):
            _course = None
        if _course == "kokuritsu_nankan":
            skipped_course += 1
            skipped_course_ids.append(row["id"])
            continue
        # 🛡️ 2026-06-12: status='paid' は skip (送信対象外)。paid 行に正しいテンプレは無い —
        # 無課金用「自動課金は発生しません」も card 用「これから課金が始まる」も契約者には虚偽。
        # monthly webhook の paid 化が trial_end=NULL を伴う同日 fix 後は新規流入しないはずで、
        # ここに来る paid 行 = fix 前の stale データ。skip + audit で可視化し、是正は Stripe
        # 実状態を確認できる reconcile (active sub 限定で trial_end クリア) に委ねる。
        if row["status"] == "paid":
            skipped_paid_stale += 1
            skipped_paid_stale_ids.append(row["id"])
            continue
        # クレカ登録済み trial 判定: trial_extended 経路 (create_trial_checkout の extend 分岐) は
        # webhook が stripe_subscription_id を保存し、status='trial' のまま 21 日 trial 中。
        # status='trial' の AND ゲートは上の paid skip との二重防御 — 体験中に月額契約した生徒
        # (status='paid' + subscription) に「これから自動課金が始まる」「体験中の解約で料金は
        # かからない」card テンプレは虚偽になる (premium/family 契約者には価格も誤り)。
        # 3視点 review MAJOR 指摘 (2026-06-12)。
        try:
            _card_registered = bool(row["stripe_subscription_id"]) and row["status"] == "trial"
        except (KeyError, IndexError):
            _card_registered = False
        # サイレント顧客スキップ: 一度もログインしていない = 継続の連絡がない顧客 (塾長指示 2026-05-06)
        # ただし _card_registered はスキップしない — 放置すると課金される契約であり、
        # 一度もログインしていない人こそ課金サプライズのリスクが最も高い (2026-06-12 review)
        try:
            _last_login = row["last_login_at"]
        except (KeyError, IndexError):
            _last_login = None
        if not _last_login and not _card_registered:
            skipped_silent += 1
            skipped_silent_ids.append(row["id"])
            continue
        # 重複チェック: この生徒に終了通知を既に送っていたらスキップ
        # (trial_ending_card は channel='email' 限定で照合 — LINE 放置アラートが同名 'trial_ending' を
        #  channel='line' で記録するため、card 向け課金前通知まで誤って抑止されないように)
        _tmpl = "trial_ending_card" if _card_registered else "trial_ending"
        if _card_registered:
            c.execute(
                "SELECT id FROM notifications WHERE student_id=? AND channel='email' AND template='trial_ending_card' AND success=1 LIMIT 1",
                (row["id"],)
            )
        else:
            c.execute(
                "SELECT id FROM notifications WHERE student_id=? AND template='trial_ending' AND success=1 LIMIT 1",
                (row["id"],)
            )
        if c.fetchone():
            skipped += 1
            continue
        # trial_end までの残日数を概算
        try:
            te = row["trial_end"]
            if isinstance(te, str):
                te = datetime.fromisoformat(te.replace("Z", "+00:00"))
            if te.tzinfo is None:
                te = te.replace(tzinfo=timezone.utc)
            days_left = max(1, int((te - now).total_seconds() / 86400))
        except Exception:
            days_left = 2
        if dry_run:
            preview.append({"student_id": row["id"], "email": row["email"], "days_left": days_left,
                            "template": _tmpl, "silent": not _last_login})
            continue
        if _card_registered:
            result = _send_trial_extended_ending_email(row["email"], row["name"] or "", days_left)
        else:
            result = _send_trial_ending_email(row["email"], row["name"] or "", days_left, f"{BASE_URL}/upgrade.html?email={row['email']}")
        c.execute(
            """INSERT INTO notifications (student_id, channel, template, payload, success, error)
               VALUES (?, 'email', ?, ?, ?, ?)""",
            (row["id"], _tmpl, json.dumps({"days_left": days_left, "card_registered": _card_registered}),
             1 if result.get("sent") else 0, result.get("error", ""))
        )
        if result.get("sent"):
            sent += 1
            if _card_registered:
                sent_card += 1
                if not _last_login:
                    silent_card_notified += 1
                    silent_card_ids.append(row["id"])
    # events に audit log (CEO ダッシュ可視化用)
    if skipped_silent > 0 and not dry_run:
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("trial_reminder_silent_skipped",
                 json.dumps({"count": skipped_silent, "student_ids": skipped_silent_ids[:50], "reason": "last_login_at IS NULL"}, ensure_ascii=False),
                 "cron")
            )
            conn.commit()
        except Exception as _e:
            log.warning(f"[trial-reminders] silent skip audit failed: {_e}")
    # クレカ登録済み×未ログインへの課金前通知の audit (特商法対応の証跡・2026-06-12)
    if silent_card_notified > 0 and not dry_run:
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("trial_reminder_card_silent_notified",
                 json.dumps({"count": silent_card_notified, "student_ids": silent_card_ids[:50],
                             "reason": "card_registered (stripe_subscription_id あり) は自動課金前通知のため silent skip 対象外"}, ensure_ascii=False),
                 "cron")
            )
            conn.commit()
        except Exception as _e:
            log.warning(f"[trial-reminders] card silent notify audit failed: {_e}")
    # 国公立難関大学コース skip の audit (塾長指示 2026-06-04)
    if skipped_course > 0 and not dry_run:
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("trial_reminder_course_skipped",
                 json.dumps({"count": skipped_course, "student_ids": skipped_course_ids[:50], "reason": "course=kokuritsu_nankan (通塾生・体験funnel対象外)"}, ensure_ascii=False),
                 "cron")
            )
            conn.commit()
        except Exception as _e:
            log.warning(f"[trial-reminders] course skip audit failed: {_e}")
    # paid なのに未来 trial_end が残る stale 行の audit (要是正リストの可視化・2026-06-12)
    if skipped_paid_stale > 0 and not dry_run:
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("trial_reminder_paid_stale_skipped",
                 json.dumps({"count": skipped_paid_stale, "student_ids": skipped_paid_stale_ids[:50],
                             "reason": "status='paid' なのに未来の trial_end が残存 (monthly webhook fix 前の stale 行) — reconcile 実行で解消"}, ensure_ascii=False),
                 "cron")
            )
            conn.commit()
        except Exception as _e:
            log.warning(f"[trial-reminders] paid stale skip audit failed: {_e}")
    conn.commit()
    conn.close()
    return {"sent": sent, "sent_card": sent_card, "skipped": skipped, "skipped_silent": skipped_silent,
            "skipped_course": skipped_course, "skipped_paid_stale": skipped_paid_stale,
            "silent_card_notified": silent_card_notified,
            "candidates": len(candidates), "preview": preview if dry_run else None}


@app.post("/api/cron/trial-nurture")
def cron_trial_nurture(x_cron_secret: str = Header(None), dry_run: bool = False):
    """📧 体験中の盛り上げメール (集客 funnel #3・塾長指示 2026-05-19)
    Day 2 (登録 1-2 日経過) + Day 5 (登録 4-5 日経過) に学習習慣エンカレッジ送信。
    既存 cron_trial_reminders (終了 1-2 日前) と orthogonal: 本 endpoint は体験「中盤」担当。
    notifications テーブルで dedup (template='trial_nurture_day2' / 'trial_nurture_day5').

    silent customer (last_login_at IS NULL) は cron_trial_unused_warning に任せ
    本 endpoint では skip (二重送信 + サイレントスキップ ルール準拠)。
    """
    if not CRON_SECRET:
        raise HTTPException(status_code=503, detail="Cron not configured")
    if not x_cron_secret or not hmac.compare_digest(x_cron_secret, CRON_SECRET):
        raise HTTPException(status_code=401, detail="Unauthorized")

    conn = db()
    c = conn.cursor()
    now = datetime.now(timezone.utc)
    sent_day2 = 0
    sent_day5 = 0
    skipped_silent = 0
    skipped_already = 0
    preview = []
    try:
        # 🛡 edge case fix (review 2026-05-19): trial_end が 48h 以内の生徒は
        # cron_trial_reminders 専管にして二重送信を排除 (legacy 7d 生徒救済 + race ハードニング)
        trial_end_threshold = (now + timedelta(hours=48)).isoformat()
        # Day 2: 登録 1-2 日経過 (24-48 時間後)・status='trial' or 'paid'
        d2_lower = now - timedelta(hours=48)  # 上限: 48 時間前
        d2_upper = now - timedelta(hours=24)  # 下限: 24 時間前
        c.execute(
            """SELECT id, name, email, last_login_at, created_at FROM students
               WHERE status IN ('trial', 'paid') AND email IS NOT NULL
                 AND created_at > ? AND created_at <= ?
                 AND (trial_end IS NULL OR trial_end > ?) AND (course IS NULL OR course != 'kokuritsu_nankan')""",
            (d2_lower.isoformat(), d2_upper.isoformat(), trial_end_threshold)
        )
        for row in c.fetchall():
            # silent skip (last_login_at IS NULL) - cron_trial_unused_warning に任せる
            try: _last_login = row["last_login_at"]
            except (KeyError, IndexError): _last_login = None
            if not _last_login:
                skipped_silent += 1
                continue
            # dedup
            c.execute(
                "SELECT id FROM notifications WHERE student_id=? AND template='trial_nurture_day2' AND success=1 LIMIT 1",
                (row["id"],)
            )
            if c.fetchone():
                skipped_already += 1
                continue
            if dry_run:
                preview.append({"day": 2, "student_id": row["id"], "email": row["email"]})
                continue
            login_url = f"{BASE_URL}/mypage.html"
            result = _send_trial_nurture_day2_email(row["email"], row["name"] or "", login_url)
            c.execute(
                """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                   VALUES (?, 'email', 'trial_nurture_day2', ?, ?, ?)""",
                (row["id"], json.dumps({"day": 2}), 1 if result.get("sent") else 0, result.get("error", ""))
            )
            if result.get("sent"): sent_day2 += 1

        # Day 5: 登録 4-5 日経過 (96-120 時間後)・trial_end 48h 以内除外 (上記同様)
        d5_lower = now - timedelta(hours=120)  # 上限: 120 時間前
        d5_upper = now - timedelta(hours=96)   # 下限: 96 時間前
        c.execute(
            """SELECT id, name, email, last_login_at, created_at FROM students
               WHERE status IN ('trial', 'paid') AND email IS NOT NULL
                 AND created_at > ? AND created_at <= ?
                 AND (trial_end IS NULL OR trial_end > ?) AND (course IS NULL OR course != 'kokuritsu_nankan')""",
            (d5_lower.isoformat(), d5_upper.isoformat(), trial_end_threshold)
        )
        for row in c.fetchall():
            try: _last_login = row["last_login_at"]
            except (KeyError, IndexError): _last_login = None
            if not _last_login:
                skipped_silent += 1
                continue
            c.execute(
                "SELECT id FROM notifications WHERE student_id=? AND template='trial_nurture_day5' AND success=1 LIMIT 1",
                (row["id"],)
            )
            if c.fetchone():
                skipped_already += 1
                continue
            if dry_run:
                preview.append({"day": 5, "student_id": row["id"], "email": row["email"]})
                continue
            login_url = f"{BASE_URL}/mypage.html"
            result = _send_trial_nurture_day5_email(row["email"], row["name"] or "", login_url)
            c.execute(
                """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                   VALUES (?, 'email', 'trial_nurture_day5', ?, ?, ?)""",
                (row["id"], json.dumps({"day": 5}), 1 if result.get("sent") else 0, result.get("error", ""))
            )
            if result.get("sent"): sent_day5 += 1

        conn.commit()
    except Exception as e:
        log.error(f"[trial-nurture] failed: {e}", exc_info=True)
        try: conn.rollback()
        except Exception: pass
        conn.close()
        raise HTTPException(status_code=500, detail=f"trial-nurture failed: {type(e).__name__}")
    conn.close()
    return {
        "sent_day2": sent_day2,
        "sent_day5": sent_day5,
        "skipped_silent": skipped_silent,
        "skipped_already": skipped_already,
        "preview": preview if dry_run else None,
    }


@app.post("/api/cron/trial-unused-warning")
def cron_trial_unused_warning(x_cron_secret: str = Header(None), dry_run: bool = False):
    """体験中で last_login_at IS NULL の生徒に通告メール送信。
    Stage 1 (early): 登録から 3 日経過 → 「体験を始めてみませんか?」
    Stage 2 (late): 体験終了 2 日前 → 「終了が迫ってます」
    notifications テーブルで重複送信防止 (template='trial_unused_early' / 'trial_unused_late')
    塾長指示 2026-05-06: 登録のみで使用歴がない人に通告
    クレカ登録済み (stripe_subscription_id あり = trial_extended) には card_registered=True を
    渡し「課金は発生しません」ではなく自動課金開始+解約方法の文面で送る (2026-06-12)。"""
    if not CRON_SECRET:
        raise HTTPException(status_code=503, detail="Cron not configured")
    if not x_cron_secret or not hmac.compare_digest(x_cron_secret, CRON_SECRET):
        raise HTTPException(status_code=401, detail="Unauthorized")

    conn = db()
    c = conn.cursor()
    now = datetime.now(timezone.utc)
    sent_early = 0
    sent_late = 0
    skipped_already = 0
    preview = []
    try:
        # Stage 1: 登録から 3 日経過 + 未ログイン (4 日目に 1 通)
        early_lower = now - timedelta(days=4)  # 4 日経過は対象外 (重複防止のための窓)
        early_upper = now - timedelta(days=3)  # 3 日経過
        c.execute(
            """SELECT id, name, email, created_at, trial_end, stripe_subscription_id FROM students
               WHERE status = 'trial' AND email IS NOT NULL AND last_login_at IS NULL
                 AND created_at > ? AND created_at <= ? AND (course IS NULL OR course != 'kokuritsu_nankan')""",
            (early_lower.isoformat(), early_upper.isoformat())
        )
        for row in c.fetchall():
            # dedup
            c.execute(
                "SELECT id FROM notifications WHERE student_id=? AND template='trial_unused_early' AND success=1 LIMIT 1",
                (row["id"],)
            )
            if c.fetchone():
                skipped_already += 1
                continue
            try:
                ca = row["created_at"]
                if isinstance(ca, str):
                    ca = datetime.fromisoformat(ca.replace("Z", "+00:00"))
                if ca.tzinfo is None: ca = ca.replace(tzinfo=timezone.utc)
                days_unused = max(1, int((now - ca).total_seconds() / 86400))
            except Exception:
                days_unused = 3
            try:
                _card_registered = bool(row["stripe_subscription_id"])
            except (KeyError, IndexError):
                _card_registered = False
            if dry_run:
                preview.append({"student_id": row["id"], "email": row["email"], "stage": "early", "days_unused": days_unused, "card_registered": _card_registered})
                continue
            login_url = f"{BASE_URL}/login.html?email={row['email']}"
            result = _send_trial_unused_warning_email(row["email"], row["name"] or "", "early", login_url, days_unused, card_registered=_card_registered)
            c.execute(
                """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                   VALUES (?, 'email', 'trial_unused_early', ?, ?, ?)""",
                (row["id"], json.dumps({"days_unused": days_unused, "card_registered": _card_registered}), 1 if result.get("sent") else 0, result.get("error", ""))
            )
            if result.get("sent"):
                sent_early += 1

        # Stage 2: 体験終了 2 日前 + 未ログイン (重複防止 dedup あり)
        late_lower = now
        late_upper = now + timedelta(days=2)
        c.execute(
            """SELECT id, name, email, trial_end, stripe_subscription_id FROM students
               WHERE status = 'trial' AND email IS NOT NULL AND last_login_at IS NULL
                 AND trial_end IS NOT NULL AND trial_end > ? AND trial_end <= ? AND (course IS NULL OR course != 'kokuritsu_nankan')""",
            (late_lower.isoformat(), late_upper.isoformat())
        )
        for row in c.fetchall():
            c.execute(
                "SELECT id FROM notifications WHERE student_id=? AND template='trial_unused_late' AND success=1 LIMIT 1",
                (row["id"],)
            )
            if c.fetchone():
                skipped_already += 1
                continue
            try:
                te = row["trial_end"]
                if isinstance(te, str):
                    te = datetime.fromisoformat(te.replace("Z", "+00:00"))
                if te.tzinfo is None: te = te.replace(tzinfo=timezone.utc)
                days_left = max(1, int((te - now).total_seconds() / 86400))
            except Exception:
                days_left = 2
            try:
                _card_registered = bool(row["stripe_subscription_id"])
            except (KeyError, IndexError):
                _card_registered = False
            if dry_run:
                preview.append({"student_id": row["id"], "email": row["email"], "stage": "late", "days_left": days_left, "card_registered": _card_registered})
                continue
            login_url = f"{BASE_URL}/login.html?email={row['email']}"
            result = _send_trial_unused_warning_email(row["email"], row["name"] or "", "late", login_url, days_left, card_registered=_card_registered)
            c.execute(
                """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                   VALUES (?, 'email', 'trial_unused_late', ?, ?, ?)""",
                (row["id"], json.dumps({"days_left": days_left, "card_registered": _card_registered}), 1 if result.get("sent") else 0, result.get("error", ""))
            )
            if result.get("sent"):
                sent_late += 1

        conn.commit()
    finally:
        conn.close()

    return {
        "ok": True,
        "sent_early": sent_early,
        "sent_late": sent_late,
        "skipped_already_sent": skipped_already,
        "dry_run": dry_run,
        "preview": preview if dry_run else None,
    }


@app.post("/api/billing/portal-session")
def create_billing_portal_session(authorization: Optional[str] = Header(None)):
    """Stripe Customer Portal のURLを返す。有料ユーザーが解約・支払方法変更に使う。"""
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    conn = db()
    c = conn.cursor()
    c.execute("SELECT stripe_customer_id, status FROM students WHERE id=?", (student["id"],))
    row = c.fetchone()
    conn.close()
    if not row or not row["stripe_customer_id"]:
        raise HTTPException(status_code=400, detail="Stripe顧客情報がありません。お問い合わせください。")
    _stripe = get_stripe()
    if not _stripe:
        raise HTTPException(status_code=503, detail="決済サービスが利用できません")
    try:
        session = _stripe.billing_portal.Session.create(
            customer=row["stripe_customer_id"],
            return_url=f"{BASE_URL}/mypage.html",
        )
        return {"url": session.url}
    except Exception as e:
        log.error(f"Portal session create failed for student {student['id']}: {e}")
        raise HTTPException(status_code=500, detail="ポータル作成に失敗しました")


@app.post("/api/billing/cancel-trial")
def cancel_trial(authorization: Optional[str] = Header(None)):
    """解約: Stripe側で解約(成功時のみwebhookがstatus更新) or 純trial(Stripe顧客なし)ならDB直接更新。

    Stripe失敗を飲み込むと課金継続 & アクセス遮断の最悪事故になるため、
    失敗時はHTTPExceptionを投げる（DBには何も書かない）。
    """
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    conn = db()
    c = conn.cursor()
    c.execute("SELECT stripe_customer_id, stripe_subscription_id, status FROM students WHERE id=?", (student["id"],))
    row = c.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Student not found")

    # Stripe有料購読中なら、Stripe経由で解約（webhookがstatus更新）
    if row["stripe_subscription_id"]:
        _stripe = get_stripe()
        if not _stripe:
            conn.close()
            raise HTTPException(status_code=503, detail="決済サービスが一時的に利用できません。しばらくしてから再度お試しください。")
        # 🔁 [cancel-idempotent] (2026-06-12) 解約 API の冪等化 (前段ガード)。成功応答の直後に mypage を
        # 再読込すると webhook 反映 (status 更新) まで解約ボタンが残り、再クリックで解約済みサブスクへの
        # delete/modify が Stripe エラー → 502「解約処理に失敗しました。お問い合わせください」になっていた。
        # 直前に「受け付けました」と案内した保護者に失敗を返すと「解約できていない? 課金される?」という
        # 不安を与えるため、先に retrieve して既に終了済み (canceled / incomplete_expired) なら成功扱い。
        # その際は後段の文字列判定 (delete/modify 失敗時の既解約フォールバック) と同一の自己修復を行う:
        # subscription.deleted webhook は過去に送信済みで再送されないため、ここで status='canceled' と
        # 死んだ sub_id のクリアまで行わないと、「完了しました」と案内したのに DB が trial/paid のまま
        # 解約ボタンが永遠に残り続ける。エラー文字列に依存しない status 直接判定なので、Stripe の
        # エラーメッセージ変更にも頑健。retrieve の一時障害は握りつぶして従来の解約処理に進む
        # (本処理失敗時の 502 / 既解約フォールバック経路は既存のまま)。
        _pre_status = None
        _pre_missing = False
        try:
            _pre_sub = _stripe.Subscription.retrieve(row["stripe_subscription_id"])
            _pre_status = _pre_sub.get("status") if _pre_sub is not None else None
        except Exception as _pre_e:
            _pre_msg = str(_pre_e).lower()
            # 存在しないサブスクも既終了扱い (admin 退会処理 delete_student の既解約イディオムと同一判定)。
            # ただし canceled を実確認できた場合と違い「別のサブスクが存在しない」ことまでは保証できない
            # ので、応答文言は請求断言なし + 問い合わせ導線つきに分ける (3視点 review UX 指摘)。
            if any(_s in _pre_msg for _s in ("no such subscription", "resource_missing")):
                _pre_status = "canceled"
                _pre_missing = True
                log.info(f"[cancel-idempotent] subscription missing on Stripe for student {student['id']} — treated as already canceled: {_pre_e}")
            else:
                log.warning(f"[cancel-idempotent] pre-cancel retrieve failed for student {student['id']}: {type(_pre_e).__name__}: {_pre_e} — proceeding with cancel")
        if _pre_status in ("canceled", "incomplete_expired"):
            log.info(f"[cancel-idempotent] subscription already ended (status={_pre_status}) for student {student['id']} — treated as success")
            # cancel_at=NULL [cancel-period-end]: canceled 遷移は解約予約状態も必ず解消する (不変条件)。
            # past_due_since=NULL: 猶予起点も canceled 化と同時に解消 (3視点 review data 指摘) —
            # 残すと再契約後の決済失敗時に COALESCE(past_due_since, …) が stale な起点を拾い、
            # 猶予期間が即失効した状態で始まる事故の温床になる。
            c.execute(
                "UPDATE students SET status='canceled', stripe_subscription_id=NULL, cancel_at=NULL, past_due_since=NULL, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                (student["id"],)
            )
            conn.commit()
            conn.close()
            if _pre_missing:
                return {"ok": True, "message": "解約手続きは既に完了しています。ご不明な点がございましたら、お気軽に info@trillion-ai-juku.com までお問い合わせください。"}
            return {"ok": True, "message": "解約手続きが完了しました。ご利用は終了となり、今後のご請求は発生しません。"}
        # 🚪 [cancel-period-end] (2026-06-12) 解約方式を status で分岐:
        # - trial (trial_extended・課金前): 従来どおり即時解約 (Subscription.delete)。請求は発生しない。
        # - paid / past_due (課金開始後): Subscription.modify(cancel_at_period_end=True) の期間末解約。
        #   従来は全員 delete → deleted webhook で status='canceled' → アクセスガード即拒否となり、
        #   支払済み期間が残っていても即時利用停止 = 「期間終了まで利用可」の応答・mypage・legal の
        #   案内と全部矛盾していた。期間末解約なら status='paid' のままアクセス継続し、期間末に
        #   Stripe が subscription.deleted を送ってきた時点で canceled 化される (ガード変更不要)。
        _is_trial_cancel = (row["status"] == "trial")
        try:
            if _is_trial_cancel:
                _stripe.Subscription.delete(row["stripe_subscription_id"])
                log.info(f"Stripe subscription canceled for student {student['id']}")
            else:
                _sub = _stripe.Subscription.modify(row["stripe_subscription_id"], cancel_at_period_end=True)
                log.info(f"Stripe subscription scheduled to cancel at period end for student {student['id']}")
        except Exception as e:
            # 🧹 [cancel-consistency] (2026-06-12): Stripe 側で既に解約済み / 存在しない subscription は
            # 「解約完了」として扱う。死んだ sub_id が DB に残留した行 (旧 webhook が canceled 遷移時に
            # sub_id を消していなかった残骸) では Stripe 呼び出しが必ず失敗 → 502 になり、UI から
            # 永久に解約できなくなるため。この場合 subscription.deleted webhook はもう来ないので、
            # ここで直接 DB を canceled に更新し、死んだ sub_id もクリアする (自己修復)。
            _e_msg = str(e).lower()
            _gone_missing = any(_s in _e_msg for _s in ("no such subscription", "resource_missing"))
            _gone_canceled = any(_s in _e_msg for _s in (
                "already canceled", "already_canceled", "has been canceled", "canceled subscription",
            ))
            if type(e).__name__ == "InvalidRequestError" and (_gone_missing or _gone_canceled):
                log.info(f"Stripe subscription already gone for student {student['id']} (treated as canceled): {e}")
                # cancel_at / past_due_since も NULL クリア: canceled 遷移の不変条件
                # (03b70c4 の解約予約解消・05604ea の stale 猶予起点解消と同一の自己修復)。
                c.execute(
                    "UPDATE students SET status='canceled', stripe_subscription_id=NULL, cancel_at=NULL, past_due_since=NULL, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                    (student["id"],)
                )
                conn.commit()
                conn.close()
                if _gone_missing and not _gone_canceled:
                    # サブスク不存在は「別のサブスクが存在しない」ことまで保証できないため請求断言なし
                    # (前段ガード 05604ea の resource_missing 文言と統一)。
                    return {"ok": True, "message": "解約手続きは既に完了しています。ご不明な点がございましたら、お気軽に info@trillion-ai-juku.com までお問い合わせください。"}
                return {"ok": True, "message": "解約手続きが完了しました。ご利用は終了となり、今後のご請求は発生しません。"}
            log.error(f"Stripe cancel failed for student {student['id']}: {type(e).__name__}: {e}")
            conn.close()
            raise HTTPException(
                status_code=502,
                detail="Stripeでの解約処理に失敗しました。お手数ですが info@trillion-ai-juku.com までお問い合わせください。"
            )
        if _is_trial_cancel:
            # DB更新はStripe webhook (customer.subscription.deleted) が担当する。
            # ただしwebhook到達まで遅延があるためクライアントには即時成功を返す。
            conn.close()
            # [mypage-keiyaku-copy] (2026-06-12) trial 中のサブスク解約 (trial_extended) は上の
            # Subscription.delete で即時解約 — 「契約期間終了まで利用可」は事実と逆 (課金は始まらず、
            # webhook 反映後はアクセス終了) なので、mypage の confirm 文言と整合する専用文言を返す。
            return {"ok": True, "message": "解約手続きを受け付けました。体験期間中の解約であれば、ご登録のカードへの請求は発生しません。体験はこれで終了となります（画面への反映には数分かかる場合があります）。"}
        # [cancel-period-end] 期間末解約の予約時刻を即時 DB 反映。webhook (subscription.updated) も同期する
        # が、到達遅延中に mypage が「解約予約済み」を出せるようここでも書く。Stripe 側の解約予約は既に
        # 確定済みなので、ここの DB 失敗では 5xx を返さない (webhook が後追いで同期する)。
        _cancel_iso = None
        try:
            _cancel_ts = _sub.get("cancel_at") or _sub.get("current_period_end")
            if _cancel_ts:
                _cancel_iso = datetime.fromtimestamp(int(_cancel_ts), tz=timezone.utc).isoformat()
        except Exception as _ce:
            log.warning(f"[cancel-period-end] cancel_at parse failed for student {student['id']}: {_ce}")
        try:
            c.execute("UPDATE students SET cancel_at=?, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                      (_cancel_iso, student["id"]))
            conn.commit()
        except Exception as _de:
            log.warning(f"[cancel-period-end] cancel_at DB update failed for student {student['id']}: {_de}")
            try:
                conn.rollback()
            except Exception:
                pass
        conn.close()
        if row["status"] == "past_due":
            # past_due は直近のお支払いが未確認 — 「期間終了まで利用可」と断言すると猶予期間切れの
            # アクセス停止と矛盾するため、猶予期間ベースの正確な文言を返す。
            return {"ok": True, "message": "解約手続きを受け付けました。次回以降のご請求はありません。なお、直近のお支払いが確認できていないため、ご利用いただけるのはお支払い猶予期間の終了までとなります。"}
        return {"ok": True, "message": "解約手続きを受け付けました。現在のご契約期間終了まではご利用いただけます（期間終了後のご請求はありません）。"}

    # 純trial (Stripe顧客なし) の場合のみDBを直接更新
    c.execute("UPDATE students SET status='canceled', updated_at=CURRENT_TIMESTAMP WHERE id=?", (student["id"],))
    conn.commit()
    conn.close()
    return {"ok": True, "message": "トライアルを解約しました。再契約をご希望の際はトライアル申込ページからお願いします。"}


@app.post("/api/cron/weekly-reports")
def cron_weekly_reports(x_cron_secret: str = Header(None), dry_run: bool = False):
    """毎週日曜19時 (JST) にスケジューラから実行。
    メール配信 (全生徒) + LINE 配信 (連携済みのみ) のデュアルチャネル。
    notifications テーブルで週次 dedup (同一生徒に週2回送らない)。"""
    if not CRON_SECRET:
        log.error("CRON_SECRET not configured; refusing cron request")
        raise HTTPException(status_code=503, detail="Cron not configured")
    if not x_cron_secret or not hmac.compare_digest(x_cron_secret, CRON_SECRET):
        raise HTTPException(status_code=401, detail="Unauthorized")

    conn = db()
    c = conn.cursor()
    # kokuritsu_nankan コース生も含めるため course も取得
    # 🛡️ 塾長指示 2026-05-26: 保護者 email 並行配信用に parent_email / parent_email_enabled を取得
    c.execute("SELECT id, name, email, line_user_id, course, parent_email, parent_email_enabled FROM students WHERE status IN ('trial', 'paid')")
    students = list(c.fetchall())
    conn.close()

    import time as _t
    sent_email = 0
    sent_line = 0
    skipped = 0
    failed = 0
    capped = 0
    previews = []
    email_index = 0
    # Resend 日次上限ガード: 他メール (ログイン/監視等) の枠を残す
    WEEKLY_REPORT_EMAIL_CAP = int(os.getenv("WEEKLY_REPORT_EMAIL_CAP", "80"))
    for row in students:
        try:
            stats = _compute_weekly_stats(row["id"], days=7)
            # 活動が全くない週はスキップ（スパム防止）
            if stats["hours"] == 0 and stats["questions"] == 0 and stats["problems_done"] == 0:
                skipped += 1
                continue
            if dry_run:
                previews.append({
                    "student_id": row["id"], "name": row["name"], "stats": stats,
                    "would_send_email": bool(row.get("email")),
                    "would_send_line": bool(row.get("line_user_id")),
                })
                continue
            # --- メール配信 (全生徒) ---
            email = row.get("email")
            if email and sent_email >= WEEKLY_REPORT_EMAIL_CAP:
                capped += 1
                log.warning(f"[WeeklyReport] Email cap ({WEEKLY_REPORT_EMAIL_CAP}) reached, skipping student {row['id']}")
            elif email:
                # 週次 dedup: 直近7日以内に同テンプレートで成功送信済みならスキップ
                _dup_conn = db()
                _dup_c = _dup_conn.cursor()
                _seven_days_ago = (datetime.now(timezone.utc) - timedelta(days=6)).isoformat()
                _dup_c.execute(
                    "SELECT id FROM notifications WHERE student_id=? AND template='weekly_report_email' AND success=1 AND sent_at > ? LIMIT 1",
                    (row["id"], _seven_days_ago)
                )
                already_sent = _dup_c.fetchone()
                _dup_conn.close()
                if already_sent:
                    log.debug(f"[WeeklyReport] dedup skip email for student {row['id']}")
                else:
                    # Resend rate limit 対策: 2通目以降は 1.5秒待機
                    if email_index > 0:
                        _t.sleep(1.5)
                    email_index += 1
                    res = _send_weekly_report_email(email, row["name"], stats)
                    _ok = res.get("sent", False)
                    # notifications テーブルに記録
                    _n_conn = db()
                    _n_c = _n_conn.cursor()
                    _n_c.execute(
                        """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                           VALUES (?, 'email', 'weekly_report_email', ?, ?, ?)""",
                        (row["id"], json.dumps(stats, ensure_ascii=False)[:500], 1 if _ok else 0,
                         res.get("error", "")[:200] if not _ok else None)
                    )
                    _n_conn.commit()
                    _n_conn.close()
                    if _ok:
                        sent_email += 1
                    else:
                        failed += 1
            # --- 📊 保護者向け並行配信 (塾長指示 2026-05-26) ---
            try:
                parent_email = row.get("parent_email") if hasattr(row, "get") else (row["parent_email"] if "parent_email" in row.keys() else None)
                parent_enabled = row.get("parent_email_enabled") if hasattr(row, "get") else (row["parent_email_enabled"] if "parent_email_enabled" in row.keys() else 1)
            except Exception:
                parent_email = None
                parent_enabled = 0
            # 保護者 email が生徒 email と同じなら 2 重送信防止で skip
            if parent_email and parent_enabled and parent_email != row.get("email"):
                if sent_email >= WEEKLY_REPORT_EMAIL_CAP:
                    capped += 1
                else:
                    # 週次 dedup: per parent_email per template
                    _pdup_conn = db()
                    _pdup_c = _pdup_conn.cursor()
                    _seven_days_ago = (datetime.now(timezone.utc) - timedelta(days=6)).isoformat()
                    _pdup_c.execute(
                        "SELECT id FROM notifications WHERE student_id=? AND template='weekly_report_parent_email' AND success=1 AND sent_at > ? LIMIT 1",
                        (row["id"], _seven_days_ago)
                    )
                    already_sent_p = _pdup_c.fetchone()
                    _pdup_conn.close()
                    if not already_sent_p:
                        if email_index > 0:
                            _t.sleep(1.5)
                        email_index += 1
                        pres = _send_weekly_report_email(parent_email, row["name"], stats)
                        _pok = pres.get("sent", False)
                        _pn_conn = db()
                        _pn_c = _pn_conn.cursor()
                        _pn_c.execute(
                            """INSERT INTO notifications (student_id, channel, template, payload, success, error)
                               VALUES (?, 'email', 'weekly_report_parent_email', ?, ?, ?)""",
                            (row["id"], json.dumps({"to": parent_email, **stats}, ensure_ascii=False)[:500], 1 if _pok else 0,
                             pres.get("error", "")[:200] if not _pok else None)
                        )
                        _pn_conn.commit()
                        _pn_conn.close()
                        if _pok:
                            sent_email += 1
                        else:
                            failed += 1
            # --- LINE 配信 (連携済みのみ・従来互換) ---
            if row.get("line_user_id"):
                try:
                    params = {
                        "hours": stats["hours"],
                        "accuracy": stats["accuracy"],
                        "questions": stats["questions"],
                        "url": f"{BASE_URL}/mypage.html",
                    }
                    _do_line_push(row["id"], "weekly_report", params)
                    sent_line += 1
                except Exception as le:
                    log.warning(f"[WeeklyReport] LINE push failed for {row['id']}: {le}")
        except Exception as e:
            log.error(f"Weekly report failed for {row['id']}: {e}")
    return {
        "sent_email": sent_email, "sent_line": sent_line,
        "skipped": skipped, "failed": failed, "capped": capped,
        "total_students": len(students),
        "previews": previews if dry_run else None,
    }


@app.post("/api/weekly-reports/preview")
def weekly_reports_preview(payload: dict, request: Request, x_stats_token: str = Header(None)):
    """塾長ダッシュボードから、特定生徒の今週レポートをプレビュー"""
    if not _origin_allowed(request):
        raise HTTPException(status_code=403, detail="Origin not allowed")
    # 塾長認証（STATS_TOKEN）
    if STATS_TOKEN and (not x_stats_token or not hmac.compare_digest(x_stats_token, STATS_TOKEN)):
        raise HTTPException(status_code=401, detail="Unauthorized")
    student_id = payload.get("student_id")
    if not student_id:
        raise HTTPException(status_code=400, detail="student_id required")
    stats = _compute_weekly_stats(int(student_id), days=int(payload.get("days", 7)))
    return {"ok": True, "stats": stats}


@app.post("/api/weekly-reports/send-one")
def weekly_reports_send_one(payload: dict, request: Request, x_stats_token: str = Header(None)):
    """塾長ダッシュボードから、特定生徒にレポートを即送信 (メール + LINE)"""
    if not _origin_allowed(request):
        raise HTTPException(status_code=403, detail="Origin not allowed")
    if STATS_TOKEN and (not x_stats_token or not hmac.compare_digest(x_stats_token, STATS_TOKEN)):
        raise HTTPException(status_code=401, detail="Unauthorized")
    student_id = payload.get("student_id")
    if not student_id:
        raise HTTPException(status_code=400, detail="student_id required")
    stats = _compute_weekly_stats(int(student_id), days=7)
    # 生徒情報を取得
    conn = db()
    c = conn.cursor()
    c.execute("SELECT name, email, line_user_id FROM students WHERE id = ?", (int(student_id),))
    row = c.fetchone()
    conn.close()
    if not row:
        raise HTTPException(status_code=404, detail="生徒が見つかりません")
    result = {"email": None, "line": None}
    # メール送信
    if row["email"]:
        result["email"] = _send_weekly_report_email(row["email"], row["name"], stats)
        # notifications に記録
        _ok = result["email"].get("sent", False)
        _n_conn = db()
        _n_c = _n_conn.cursor()
        _n_c.execute(
            """INSERT INTO notifications (student_id, channel, template, payload, success, error)
               VALUES (?, 'email', 'weekly_report_email', ?, ?, ?)""",
            (int(student_id), json.dumps(stats, ensure_ascii=False)[:500], 1 if _ok else 0,
             result["email"].get("error", "")[:200] if not _ok else None)
        )
        _n_conn.commit()
        _n_conn.close()
    # LINE 送信 (連携済みなら)
    if row.get("line_user_id"):
        try:
            params = {
                "hours": stats["hours"],
                "accuracy": stats["accuracy"],
                "questions": stats["questions"],
                "url": f"{BASE_URL}/mypage.html",
            }
            result["line"] = _do_line_push(int(student_id), "weekly_report", params)
        except Exception:
            result["line"] = {"ok": False}
    return result

# ==========================================================================
# Routes: Analytics
# ==========================================================================
# ==========================================================================
# Routes: AI Proxy（塾長のAPIキーで全顧客のAI呼び出しを代理）
# 顧客は自分でAPIキーを設定不要。月謝に含まれるシームレスなUX。
# ==========================================================================
class AIProxyRequest(BaseModel):
    system: str
    messages: List[dict]
    model: Optional[str] = "claude-opus-4-7"
    max_tokens: Optional[int] = 2000
    thinking: Optional[bool] = False
    thinking_budget: Optional[int] = 4000
    kind: Optional[str] = "chat"
    student_id: Optional[int] = None
    # 月次クォータの対象機能。"problems"/"essays"/"textbooks" のいずれか
    # それ以外の値 (chat等) は制限なし
    feature: Optional[str] = None

def _origin_allowed(request: Request) -> bool:
    """Origin/Referer が許可リストに含まれるか。サーバ間呼び出しを排除するため
    Origin または Referer のどちらかが ALLOWED_ORIGINS の接頭辞と一致することを要求。"""
    origin = (request.headers.get("origin") or "").rstrip("/")
    referer = request.headers.get("referer") or ""
    for allowed in ALLOWED_ORIGINS:
        a = allowed.rstrip("/")
        if origin == a or referer.startswith(a + "/") or referer == a:
            return True
    return False


def _verify_student_active(student_id: int) -> dict:
    """student_id が trial/paid で有効期限内なら student row (dict) を返す。
    無効なら HTTPException を raise。"""
    if not student_id or student_id <= 0:
        raise HTTPException(status_code=400, detail="student_id が必要です")
    conn = db()
    c = conn.cursor()
    c.execute(
        "SELECT id, status, trial_end, plan, course, past_due_since FROM students WHERE id = ?",
        (student_id,),
    )
    row = c.fetchone()
    conn.close()
    if not row:
        raise HTTPException(status_code=404, detail="生徒が見つかりません")
    _row_course = row["course"] if "course" in row.keys() else None
    status = row["status"]
    if status == "paid":
        return dict(row)
    # 💳 決済失敗の猶予期間中のみアクセス許可 (grace 超過は拒否 → AI コスト経路の使い放題を防ぐ・2026-05-29)
    # _get_current_student と同一の grace 判定を共有し、AI 代理実行 (/api/ai/call 等) も grace bound する。
    if status == "past_due":
        _pds = row["past_due_since"] if "past_due_since" in row.keys() else None
        if _is_past_due_within_grace(_pds):
            return dict(row)
        raise HTTPException(status_code=403, detail="お支払いの確認ができていません。カード情報を更新してください。")
    # 国公立難関大学コース = premium 同等 → trial_end に関係なく永久アクセス (塾長指示)
    if _row_course == "kokuritsu_nankan":
        return dict(row)
    if status == "trial":
        # トライアル期限切れチェック（Postgres は datetime、SQLite は str で返す）
        trial_end_raw = row["trial_end"]
        if trial_end_raw:
            te = None
            if isinstance(trial_end_raw, str):
                try:
                    te = datetime.fromisoformat(trial_end_raw.replace("Z", "+00:00"))
                except ValueError:
                    te = None
            else:
                te = trial_end_raw  # datetime (Postgres)
            if te is not None:
                if te.tzinfo is None:
                    te = te.replace(tzinfo=timezone.utc)
                if datetime.now(timezone.utc) > te:
                    raise HTTPException(status_code=403, detail="トライアル期間が終了しています。契約を継続してください。")
        return dict(row)
    raise HTTPException(status_code=403, detail=f"契約状態が無効です (status={status})")


def _check_ai_budget(student_id: int) -> None:
    """その生徒が直近24hで消費したAIトークンが Plan 別 budget を超えていないか確認。
    Plan 別 (塾長指示 2026-04-30): premium/family/founder_special は実質無制限の 2M tokens。
    旧プラン名 (founder1/hybrid/intensive/ai) も後方互換でカバー (DB 既存データ対策)。"""
    one_day_ago = datetime.now(timezone.utc) - timedelta(days=1)
    conn = db()
    c = conn.cursor()
    # 生徒の plan + course を取得して budget を決定
    plan = "trial"
    _course = None
    try:
        c.execute("SELECT plan, course FROM students WHERE id = ?", (student_id,))
        row = c.fetchone()
        if row and row["plan"]:
            plan = str(row["plan"])
        if row:
            _course = row["course"] if "course" in row.keys() else None
    except Exception:
        pass
    # 国公立難関大学コース = premium 同等 (塾長指示: プレミアムの名前を変えて使っている)
    is_premium_tier = plan in PREMIUM_TIER_PLANS or _course == "kokuritsu_nankan"
    if _course == "kokuritsu_nankan":
        budget = PLAN_DAILY_TOKEN_BUDGET.get("premium", 2_000_000)
    else:
        budget = PLAN_DAILY_TOKEN_BUDGET.get(plan, AI_DAILY_TOKEN_BUDGET)
    # psycopg は % をプレースホルダ誤検知するため LIKE パターンもパラメータで渡す
    c.execute(
        """SELECT props FROM events
           WHERE session_id = ?
             AND name LIKE ?
             AND created_at > ?""",
        (str(student_id), 'ai_call_%', one_day_ago),
    )
    total = 0
    for row in c.fetchall():
        try:
            p = json.loads(row["props"] or "{}")
            total += int(p.get("input_tokens", 0)) + int(p.get("output_tokens", 0))
        except (json.JSONDecodeError, ValueError, TypeError):
            continue
    conn.close()
    if total >= budget:
        # Plan 別に upgrade 文言を出し分け (premium tier は upgrade 不要)
        if is_premium_tier:
            detail = (
                f"AI_BUDGET_PREMIUM:1日あたりのAI利用上限({budget:,}トークン)に達しました。"
                f"明日(JST 0時頃)にリセットされます。{plan}プランは大量生成にも耐える設計ですが、"
                f"教材一括生成等で稀に到達することがあります。"
            )
        else:
            detail = (
                f"AI_BUDGET_TRIAL:1日あたりのAI利用上限({budget:,}トークン)に達しました。"
                f"明日リセットされます。プレミアムプランなら 1日 2,000,000 トークンまで利用可能です。"
            )
        raise HTTPException(status_code=429, detail=detail)


# ==========================================================================
# 月次クォータ (プランごとの「使えるシステム」差別化)
# ==========================================================================
def _jst_year_month() -> str:
    """JST(UTC+9) ベースの 'YYYYMM' を返す。Stripe請求月と一致させる。"""
    now = datetime.now(timezone.utc) + timedelta(hours=9)
    return now.strftime("%Y%m")


def _get_monthly_usage(student_id: int, feature: str, year_month: Optional[str] = None) -> int:
    """この生徒の今月の機能別使用回数を返す。"""
    if not year_month:
        year_month = _jst_year_month()
    conn = db()
    c = conn.cursor()
    c.execute(
        "SELECT used_count FROM usage_monthly WHERE student_id = ? AND feature = ? AND year_month = ?",
        (student_id, feature, year_month),
    )
    row = c.fetchone()
    conn.close()
    return int(row["used_count"]) if row else 0


def _get_all_monthly_usage(student_id: int, year_month: Optional[str] = None) -> dict:
    """この生徒の今月の全機能の使用回数を {feature: count} で返す。"""
    if not year_month:
        year_month = _jst_year_month()
    conn = db()
    c = conn.cursor()
    c.execute(
        "SELECT feature, used_count FROM usage_monthly WHERE student_id = ? AND year_month = ?",
        (student_id, year_month),
    )
    rows = c.fetchall()
    conn.close()
    return {r["feature"]: int(r["used_count"]) for r in rows}


def _effective_quota_plan(student: dict) -> str:
    """月次クォータ計算に使う実効プラン名を返す。
    status='trial' の students.plan には申込時の「希望プラン」が入る (checkout の
    デフォルト radio = founder_special / trial_signup のデフォルト hybrid) ため、
    plan だけで引くと無課金体験に premium 相当の無制限クォータが漏れる。
    体験中は一律 trial 制限とし、支払い確定 (status='paid') 後に plan 本来の
    クォータが有効化される。past_due は猶予期間中のアクセス維持方針に合わせ plan を維持。"""
    if (student.get("status") or "").lower() == "trial":
        return "trial"
    return (student.get("plan") or "trial").lower()


def _check_quota(student: dict, feature: str) -> None:
    """その生徒のプランで feature が今月の上限に達していないか確認。
    達していれば 429 + プラン情報付きエラーを返す。"""
    if feature not in QUOTA_FEATURES:
        return  # クォータ対象外
    # 国公立難関大学コース = premium 同等 → 全機能無制限 (塾長指示)
    _sq_course = student.get("course")
    if _sq_course == "kokuritsu_nankan":
        return  # 無制限
    plan = _effective_quota_plan(student)
    quotas = PLAN_QUOTAS.get(plan, PLAN_QUOTAS["trial"])
    limit = quotas.get(feature)
    if limit is None:
        return  # 無制限
    used = _get_monthly_usage(int(student["id"]), feature)
    if used >= limit:
        feature_label = {"problems": "問題生成", "essays": "添削", "textbooks": "参考書生成"}.get(feature, feature)
        raise HTTPException(
            status_code=429,
            detail=(
                f"今月の{feature_label}回数 {limit}回 の上限に達しました。"
                f"プレミアムプランにアップグレードすると無制限で使えます。"
            ),
        )


def _increment_usage(student_id: int, feature: str) -> int:
    """使用回数を +1。INSERT or UPDATE (UPSERT)。新カウントを返す。"""
    if feature not in QUOTA_FEATURES:
        return 0
    year_month = _jst_year_month()
    conn = db()
    c = conn.cursor()
    # 既存行を update を試みて、影響行 0 なら insert (Postgres/SQLite 両対応)
    c.execute(
        "UPDATE usage_monthly SET used_count = used_count + 1 "
        "WHERE student_id = ? AND feature = ? AND year_month = ?",
        (student_id, feature, year_month),
    )
    if c.rowcount == 0:
        try:
            c.execute(
                "INSERT INTO usage_monthly (student_id, feature, year_month, used_count) "
                "VALUES (?, ?, ?, 1)",
                (student_id, feature, year_month),
            )
        except Exception:
            # 並行 INSERT で重複した場合の救済
            c.execute(
                "UPDATE usage_monthly SET used_count = used_count + 1 "
                "WHERE student_id = ? AND feature = ? AND year_month = ?",
                (student_id, feature, year_month),
            )
    conn.commit()
    new_count = _get_monthly_usage(student_id, feature, year_month)
    conn.close()
    return new_count


def _record_ai_call_failure(stage: str, status_code: int, detail: str, payload_obj=None,
                              request_obj: Request = None):
    """ai_proxy の前段 check or AI 呼出で発生した失敗を events テーブルに記録。
    塾長が CEO ダッシュ /api/admin/ai/recent-failures から直近の失敗詳細を見られる。
    Why: probe-tutor は前段 check bypass で動くが、本物の /api/ai/call は前段で
    止まる可能性があるため、前段 check の失敗も可視化する必要がある (memory: feedback_self_healing_dashboard)。
    """
    try:
        conn = db()
        c = conn.cursor()
        props = {
            "stage": stage,
            "status_code": status_code,
            "detail": (detail or "")[:500],
            "student_id": getattr(payload_obj, "student_id", None) if payload_obj else None,
            "model": getattr(payload_obj, "model", None) if payload_obj else None,
            "kind": getattr(payload_obj, "kind", None) if payload_obj else None,
            "feature": getattr(payload_obj, "feature", None) if payload_obj else None,
            "thinking": getattr(payload_obj, "thinking", None) if payload_obj else None,
            "origin": (request_obj.headers.get("origin") if request_obj else None),
            "referer": (request_obj.headers.get("referer") if request_obj else None)[:200] if request_obj and request_obj.headers.get("referer") else None,
        }
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            ("ai_call_failure", json.dumps(props, ensure_ascii=False), "ai_proxy_check"),
        )
        conn.commit()
        conn.close()
    except Exception as e:
        log.error(f"_record_ai_call_failure failed: {e}")


@app.post("/api/ai/call")
async def ai_proxy(payload: AIProxyRequest, request: Request):
    """顧客の全AI呼び出しを塾長のAPIキーで代理実行。
    Origin検証・student_id存在/有効性検証・1日あたりトークンbudgetで多層防御。"""
    if not ANTHROPIC_API_KEY:
        _record_ai_call_failure("anthropic_unconfigured", 503, "ANTHROPIC_API_KEY 未設定", payload, request)
        raise HTTPException(
            status_code=503,
            detail="AI サービスが構成されていません。管理者にお問い合わせください。",
        )

    # 1) Origin/Referer が許可ドメインか
    if not _origin_allowed(request):
        origin_header = request.headers.get('origin')
        referer_header = request.headers.get('referer')
        log.warning(
            f"/api/ai/call blocked by origin check: origin={origin_header} referer={referer_header} ip={request.client.host if request.client else '?'}"
        )
        _record_ai_call_failure(
            "origin_check",
            403,
            f"origin={origin_header}, referer={(referer_header or '')[:120]}",
            payload, request,
        )
        raise HTTPException(status_code=403, detail="Origin not allowed")

    # 2-3) student_id と budget 検証。DBエラー時は 500 を裸文字列ではなく JSON で返す。
    student_row = None
    try:
        student_row = _verify_student_active(payload.student_id)
        _check_ai_budget(payload.student_id)
        # 機能別月次クォータ check (problems / essays / textbooks)
        if payload.feature:
            _check_quota(student_row, payload.feature)
    except HTTPException as e:
        # 4xx はそのまま伝搬するが、events に詳細を記録 (塾長デバッグ用)
        _record_ai_call_failure(
            "student_or_budget_or_quota",
            e.status_code,
            str(e.detail)[:300],
            payload, request,
        )
        raise
    except Exception as e:
        log.error(f"/api/ai/call validation exception: {type(e).__name__}: {e}")
        _record_ai_call_failure(
            "validation_unexpected", 500,
            f"{type(e).__name__}: {str(e)[:200]}",
            payload, request,
        )
        raise HTTPException(status_code=500, detail=f"validation error: {type(e).__name__}: {str(e)[:200]}")

    # 4) モデルとトークン数の上限ガード（異常値を弾く）。
    #    30〜50問の大量生成・市販参考書級のテキスト教材に対応するため 24000 まで許容。
    max_tokens = max(1, min(int(payload.max_tokens or 2000), 24000))

    # 5) Prompt Injection 緩和: system / messages のサイズと明白な jailbreak フレーズを弾く。
    #    完全な防御は不可能だが、学生端末を経由した塾のAPIキー横取り用途を大幅に抑制する。
    _JAILBREAK_PATTERNS = (
        "ignore previous", "ignore all prior", "disregard previous",
        "system prompt", "developer mode", "jailbreak",
        "you are now", "act as dan", "dan mode",
    )
    _sys = (payload.system or "")
    # 上限 12000 chars: AI チューター system prompt は科目別指導方針を全 inline する設計のため
    # 7500-8500 chars 必要。以前 6000 制限で 400 → frontend が demo fallback してしまう不具合の修正 (2026-05-06)。
    # Anthropic API 自体は 200k token 対応なので 12000 chars は十分余裕がある。
    if len(_sys) > 12000:
        _record_ai_call_failure("system_too_long", 400, f"len={len(_sys)}", payload, request)
        raise HTTPException(status_code=400, detail="system prompt too long")
    _sys_low = _sys.lower()
    matched_jb = next((p for p in _JAILBREAK_PATTERNS if p in _sys_low), None)
    if matched_jb:
        log.warning(f"/api/ai/call blocked by jailbreak pattern check: student_id={payload.student_id}")
        _record_ai_call_failure("jailbreak_pattern", 403, f"pattern={matched_jb}", payload, request)
        raise HTTPException(status_code=403, detail="prohibited system prompt")
    # messages 総長も上限（画像除く）
    _msg_text_total = 0
    for m in (payload.messages or []):
        content = m.get("content") if isinstance(m, dict) else None
        if isinstance(content, str):
            _msg_text_total += len(content)
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and part.get("type") == "text":
                    _msg_text_total += len(part.get("text") or "")
    if _msg_text_total > 40000:
        _record_ai_call_failure("messages_too_long", 413, f"total_chars={_msg_text_total}", payload, request)
        raise HTTPException(status_code=413, detail="messages too long")
    # 🛡️ 2026-06-02: image/document ブロック数の上限 (AI コスト/DoS 保護)。
    # frontend は chat=最大5枚・写真採点=2枚に制限するが、直接 POST で content 配列に大量の
    # image block を詰めて単発で高コスト呼び出しする迂回を防ぐ。全 caller 中の正当な最大は 5 枚
    # なので余裕を見て 10 で hard cap (正当用途は阻害しない・kind 分岐不要)。
    # _check_ai_budget は「過去 24h の累積」しか見ず、この単発の巨大コール自体は抑止できないため、
    # ここで枚数を直接制限するのが最後の砦。
    _img_block_total = 0
    for m in (payload.messages or []):
        content = m.get("content") if isinstance(m, dict) else None
        if isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and part.get("type") in ("image", "document"):
                    _img_block_total += 1
    if _img_block_total > 10:
        _record_ai_call_failure("too_many_images", 413, f"image_blocks={_img_block_total}", payload, request)
        raise HTTPException(status_code=413, detail="添付画像/PDF が多すぎます (1 リクエストあたり 10 個まで)")

    body = {
        "model": payload.model,
        "max_tokens": max_tokens,
        "system": payload.system,
        "messages": payload.messages,
    }

    # Gemini ルート: model="gemini-*" を frontend から指定された場合は直接 Gemini を呼ぶ
    # (塾長指示 2026-05-06: コスト削減のため text 系 AI 機能は Gemini に切替)
    # Vision (image) は Gemini route 未対応 → Anthropic に強制 fallback
    if (payload.model or "").startswith("gemini-"):
        # 🚨 2026-05-07: Gemini quota 連続失敗時は Gemini をスキップして直接 Anthropic 経由
        # (Gemini → Anthropic の二重 round-trip でコスト増を防ぐ・circuit breaker パターン)
        import time as _t
        if _GEMINI_QUOTA_FAIL.get("skip_until", 0.0) > _t.time():
            log.info(f"[AIProxy][Gemini circuit breaker] Gemini skip active until {_GEMINI_QUOTA_FAIL['skip_until']:.0f}, going direct to Anthropic")
            if ANTHROPIC_API_KEY:
                fallback_body = dict(body)
                fallback_body["model"] = "claude-sonnet-4-6"
                try:
                    data = _call_anthropic_safe(fallback_body, kind=payload.kind)
                    if isinstance(data, dict):
                        data["_fallback_from"] = "gemini_circuit_breaker"
                    return data
                except HTTPException:
                    raise
                except Exception as ce:
                    log.error(f"[AIProxy][Gemini skip → Anthropic] failed: {type(ce).__name__}: {str(ce)[:120]}")
                    raise HTTPException(status_code=503, detail="AI サービスが一時的に応答できません。少し時間をおいてもう一度お試しください。")
            # Anthropic も無ければ Gemini を試すしかない (skip 解除して通常経路へ)
        if not GEMINI_API_KEY:
            _record_ai_call_failure("gemini_unconfigured", 503, "GEMINI_API_KEY 未設定", payload, request)
            raise HTTPException(status_code=503, detail="Gemini が構成されていません")
        # 画像入力検知
        _has_image = False
        for _m in (payload.messages or []):
            _c = _m.get("content") if isinstance(_m, dict) else None
            if isinstance(_c, list):
                for _part in _c:
                    if isinstance(_part, dict) and _part.get("type") == "image":
                        _has_image = True; break
            if _has_image: break
        if _has_image:
            _record_ai_call_failure("gemini_no_vision", 400, "Gemini route は image 入力非対応", payload, request)
            raise HTTPException(status_code=400, detail="画像入力は claude-* モデルを指定してください")
        try:
            data = _call_gemini(body, model=payload.model, kind=payload.kind)
            usage = data.get("usage", {}) or {}
            if payload.student_id and usage:
                try:
                    _conn = db()
                    _c = _conn.cursor()
                    _c.execute(
                        "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                        (f"ai_call_{payload.kind}",
                         json.dumps({"model": data.get("_actual_model") or payload.model, "provider": "gemini",
                                     "input_tokens": usage.get("input_tokens", 0), "output_tokens": usage.get("output_tokens", 0)}),
                         str(payload.student_id))
                    )
                    _conn.commit()
                    _conn.close()
                except Exception as _ev:
                    log.warning(f"[AIProxy][Gemini] cost tracking failed: {_ev}")
            return data
        except HTTPException:
            raise
        except Exception as e:
            # 🚨 2026-05-07: Gemini 失敗時は Anthropic に自動 fallback
            # memory 「AI never-fail 原則」: Gemini quota (429) 等で 503 を顧客に返さない
            # 顧客 (森澤さん級の決済前段階) で AI 計画生成が止まると致命的に機会損失
            err_str = f"{type(e).__name__}: {str(e)[:200]}"
            err_lower = err_str.lower()
            # quota 系 429 を circuit breaker でカウント (5 分窓で 3 回 → 30 分 skip)
            import time as _tt
            if "429" in err_str or "quota" in err_lower or "exceed" in err_lower:
                now_ts = _tt.time()
                if now_ts - _GEMINI_QUOTA_FAIL.get("window_start", 0) > 300:
                    _GEMINI_QUOTA_FAIL["window_start"] = now_ts
                    _GEMINI_QUOTA_FAIL["count_in_window"] = 1
                else:
                    _GEMINI_QUOTA_FAIL["count_in_window"] += 1
                if _GEMINI_QUOTA_FAIL["count_in_window"] >= 3:
                    _GEMINI_QUOTA_FAIL["skip_until"] = now_ts + 1800  # 30 min skip
                    log.warning(f"[AIProxy][Gemini circuit breaker] Activated for 30 min after {_GEMINI_QUOTA_FAIL['count_in_window']} 429s in 5min window")
                    _record_ai_critical_event("gemini_circuit_breaker_activated", {
                        "fail_count": _GEMINI_QUOTA_FAIL["count_in_window"],
                        "skip_minutes": 30,
                    })
            log.warning(f"[AIProxy][Gemini→Anthropic fallback] Gemini failed ({err_str}), trying Anthropic")
            if not ANTHROPIC_API_KEY:
                _record_ai_call_failure("gemini_failed_anthropic_unconfigured", 503, err_str, payload, request)
                raise HTTPException(status_code=503, detail=f"AI 呼び出しに失敗 (Gemini quota + Anthropic 未構成): {err_str[:120]}")
            try:
                # Anthropic に切替 (Sonnet 4.6 default)
                fallback_body = dict(body)
                fallback_body["model"] = "claude-sonnet-4-6"
                data = _call_anthropic_safe(fallback_body, kind=payload.kind)
                # 結果に fallback flag を埋める
                if isinstance(data, dict):
                    data["_fallback_from"] = "gemini"
                    data["_fallback_reason"] = err_str[:100]
                # cost tracking (Anthropic 経由)
                if payload.student_id:
                    try:
                        _conn = db()
                        _c = _conn.cursor()
                        usage = data.get("usage", {}) or {}
                        _c.execute(
                            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                            (f"ai_call_{payload.kind}",
                             json.dumps({"model": data.get("_actual_model") or "claude-sonnet-4-6",
                                         "provider": "anthropic",
                                         "fallback_from": "gemini",
                                         "fallback_reason": err_str[:80],
                                         "input_tokens": usage.get("input_tokens", 0),
                                         "output_tokens": usage.get("output_tokens", 0)}),
                             str(payload.student_id))
                        )
                        _conn.commit()
                        _conn.close()
                    except Exception as _ev:
                        log.warning(f"[AIProxy][Anthropic fallback] cost tracking failed: {_ev}")
                log.info(f"[AIProxy][Gemini→Anthropic fallback] success after Gemini fail")
                return data
            except HTTPException:
                raise
            except Exception as e2:
                log.error(f"[AIProxy] BOTH Gemini and Anthropic failed: gemini={err_str} / anthropic={type(e2).__name__}: {str(e2)[:120]}")
                _record_ai_call_failure("gemini_and_anthropic_failed", 503, f"gemini={err_str[:80]} / anthropic={type(e2).__name__}: {str(e2)[:80]}", payload, request)
                raise HTTPException(status_code=503, detail="AI サービスが一時的に応答できません。少し時間をおいてもう一度お試しください。")

    # Opus 4.7 は thinking + output_config + temperature が **必須** (memory: feedback_opus47_proxy_required.md)
    # frontend から thinking=false で来ても backend で必ず補完する。
    # Tier 2 (Sonnet) 降格時は _call_anthropic_safe 内部で thinking/output_config が pop されるので
    # 補完しても降格パスで問題は起きない。
    if (payload.model or "").startswith("claude-opus-4-7"):
        # thinking=true の用途 (diagnostic/curriculum/essay/problems): budget に応じた effort
        # thinking=false の用途 (chat/parent/prep/speaking): adaptive + low で軽く回す (latency/cost 抑制)
        if payload.thinking:
            budget = int(payload.thinking_budget or 4000)
            effort = "high" if budget >= 4000 else ("medium" if budget >= 1500 else "low")
        else:
            effort = "low"
        body["thinking"] = {"type": "adaptive"}
        body["output_config"] = {"effort": effort}
        body["temperature"] = 1.0
    elif payload.thinking:
        # Sonnet 4.6 以下は "enabled" + budget_tokens 形式
        body["temperature"] = 1.0
        body["thinking"] = {"type": "enabled", "budget_tokens": min(int(payload.thinking_budget or 4000), 16000)}

    # AI never-fail 原則: _call_anthropic_safe() 経由で 4 段降格 (Opus→Sonnet→Haiku→Gemini)。
    # 直叩きから _call_anthropic_safe() に移行 (memory: feedback_ai_never_fail.md)
    try:
        data = _call_anthropic_safe(body, kind=f"call_{payload.kind}", student_id=payload.student_id)

        # Track cost per student (for CEO analytics)
        usage = data.get("usage", {})
        if payload.student_id and usage:
            conn = db()
            c = conn.cursor()
            c.execute(
                """INSERT INTO events (name, props, session_id)
                   VALUES (?, ?, ?)""",
                (
                    f"ai_call_{payload.kind}",
                    json.dumps({
                        "model": data.get("_actual_model") or payload.model,
                        "provider": data.get("_provider") or "anthropic",
                        "input_tokens": usage.get("input_tokens", 0),
                        "output_tokens": usage.get("output_tokens", 0),
                    }),
                    str(payload.student_id),
                ),
            )
            # Update last activity
            c.execute(
                "UPDATE students SET updated_at=CURRENT_TIMESTAMP WHERE id=?",
                (payload.student_id,),
            )
            conn.commit()
            conn.close()

        # 機能別月次カウント+1 (problems / essays / textbooks のみ)
        # API 呼び出し成功後に increment する (失敗時は加算しないことでフェアネス確保)
        if payload.student_id and payload.feature in QUOTA_FEATURES:
            try:
                _increment_usage(int(payload.student_id), payload.feature)
            except Exception as e:
                log.warning(f"_increment_usage failed silently: {e}")

        return data
    except HTTPException as e:
        # _call_anthropic_safe が raise した 503 (全 tier 失敗) を events に記録 + 素通し
        _record_ai_call_failure(
            "anthropic_all_tiers_failed", e.status_code, str(e.detail)[:300],
            payload, request,
        )
        raise
    except Exception as e:
        log.error(f"AI proxy exception: {e}")
        _record_ai_call_failure(
            "ai_call_unexpected", 500, f"{type(e).__name__}: {str(e)[:300]}",
            payload, request,
        )
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/ai/status")
def ai_status():
    """フロントエンドがバックエンドAI proxyの有無を確認"""
    return {
        "backend_ai_available": bool(ANTHROPIC_API_KEY),
        "hosted_mode": bool(ANTHROPIC_API_KEY),
    }

# ==========================================================================
# Routes: Auto-Alert System
# ==========================================================================
class AlertCheckRequest(BaseModel):
    threshold_days: int = 3

class AlertTestRequest(BaseModel):
    type: str
    destination: str

@app.post("/api/activity/log")
def log_activity(payload: dict, request: Request):
    """生徒の活動を記録（ログイン、質問、クエスト完了等）。
    無認証POSTでDB汚染（他人のupdated_at偽装、events爆撃）されないよう
    Origin検証＋生徒有効性検証＋サイズ上限を課す。"""
    if not _origin_allowed(request):
        raise HTTPException(status_code=403, detail="Origin not allowed")
    if len(json.dumps(payload)) > 4000:
        raise HTTPException(status_code=413, detail="payload too large")
    student_id = payload.get("student_id")
    activity_type = str(payload.get("type", "unknown"))[:64]
    if not student_id:
        raise HTTPException(status_code=400, detail="student_id required")
    _verify_student_active(int(student_id))
    conn = db()
    c = conn.cursor()
    c.execute(
        "UPDATE students SET updated_at=CURRENT_TIMESTAMP WHERE id=?",
        (student_id,)
    )
    c.execute(
        "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
        (f"activity_{activity_type}", json.dumps(payload), str(student_id))
    )
    conn.commit()
    conn.close()
    return {"ok": True}

@app.post("/api/alerts/check-inactivity")
def check_inactivity(payload: AlertCheckRequest, x_cron_secret: str = Header(None)):
    """外部cronから呼び出し、非活動生徒を検知してアラート送信"""
    if not CRON_SECRET:
        log.error("CRON_SECRET not configured; refusing cron request")
        raise HTTPException(status_code=503, detail="Cron not configured")
    if not x_cron_secret or not hmac.compare_digest(x_cron_secret, CRON_SECRET):
        raise HTTPException(status_code=401, detail="Unauthorized")

    threshold_dt = datetime.now(timezone.utc) - timedelta(days=payload.threshold_days)
    conn = db()
    c = conn.cursor()
    # Find students inactive for N days（N日以上更新がない生徒）
    # 🛡️ 国公立難関大学コース ('kokuritsu_nankan') = 塾の通塾生 (無期限) は再エンゲージ/継続案内の
    #    対象外 (塾長指示)。streak_reminder / trial_ending (10年trial生に不適切) の LINE push を送らない。
    #    継続メール全7経路 (trial-reminders/followups/nurture/unused-warning/rescue) と同じ除外。
    c.execute(
        """SELECT id, name, line_user_id, status, updated_at
           FROM students
           WHERE status IN ('trial', 'paid')
             AND updated_at <= ?
             AND (course IS NULL OR course != 'kokuritsu_nankan')""",
        (threshold_dt,)
    )
    inactive = c.fetchall()
    conn.close()

    now = datetime.now(timezone.utc)
    sent_count = 0
    for row in inactive:
        updated = row["updated_at"]
        if isinstance(updated, str):
            try:
                updated_dt = datetime.fromisoformat(updated.replace("Z", "+00:00"))
                if updated_dt.tzinfo is None:
                    updated_dt = updated_dt.replace(tzinfo=timezone.utc)
            except ValueError:
                updated_dt = now
        else:
            updated_dt = updated if updated.tzinfo else updated.replace(tzinfo=timezone.utc)
        days = int((now - updated_dt).total_seconds() / 86400)
        level = 3 if days >= 7 else 2 if days >= 5 else 1
        try:
            if row["line_user_id"]:
                template = "streak_reminder" if level == 1 else "trial_ending"
                _do_line_push(
                    row["id"],
                    template,
                    {"days_inactive": days, "streak": 0},
                )
                sent_count += 1
        except Exception as e:
            log.error(f"Alert send failed for student {row['id']}: {e}")

    return {"inactive_count": len(inactive), "sent": sent_count}

