@app.get("/api/mock-exam/templates")
def mock_exam_templates():
    """利用可能な模試テンプレート一覧 (LP/UI セレクト用)。"""
    out = []
    for k, v in MOCK_EXAM_TEMPLATES.items():
        section_total = sum(s["count"] * s["points_per"] for s in v["sections"])
        out.append({
            "exam_type": k,
            "label": v["label"],
            "duration_min": v["duration_min"],
            "max_score": section_total,
            "section_count": len(v["sections"]),
        })
    return {"templates": out}


@app.post("/api/mock-exam/generate")
def mock_exam_generate(payload: dict, request: Request, authorization: Optional[str] = Header(None)):
    """模試を動的に生成。
    payload: {"exam_type": "kyotsu" | "todai" | ..., "student_id": optional}
    既存の exam_questions プールから section ごとに最新順 N 件を取得。
    返却: {session_id, label, duration_min, sections: [{name, questions: [...]}], max_score}

    🛡️ IDOR fix 2026-05-26 (3視点 audit 発見・hybrid pattern):
    - admin Bearer: payload student_id をそのまま使用 (任意生徒として作成可)
    - 生徒 session_token: claims["student_id"] を採用 (payload 値は信用しない・他生徒 ID enumerate 防御)
    - 未認証: student_id=NULL で「ゲスト体験 session」として作成 (LP 訪問者用)
    - rate limit: per-IP 20 req/60s で空 session 量産 DoS 防御
    """
    # 🛡️ rate limit (空 session 量産 DoS 防御・校内 NAT 対応で生徒単位 audit M5 fix)
    _check_rate_limit_caller(request, authorization, bucket="mock_exam_generate", limit=20, window=60)

    exam_type = payload.get("exam_type")
    if exam_type not in MOCK_EXAM_TEMPLATES:
        raise HTTPException(status_code=400, detail=f"Unknown exam_type: {exam_type}")

    # 認証 + student_id 決定
    is_admin = False
    auth_student_id: Optional[int] = None
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            is_admin = True
        else:
            claims = _verify_session_token(token)
            if claims and claims.get("student_id"):
                try:
                    auth_student_id = int(claims["student_id"])
                except (TypeError, ValueError):
                    auth_student_id = None

    # student_id 確定 (admin → payload / 生徒 → claims / 未認証 → NULL ゲスト)
    payload_student_id = payload.get("student_id")
    if is_admin:
        try:
            student_id = int(payload_student_id) if payload_student_id else None
        except (TypeError, ValueError):
            student_id = None
    elif auth_student_id:
        student_id = auth_student_id  # payload を信用しない (IDOR 防御)
    else:
        student_id = None  # ゲスト体験 session

    tpl = MOCK_EXAM_TEMPLATES[exam_type]

    conn = db()
    c = conn.cursor()
    sections_out = []
    max_score = 0
    snapshot = []  # 採点用の正解データ
    for sec in tpl["sections"]:
        # 該当 part の最新 count 件をランダム抽出 (created_at DESC LIMIT で多様性確保)
        c.execute(
            "SELECT id, question_data FROM exam_questions WHERE exam_id=? AND part_key=? AND eiken_grade=? ORDER BY RANDOM() LIMIT ?",
            (sec["exam_id"], sec["part_key"], sec["eiken_grade"], sec["count"]),
        )
        rows = c.fetchall()
        section_questions = []
        for r in rows:
            qid = r[0] if not hasattr(r, 'keys') else r["id"]
            qdata_raw = r[1] if not hasattr(r, 'keys') else r["question_data"]
            qdata = json.loads(qdata_raw) if isinstance(qdata_raw, str) else qdata_raw
            sub_questions = qdata.get("questions", [])
            section_questions.append({
                "exam_question_id": qid,
                "passage": qdata.get("passage", ""),
                "audio_script": qdata.get("audio_script", ""),
                "prompt": qdata.get("prompt", ""),
                "year_simulated": qdata.get("year_simulated"),
                "univ_simulated": qdata.get("univ_simulated"),
                "questions": sub_questions,
            })
            # 採点用 snapshot
            # 🎯 [全問正解=100% fix 2026-06-17] 採点可能(multiple_choice)の小問だけを満点に数える。
            #   非選択式(記述/数列の一般項 等)は自動採点できないので満点からも除外し、全問正解=100% にする。
            #   配点は points_per を「MC 小問数」で割る(非MC小問で薄めない)。MC 0 件(essay 等)は満点に 0 加算。
            mc_subs = [sq for sq in sub_questions if sq.get("type") == "multiple_choice"]
            per_pt = max(sec["points_per"] // max(len(mc_subs), 1), 1)  # 端数で 0 点問題にならないよう下限1
            snap_subs = [{"id": sq.get("id"), "answer": sq.get("answer"), "points": per_pt} for sq in mc_subs]
            snapshot.append({
                "section_name": sec["name"],
                "exam_question_id": qid,
                "sub_questions": snap_subs,
            })
            max_score += per_pt * len(snap_subs)  # 採点可能分のみ満点に加算 (= 全問正解で 100%)
        sections_out.append({
            "name": sec["name"],
            "points_per_question": sec["points_per"],
            "questions": section_questions,
            "auto_graded": sec.get("part_key") != "w_essay",  # essay は別経路 (5 AI 多視点・自動採点対象外)
        })
        # 🎯 [2026-06-17] max_score は上の per-大問 ループで「採点可能(MC)小問の配点合計」を加算済み。
        #   旧実装 (count * points_per) は非MC小問や端数を満点に含め、全問正解でも 100% 未満になる
        #   致命バグだった (例: 数列の一般項型を含む数学で全問正解=75%)。w_essay も MC 0 件で自動的に 0 加算。

    # 🎯 [2026-06-17 guard] 全セクションが記述/非MCで gradeable 合計が 0 の回 (todai/kyodai の全記述抽選等)は、
    #   旧来どおり nominal 満点 (count*points_per・w_essay 除く) を denominator に使い score_max=0 を回避。
    #   (MC が無い回なので % は 0 になるが記述は別途 5AI 採点へ。旧実装と同挙動で reader への波及なし)
    if max_score <= 0:
        max_score = sum(s["count"] * s["points_per"] for s in tpl["sections"] if s.get("part_key") != "w_essay")

    # セッション作成
    snapshot_json = json.dumps({"sections": sections_out, "answer_key": snapshot}, ensure_ascii=False)
    c.execute(
        "INSERT INTO mock_exam_sessions (student_id, exam_type, target_label, duration_min, started_at, score_max, questions_json) VALUES (?,?,?,?,?,?,?) RETURNING id",
        (student_id, exam_type, tpl["label"], tpl["duration_min"], datetime.now(timezone.utc).isoformat(), max_score, snapshot_json),
    )
    sid_row = c.fetchone()
    session_id = (sid_row[0] if not hasattr(sid_row, 'keys') else sid_row.get("id")) if sid_row else None
    conn.commit()
    conn.close()

    return {
        "session_id": session_id,
        "exam_type": exam_type,
        "label": tpl["label"],
        "duration_min": tpl["duration_min"],
        "max_score": max_score,
        "sections": sections_out,
    }


@app.post("/api/mock-exam/submit")
def mock_exam_submit(payload: dict, request: Request, authorization: Optional[str] = Header(None)):
    """模試の採点。
    payload: {"session_id": N, "answers": {"<exam_question_id>_<sub_id>": "<choice_index>"}}
    返却: {score_total, score_max, percentage, deviation_estimate, section_scores, weak_topics}

    🛡️ Write IDOR fix 2026-05-26 (3視点 audit 発見・最大破壊力 endpoint):
    - 旧実装: 無認証 + session_id query のみで他生徒の成績・偏差値を**改竄可**だった
    - 修正: session.student_id IS NULL (ゲスト体験) → 誰でも採点可 / IS NOT NULL → 本人 session_token or admin Bearer 必須
    - rate limit: per-IP 30 req/60s で同 session への spam 攻撃防御
    """
    # 🛡️ rate limit (session spam 攻撃防御・校内 NAT 対応で生徒単位 audit M5 fix)
    _check_rate_limit_caller(request, authorization, bucket="mock_exam_submit", limit=30, window=60)

    session_id = payload.get("session_id")
    answers = payload.get("answers") or {}
    if not session_id:
        raise HTTPException(status_code=400, detail="session_id required")
    # 🛡️ probe 防御 2026-05-26 (M2): session_id を integer cast (文字列 ID で 404 enumerate 防御)
    try:
        session_id = int(session_id)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="session_id 不正")

    conn = db()
    c = conn.cursor()
    c.execute("SELECT student_id, exam_type, score_max, questions_json, submitted_at FROM mock_exam_sessions WHERE id=?", (session_id,))
    row = c.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="session not found")
    student_id = row[0] if not hasattr(row, 'keys') else row["student_id"]
    exam_type = row[1] if not hasattr(row, 'keys') else row["exam_type"]
    score_max = row[2] if not hasattr(row, 'keys') else row["score_max"]
    snap_json = row[3] if not hasattr(row, 'keys') else row["questions_json"]
    already_submitted = (row[4] if not hasattr(row, 'keys') else row["submitted_at"]) is not None

    # 🛡️ IDOR check: 本人 only (ゲスト session = student_id NULL は誰でも更新可)
    if student_id is not None:
        is_admin = False
        auth_student_id: Optional[int] = None
        if authorization and authorization.startswith("Bearer "):
            token = authorization[len("Bearer "):].strip()
            if _verify_admin_token(token):
                is_admin = True
            else:
                claims = _verify_session_token(token)
                if claims and claims.get("student_id"):
                    try:
                        auth_student_id = int(claims["student_id"])
                    except (TypeError, ValueError):
                        auth_student_id = None
        if not is_admin and auth_student_id != int(student_id):
            conn.close()
            raise HTTPException(status_code=403, detail="他生徒の模試にはアクセスできません")

    # 🛡️ 二重採点防止 2026-05-26 (M1): submitted_at IS NOT NULL なら 409
    # ゲスト session でも二重採点で他人が上書きするのを防御
    if already_submitted:
        conn.close()
        raise HTTPException(status_code=409, detail="この模試は既に採点済みです")

    snap = json.loads(snap_json)
    answer_key = snap.get("answer_key", [])

    score_total = 0
    section_scores = {}
    weak_topics = []
    # 📝 2026-05-22 塾長指示: 各 sub-question を question_attempts に記録 (弱点プリント基盤)
    attempts_to_insert = []  # list of (subject, topic, is_correct, score_got, score_max, eq_id, sub_id, section_name)
    for ak in answer_key:
        sec_name = ak["section_name"]
        eq_id = ak["exam_question_id"]
        sec = section_scores.setdefault(sec_name, {"got": 0, "max": 0})
        # exam_questions から subject/topic を取得 (1 query per eq_id)
        # 🎯 [Defect A fix 2026-06-17] 弱点 topic を「大問単位」から「小問単位の単元」へ。
        #   旧: eq_topic = qd.topic or univ_simulated(校名) を全小問に付与 → 弱点が '共通テスト' や
        #   校名に潰れて単元別に立たず、findPresetForWeakness も解決できず卒業もしなかった。
        #   新: 小問ごとに _derive_question_unit (dojo と同一規約) で単元を引く。fallback も校名でなく
        #   qd.topic > section 名 とし、ゴミ単元 (校名) を作らない。
        eq_subject, eq_topic_fallback, sub_unit_map = None, None, {}
        try:
            c.execute("SELECT exam_id, part_key, question_data FROM exam_questions WHERE id=?", (eq_id,))
            eqrow = c.fetchone()
            if eqrow:
                eq_exam = eqrow[0] if not hasattr(eqrow, 'keys') else eqrow["exam_id"]
                eq_part = eqrow[1] if not hasattr(eqrow, 'keys') else eqrow["part_key"]
                eq_qdata = eqrow[2] if not hasattr(eqrow, 'keys') else eqrow["question_data"]
                # subject 推定: exam_id + part_key (例: rikei + math_q1 → 'math')
                eq_subject = _infer_subject_from_pool(eq_exam, eq_part)
                try:
                    qd = json.loads(eq_qdata) if isinstance(eq_qdata, str) else (eq_qdata or {})
                    eq_topic_fallback = qd.get("topic") or sec_name  # 校名(univ_simulated)は使わない
                    for q in (qd.get("questions") or []):
                        qidk = q.get("id")
                        if qidk is not None:
                            sub_unit_map[str(qidk)] = _derive_question_unit(q)
                except Exception:
                    eq_topic_fallback = sec_name
        except Exception:
            pass
        for sq in ak["sub_questions"]:
            sub_id = sq.get("id")
            correct = str(sq.get("answer", ""))
            points = int(sq.get("points") or 0)
            sec["max"] += points
            user_ans_key = f"{eq_id}_{sub_id}"
            user_ans = str(answers.get(user_ans_key, "")).strip()
            is_correct = 1 if (user_ans and user_ans == correct) else 0
            score_got = points if is_correct == 1 else 0
            if is_correct == 1:
                score_total += points
                sec["got"] += points
            elif points > 0:
                weak_topics.append({"section": sec_name, "exam_question_id": eq_id, "sub_id": sub_id})
            # ✅ 2026-05-22 P0 fix: section_name fallback は canonical key と不一致で worksheet 無視リスク
            # → eq_subject が無ければ "unknown" に統一 (集計時に "unknown" 行は無視される)
            # 🎯 [Defect A fix] 小問ごとの単元を topic に (無ければ大問 fallback)
            unit_topic = sub_unit_map.get(str(sub_id)) or eq_topic_fallback
            attempts_to_insert.append((
                eq_subject if eq_subject else "unknown",  # subject canonical fallback
                unit_topic,              # topic = 小問単位の単元 (Defect A fix)
                is_correct,
                score_got,
                points,
                eq_id,
                sub_id,
                sec_name,
            ))

    pct = round(100 * score_total / score_max, 1) if score_max > 0 else 0
    # 偏差値の簡易推定: 50 + (pct - 60) / 2 (60% = 50, 80% = 60, 40% = 40)
    deviation_estimate = round(50 + (pct - 60) / 2, 1)
    # 範囲制限
    deviation_estimate = max(30.0, min(80.0, deviation_estimate))

    section_scores_list = [{"name": k, "got": v["got"], "max": v["max"], "pct": round(100 * v["got"] / max(v["max"], 1), 1)} for k, v in section_scores.items()]

    c.execute(
        "UPDATE mock_exam_sessions SET submitted_at=?, score_total=?, deviation_estimate=?, section_scores=?, answers_json=? WHERE id=?",
        (datetime.now(timezone.utc).isoformat(), score_total, deviation_estimate, json.dumps(section_scores_list, ensure_ascii=False), json.dumps(answers, ensure_ascii=False), session_id),
    )
    # 📝 2026-05-22 塾長指示: 各 sub-question を question_attempts に記録 (弱点プリント基盤)
    # 🛡️ 2026-05-26 audit fix (C): ゲスト session (student_id IS NULL) は question_attempts.student_id
    # NOT NULL 違反で transaction abort し UPDATE mock_exam_sessions も巻き戻る regression を防止 → skip
    if student_id is not None:
        try:
            now_iso = datetime.now(timezone.utc).isoformat()
            for (a_subject, a_topic, a_is_correct, a_score_got, a_score_max, a_eq_id, a_sub_id, a_sec_name) in attempts_to_insert:
                meta = json.dumps({"section_name": a_sec_name, "sub_id": a_sub_id, "session_id": session_id}, ensure_ascii=False)
                c.execute(
                    "INSERT INTO question_attempts (student_id, source, exam_question_id, subject, topic, is_correct, score_got, score_max, metadata, created_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
                    (student_id, 'mock_exam', a_eq_id, a_subject, a_topic, a_is_correct, a_score_got, a_score_max, meta, now_iso),
                )
        except Exception as e:
            log.warning(f"[mock_exam_submit] question_attempts INSERT failed (non-fatal): {e}")
    conn.commit()
    conn.close()

    return {
        "session_id": session_id,
        "exam_type": exam_type,
        "score_total": score_total,
        "score_max": score_max,
        "percentage": pct,
        "deviation_estimate": deviation_estimate,
        "section_scores": section_scores_list,
        "weak_count": len(weak_topics),
    }


# ==========================================================================
# 🎓 大学別 過去問風オリジナル問題 (塾長指示 2026-05-03)
# 著作権: 全て Claude 生成のオリジナル問題。過去問の出題スタイル・トピックのみ参考、
# 実問題文の転載は禁止。inspired_by フィールドに「東大2022年第1問の長文読解スタイル」等
# のメタ情報を保存するが、これは事実情報 (どの大学のどの年度のどの形式の問題を模した
# かの説明) で、原問題のテキスト自体は含まない。
# ==========================================================================
# 🛡️ 2026-05-26 audit fix: 上の `@app.get("/api/mock-exam/history")` decorator は
# 旧 commit で残された orphan で、本来 university_problems_list には適用すべきでなかった。
# FastAPI の decorator chain で同一関数が 2 path に登録され、
# /api/mock-exam/history が university_problems_list を呼び出す bug 状態になっていた。
# 正規の mock_exam_history (auth gate 付き) は別途下で定義されているので orphan を削除。
@app.get("/api/university-problems")
def university_problems_list(university: Optional[str] = None, subject: Optional[str] = None,
                              year: Optional[int] = None, limit: int = 30, offset: int = 0):
    """大学別問題一覧。重い question_text 等は含めず、ID + メタのみ。
    🛡️ 2026-05-27: pdf_url を含めることで生徒画面で「📄 配布プリント版」ボタンを直接表示可能に。"""
    conn = db(); c = conn.cursor()
    sql = "SELECT id, university, faculty, year, subject, topic, problem_type, difficulty, inspired_by, tags, pdf_url, pdf_title, answer_pdf_url, answer_pdf_title, strict_pdf_url, strict_pdf_title, created_at FROM university_problems WHERE status='published'"
    params = []
    if university:
        sql += " AND university = ?"; params.append(university)
    if subject:
        sql += " AND subject = ?"; params.append(subject)
    if year:
        sql += " AND year = ?"; params.append(year)
    sql += " ORDER BY university, subject, year DESC, id DESC LIMIT ? OFFSET ?"
    params.extend([limit, offset])
    c.execute(sql, tuple(params))
    out = []
    for r in c.fetchall():
        d = dict(r) if hasattr(r, 'keys') else {}
        out.append(d)
    conn.close()
    return {"items": out, "count": len(out)}


@app.get("/api/university-problems/{pid}")
def university_problems_detail(pid: int):
    """1 問の詳細 (問題文・選択肢・解答・解説 全て返す)。
    🛡️ 2026-05-27: pdf_url / pdf_title を含めて返す (生徒画面で「📄 配布プリント版で開く」ボタン用)。
    🎯 2026-05-28: lesson_prints と JOIN して sub_question_topics (小問単位 単元 mapping) も返す
       (university-exam.html の解答入力 UI で間違えた小問の topic 抽出に使用)"""
    conn = db(); c = conn.cursor()
    c.execute("SELECT id, university, faculty, year, subject, topic, problem_type, question_text, choices, answer, explanation, difficulty, inspired_by, tags, pdf_url, pdf_title, answer_pdf_url, answer_pdf_title, strict_pdf_url, strict_pdf_title, created_at FROM university_problems WHERE id=? AND status='published'", (pid,))
    r = c.fetchone()
    if not r:
        conn.close()
        raise HTTPException(status_code=404, detail="not found")
    d = dict(r) if hasattr(r, 'keys') else {}
    if d.get("choices"):
        try: d["choices"] = json.loads(d["choices"])
        except: pass
    # 🎯 sub_question_topics を lesson_prints から取得 (pdf_url で JOIN)
    if d.get("pdf_url"):
        try:
            c.execute("SELECT sub_question_topics FROM lesson_prints WHERE file_path = ?", (d["pdf_url"],))
            lp_row = c.fetchone()
            if lp_row:
                sqt = lp_row["sub_question_topics"] if hasattr(lp_row, "keys") else lp_row[0]
                if sqt:
                    try:
                        d["sub_question_topics"] = json.loads(sqt)
                    except Exception:
                        d["sub_question_topics"] = None
        except Exception:
            pass  # lesson_prints 連携 fail でも problem 詳細は返す
    conn.close()
    return d


@app.get("/api/university-problems/meta/universities")
def university_problems_meta():
    """利用可能な (university, subject) の組合せと件数。生徒画面のフィルタ UI 用。"""
    conn = db(); c = conn.cursor()
    c.execute("SELECT university, subject, COUNT(*) AS cnt FROM university_problems WHERE status='published' GROUP BY university, subject ORDER BY university, subject")
    rows = []
    for r in c.fetchall():
        rows.append({
            "university": r["university"] if hasattr(r, 'keys') else r[0],
            "subject":    r["subject"]    if hasattr(r, 'keys') else r[1],
            "count":      r["cnt"]        if hasattr(r, 'keys') else r[2],
        })
    conn.close()
    return {"items": rows}


@app.post("/api/admin/university-problems/import")
def university_problems_import(payload: dict, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """大学別オリジナル問題の一括 import (admin)。
    payload: {"items": [{university, faculty, year, subject, topic, problem_type, question_text,
                          choices(list|None), answer, explanation, difficulty, inspired_by, tags}, ...]}"""
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token): authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    items = payload.get("items") or []
    if not isinstance(items, list) or not items:
        raise HTTPException(status_code=400, detail="items が空")

    inserted = 0; failed = 0; failed_details = []
    conn = db(); c = conn.cursor()
    try:
        for i, it in enumerate(items):
            try:
                if not it.get("university") or not it.get("subject") or not it.get("question_text") or not it.get("answer") or not it.get("explanation"):
                    failed += 1; failed_details.append({"i": i, "reason": "missing required"}); continue
                choices_raw = it.get("choices")
                choices_str = json.dumps(choices_raw, ensure_ascii=False) if isinstance(choices_raw, list) else (choices_raw or "")
                c.execute(
                    """INSERT INTO university_problems
                       (university, faculty, year, subject, topic, problem_type, question_text, choices,
                        answer, explanation, difficulty, inspired_by, tags, source)
                       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        it["university"], it.get("faculty",""), it.get("year"),
                        it["subject"], it.get("topic",""), it.get("problem_type","multiple_choice"),
                        it["question_text"], choices_str, it["answer"], it["explanation"],
                        it.get("difficulty","standard"), it.get("inspired_by",""),
                        it.get("tags",""), it.get("source","claude_max"),
                    )
                )
                inserted += 1
            except Exception as e:
                failed += 1; failed_details.append({"i": i, "reason": f"{type(e).__name__}: {str(e)[:80]}"})
                try: conn.rollback()
                except Exception: pass
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "inserted": inserted, "failed": failed, "failed_details": failed_details[:5]}


@app.post("/api/admin/university-problems/backfill-pdf-links")
def university_problems_backfill_pdf_links(
    payload: dict = None,
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🛡️ 塾長指示 2026-05-27 (案 A): university_problems の各 record に対応する PDF を
    lesson_prints から自動マッチングして pdf_url / pdf_title を埋める。

    マッチング規則 (優先順位):
    1. lesson_prints.target_university が university と一致 + lesson_prints.subject が subject と一致
    2. lesson_prints.title or filename に university + subject が含まれる (LIKE マッチ)

    payload (optional): {"dry_run": true, "university": "京大", "subject": "物理"} で部分実行可

    認証: admin Bearer or x-cron-secret"""
    import hmac as _hmac
    import re  # 🛡️ 2026-05-27 hotfix: 関数内で re.compile を使うため明示 import (top-level に re 無し)
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and _hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    payload = payload or {}
    dry_run = bool(payload.get("dry_run", False))
    filter_univ = payload.get("university")
    filter_subj = payload.get("subject")
    # 🛡️ 2026-05-27 「A: topic 必須化」 と組み合わせ: clear_first=True で全 pdf_url を NULL に戻してから紐付け直す
    # (旧 univ+subj だけマッチで誤紐付けされたデータを clean state にしてから topic 一致のみで再紐付け)
    clear_first = bool(payload.get("clear_first", False))

    # 大学名の正規化マップ (双方向): どちらの表記でも引けるよう、各 alias がキーになるよう構築
    # 🛡️ 3 視点 review fix 2026-05-27 (致命 1 / 準致命 A 対応):
    # - 「東大実践模試」を「東大」alias から除外 (本物の東大過去問が模試 PDF にハイジャックされる致命傷)
    # - 双方向 alias: 旧字体「慶應」と新字体「慶応」両方を引けるようにする
    # - MARCH / 関関同立 / その他大学を追加
    _ALIAS_GROUPS = [
        ["東大", "東京大学"],
        ["京大", "京都大学"],
        ["早稲田", "早稲田大学", "早稲田文化構想"],
        ["一橋", "一橋大学"],
        ["慶応", "慶應", "慶応大学", "慶應大学", "慶應義塾", "慶応義塾"],
        ["上智", "上智大学"],
        ["ICU", "国際基督教大学"],
        ["明治", "明治大学"],
        ["青山学院", "青山", "青学"],
        ["立教", "立教大学"],
        ["中央", "中央大学"],
        ["法政", "法政大学"],
        ["同志社", "同志社大学"],
        ["立命館", "立命館大学"],
        ["関西大", "関西大学", "関大"],
        ["関学", "関西学院", "関西学院大学"],
        ["横浜国立", "横浜国立大学", "横国"],
        ["千葉医", "千葉大学医", "千葉大学", "千葉大"],
        ["東工大", "東京工業大学", "東京工大"],
        ["神戸大", "神戸", "神戸大学"],
        ["東医歯", "東京医科歯科", "東京医科歯科大学"],
        ["お茶の水", "お茶の水女子大学", "お茶大"],
        ["MARCH", "march"],
        ["医学部", "医学部受験"],
    ]
    UNIV_ALIASES = {}
    for group in _ALIAS_GROUPS:
        for name in group:
            UNIV_ALIASES[name] = group

    conn = db()
    c = conn.cursor()
    try:
        # 🛡️ 2026-05-27 「A: topic 必須化」: clear_first=True なら旧紐付けを全 NULL に戻してから新マッチング
        cleared_count = 0
        if clear_first and not dry_run:
            # 🛡️ 2026-05-27 「本番試験版」列も追加 (margin notes 全削除版)
            c.execute("UPDATE university_problems SET pdf_url = NULL, pdf_title = NULL, answer_pdf_url = NULL, answer_pdf_title = NULL, strict_pdf_url = NULL, strict_pdf_title = NULL WHERE pdf_url IS NOT NULL OR answer_pdf_url IS NOT NULL OR strict_pdf_url IS NOT NULL")
            try:
                cleared_count = c.rowcount or 0
            except Exception:
                cleared_count = -1
            conn.commit()
        # 1. lesson_prints から PDF 一覧取得
        # 🛡️ 3 視点 review fix: target_type='模試' も除外 (東大実践模試 PDF が東大過去問に誤マッチする致命傷防止)
        # 🛡️ 2026-05-27 塾長指示「解答解説 PDF も + 本番試験版 PDF」: 3 種類を別々のリストで取得
        c.execute("SELECT id, title, subject, target_university, file_path, target_type FROM lesson_prints WHERE is_published = 1 AND COALESCE(target_type, '') NOT IN ('解答解説', '本番試験版', '模試', '模擬試験')")
        lp_rows = c.fetchall()
        # 解答解説 PDF 一覧 (target_type='解答解説' or タイトルに「解答解説」を含む)
        c.execute("SELECT id, title, subject, target_university, file_path, target_type FROM lesson_prints WHERE is_published = 1 AND (COALESCE(target_type, '') = '解答解説' OR title LIKE '%解答解説%' OR file_path LIKE '%_answers.pdf%')")
        lp_ans_rows = c.fetchall()
        # 本番試験版 PDF 一覧 (target_type='本番試験版' or タイトルに「本番試験版」を含む or _strict.pdf)
        c.execute("SELECT id, title, subject, target_university, file_path, target_type FROM lesson_prints WHERE is_published = 1 AND (COALESCE(target_type, '') = '本番試験版' OR title LIKE '%本番試験版%' OR file_path LIKE '%_strict.pdf%')")
        lp_strict_rows = c.fetchall()
        pdfs = []
        for row in lp_rows:
            if isinstance(row, dict):
                pdfs.append({
                    "id": row.get("id"),
                    "title": row.get("title") or "",
                    "subject": row.get("subject") or "",
                    "target_university": row.get("target_university") or "",
                    "file_path": row.get("file_path") or "",
                    "target_type": row.get("target_type") or "",
                })
            else:
                pdfs.append({"id": row[0], "title": row[1] or "", "subject": row[2] or "",
                             "target_university": row[3] or "", "file_path": row[4] or "",
                             "target_type": (row[5] if len(row) > 5 else "") or ""})
        # 解答解説 PDF リスト
        ans_pdfs = []
        for row in lp_ans_rows:
            if isinstance(row, dict):
                ans_pdfs.append({
                    "id": row.get("id"),
                    "title": row.get("title") or "",
                    "subject": row.get("subject") or "",
                    "target_university": row.get("target_university") or "",
                    "file_path": row.get("file_path") or "",
                })
            else:
                ans_pdfs.append({"id": row[0], "title": row[1] or "", "subject": row[2] or "",
                                 "target_university": row[3] or "", "file_path": row[4] or ""})
        # 本番試験版 PDF リスト (margin notes 全削除版)
        strict_pdfs = []
        for row in lp_strict_rows:
            if isinstance(row, dict):
                strict_pdfs.append({
                    "id": row.get("id"),
                    "title": row.get("title") or "",
                    "subject": row.get("subject") or "",
                    "target_university": row.get("target_university") or "",
                    "file_path": row.get("file_path") or "",
                })
            else:
                strict_pdfs.append({"id": row[0], "title": row[1] or "", "subject": row[2] or "",
                                    "target_university": row[3] or "", "file_path": row[4] or ""})

        # 2. university_problems を SELECT (filter 適用)
        sql = "SELECT id, university, subject, topic FROM university_problems WHERE status='published'"
        params = []
        if filter_univ:
            sql += " AND university = ?"; params.append(filter_univ)
        if filter_subj:
            sql += " AND subject = ?"; params.append(filter_subj)
        c.execute(sql, tuple(params))
        up_rows = c.fetchall()

        matched = 0
        updated = 0
        no_match = []
        match_log = []

        # 🛡️ ヘルパー関数を loop 外で 1 回定義 (パフォーマンス + scope 明確化)
        _all_univ_aliases_sorted = sorted({a for grp in _ALIAS_GROUPS for a in grp}, key=len, reverse=True)
        def _strip_univ_prefix(kw):
            for alias in _all_univ_aliases_sorted:
                if kw.startswith(alias) and len(kw) > len(alias):
                    return kw[len(alias):]
            return kw

        _STOP_WORDS = {
            "基礎", "標準", "発展", "応用", "演習", "問題", "対策", "練習", "解説",
            "自習", "プリント", "本番", "模試", "模擬", "テキスト", "過去問", "過去問風", "風", "形式",
            "自習プリント", "英語自習プリント", "本番水準", "授業テキスト",
            "大学", "大学院", "学部", "予備校", "入試", "受験",
            "数学", "物理", "化学", "生物", "国語", "英語",
            "日本史", "世界史", "地理", "公民", "倫理", "政治経済",
            "について", "ため", "ものを", "ことを",
        }
        _PARTICLE_RE = re.compile(r"(の|と|を|に|へ|で|から|まで|や|か|が|は|も|だ|に対して)")
        # 🛡️ 2026-05-27 fix: _ + - も separator として扱う (ファイル名連結記法対応)
        # 例: "東大生物_遺伝子発現-代謝-生態系" → ["東大生物","遺伝子発現","代謝","生態系"]
        # ハイフン (-) は Vercel が `+` を space と解釈する bug 回避で `+` の代替として使用
        _SEPARATOR_RE = re.compile(r"[・/、,。\s()()「」『』【】「」_+\-]+")

        def _extract_topic_kws(topic_str):
            if not topic_str:
                return []
            s = topic_str.replace("スタイル", "").replace("型", "").strip()
            s = _PARTICLE_RE.sub(" ", s)
            parts = _SEPARATOR_RE.split(s)
            stripped = [_strip_univ_prefix(p) for p in parts]
            return [p for p in stripped if len(p) >= 2 and p not in _STOP_WORDS]

        for row in up_rows:
            if isinstance(row, dict):
                up_id = row.get("id")
                up_univ = (row.get("university") or "").strip()
                up_subj = (row.get("subject") or "").strip()
                up_topic = (row.get("topic") or "").strip()
            else:
                up_id = row[0]
                up_univ = (row[1] or "").strip()
                up_subj = (row[2] or "").strip()
                # 🛡️ row[3] safe access (簡略化 + None ガード)
                up_topic = ""
                if len(row) > 3 and row[3]:
                    up_topic = str(row[3]).strip()

            if not up_univ or not up_subj:
                continue

            # 大学名のエイリアス取得 (双方向 alias 化済 → どの表記でも引ける)
            aliases = UNIV_ALIASES.get(up_univ, [up_univ])
            # subject 表記揺れ対策 (例: "国語(現代文)" "国語(現代文)" → "国語")。半角/全角両対応。
            subj_normalized = up_subj.split("(")[0].split("(")[0].strip()

            # 🛡️ 2026-05-27 塾長指示「A: トピック一致必須」(整合性致命傷修正):
            # 旧 bug: univ+subject 厳密一致だけでは「東大数学」配下の全問題が
            #   「東大ベクトル PDF」一つに紐付き、放物線問題にベクトル PDF が出る致命傷。
            # 新規則: topic キーワードが PDF タイトル/path に含まれることを必須化。
            # topic なし問題は紐付けない (整合性優先・誤マッチ防止)。

            topic_kws = _extract_topic_kws(up_topic)

            def _topic_match(pdf):
                """🛡️ 双方向 substring match:
                ① topic kw が PDF タイトル/path に含まれる (例: 「放物線」が「東大放物線 自習プリント」に含まれる)
                ② PDF タイトルから抽出した kw が up_topic に含まれる (逆方向)
                topic なしの場合は False (紐付けない・整合性優先)"""
                if not topic_kws:
                    return False
                hay = (pdf.get("title", "") + " " + pdf.get("file_path", ""))
                # 方向 ①: topic_kw が hay に含まれる
                if any(kw in hay for kw in topic_kws):
                    return True
                # 方向 ②: PDF タイトル kw が up_topic 文字列に含まれる
                pdf_kws = _extract_topic_kws(pdf.get("title", ""))
                if pdf_kws and any(kw in up_topic for kw in pdf_kws):
                    return True
                return False

            # 🛡️ 2026-05-31 塾長指示「英文法と英検」: 問題 ID ベース 1:1 直接リンク (最優先)
            # 1 問 = 1 PDF のファイル名には `_id{up_id}_` が含まれる (例: ..._id826_問題.pdf)。
            # topic が非ユニークな問題群 (英文法 210 問が全て topic「正誤問題」等) でも、
            # ファイル名の id token で確実に 1:1 紐付けできる。trailing `_` で部分一致を防止
            # (`_id82_` は `_id826_` にマッチしない)。
            _id_token = f"_id{up_id}_"
            best_pdf = next((p for p in pdfs if _id_token in (p.get("file_path") or "")), None)
            best_ans_pdf = next((p for p in ans_pdfs if _id_token in (p.get("file_path") or "")), None)
            best_strict_pdf = next((p for p in strict_pdfs if _id_token in (p.get("file_path") or "")), None)

            # ── id-match しなかった種別のみ従来 topic-based fallback ──
            # Pass 1: target_university 一致 + subject 厳密一致 + topic 一致
            if best_pdf is None:
                for pdf in pdfs:
                    lp_univ = pdf["target_university"]
                    lp_subj = pdf["subject"]
                    if lp_univ in aliases and lp_subj == subj_normalized and _topic_match(pdf):
                        best_pdf = pdf
                        break
            # Pass 2: title に大学 alias 含有 + subject 厳密一致 + topic 一致
            if best_pdf is None:
                for pdf in pdfs:
                    lp_title = pdf["title"]
                    lp_subj = pdf["subject"]
                    if lp_title and any(a in lp_title for a in aliases) and lp_subj == subj_normalized and _topic_match(pdf):
                        best_pdf = pdf
                        break

            # 🛡️ 2026-05-27 塾長指示「解答解説 PDF も」+「A: topic 一致必須」
            if best_ans_pdf is None:
                for pdf in ans_pdfs:
                    lp_univ = pdf["target_university"]
                    lp_subj = pdf["subject"]
                    if lp_univ in aliases and lp_subj == subj_normalized and _topic_match(pdf):
                        best_ans_pdf = pdf
                        break
            if best_ans_pdf is None:
                for pdf in ans_pdfs:
                    lp_title = pdf["title"]
                    lp_subj = pdf["subject"]
                    if lp_title and any(a in lp_title for a in aliases) and lp_subj == subj_normalized and _topic_match(pdf):
                        best_ans_pdf = pdf
                        break

            # 🛡️ 2026-05-27 塾長指示「途中のヒント無しの問題だけのパターン」: 本番試験版 PDF も同様に紐付け
            if best_strict_pdf is None:
                for pdf in strict_pdfs:
                    lp_univ = pdf["target_university"]
                    lp_subj = pdf["subject"]
                    if lp_univ in aliases and lp_subj == subj_normalized and _topic_match(pdf):
                        best_strict_pdf = pdf
                        break
            if best_strict_pdf is None:
                for pdf in strict_pdfs:
                    lp_title = pdf["title"]
                    lp_subj = pdf["subject"]
                    if lp_title and any(a in lp_title for a in aliases) and lp_subj == subj_normalized and _topic_match(pdf):
                        best_strict_pdf = pdf
                        break

            if best_pdf:
                matched += 1
                match_log.append({
                    "up_id": up_id, "up_univ": up_univ, "up_subj": up_subj,
                    "pdf_title": best_pdf["title"], "pdf_path": best_pdf["file_path"],
                    "answer_pdf_title": (best_ans_pdf["title"] if best_ans_pdf else None),
                    "answer_pdf_path": (best_ans_pdf["file_path"] if best_ans_pdf else None),
                    "strict_pdf_title": (best_strict_pdf["title"] if best_strict_pdf else None),
                    "strict_pdf_path": (best_strict_pdf["file_path"] if best_strict_pdf else None),
                })
                if not dry_run:
                    c.execute(
                        "UPDATE university_problems SET pdf_url = ?, pdf_title = ?, answer_pdf_url = ?, answer_pdf_title = ?, strict_pdf_url = ?, strict_pdf_title = ? WHERE id = ?",
                        (best_pdf["file_path"], best_pdf["title"],
                         (best_ans_pdf["file_path"] if best_ans_pdf else None),
                         (best_ans_pdf["title"] if best_ans_pdf else None),
                         (best_strict_pdf["file_path"] if best_strict_pdf else None),
                         (best_strict_pdf["title"] if best_strict_pdf else None),
                         up_id)
                    )
                    updated += 1
            elif best_ans_pdf or best_strict_pdf:
                # 本編なし・解答解説/本番試験版のみ存在 (稀)
                matched += 1
                match_log.append({
                    "up_id": up_id, "up_univ": up_univ, "up_subj": up_subj,
                    "pdf_title": None, "pdf_path": None,
                    "answer_pdf_title": (best_ans_pdf["title"] if best_ans_pdf else None),
                    "answer_pdf_path": (best_ans_pdf["file_path"] if best_ans_pdf else None),
                    "strict_pdf_title": (best_strict_pdf["title"] if best_strict_pdf else None),
                    "strict_pdf_path": (best_strict_pdf["file_path"] if best_strict_pdf else None),
                })
                if not dry_run:
                    c.execute(
                        "UPDATE university_problems SET answer_pdf_url = ?, answer_pdf_title = ?, strict_pdf_url = ?, strict_pdf_title = ? WHERE id = ?",
                        ((best_ans_pdf["file_path"] if best_ans_pdf else None),
                         (best_ans_pdf["title"] if best_ans_pdf else None),
                         (best_strict_pdf["file_path"] if best_strict_pdf else None),
                         (best_strict_pdf["title"] if best_strict_pdf else None),
                         up_id)
                    )
                    updated += 1
            else:
                no_match.append({"up_id": up_id, "up_univ": up_univ, "up_subj": up_subj})

        if not dry_run:
            conn.commit()
    finally:
        conn.close()

    # 🛡️ 3 視点 review fix (準致命 C): 複数 up が同一 PDF にマッピングされたケースを検出
    pdf_to_ups = {}
    for entry in match_log:
        pdf_path = entry.get("pdf_path", "")
        if pdf_path:
            pdf_to_ups.setdefault(pdf_path, []).append(entry["up_id"])
    duplicates = {k: v for k, v in pdf_to_ups.items() if len(v) > 1}
    return {
        "ok": True,
        "dry_run": dry_run,
        "clear_first": clear_first,
        "cleared_count": cleared_count if clear_first else 0,
        "matched": matched,
        "updated": updated,
        "no_match_count": len(no_match),
        "no_match_sample": no_match[:30],
        "match_log_sample": match_log[:50],
        "duplicate_pdf_assignments": len(duplicates),
        "duplicate_sample": dict(list(duplicates.items())[:5]),
    }


@app.get("/api/mock-exam/history")
def mock_exam_history(request: Request, student_id: int, authorization: Optional[str] = Header(None)):
    """生徒の模試履歴 (mypage 用)。

    🛡️ IDOR fix 2026-05-26 (3視点 audit 発見・student_weakness_top3 と同パターン):
    - 旧実装: 無認証 + student_id query のみで他生徒の履歴が enumerate 可能だった
    - 修正: admin Bearer or 本人 session token のみ。per-IP rate limit 付き。
    """
    # 🛡️ rate limit (IDOR enumerate 防御・校内 NAT 対応で生徒単位 audit M5 fix)
    _check_rate_limit_caller(request, authorization, bucket="mock_exam_history", limit=30, window=60)

    # 認証: admin or 本人 session token のみ
    is_admin = False
    auth_student_id: Optional[int] = None
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            is_admin = True
        else:
            claims = _verify_session_token(token)
            if claims and claims.get("student_id"):
                try:
                    auth_student_id = int(claims["student_id"])
                except (TypeError, ValueError):
                    auth_student_id = None
    try:
        student_id = int(student_id)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="student_id 不正")
    if student_id <= 0:
        raise HTTPException(status_code=400, detail="student_id 必須")

    # 🛡️ IDOR fix: 本人 only (admin Bearer は例外)
    if not is_admin:
        if not auth_student_id:
            raise HTTPException(status_code=403, detail="ログインが必要です (session token 未提供)")
        if auth_student_id != student_id:
            raise HTTPException(status_code=403, detail="他生徒のデータにはアクセスできません")

    conn = db()
    c = conn.cursor()
    c.execute("SELECT id, exam_type, target_label, score_total, score_max, deviation_estimate, submitted_at FROM mock_exam_sessions WHERE student_id=? AND submitted_at IS NOT NULL ORDER BY submitted_at DESC LIMIT 30", (student_id,))
    rows = c.fetchall()
    conn.close()
    out = []
    for r in rows:
        d = dict(r) if hasattr(r, 'keys') else {"id": r[0], "exam_type": r[1], "target_label": r[2], "score_total": r[3], "score_max": r[4], "deviation_estimate": r[5], "submitted_at": r[6]}
        out.append(d)
    return {"history": out}


# ==========================================================================
# 📚 AI 単語帳 (Spaced Repetition) — Leitner Box system (2026-05-03)
# ==========================================================================

LEITNER_INTERVALS = {1: 1, 2: 3, 3: 7, 4: 21, 5: 60}  # box → days until next review


@app.post("/api/admin/vocab/import")
def vocab_import(payload: dict, authorization: Optional[str] = Header(None), x_cron_secret: Optional[str] = Header(None)):
    """単語データの一括 import (admin)。
    payload: {"words": [{"word":"...", "pos":"...", "meaning_jp":"...", "example_en":"...", "example_jp":"...", "level":"...", "tags":"..."}, ...]}
    """
    authed = False
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail="未認証")

    words = payload.get("words") or []
    if not isinstance(words, list) or not words:
        raise HTTPException(status_code=400, detail="words が空")

    inserted = 0
    skipped = 0
    failed = []
    conn = db()
    c = conn.cursor()
    try:
        for i, w in enumerate(words):
            try:
                if not w.get("word") or not w.get("meaning_jp") or not w.get("level"):
                    failed.append({"i": i, "reason": "missing required fields"})
                    continue
                # 事前 SELECT で重複チェック (rowcount が _Cursor wrapper で参照不可のため)
                c.execute("SELECT id FROM vocab_words WHERE word=?", (w["word"],))
                existing = c.fetchone()
                if existing:
                    skipped += 1
                    continue
                c.execute("INSERT INTO vocab_words (word, pos, meaning_jp, example_en, example_jp, level, tags) VALUES (?,?,?,?,?,?,?)",
                          (w["word"], w.get("pos", ""), w["meaning_jp"], w.get("example_en", ""), w.get("example_jp", ""), w["level"], w.get("tags", "")))
                inserted += 1
            except Exception as e:
                failed.append({"i": i, "reason": f"{type(e).__name__}: {str(e)[:80]}"})
                try: conn.rollback()
                except Exception: pass
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "inserted": inserted, "skipped": skipped, "failed": len(failed), "failed_details": failed[:10]}


@app.get("/api/vocab/queue")
def vocab_queue(student_id: Optional[int] = None, level: Optional[str] = None, limit: int = 20, authorization: Optional[str] = Header(None)):
    """次に復習すべき単語キューを返す。student_id は token から解決 (IDOR fix)。
    優先順位: 1) 今復習期限の単語 2) まだ未学習の単語

    limit clamp: max=100 / min=1。 quiz endpoint と統一 (2026-05-03)。
    """
    # 🔑 [trust-identity] vocab IDOR fix の取りこぼし (queue だけ未対策だった) を塞ぐ
    student_id = _vocab_resolve_student_id(student_id, authorization)
    # limit clamp (silent fallback 防止)
    orig_limit = limit
    if limit is None or limit < 1:
        limit = 10
    if limit > 100:
        limit = 100
    conn = db()
    c = conn.cursor()
    out = []
    # 1) 期限到来の progress
    now = datetime.now(timezone.utc).isoformat()
    sql_due = """
        SELECT vw.id, vw.word, vw.pos, vw.meaning_jp, vw.example_en, vw.example_jp, vw.level, vw.tags, vp.box
        FROM vocab_progress vp
        JOIN vocab_words vw ON vw.id = vp.word_id
        WHERE vp.student_id = ? AND vp.next_review_at <= ?
    """
    params = [student_id, now]
    if level:
        sql_due += " AND vw.level = ?"
        params.append(level)
    sql_due += " ORDER BY vp.next_review_at ASC LIMIT ?"
    params.append(limit)
    c.execute(sql_due, tuple(params))
    for r in c.fetchall():
        d = dict(r) if hasattr(r, 'keys') else {"id": r[0], "word": r[1], "pos": r[2], "meaning_jp": r[3], "example_en": r[4], "example_jp": r[5], "level": r[6], "tags": r[7], "box": r[8]}
        d["status"] = "review"
        out.append(d)

    # 2) 残り枠で未学習
    remaining = limit - len(out)
    if remaining > 0:
        sql_new = """
            SELECT id, word, pos, meaning_jp, example_en, example_jp, level, tags
            FROM vocab_words
            WHERE id NOT IN (SELECT word_id FROM vocab_progress WHERE student_id = ?)
        """
        params2 = [student_id]
        if level:
            sql_new += " AND level = ?"
            params2.append(level)
        sql_new += " ORDER BY id LIMIT ?"
        params2.append(remaining)
        c.execute(sql_new, tuple(params2))
        for r in c.fetchall():
            d = dict(r) if hasattr(r, 'keys') else {"id": r[0], "word": r[1], "pos": r[2], "meaning_jp": r[3], "example_en": r[4], "example_jp": r[5], "level": r[6], "tags": r[7]}
            d["box"] = 0
            d["status"] = "new"
            out.append(d)
    conn.close()
    return {"queue": out, "count": len(out), "requested_limit": orig_limit, "applied_limit": limit}


def _vocab_resolve_student_id(client_sid, authorization: Optional[str]):
    """🔑 2026-06-14 [trust-identity / IDOR fix] vocab endpoint 共通の生徒解決。
    生徒トークン → 本人 id に固定 (client が送る student_id は完全に無視し、他生徒の
    単語統計取得・採点書込みを構造的に不可能にする)。admin トークン → client 値を許可
    (ceo の生徒なりすまし/閲覧用)。トークン無し/無効 → 401。
    従来 vocab は token 検証ゼロ・client の student_id を直接信用しており、未ログインや
    別 id 指定で他生徒の vocab を閲覧・汚染できた (mock-exam は IDOR fix 済だった差)。"""
    if authorization and authorization.startswith("Bearer "):
        tok = authorization[len("Bearer "):].strip()
        claims = _verify_session_token(tok)
        if claims and claims.get("student_id"):
            return int(claims["student_id"])
        if _verify_admin_token(tok):
            if client_sid is None:
                raise HTTPException(status_code=400, detail="student_id required")
            return int(client_sid)
    raise HTTPException(status_code=401, detail="ログインが必要です")


@app.post("/api/vocab/grade")
def vocab_grade(payload: dict, authorization: Optional[str] = Header(None)):
    """単語の自己評価を記録。Leitner box 方式で次回復習日を更新。
    payload: {"word_id": M, "knew": true/false} — student_id は token から解決 (IDOR fix)。
    """
    student_id = _vocab_resolve_student_id(payload.get("student_id"), authorization)
    word_id = payload.get("word_id")
    knew = bool(payload.get("knew"))
    if not student_id or not word_id:
        raise HTTPException(status_code=400, detail="student_id / word_id required")

    conn = db()
    c = conn.cursor()
    c.execute("SELECT id, box, review_count, correct_count FROM vocab_progress WHERE student_id=? AND word_id=?", (student_id, word_id))
    row = c.fetchone()
    now = datetime.now(timezone.utc)
    if row:
        # 既存: box を更新
        prog_id = row[0] if not hasattr(row, 'keys') else row["id"]
        cur_box = int(row[1] if not hasattr(row, 'keys') else row["box"])
        review_count = int(row[2] if not hasattr(row, 'keys') else row["review_count"])
        correct_count = int(row[3] if not hasattr(row, 'keys') else row["correct_count"])
        new_box = min(5, cur_box + 1) if knew else 1
        days = LEITNER_INTERVALS.get(new_box, 1)
        next_at = (now + timedelta(days=days)).isoformat()
        c.execute("UPDATE vocab_progress SET box=?, next_review_at=?, last_reviewed_at=?, review_count=?, correct_count=? WHERE id=?",
                  (new_box, next_at, now.isoformat(), review_count + 1, correct_count + (1 if knew else 0), prog_id))
    else:
        # 新規
        new_box = 2 if knew else 1
        days = LEITNER_INTERVALS.get(new_box, 1)
        next_at = (now + timedelta(days=days)).isoformat()
        c.execute("INSERT INTO vocab_progress (student_id, word_id, box, next_review_at, last_reviewed_at, review_count, correct_count) VALUES (?,?,?,?,?,?,?)",
                  (student_id, word_id, new_box, next_at, now.isoformat(), 1, 1 if knew else 0))
    conn.commit()
    conn.close()
    return {"ok": True, "new_box": new_box, "next_review_in_days": LEITNER_INTERVALS.get(new_box, 1)}


@app.get("/api/vocab/stats")
def vocab_stats(student_id: Optional[int] = None, authorization: Optional[str] = Header(None)):
    """生徒の単語学習統計 (mypage 用)。student_id は token から解決 (IDOR fix)。"""
    student_id = _vocab_resolve_student_id(student_id, authorization)
    def _val(row, idx, key):
        # sqlite3.Row / psycopg _Row どちらも row[key] (列名アクセス) をサポートする。
        # 旧コードは row.get(key) を使い sqlite3.Row に .get が無く SQLite で crash していた
        # (本番 Postgres のみ動作・ローカル不可だった) ため row[key] へ統一。
        if row is None: return 0
        try:
            return row[key] or 0
        except (KeyError, IndexError, TypeError):
            try:
                return (row[idx] if idx < len(row) else 0) or 0
            except Exception:
                return 0

    conn = db()
    c = conn.cursor()
    by_box = {}
    try:
        c.execute("SELECT box AS box_n, COUNT(*) AS cnt FROM vocab_progress WHERE student_id=? GROUP BY box", (student_id,))
        for r in c.fetchall():
            b = _val(r, 0, 'box_n')
            n = _val(r, 1, 'cnt')
            by_box[int(b)] = int(n)
    except Exception:
        by_box = {}

    c.execute("SELECT COUNT(*) AS cnt FROM vocab_progress WHERE student_id=? AND next_review_at <= ?", (student_id, datetime.now(timezone.utc).isoformat()))
    due_now = int(_val(c.fetchone(), 0, 'cnt'))

    c.execute("SELECT COUNT(*) AS cnt FROM vocab_words")
    total_words = int(_val(c.fetchone(), 0, 'cnt'))

    c.execute("SELECT COALESCE(SUM(review_count), 0) AS rsum, COALESCE(SUM(correct_count), 0) AS csum FROM vocab_progress WHERE student_id=?", (student_id,))
    rr = c.fetchone()
    total_reviews = int(_val(rr, 0, 'rsum'))
    total_correct = int(_val(rr, 1, 'csum'))

    # 🔴 間違えた単語数: 一度でも間違えた単語 (review_count > correct_count) を母数とする
    # 塾長指示 2026-05-25: 生徒からの要望「間違えた単語を別タグに保存」
    try:
        c.execute("SELECT COUNT(*) AS cnt FROM vocab_progress WHERE student_id=? AND review_count > correct_count", (student_id,))
        mistakes_count = int(_val(c.fetchone(), 0, 'cnt'))
    except Exception:
        mistakes_count = 0
    conn.close()
    accuracy = round(100 * total_correct / max(total_reviews, 1), 1)
    return {
        "total_words_in_pool": total_words,
        "by_box": by_box,
        "mastered": by_box.get(5, 0),
        "due_now": due_now,
        "total_reviews": total_reviews,
        "accuracy_percent": accuracy,
        "mistakes_count": mistakes_count,
    }


# ==========================================================================
# 📖 単語: 4 択クイズ + 自動詞/他動詞・品詞ラベル (塾長指示 2026-05-03)
# ==========================================================================
_POS_LABEL_JP = {
    "verb": "動詞", "v": "動詞",
    "noun": "名詞", "n": "名詞",
    "adjective": "形容詞", "adj": "形容詞", "a": "形容詞",
    "adverb": "副詞", "adv": "副詞",
    "preposition": "前置詞", "prep": "前置詞",
    "conjunction": "接続詞", "conj": "接続詞",
    "pronoun": "代名詞", "pron": "代名詞",
    "interjection": "間投詞", "intj": "間投詞",
    "determiner": "限定詞", "det": "限定詞",
    "phrase": "熟語",
}


def _pos_label_jp(pos: str) -> str:
    if not pos: return ""
    return _POS_LABEL_JP.get(pos.strip().lower(), pos)


def _detect_transitivity(pos: str, meaning_jp: str, tags: str = "") -> str:
    """自動詞 (vi) / 他動詞 (vt) / vt+vi を判定。
    1) tags に明示があれば最優先 (Netlify import の動・他/動・自/動・自他 由来)
    2) 無ければ meaning_jp の「〜を」パターンから推定
    動詞以外は空文字。"""
    if not pos: return ""
    pl = pos.strip().lower()
    if "verb" not in pl and pl not in ("v",):
        return ""
    # tags 由来 (import データに付与) を優先
    if tags:
        t_set = {t.strip() for t in tags.split(",")}
        if "vt+vi" in t_set: return "vt+vi"
        if "vt" in t_set: return "vt"
        if "vi" in t_set: return "vi"
    # フォールバック: meaning_jp の 〜を/〜に パターン
    m = (meaning_jp or "").replace("～", "〜")
    has_wo = "〜を" in m or "~を" in m
    has_other = any(p in m for p in ("〜に", "~に", "〜と", "~と", "〜が", "~が"))
    if has_wo and has_other:
        return "vt+vi"
    if has_wo:
        return "vt"
    return "vi"


def _transitivity_label_jp(t: str) -> str:
    return {"vt": "他動詞", "vi": "自動詞", "vt+vi": "自他両用"}.get(t, "")


# 同等レベル横断マップ (塾長指示 2026-05-03): 同じ英単語は1レベルにしか入れられないため、
# クイズ抽出時に関連レベルからも引く。例: 英検2級は intermediate / kyotsu からも引く
_LEVEL_RELATED = {
    'eiken_g5':       ['chu1'],
    'eiken_g4':       ['chu1', 'chu2'],
    'eiken_g3':       ['chu3', 'basic'],
    'eiken_gp2':      ['basic', 'intermediate'],
    'eiken_g2':       ['intermediate', 'kyotsu'],
    'eiken_gp1':      ['advanced', 'march'],
    'eiken_g1':       ['soukeijou', 'todai_kyodai'],
    'kyotsu':         ['intermediate'],
    'chihokkokuritsu':['kyotsu', 'intermediate'],
    'march':          ['advanced'],
    'soukeijou':      ['advanced', 'march'],
    'todai_kyodai':   ['soukeijou', 'advanced'],
}


def _expand_levels(level: Optional[str]) -> list:
    """指定 level + 関連 level を返す。level なしなら []."""
    if not level:
        return []
    out = [level]
    out.extend(_LEVEL_RELATED.get(level, []))
    return out


@app.get("/api/vocab/mistaken-words")
def vocab_mistaken_words(student_id: Optional[int] = None, level: Optional[str] = None, univ: Optional[str] = None, limit: int = 100, authorization: Optional[str] = Header(None)):
    """🔴 間違えた単語一覧 (一度でも誤答した全単語)。student_id は token から解決 (IDOR fix)。
    塾長指示 2026-05-25 (生徒要望): 間違えた単語を別タグに保存して復習可能に。
    定義: review_count > correct_count → 過去に1回以上誤答ありの単語。
    並び順: 誤答回数多い順 → 直近誤答順 (mistake_count DESC, last_reviewed_at DESC)。
    """
    student_id = _vocab_resolve_student_id(student_id, authorization)
    # limit clamp
    if limit is None or limit < 1:
        limit = 100
    if limit > 500:
        limit = 500
    conn = db()
    c = conn.cursor()
    levels = _expand_levels(level)
    placeholders = ",".join(["?"] * len(levels)) if levels else ""
    sql = """
        SELECT vw.id, vw.word, vw.pos, vw.meaning_jp, vw.example_en, vw.example_jp, vw.level, vw.tags,
               vp.box, vp.review_count, vp.correct_count, vp.last_reviewed_at, vp.next_review_at
        FROM vocab_progress vp
        JOIN vocab_words vw ON vw.id = vp.word_id
        WHERE vp.student_id = ? AND vp.review_count > vp.correct_count
    """
    params = [student_id]
    if levels:
        sql += f" AND vw.level IN ({placeholders})"
        params.extend(levels)
    sql += " ORDER BY (vp.review_count - vp.correct_count) DESC, vp.last_reviewed_at DESC LIMIT ?"
    # univ filter は post-fetch なので余裕を持って取得
    fetch_limit = limit * 3 if univ else limit
    params.append(fetch_limit)
    c.execute(sql, tuple(params))
    items = []
    for r in c.fetchall():
        d = dict(r) if hasattr(r, 'keys') else {
            "id": r[0], "word": r[1], "pos": r[2], "meaning_jp": r[3],
            "example_en": r[4], "example_jp": r[5], "level": r[6], "tags": r[7],
            "box": r[8], "review_count": r[9], "correct_count": r[10],
            "last_reviewed_at": r[11], "next_review_at": r[12],
        }
        tags_s = d.get("tags") or ""
        if univ and f"univ:{univ}" not in tags_s:
            continue
        wpos = (d.get("pos") or "").strip()
        review_count = int(d.get("review_count") or 0)
        correct_count = int(d.get("correct_count") or 0)
        mistake_count = max(0, review_count - correct_count)
        accuracy_per_word = round(100 * correct_count / max(review_count, 1), 1)
        transitivity = _detect_transitivity(wpos, d.get("meaning_jp") or "", tags_s)
        items.append({
            "id": d["id"],
            "word": d["word"],
            "pos": wpos,
            "pos_label_jp": _pos_label_jp(wpos),
            "transitivity": transitivity,
            "transitivity_label_jp": _transitivity_label_jp(transitivity),
            "meaning_jp": d["meaning_jp"],
            "example_en": d.get("example_en") or "",
            "example_jp": d.get("example_jp") or "",
            "level": d["level"],
            "tags": tags_s,
            "box": int(d.get("box") or 0),
            "review_count": review_count,
            "correct_count": correct_count,
            "mistake_count": mistake_count,
            "accuracy_percent": accuracy_per_word,
            "last_reviewed_at": d.get("last_reviewed_at"),
            "next_review_at": d.get("next_review_at"),
        })
        if len(items) >= limit:
            break
    conn.close()
    return {"items": items, "count": len(items), "limit": limit}


@app.get("/api/vocab/quiz")
def vocab_quiz(student_id: Optional[int] = None, level: Optional[str] = None, limit: int = 10, univ: Optional[str] = None, mistakes_only: int = 0, authorization: Optional[str] = Header(None)):
    """4 択形式の単語クイズキュー。各 item は target word + 同 pos の distractor 3 個 + 品詞 + 自他動詞ラベル。
    塾長指示 (2026-05-03): 4 択は同品詞で固める / 自他動詞 + 品詞を表示。
    フロントが distractors を shuffle して出題する想定 (server は shuffle 済み choices も返す)。
    レベル指定時は _LEVEL_RELATED の関連レベルからも引いて実プールを拡張する。

    limit clamp: max=100 / min=1。 過大値 (99999 等) は内部で limit*3 を distractor SQL に渡して
    silent fallback (count=0) になっていた致命 issue の修正 (2026-05-03)。

    mistakes_only=1: 過去に誤答ありの単語 (review_count > correct_count) のみ。
    SRS スケジュール無視で即出題。塾長指示 2026-05-25 (生徒要望「間違えた単語を別タグに」)。
    student_id は token から解決 (IDOR fix)。
    """
    student_id = _vocab_resolve_student_id(student_id, authorization)
    import random as _r
    # limit clamp (silent fallback 防止)
    orig_limit = limit
    if limit is None or limit < 1:
        limit = 10
    if limit > 100:
        limit = 100
    conn = db()
    c = conn.cursor()
    now = datetime.now(timezone.utc).isoformat()
    levels = _expand_levels(level)
    placeholders = ",".join(["?"] * len(levels)) if levels else ""
    candidates = []
    seen_ids = set()

    if mistakes_only:
        # 🔴 mistakes_only モード: 誤答ある単語だけ・SRS 無視・新単語 fallback なし
        sql_m = """
            SELECT vw.id, vw.word, vw.pos, vw.meaning_jp, vw.example_en, vw.example_jp, vw.level, vw.tags, vp.box
            FROM vocab_progress vp
            JOIN vocab_words vw ON vw.id = vp.word_id
            WHERE vp.student_id = ? AND vp.review_count > vp.correct_count
        """
        params_m = [student_id]
        if levels:
            sql_m += f" AND vw.level IN ({placeholders})"
            params_m.extend(levels)
        sql_m += " ORDER BY (vp.review_count - vp.correct_count) DESC, vp.last_reviewed_at DESC LIMIT ?"
        # univ post-fetch filter で削られる分を考慮し fetch_limit を増やす (致命 fix 2026-05-25)
        fetch_limit_m = limit * 10 if univ else limit * 3
        params_m.append(fetch_limit_m)
        c.execute(sql_m, tuple(params_m))
        for r in c.fetchall():
            d = dict(r) if hasattr(r, 'keys') else {"id": r[0], "word": r[1], "pos": r[2], "meaning_jp": r[3], "example_en": r[4], "example_jp": r[5], "level": r[6], "tags": r[7], "box": r[8]}
            d["status"] = "mistake"
            if d["id"] not in seen_ids:
                candidates.append(d); seen_ids.add(d["id"])
    else:
        # 1) 期限到来の progress (queue と同じ優先順位)
        sql_due = """
            SELECT vw.id, vw.word, vw.pos, vw.meaning_jp, vw.example_en, vw.example_jp, vw.level, vw.tags, vp.box
            FROM vocab_progress vp
            JOIN vocab_words vw ON vw.id = vp.word_id
            WHERE vp.student_id = ? AND vp.next_review_at <= ?
        """
        params = [student_id, now]
        if levels:
            sql_due += f" AND vw.level IN ({placeholders})"
            params.extend(levels)
        sql_due += " ORDER BY vp.next_review_at ASC LIMIT ?"
        params.append(limit * 3)  # univ filter で絞られる可能性があるので余裕めに
        c.execute(sql_due, tuple(params))
        for r in c.fetchall():
            d = dict(r) if hasattr(r, 'keys') else {"id": r[0], "word": r[1], "pos": r[2], "meaning_jp": r[3], "example_en": r[4], "example_jp": r[5], "level": r[6], "tags": r[7], "box": r[8]}
            d["status"] = "review"
            candidates.append(d); seen_ids.add(d["id"])

        if len(candidates) < limit:
            sql_new = """
                SELECT id, word, pos, meaning_jp, example_en, example_jp, level, tags
                FROM vocab_words
                WHERE id NOT IN (SELECT word_id FROM vocab_progress WHERE student_id = ?)
            """
            params2 = [student_id]
            if levels:
                sql_new += f" AND level IN ({placeholders})"
                params2.extend(levels)
            sql_new += " ORDER BY id LIMIT ?"
            params2.append((limit - len(candidates)) * 3)
            c.execute(sql_new, tuple(params2))
            for r in c.fetchall():
                d = dict(r) if hasattr(r, 'keys') else {"id": r[0], "word": r[1], "pos": r[2], "meaning_jp": r[3], "example_en": r[4], "example_jp": r[5], "level": r[6], "tags": r[7]}
                d["box"] = 0; d["status"] = "new"
                if d["id"] not in seen_ids:
                    candidates.append(d); seen_ids.add(d["id"])

    # univ tag filter
    if univ:
        want = f"univ:{univ}"
        candidates = [w for w in candidates if want in (w.get("tags") or "")]

    candidates = candidates[:limit]

    # 各 candidate に対して同 pos の distractor を 3 件取得
    quiz_items = []
    for w in candidates:
        wpos = (w.get("pos") or "").strip()
        # 同 pos / 異なる id / 同 level 優先 → 不足なら同 pos / 全 level
        c.execute(
            "SELECT meaning_jp FROM vocab_words WHERE pos=? AND id<>? AND level=? ORDER BY RANDOM() LIMIT 3",
            (wpos, w["id"], w["level"]),
        )
        distractors = [row["meaning_jp"] if hasattr(row, 'keys') else row[0] for row in c.fetchall()]
        if len(distractors) < 3:
            need = 3 - len(distractors)
            c.execute(
                "SELECT meaning_jp FROM vocab_words WHERE pos=? AND id<>? AND meaning_jp NOT IN (" + ",".join(["?"]*max(1,len(distractors))) + ") ORDER BY RANDOM() LIMIT ?",
                (wpos, w["id"], *(distractors or [""]), need),
            )
            for row in c.fetchall():
                m = row["meaning_jp"] if hasattr(row, 'keys') else row[0]
                if m not in distractors:
                    distractors.append(m)
        # 同 pos ですら 3 件揃わない場合は any pos からフォールバック (英検3級など pool 薄い時用)
        if len(distractors) < 3:
            need = 3 - len(distractors)
            c.execute(
                "SELECT meaning_jp FROM vocab_words WHERE id<>? ORDER BY RANDOM() LIMIT ?",
                (w["id"], need * 3),
            )
            for row in c.fetchall():
                m = row["meaning_jp"] if hasattr(row, 'keys') else row[0]
                if m not in distractors and m != w["meaning_jp"]:
                    distractors.append(m)
                    if len(distractors) >= 3: break

        choices = [w["meaning_jp"]] + distractors[:3]
        _r.shuffle(choices)
        correct_index = choices.index(w["meaning_jp"])
        transitivity = _detect_transitivity(wpos, w.get("meaning_jp") or "", w.get("tags") or "")
        quiz_items.append({
            "id": w["id"],
            "word": w["word"],
            "pos": wpos,
            "pos_label_jp": _pos_label_jp(wpos),
            "transitivity": transitivity,
            "transitivity_label_jp": _transitivity_label_jp(transitivity),
            "meaning_jp": w["meaning_jp"],
            "example_en": w.get("example_en") or "",
            "example_jp": w.get("example_jp") or "",
            "level": w["level"],
            "tags": w.get("tags") or "",
            "box": w.get("box", 0),
            "status": w.get("status", "new"),
            "choices": choices,
            "correct_index": correct_index,
        })
    conn.close()
    return {"quiz": quiz_items, "count": len(quiz_items), "requested_limit": orig_limit, "applied_limit": limit}


