# rate limit (重 endpoint・3 AI 並列 + 2 回チェックで最大 6 LLM call)
_SOLVE_RATE_LIMIT: dict = {}  # {student_id: [ts, ...]}
_SOLVE_RATE_LIMIT_PER_HOUR = 10
# 複数画像対応 (2026-06-02): 1 リクエストの画像枚数上限。
# rate limit は「枚数」で加重消費する (5 枚送れば 5 ユニット消費) ことで、複数画像でも
# 1 時間あたりの AI 解析量 (= コスト) を単一画像時と同等の上限に保つ (コスト暴走防御)。
_SOLVE_MAX_IMAGES = 5

def _check_solve_rate(student_id: int, weight: int = 1) -> None:
    """重 endpoint の per-student rate limit。
    weight: このリクエストが消費するユニット数 (= 画像枚数)。複数画像で AI コストが比例増するため
            枚数分のユニットを消費させ、1 時間あたりの総解析量を一定に保つ。weight=1 は従来挙動。
    """
    import time as _t
    now = _t.time()
    h_ago = now - 3600
    try:
        weight = max(1, min(int(weight), _SOLVE_MAX_IMAGES))
    except (TypeError, ValueError):
        weight = 1
    ts = _SOLVE_RATE_LIMIT.get(student_id, [])
    ts = [t for t in ts if t > h_ago]
    if len(ts) >= _SOLVE_RATE_LIMIT_PER_HOUR:
        oldest = min(ts)
        retry_after_min = max(1, int((oldest + 3600 - now) / 60))
        raise HTTPException(
            status_code=429,
            detail=f"3 AI 写真解答は 1 時間あたり画像 {_SOLVE_RATE_LIMIT_PER_HOUR} 枚まで。約 {retry_after_min} 分後に再試行してください。"
        )
    # weight ユニット分のタイムスタンプを記録 (複数画像は枚数分消費・単一は従来どおり 1)
    ts.extend([now] * weight)
    _SOLVE_RATE_LIMIT[student_id] = ts


def _solve_one_ai(ai_id: str, images: Optional[list], mime_pdf: bool,
                   problem_text: Optional[str], prior_answers: Optional[list] = None) -> dict:
    """1 AI で 1 round の解答を実行 (sync・thread pool から呼ぶ)。
    images: [{"b64": <base64>, "mime": <mime>}, ...] の配列 (2026-06-02 複数画像対応・最大 5 枚)。
      mime_pdf=True のときは images[0] を PDF document として扱う (PDF は単一のみ)。
    prior_answers が指定された場合 = Round 2: 他 AI の解答を参考に再評価。
    返却: {ai_id, model, subject, topic, ..., elapsed_ms} or {ai_id, model, error, elapsed_ms}
    """
    import time as _t
    t0 = _t.time()
    ai_def = _SOLVE_AI_DEFINITIONS[ai_id]

    # 🛡️ 3視点 review 致命#1 対応 (2026-05-13): PDF は Anthropic (Claude) のみ対応
    # _call_gemini / _call_openai の content converter は type="document" を黙って捨てるため、
    # PDF を渡すと「PDF 無しテキストのみ」で解答してしまい、誤答を「自信 high」で返す silent fail 発生。
    # memory: feedback_ai_tutor_demo_fallback.md と同パターン → 明示エラーで早期 fail させる。
    if mime_pdf and ai_def["kind"] != "anthropic":
        return {
            "ai_id": ai_id,
            "label": ai_def["label"],
            "model": ai_def["model"],
            "error": "PDF は Claude のみ対応 (現状 Gemini/OpenAI は PDF 直接読込み不可)",
            "elapsed_ms": int((_t.time() - t0) * 1000),
        }

    # user text 構築
    user_parts = []
    if problem_text:
        user_parts.append(f"## 補足説明 (生徒からの追加情報)\n{problem_text}\n")
    if images:
        if not mime_pdf and len(images) > 1:
            user_parts.append(f"{len(images)} 枚の画像に問題が写っています。すべての画像を順に読み取り、関連づけて 1 つの問題として解いてください。\n")
        else:
            user_parts.append("画像に問題が写っています。OCR/読解してから解いてください。\n")
    if prior_answers:
        # Round 2: 他 AI の解答を見せて再検証
        user_parts.append(
            "## 🔄 Round 2 (相互検証): 以下は他 AI の Round 1 解答です。\n"
            "もし他 AI の解答に誤り・見落としがあれば指摘し、必要なら自分の解答を修正してください。\n"
            "完全一致する場合は self confidence を high にして同じ解答を返してください。\n\n"
        )
        for pa in prior_answers:
            if pa.get("ai_id") == ai_id:
                continue  # 自分の Round 1 はスキップ
            user_parts.append(
                f"### {pa.get('label', pa.get('ai_id'))} の解答:\n"
                f"- 単元: {pa.get('topic', '?')}\n"
                f"- 手順: {' / '.join((pa.get('solution_steps') or [])[:4])}\n"
                f"- 最終解答: {pa.get('final_answer', '?')}\n"
                f"- 自信: {pa.get('confidence_self', '?')}\n\n"
            )
        user_parts.append("以上を踏まえて、もう一度同じ JSON 形式で最終解答を返してください。")
    else:
        user_parts.append("Solve completely and return JSON.")
    user_text = "\n".join(user_parts)

    # Anthropic 互換 content blocks (2026-06-02: 複数画像対応)
    content_blocks = []
    if images:
        if mime_pdf:
            # Anthropic PDF input: type=document (PDF は単一のみ・images[0] を使用)
            content_blocks.append({
                "type": "document",
                "source": {"type": "base64", "media_type": "application/pdf", "data": images[0]["b64"]},
            })
        else:
            # 画像 1〜5 枚をそれぞれ image block として添付。
            # OpenAI/Gemini の content converter も content list 内の全 image block をループ変換するため、
            # 複数画像はそのまま 3 AI すべてに渡る。
            for _im in images:
                content_blocks.append({
                    "type": "image",
                    "source": {"type": "base64", "media_type": _im.get("mime") or "image/jpeg", "data": _im["b64"]},
                })
    content_blocks.append({"type": "text", "text": user_text})

    # 🛡️ 2026-05-13 致命 fix: max_tokens=2000 が小さすぎて
    # - Gemini: explanation_jp 600-1500字を出力する前に上限到達 → JSON 途中で切れる
    # - Claude Opus 4.7: thinking adaptive + effort=high で thinking に tokens 全消費 → text content 空
    # → max_tokens を 8000 に増量 + Opus 4.7 は Sonnet 4.6 に降格 (JSON 安定性 + コスト削減)
    body = {
        "model": ai_def["model"],
        "max_tokens": 8000,
        "system": ai_def["system"],
        "messages": [{"role": "user", "content": content_blocks}],
    }
    # Opus 4.7 は thinking で max_tokens を食い尽くす問題があるため Sonnet 4.6 に降格済み (_SOLVE_AI_DEFINITIONS 変更)
    # 万一 Opus 4.7 が指定された場合の互換性パラメータは残す (memory: feedback_opus47_proxy_required.md)
    if ai_def["model"].startswith("claude-opus-4-7"):
        body["thinking"] = {"type": "adaptive"}
        body["output_config"] = {"effort": "high"}
        body["temperature"] = 1.0
    # 🛡️ 2026-05-13 塾長指摘 fix: OpenAI/Gemini 用 JSON 強制モード指定
    # Anthropic 系は API が response_format を理解しないため指定しない (Anthropic は system prompt で JSON 強制)
    # OpenAI: response_format={"type":"json_object"} → API 側で JSON 形式強制
    # Gemini: _call_gemini が response_format を読んで generation_config.response_mime_type に変換
    if ai_def["kind"] in ("openai", "gemini"):
        body["response_format"] = {"type": "json_object"}

    try:
        if ai_def["kind"] == "anthropic":
            data = _call_anthropic_safe(body, kind=f"tutor_solve_{ai_id}", student_id=None)
        elif ai_def["kind"] == "openai":
            # 🛡️ 致命 fix (2026-05-13 3視点review): body["model"] が無視され env default model
            # で動作する bug → model= を明示渡し。これで Gemini/OpenAI が _SOLVE_AI_DEFINITIONS の
            # 指定 model (gemini-2.5-flash / gpt-4o-mini) で確実に動作する
            data = _call_openai(body, model=ai_def["model"], kind=f"tutor_solve_{ai_id}")
        elif ai_def["kind"] == "gemini":
            data = _call_gemini(body, model=ai_def["model"], kind=f"tutor_solve_{ai_id}")
        else:
            raise RuntimeError(f"unknown ai kind: {ai_def['kind']}")

        text = (data.get("content") or [{}])[0].get("text", "") if data.get("content") else ""

        # 🛡️ 致命 fix (2026-05-13 塾長指摘):
        # 旧実装は parse 失敗時 explanation_jp に生 JSON を流し込んで UI で生 JSON が
        # 「最終解答」として表示される事故 → JSON 抽出を堅牢化 + 失敗時は明示エラー化。
        parsed = _extract_json_robust(text)
        parse_failed = parsed is None
        if parse_failed:
            parsed = {}  # 全 field 空で扱う・explanation_jp は別 field でエラー明示

        # 🛡️ 致命 fix v2 (2026-05-13): provider fallback の表示は UI 側 (provider_fallback フラグ)
        # のみで行う。バックエンドの label 改変は UI 側表示と重複し「⚠️」が 2 回出るバグになるため削除。
        actual_provider = data.get("_provider") or ai_def["kind"]
        actual_model = data.get("_actual_model") or ai_def["model"]
        label = ai_def["label"]  # 元のラベルをそのまま保持
        provider_fallback = (actual_provider != ai_def["kind"])

        # final_answer / explanation_jp の clean up (生 JSON を絶対に流さない)
        raw_final = (parsed.get("final_answer") or "").strip() if isinstance(parsed.get("final_answer"), str) else ""
        raw_expl = (parsed.get("explanation_jp") or "").strip() if isinstance(parsed.get("explanation_jp"), str) else ""
        # 生 JSON 混入の sanitize: { や ``` で始まる explanation はエラー扱い
        if raw_expl.startswith("{") or raw_expl.startswith("```"):
            raw_expl = ""
            parse_failed = True

        if parse_failed:
            # 🛡️ 2026-05-13 致命盲点 fix: parse_failed パスは except 節を通らず events 記録なし
            # → 原因解明不能だったので明示的に critical event 記録 (raw text 込み)
            try:
                _record_ai_critical_event("tutor_solve_individual_failure", {
                    "ai_id": ai_id,
                    "model": actual_model,
                    "kind": actual_provider,
                    "error": "json_parse_failed",
                    "raw_text_preview": text[:500] if text else "",  # ★ 重要: 実応答を 500 字保存
                    "round": "round2" if prior_answers else "round1",
                    "system_prompt_length": len(ai_def.get("system") or ""),
                })
            except Exception:
                pass
            return {
                "ai_id": ai_id,
                "label": label,
                "model": actual_model,
                "provider": actual_provider,
                "provider_fallback": provider_fallback,
                "error": "AI 応答の解答抽出に失敗 (JSON フォーマット不正)",
                "raw_text_preview": text[:200] if text else "",
                "elapsed_ms": int((_t.time() - t0) * 1000),
            }

        return {
            "ai_id": ai_id,
            "label": label,
            "model": actual_model,
            "provider": actual_provider,
            "provider_fallback": provider_fallback,
            "subject": (parsed.get("subject") or "other").strip().lower() if isinstance(parsed.get("subject"), str) else "other",
            "topic": (parsed.get("topic") or "").strip() if isinstance(parsed.get("topic"), str) else "",
            "difficulty_level": (parsed.get("difficulty_level") or "standard").strip() if isinstance(parsed.get("difficulty_level"), str) else "standard",
            "problem_text": (parsed.get("problem_text") or "").strip() if isinstance(parsed.get("problem_text"), str) else "",
            "solution_steps": parsed.get("solution_steps") or [],
            "final_answer": raw_final,
            "explanation_jp": raw_expl,
            "confidence_self": (parsed.get("confidence_self") or "medium").strip().lower() if isinstance(parsed.get("confidence_self"), str) else "medium",
            "elapsed_ms": int((_t.time() - t0) * 1000),
        }
    except Exception as e:
        # 🛡️ 2026-05-13 塾長指摘「3 AI 中 1 のみ応答」の原因不明 fix:
        # 旧実装は個別 AI 失敗を events に記録していなかったため診断不能 → critical event 記録
        err_summary = f"{type(e).__name__}: {str(e)[:300]}"
        try:
            _record_ai_critical_event("tutor_solve_individual_failure", {
                "ai_id": ai_id,
                "model": ai_def["model"],
                "kind": ai_def["kind"],
                "error": err_summary,
                "mime_pdf": mime_pdf,
                "has_image": bool(images),
                "round": "round2" if prior_answers else "round1",
            })
        except Exception:
            pass
        return {
            "ai_id": ai_id,
            "label": ai_def["label"],
            "model": ai_def["model"],
            "error": err_summary,
            "elapsed_ms": int((_t.time() - t0) * 1000),
        }


def _pdf_to_image_b64(pdf_bytes: bytes, *, dpi: int = 150, max_pages: int = 7,
                       max_image_bytes: int = 4 * 1024 * 1024,
                       max_combined_pixels: int = 50_000_000) -> dict:
    """🛡️ PDF → 画像変換 (2026-05-13 塾長指示 v2・review 致命 fix 込み)
    塾長指摘「PDF だと 3 AI 並列不可」の根本解決。PDF を PyMuPDF でページ単位 JPG に変換し、
    すべての AI (Claude/GPT-4o/Gemini) に画像として送信できるようにする。

    引数:
      - pdf_bytes: PDF の raw bytes (caller 側で b64decode 済・致命 fix H-4: 二重 decode 防止)

    返却:
      {ok, image_b64, mime, page_count, pages_used, size_bytes} or {ok=False, error}

    パラメータ:
      - dpi: 150 (印刷物の最低読み取り精度)
      - max_pages: 7 (2026-05-28 塾長指示「PDF 上限拡張」で 3 → 7。複数ページ問題集対応)
      - max_image_bytes: 4MB (各 AI 画像上限 5MB の安全マージン)
      - max_combined_pixels: 5000万 (memory DoS 防御・review H-1)
    """
    import base64 as _b64
    import io as _io
    try:
        import fitz  # PyMuPDF
    except ImportError:
        return {"ok": False, "error": "PyMuPDF (fitz) 未 install。Railway redeploy 後に再試行してください"}
    try:
        from PIL import Image
    except ImportError:
        return {"ok": False, "error": "Pillow 未 install"}

    if not isinstance(pdf_bytes, (bytes, bytearray)):
        return {"ok": False, "error": "pdf_bytes は bytes 必須"}

    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
    except Exception as e:
        return {"ok": False, "error": f"PDF を開けません (壊れている可能性): {e}"}

    # 🛡️ review CRITICAL C-1 fix: doc.close() 後の page_count アクセスは例外発生する
    # → ローカル変数に保存してから close() する
    try:
        total_pages = int(doc.page_count)
        if total_pages == 0:
            return {"ok": False, "error": "PDF にページがありません"}
        pages_used = min(total_pages, max_pages)

        # zoom factor: 150 DPI / 72 DPI (PDF default) = 約 2.08
        zoom = dpi / 72.0
        mat = fitz.Matrix(zoom, zoom)

        page_imgs = []
        for i in range(pages_used):
            page = doc.load_page(i)
            pix = page.get_pixmap(matrix=mat, alpha=False)
            img_bytes = pix.tobytes(output="jpeg")
            page_imgs.append(Image.open(_io.BytesIO(img_bytes)).convert("RGB"))
    except Exception as e:
        # 🛡️ review CRITICAL C-2 fix: 例外時も必ず doc.close() を保証
        try:
            doc.close()
        except Exception:
            pass
        return {"ok": False, "error": f"PDF ページ読込失敗: {type(e).__name__}: {str(e)[:200]}"}
    finally:
        # 通常パスでも doc.close() を保証
        try:
            doc.close()
        except Exception:
            pass

    if not page_imgs:
        return {"ok": False, "error": "ページ画像化できませんでした"}

    if len(page_imgs) == 1:
        combined = page_imgs[0]
    else:
        # 縦並び結合 (各ページのオリジナル height を保つ)
        total_h = sum(im.height for im in page_imgs)
        max_w = max(im.width for im in page_imgs)
        # 🛡️ review HIGH H-1 fix: combined pixel 数の sanity check (memory DoS 防御)
        if max_w * total_h > max_combined_pixels:
            return {
                "ok": False,
                "error": f"PDF サイズが大きすぎます (combined {max_w}x{total_h} px > {max_combined_pixels:,} 上限)。ページ数を減らすか、低解像度の PDF にしてください。",
            }
        combined = Image.new("RGB", (max_w, total_h), "white")
        y_offset = 0
        for im in page_imgs:
            combined.paste(im, (0, y_offset))
            y_offset += im.height

    # JPEG 圧縮 (4MB 以下に収まるまで quality 落とす)
    quality = 85
    out_bytes = b""
    while quality >= 40:
        buf = _io.BytesIO()
        combined.save(buf, format="JPEG", quality=quality, optimize=True)
        out_bytes = buf.getvalue()
        if len(out_bytes) <= max_image_bytes:
            break
        quality -= 10
    # まだ大きい場合は解像度を縮小
    if len(out_bytes) > max_image_bytes:
        scale = 1500 / max(combined.size)
        new_size = (max(1, int(combined.size[0] * scale)), max(1, int(combined.size[1] * scale)))
        combined = combined.resize(new_size, Image.LANCZOS)
        buf = _io.BytesIO()
        combined.save(buf, format="JPEG", quality=80, optimize=True)
        out_bytes = buf.getvalue()

    return {
        "ok": True,
        "image_b64": _b64.b64encode(out_bytes).decode("ascii"),
        "mime": "image/jpeg",
        "page_count": total_pages,  # 🛡️ C-1 fix: ローカル変数を使う
        "pages_used": pages_used,
        "size_bytes": len(out_bytes),
    }


def _extract_json_robust(text: str) -> Optional[dict]:
    """🛡️ Markdown fence / 前後説明文 / invalid escape を含む生テキストから JSON を抽出。
    塾長指摘 2026-05-13「最終解答が JSON 生のまま表示」事故への対処。

    対応パターン:
    - ```json\n{...}\n```        (標準 markdown fence)
    - ```{...}```                (json タグなし fence)
    - 前後に説明文 + {...}        (Gemini が混入させがち)
    - 単一 { ... } のみ           (理想形)

    返却: parse 成功 → dict / 失敗 → None
    """
    if not text:
        return None
    import re as _re
    src = text.strip()

    # Step 1: markdown fence 内の JSON を抽出 (greedy・複数行対応)
    m = _re.search(r"```(?:json)?\s*\n?(.+?)\n?```", src, _re.DOTALL)
    if m:
        candidate = m.group(1).strip()
    else:
        # Step 2: 最初の { から最後の } までを抽出 (前後の説明文を除去)
        s = src.find("{")
        e = src.rfind("}")
        if s >= 0 and e > s:
            candidate = src[s:e+1]
        else:
            candidate = src

    # Step 3: parse 試行
    try:
        result = json.loads(candidate)
        return result if isinstance(result, dict) else None
    except json.JSONDecodeError:
        pass

    # Step 4: invalid escape を緩和 (LaTeX 等の \n や日本語 \" を許容)
    # 多くの LLM が \\n を出力してしまうケースを救済
    try:
        # JSON 内の改行を許容 (multi-line string は許容しないが Gemini が出すケース)
        repaired = candidate.replace("\n", "\\n").replace("\r", "")
        # ただし \\" は壊れる可能性大 → 慎重に
        result = json.loads(repaired)
        return result if isinstance(result, dict) else None
    except json.JSONDecodeError:
        pass

    return None


def _consolidate_solve_answers(successful: list) -> dict:
    """3 AI の解答から consensus + confidence を計算。
    - 全 AI 一致 (文字列類似度) → confidence=high
    - 過半数一致 → confidence=medium・多数派採用
    - バラバラ → confidence=low・最も confidence_self が高い解答を primary に

    🛡️ 2026-05-13 P1 課題 fix: 短答 (10文字以下) は完全一致基準、長い解答は
    difflib.SequenceMatcher >= 0.7 で類似グループ化。記述式・数式の表記揺れを許容。
    """
    if not successful:
        return {
            "final_answer": "",
            "explanation_jp": "⚠️ AI 応答なし。再試行してください。",
            "confidence": "low",
            "consensus": "no_data",
        }

    def _norm(s):
        return (s or "").strip().lower().replace(" ", "").replace("　", "")

    # 🛡️ 類似度判定で類似グループ化 (記述式・数式の表記揺れ吸収)
    from difflib import SequenceMatcher as _SM
    def _similar(a, b, threshold=0.7):
        """短答 (10字以下) は完全一致・長い解答は類似度 >= threshold"""
        if not a or not b:
            return False
        if len(a) <= 10 and len(b) <= 10:
            return a == b
        return _SM(None, a, b).ratio() >= threshold

    # successful を similar 関係でグループ化 (transitive closure 不要・代表との比較で十分)
    normed = [(_norm(s.get("final_answer")), s) for s in successful]
    groups: list = []  # [(rep_answer, [s, s, ...])]
    for ans, s in normed:
        if not ans:
            continue
        placed = False
        for i, (rep, lst) in enumerate(groups):
            if _similar(ans, rep):
                lst.append(s)
                placed = True
                break
        if not placed:
            groups.append((ans, [s]))

    if not groups:
        # 🛡️ 致命 fix (2026-05-13): 旧実装は explanation_jp[:300] を final_answer に
        # 流していたため、JSON parse 失敗で生 JSON が「最終解答」として表示される事故が発生。
        # → 明示的なエラーメッセージのみ表示し、生 JSON を絶対に流さない。
        return {
            "final_answer": "",
            "explanation_jp": "⚠️ AI が問題を読み取れませんでした。考えられる原因: ①写真が暗い/ブレている ②問題文が日本語以外で複雑 ③PDF の場合は文字認識困難。撮り直し or「補足説明」欄に問題文を手入力してから再試行してください。",
            "confidence": "low",
            "consensus": "no_final_answer",
            "primary_ai": successful[0].get("ai_id"),
            "retry_recommended": True,
        }

    # 最大グループ (top group) を特定
    groups.sort(key=lambda g: -len(g[1]))
    top_norm, matching = groups[0][0], groups[0][1]
    top_count = len(matching)
    if top_count == len(successful):
        # 全員一致
        # 🛡️ 致命 fix (2026-05-13): 1 AI のみ応答時の「全員一致」誤判定を防ぐ
        # 1 AI だけで confidence=high にすると「3 AI 並列検証」の触れ込みが嘘になる
        primary = matching[0]
        if len(successful) == 1:
            return {
                "final_answer": primary.get("final_answer"),
                "explanation_jp": primary.get("explanation_jp"),
                "confidence": "low",
                "consensus": "single_ai_only",
                "primary_ai": primary.get("ai_id"),
                "note": "⚠️ 3 AI のうち 1 AI のみ応答。3 AI 並列検証が成立していません。再試行 or 画像形式 (JPG/PNG) で投稿し直してください。",
            }
        return {
            "final_answer": primary.get("final_answer"),
            "explanation_jp": primary.get("explanation_jp"),
            "confidence": "high",
            "consensus": f"unanimous_{len(successful)}",
            "primary_ai": primary.get("ai_id"),
        }
    if top_count >= 2:
        # 過半数一致 (3 AI 中 2)
        primary = matching[0]
        # dissenting AI 取得 (top group 以外の AI)
        top_ai_ids = {s.get("ai_id") for s in matching}
        dissenting = [s.get("ai_id") for s in successful if s.get("ai_id") not in top_ai_ids]
        return {
            "final_answer": primary.get("final_answer"),
            "explanation_jp": primary.get("explanation_jp"),
            "confidence": "medium",
            "consensus": f"majority_{top_count}_of_{len(successful)}",
            "primary_ai": primary.get("ai_id"),
            "dissenting_ai": dissenting,
        }
    # バラバラ → confidence_self が最も高い解答を primary
    rank = {"high": 3, "medium": 2, "low": 1}
    primary = max(successful, key=lambda s: rank.get(s.get("confidence_self"), 0))
    return {
        "final_answer": primary.get("final_answer"),
        "explanation_jp": primary.get("explanation_jp"),
        "confidence": "low",
        "consensus": "split",
        "primary_ai": primary.get("ai_id"),
        "note": "3 AI の解答が分かれました。各解答を比較学習の機会としてご活用ください。",
    }


@app.post("/api/ai-tutor/solve-from-image")
async def ai_tutor_solve_from_image(payload: dict, authorization: Optional[str] = Header(None)):
    """🌟 3 AI 写真/PDF 完璧解答 + 2 回チェック (essay_review mode)
    塾長指示 2026-05-13「アプリ使いやすさアピール」の実装。

    payload:
      {
        "images": [{"image_base64": "<b64>", "mime_type": "image/jpeg"}, ...]  (複数画像・最大5枚・jpeg/png/webp),
        "image_base64": "<base64>" (単一・image or PDF・後方互換),
        "mime_type": "image/jpeg" | "image/png" | "image/webp" | "application/pdf",
        "problem_text": "<生徒の補足説明>" (optional),
        "mode": "standard" | "essay_review" (default: "standard"),
        "auto_mode": true (default true・記述式/国語を auto 検出して essay_review へ昇格),
        "student_id": <int>
      }

    mode:
      - standard: 3 AI 並列 1 回 (~15s, 計算/標準問題向き)
      - essay_review: 3 AI Round 1 → Round 2 相互検証 (~30s, 記述式/国語の精度↑)

    rate limit: 1h 10 回 / student。
    """
    import asyncio as _asyncio
    import base64 as _b64

    image_b64 = (payload.get("image_base64") or "").strip()
    mime = (payload.get("mime_type") or "image/jpeg").strip()
    problem_text = (payload.get("problem_text") or "").strip()
    mode = (payload.get("mode") or "standard").strip().lower()
    auto_mode = bool(payload.get("auto_mode", True))
    student_id = payload.get("student_id")

    if mode not in ("standard", "essay_review"):
        mode = "standard"

    # 🛡️ 認証 + rate limit
    # 🛡️ IDOR fix 2026-05-30 (logic/security レビュアー LOW 指摘・正パターン= grade-essay-multiview 28371):
    # 生徒 session_token があれば claims["student_id"] を強制 override (payload を信用しない)。
    # → ログイン中の有効生徒が別の有効生徒の ID を payload に入れて rate-limit 消費 / weakness 集計を
    #   他生徒 ID に付け替える軽微な IDOR を防御。token 無し経路は後方互換 (payload student_id 維持)。
    is_admin_call = False
    _auth_student_id_from_claims: Optional[int] = None
    if authorization and authorization.startswith("Bearer "):
        _admin_token_try = authorization[len("Bearer "):].strip()
        if _verify_admin_token(_admin_token_try):
            is_admin_call = True
        else:
            _claims_try = _verify_session_token(_admin_token_try)
            if _claims_try and _claims_try.get("student_id"):
                try:
                    _auth_student_id_from_claims = int(_claims_try["student_id"])
                except (TypeError, ValueError):
                    _auth_student_id_from_claims = None

    try:
        student_id = int(student_id) if student_id else 0
    except (TypeError, ValueError):
        student_id = 0

    # 🛡️ session_token あれば payload を override (IDOR 防御)
    if not is_admin_call and _auth_student_id_from_claims:
        student_id = _auth_student_id_from_claims

    if not is_admin_call:
        if not student_id or student_id <= 0:
            raise HTTPException(status_code=403, detail="ログインが必要です (student_id 未提供)")
        # 🛡️ 契約 status 検証 (2026-05-29 塾長指示・コスト保護): 存在確認のみ → _verify_student_active に置換。
        # trial 期限切れ / canceled / past_due(grace 超過) の生徒が 3 AI 並列解答 ($0.10-0.30/req) を
        # タダ使いするのを防ぐ。/api/ai/call と同じく HTTPException(403/404) は伝搬・DB 異常のみ 500 化。
        try:
            _verify_student_active(student_id)
        except HTTPException:
            raise
        except Exception as e:
            log.error(f"[solve-from-image] _verify_student_active error: {type(e).__name__}: {e}")
            raise HTTPException(status_code=500, detail="契約状態の確認に失敗しました")
        # 複数画像は枚数で rate limit を加重消費 (AI コスト比例・枚数は _check_solve_rate 内で上限 clamp)
        _raw_imgs_for_rate = payload.get("images")
        _img_weight = len(_raw_imgs_for_rate) if isinstance(_raw_imgs_for_rate, list) and _raw_imgs_for_rate else 1
        _check_solve_rate(student_id, weight=_img_weight)

    # ---- 入力画像の正規化 (2026-06-02: 複数画像アップロード対応・最大 5 枚) ----
    # 優先: images 配列 [{image_base64, mime_type}, ...] (jpeg/png/webp のみ・PDF 不可)。
    # 後方互換: 単一 image_base64 + mime_type (画像 or PDF) も従来通り受け付ける。
    # PDF は単一アップロードのみ対応 (複数 PDF や 画像との混在は不可)。
    # (_SOLVE_MAX_IMAGES はモジュール定数・rate limit と共有)
    raw_images = payload.get("images")
    image_items = []   # [{"b64": str, "mime": str}] — 各 AI に渡す画像群
    mime_pdf = False
    pdf_conversion_info = None

    if isinstance(raw_images, list) and len(raw_images) > 0:
        # --- 複数画像モード (jpeg/png/webp のみ) ---
        if len(raw_images) > _SOLVE_MAX_IMAGES:
            raise HTTPException(status_code=400, detail=f"画像は最大 {_SOLVE_MAX_IMAGES} 枚までです")
        for _idx, _it in enumerate(raw_images):
            if not isinstance(_it, dict):
                continue
            _b = (_it.get("image_base64") or _it.get("b64") or "").strip()
            _m = (_it.get("mime_type") or _it.get("mime") or "image/jpeg").strip()
            if not _b:
                continue
            try:
                _dec = _b64.b64decode(_b, validate=True)
            except Exception as e:
                raise HTTPException(status_code=400, detail=f"画像 {_idx + 1} の base64 decode 失敗: {e}")
            if len(_dec) > 5 * 1024 * 1024:
                raise HTTPException(status_code=400, detail=f"画像 {_idx + 1} が大きすぎます (1 枚 5MB 以内)")
            if _m not in ("image/jpeg", "image/png", "image/webp"):
                raise HTTPException(status_code=400, detail=f"画像 {_idx + 1} の mime_type は jpeg/png/webp のみ (PDF は単一アップロードのみ対応)")
            image_items.append({"b64": _b, "mime": _m})
        if not image_items:
            raise HTTPException(status_code=400, detail="images 配列に有効な画像がありません")
    elif image_b64:
        # --- 単一ファイルモード (画像 or PDF) — 従来ロジック ---
        mime_pdf = (mime == "application/pdf")
        try:
            decoded = _b64.b64decode(image_b64, validate=True)
        except Exception as e:
            raise HTTPException(status_code=400, detail=f"image_base64 decode 失敗: {e}")
        # 🛡️ 2026-05-28 塾長指示「PDF 上限拡張」: PDF 10MB → 20MB
        max_size = 20 * 1024 * 1024 if mime_pdf else 5 * 1024 * 1024
        if len(decoded) > max_size:
            raise HTTPException(status_code=400,
                                detail=f"ファイルが大きすぎます ({'PDF 20MB' if mime_pdf else '画像 5MB'} 以内)")
        if mime not in ("image/jpeg", "image/png", "image/webp", "application/pdf"):
            raise HTTPException(status_code=400, detail="mime_type は jpeg/png/webp/pdf のみ")
        # 🛡️ Task 1 (2026-05-13・review fix v2): PDF → 画像変換で 3 AI 全部対応
        # 旧: PDF は Claude のみ → Claude 失敗 (credit_low 等) で 3 AI 全失敗
        # 新: PDF を PyMuPDF で JPG 化 → Claude/GPT-4o/Gemini すべてで処理可能
        if mime_pdf:
            # 🛡️ 2026-05-28 塾長指示「PDF 上限拡張」: max_pages 3 → 7
            conv = _pdf_to_image_b64(decoded, dpi=150, max_pages=7)
            if conv.get("ok"):
                image_b64 = conv["image_b64"]
                mime = conv["mime"]
                mime_pdf = False  # 内部画像化したので以降は画像として扱う
                pdf_conversion_info = {
                    "converted": True,
                    "page_count": conv.get("page_count"),
                    "pages_used": conv.get("pages_used"),
                    "size_kb": round((conv.get("size_bytes") or 0) / 1024, 1),
                }
                log.info(f"[solve-from-image] PDF→JPG converted: {pdf_conversion_info}")
            else:
                # 変換失敗 → PDF のまま Anthropic に投げる (従来挙動)
                log.warning(f"[solve-from-image] PDF conversion failed, falling back to native PDF: {conv.get('error')}")
                pdf_conversion_info = {"converted": False, "error": conv.get("error")}
        image_items = [{"b64": image_b64, "mime": mime}]

    # 画像 (単一/複数) か 補足テキストのいずれかは必須
    if not image_items and not problem_text:
        raise HTTPException(status_code=400, detail="画像 (image_base64 / images) か problem_text のいずれか必須")
    if problem_text and len(problem_text) > 4000:
        raise HTTPException(status_code=400, detail="problem_text が長すぎます (4000 文字以内)")

    # Round 1: 3 AI 並列で独立解答
    import time as _t
    t0_total = _t.time()
    loop = _asyncio.get_running_loop()
    ai_ids = list(_SOLVE_AI_DEFINITIONS.keys())
    tasks_r1 = []
    for aid in ai_ids:
        future = loop.run_in_executor(
            None, _solve_one_ai, aid, image_items, mime_pdf, problem_text, None
        )
        tasks_r1.append(_asyncio.wait_for(future, timeout=90))

    r1_results = await _asyncio.gather(*tasks_r1, return_exceptions=True)
    round1 = []
    for i, aid in enumerate(ai_ids):
        r = r1_results[i]
        if isinstance(r, (_asyncio.TimeoutError, TimeoutError)):
            round1.append({"ai_id": aid, "label": _SOLVE_AI_DEFINITIONS[aid]["label"],
                           "model": _SOLVE_AI_DEFINITIONS[aid]["model"], "error": "timeout (90s)"})
        elif isinstance(r, Exception):
            round1.append({"ai_id": aid, "label": _SOLVE_AI_DEFINITIONS[aid]["label"],
                           "model": _SOLVE_AI_DEFINITIONS[aid]["model"],
                           "error": f"{type(r).__name__}: {str(r)[:200]}"})
        else:
            round1.append(r)

    successful_r1 = [r for r in round1 if "final_answer" in r and "error" not in r]
    # 3視点 review 致命#1 対応: PDF は Claude のみ対応のため最低 1 AI で許容、画像は 2 AI 以上必須
    min_required = 1 if mime_pdf else 2
    if len(successful_r1) < min_required:
        # 🛡️ 2026-05-13 塾長指摘 fix: 全失敗時も各 AI のエラー詳細を返す (診断可能化)
        error_summary = []
        for r in round1:
            if r.get("error"):
                error_summary.append(f"[{r.get('ai_id', '?')}/{r.get('model', '?')}] {r['error']}")
        detail_str = f"3 AI 中 {len(successful_r1)} のみ応答 (必要 {min_required}+)。再試行を推奨します。"
        if error_summary:
            detail_str += "\n各 AI のエラー: " + " ; ".join(error_summary)
        # 親 endpoint レベルでも critical event 記録 (失敗の総括)
        try:
            _record_ai_critical_event("tutor_solve_total_failure", {
                "successful": len(successful_r1),
                "min_required": min_required,
                "errors": [{"ai_id": r.get("ai_id"), "error": r.get("error")} for r in round1 if r.get("error")],
                "mime_pdf": mime_pdf,
                "had_pdf_conversion": bool(pdf_conversion_info),
                "student_id": student_id,
            })
        except Exception:
            pass
        raise HTTPException(status_code=502, detail=detail_str)

    # auto_mode 判定: Round 1 の subject から essay_review 昇格判定
    auto_promoted = False
    if auto_mode and mode == "standard":
        # 過半数が「japanese / english」かつ topic に「記述/作文/読解/論述」を含む → 昇格
        subjects = [r.get("subject", "") for r in successful_r1]
        topics = [r.get("topic", "") for r in successful_r1]
        essay_keywords = ("記述", "作文", "論述", "読解", "essay", "要約", "summary")
        is_japanese = any(s == "japanese" for s in subjects)
        is_english_essay = sum(1 for s in subjects if s == "english") >= 2 and any(
            any(k in t for k in essay_keywords) for t in topics
        )
        # 難問判定: hard が過半数
        is_hard = sum(1 for r in successful_r1 if r.get("difficulty_level") == "hard") >= 2
        if is_japanese or is_english_essay or is_hard:
            mode = "essay_review"
            auto_promoted = True

    # Round 2 (essay_review mode のみ): 各 AI に他 AI の Round 1 解答を見せて再評価
    round2 = None
    if mode == "essay_review":
        tasks_r2 = []
        for aid in ai_ids:
            future = loop.run_in_executor(
                None, _solve_one_ai, aid, image_items, mime_pdf, problem_text, successful_r1
            )
            tasks_r2.append(_asyncio.wait_for(future, timeout=90))
        r2_results = await _asyncio.gather(*tasks_r2, return_exceptions=True)
        round2 = []
        for i, aid in enumerate(ai_ids):
            r = r2_results[i]
            if isinstance(r, (_asyncio.TimeoutError, TimeoutError)):
                round2.append({"ai_id": aid, "label": _SOLVE_AI_DEFINITIONS[aid]["label"],
                               "model": _SOLVE_AI_DEFINITIONS[aid]["model"], "error": "timeout (90s)"})
            elif isinstance(r, Exception):
                round2.append({"ai_id": aid, "label": _SOLVE_AI_DEFINITIONS[aid]["label"],
                               "model": _SOLVE_AI_DEFINITIONS[aid]["model"],
                               "error": f"{type(r).__name__}: {str(r)[:200]}"})
            else:
                round2.append(r)

    # 統合 (Round 2 があればそれを優先・なければ Round 1)
    successful_final = [r for r in (round2 or round1) if "final_answer" in r and "error" not in r]
    if not successful_final:
        successful_final = successful_r1  # fallback
    consensus = _consolidate_solve_answers(successful_final)
    elapsed_ms_total = int((_t.time() - t0_total) * 1000)

    # subject_guess / topic_guess (多数派採用)
    subjects = [r.get("subject", "other") for r in successful_final]
    topics = [r.get("topic", "") for r in successful_final if r.get("topic")]
    from collections import Counter as _Counter
    subject_guess = _Counter(subjects).most_common(1)[0][0] if subjects else "other"
    topic_guess = _Counter(topics).most_common(1)[0][0] if topics else ""

    # ai_tutor_solve_log に保存 (弱点ストック準備)
    try:
        conn_log = db()
        c_log = conn_log.cursor()
        c_log.execute(
            "INSERT INTO ai_tutor_solve_log "
            "(student_id, mode, subject_guess, topic_guess, problem_text, has_image, "
            " round_count, final_answer, confidence, ai_models, elapsed_ms) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                student_id or None,
                mode,
                subject_guess,
                topic_guess[:200] if topic_guess else None,
                (problem_text or successful_final[0].get("problem_text", ""))[:1000] if successful_final else None,
                1 if image_items else 0,
                2 if round2 else 1,
                (consensus.get("final_answer") or "")[:1000],
                consensus.get("confidence", "low"),
                ",".join(r.get("ai_id", "?") for r in successful_final),
                elapsed_ms_total,
            ),
        )
        conn_log.commit()
        conn_log.close()
    except Exception as ee:
        log.warning(f"[solve-from-image] db log failed: {ee}")

    # event 記録
    try:
        _record_ai_critical_event("tutor_solve_done", {
            "mode": mode,
            "auto_promoted": auto_promoted,
            "subject_guess": subject_guess,
            "topic_guess": topic_guess[:80] if topic_guess else None,
            "confidence": consensus.get("confidence"),
            "successful_r1": len(successful_r1),
            "successful_final": len(successful_final),
            "round_count": 2 if round2 else 1,
            "elapsed_ms": elapsed_ms_total,
            "student_id": student_id,
            "is_admin": is_admin_call,
        })
    except Exception as ee:
        log.warning(f"[solve-from-image] event log failed: {ee}")

    # 🛡️ Task 2 (2026-05-13 塾長指示): Anthropic credit_low 状態を response に含めて UI で代替表示
    import time as _time_ai
    anthropic_credit_low = _AI_CIRCUIT_BREAKER.get("credit_low_until", 0) > _time_ai.time()
    active_ais = []
    if not anthropic_credit_low:
        active_ais.append("claude")
    active_ais.extend(["gemini", "openai"])  # この 2 つは別 provider なので常時 active

    return {
        "ok": True,
        "mode": mode,
        "auto_promoted": auto_promoted,
        "subject_guess": subject_guess,
        "topic_guess": topic_guess,
        "round1": round1,
        "round2": round2,  # essay_review 時のみ存在
        "consensus": consensus,
        "elapsed_ms_total": elapsed_ms_total,
        "pdf_conversion": pdf_conversion_info,  # PDF→画像変換情報 (PDF 受信時のみ非 null)
        "ai_health": {
            "anthropic_credit_low": anthropic_credit_low,
            "active_count": len(active_ais),
            "active_ais": active_ais,
            "fallback_active": anthropic_credit_low,
            "message": (
                "⚠️ Anthropic Claude が一時的に利用不可です。Gemini + OpenAI の 2 AI 体制で動作中。"
                "塾長に「Anthropic クレジット補充」をお伝えください。"
            ) if anthropic_credit_low else None,
        },
    }


@app.post("/api/mock-exam/grade-essay")
def mock_exam_grade_essay(payload: dict, request: Request, authorization: Optional[str] = Header(None)):
    """模試内 essay (英作文) を AI で採点 — 単一 AI シンプル版 (高速・後方互換)。
    payload: {"prompt": "...", "essay": "...", "level": "todai" | "kyodai" | "eiken_g1" | ...}
    返却: {scores: {structure, content, language}, overall, total_points, feedback_jp}

    2026-05-10 修正: 旧 _call_anthropic_safe(system=, user=, max_tokens=) signature mismatch
    bug を修正 (`body: dict` 形式に統一・AI never-fail 5 段防御に乗る)。
    多視点採点が欲しい場合は /api/mock-exam/grade-essay-multiview を使用。

    🛡️ IDOR + AI 課金 DoS fix 2026-05-26 (3視点 audit 発見):
    - 旧実装: auth gate + rate-limit ゼロで AI 課金経路 ($$ 暴走可能)
    - 修正: admin Bearer or 本人 session_token 必須 (frontend caller 0 件・将来の安全網)
    - rate limit: per-IP 10 req/60s (AI 課金保護・grade-essay-multiview と同等)
    """
    # 🛡️ rate limit (AI 課金保護・校内 NAT 対応で生徒単位 audit M5 fix)
    _check_rate_limit_caller(request, authorization, bucket="mock_exam_grade_essay", limit=10, window=60)

    # 認証: admin or 本人 session token 必須
    is_admin = False
    auth_student_id: Optional[int] = None
    if authorization and authorization.startswith("Bearer "):
        token = authorization[len("Bearer "):].strip()
        if _verify_admin_token(token):
            is_admin = True
        else:
            claims = _verify_session_token(token)
            if claims and claims.get("student_id"):
                try:
                    auth_student_id = int(claims["student_id"])
                except (TypeError, ValueError):
                    auth_student_id = None
    if not is_admin and not auth_student_id:
        raise HTTPException(status_code=401, detail="ログインが必要です")

    prompt = (payload.get("prompt") or "").strip()
    essay = (payload.get("essay") or "").strip()
    level = (payload.get("level") or "todai").strip()
    if not essay or len(essay) < 20:
        raise HTTPException(status_code=400, detail="essay が短すぎます (20 文字以上必須)")
    if len(essay) > 4000:
        raise HTTPException(status_code=400, detail="essay が長すぎます (4000 文字以内)")

    system = (
        "You are an experienced English exam grader for Japanese university entrance exams. "
        "Grade the student's essay strictly but fairly. Score on 3 dimensions (0-10 each):\n"
        "1) Structure: thesis clarity, paragraph organization, logical flow\n"
        "2) Content: argument depth, evidence/examples, originality\n"
        "3) Language: grammar accuracy, vocabulary range, naturalness\n\n"
        "Return ONLY valid JSON: {\"structure\": <0-10>, \"content\": <0-10>, \"language\": <0-10>, "
        "\"overall_comment_jp\": \"...\", \"strengths_jp\": [\"...\"], \"improvements_jp\": [\"...\"]}\n"
        "Comment in Japanese for the student."
    )
    user = f"Level: {level}\n\nPrompt: {prompt}\n\nStudent essay:\n{essay}\n\nGrade now (JSON only)."

    try:
        # 2026-05-10 bug 修正: _call_anthropic_safe の正しい signature (body: dict) を使用
        body = {
            "model": "claude-haiku-4-5",
            "max_tokens": 1500,
            "system": system,
            "messages": [{"role": "user", "content": user}],
        }
        data = _call_anthropic_safe(body, kind="grade_essay", student_id=payload.get("student_id"))
        resp_text = (data.get("content") or [{}])[0].get("text", "") if data.get("content") else "{}"
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"AI 採点失敗: {type(e).__name__}: {str(e)[:120]}")

    # JSON パース (```json fence 除去)
    try:
        cleaned = resp_text.strip()
        if cleaned.startswith("```"):
            cleaned = cleaned.split("\n", 1)[1] if "\n" in cleaned else cleaned
            if cleaned.endswith("```"):
                cleaned = cleaned.rsplit("```", 1)[0]
        scores = json.loads(cleaned)
    except Exception:
        scores = {"structure": 5, "content": 5, "language": 5,
                  "overall_comment_jp": resp_text[:400],
                  "strengths_jp": [], "improvements_jp": []}

    s = int(scores.get("structure") or 0)
    c_ = int(scores.get("content") or 0)
    l_ = int(scores.get("language") or 0)
    total_30 = s + c_ + l_
    return {
        "scores": {"structure": s, "content": c_, "language": l_},
        "total_30": total_30,
        "overall_pct": round(100 * total_30 / 30, 1),
        "overall_comment_jp": scores.get("overall_comment_jp", ""),
        "strengths_jp": scores.get("strengths_jp", []),
        "improvements_jp": scores.get("improvements_jp", []),
    }


# ==========================================================================
# Routes: Study Logs (学習記録 - Studyplus for School 代替)
# 塾長指示 2026-05-04: コスト削減のため Studyplus for School 機能を内製化
# 国公立難関大学コース (course='kokuritsu_nankan') 受講生のみ提供
# Phase 1: 学習記録 + タイムライン + ヒートマップ + リアクション
# ==========================================================================
_STUDY_SUBJECTS = {
    "英語", "数学", "国語", "現代文", "古文", "漢文",
    "理科", "物理", "化学", "生物", "地学",
    "社会", "日本史", "世界史", "地理", "倫理", "政経",
    "情報", "小論文", "面接対策", "その他",
}
_STUDY_LOG_TARGET_COURSE = "kokuritsu_nankan"  # 国公立難関大学コース 識別子

# JST (UTC+9) helper - JST 基準で「今日」を計算しないと夜間学習の記録が翌日扱いになる
_JST = timezone(timedelta(hours=9))

def _today_jst():
    return datetime.now(_JST).date()


def _verify_admin_required(authorization: Optional[str]) -> None:
    """admin Bearer token 検証 (失敗で 401)。"""
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="未認証")
    token = authorization[len("Bearer "):].strip()
    if not _verify_admin_token(token):
        raise HTTPException(status_code=401, detail="未認証")


_STUDY_LOG_ALLOWED_PLANS = {"premium", "family", "founder_special", "student_addon"}  # 新プラン体系 2026-05-06

def _require_study_log_course(student: dict) -> None:
    """学習管理機能 (学習記録・カリキュラム・模試分析・弱点プリント) アクセス判定。
    新プラン体系 2026-05-06 (通塾生優遇方針 2026-05-06):
      - course='kokuritsu_nankan' (本クラス所属生徒・無料 sub) → 解放
      - plan='premium' (¥19,800・国公立難関機能含むフル) → 解放
      - plan='family' (¥39,800・プレミアム×3名) → 解放
      - plan='founder_special' (¥14,500 永年・既契約者特典) → 解放
      - plan='student_addon' (通塾生 ¥5,000・招待制限定) → 解放 (塾長指示 2026-05-06)
    塾長指示 2026-05-06: 旧 standard (¥24,980 募集停止) のみ AI のみで学習管理 NG
    通塾生は塾の月謝も払う高単価層で招待制限定のため学習管理を解放
    """
    if not student:
        raise HTTPException(status_code=403, detail="この機能はログイン必須です")
    # 国公立難関本クラス所属
    if student.get("course") == _STUDY_LOG_TARGET_COURSE:
        return
    # プレミアム / 家族 / 創設メンバー のいずれか
    plan = (student.get("plan") or "").lower()
    if plan in _STUDY_LOG_ALLOWED_PLANS:
        return
    raise HTTPException(
        status_code=403,
        detail="この機能はプレミアム以上または国公立難関大学コース受講生のみ利用可能です"
    )


def _sanitize_text(s, maxlen):
    """制御文字除去 + 長さ切り詰め + strip。空なら None。"""
    import re as _re
    if s is None:
        return None
    s = _re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]', '', str(s))[:maxlen].strip()
    return s or None


class StudyLogCreateRequest(BaseModel):
    studied_date: Optional[str] = None
    subject: str
    material: Optional[str] = None
    minutes: int
    pages: Optional[int] = None
    note: Optional[str] = None


@app.post("/api/study-logs")
def create_study_log(payload: StudyLogCreateRequest, request: Request, authorization: Optional[str] = Header(None)):
    """生徒が学習記録を投稿。国公立難関大学コース限定。"""
    _check_rate_limit_caller(request, authorization, bucket="study_log_create", limit=30, window=60)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)

    subject = (payload.subject or "").strip()
    if subject not in _STUDY_SUBJECTS:
        raise HTTPException(status_code=400, detail="科目が不正です")

    try:
        minutes = int(payload.minutes or 0)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="勉強時間が不正です")
    if minutes <= 0 or minutes > 1440:
        raise HTTPException(status_code=400, detail="勉強時間は 1〜1440 分で指定してください")

    today = _today_jst()
    studied_date = (payload.studied_date or today.isoformat()).strip()
    try:
        d = datetime.strptime(studied_date, "%Y-%m-%d").date()
        if d > today:
            raise HTTPException(status_code=400, detail="未来の日付は登録できません")
        if (today - d).days > 365:
            raise HTTPException(status_code=400, detail="1年以上前の日付は登録できません")
    except HTTPException:
        raise
    except ValueError:
        raise HTTPException(status_code=400, detail="日付フォーマットが不正です (YYYY-MM-DD)")

    material = _sanitize_text(payload.material, 200)
    note = _sanitize_text(payload.note, 1000)
    pages = None
    if payload.pages is not None:
        try:
            p = int(payload.pages)
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="ページ数が不正です")
        if not (0 <= p <= 10000):
            raise HTTPException(status_code=400, detail="ページ数は 0〜10000 で指定してください")
        pages = p

    conn = db()
    try:
        c = conn.cursor()
        # 直近10秒以内の重複投稿を弾く (連打防止・seed_questions 致命事故と同パターン回避)
        if USE_POSTGRES:
            c.execute(
                "SELECT id FROM study_logs WHERE student_id = ? AND studied_date = ? AND subject = ? "
                "AND COALESCE(material,'') = COALESCE(?,'') AND minutes = ? "
                "AND created_at > NOW() - INTERVAL '10 seconds' LIMIT 1",
                (student["id"], studied_date, subject, material, minutes)
            )
        else:
            c.execute(
                "SELECT id FROM study_logs WHERE student_id = ? AND studied_date = ? AND subject = ? "
                "AND COALESCE(material,'') = COALESCE(?,'') AND minutes = ? "
                "AND created_at > datetime('now','-10 seconds') LIMIT 1",
                (student["id"], studied_date, subject, material, minutes)
            )
        if c.fetchone():
            raise HTTPException(status_code=409, detail="重複投稿です。少し待ってから再度お試しください。")

        c.execute(
            "INSERT INTO study_logs (student_id, studied_date, subject, material, minutes, pages, note) VALUES (?,?,?,?,?,?,?) RETURNING id",
            (student["id"], studied_date, subject, material, minutes, pages, note)
        )
        returned = c.fetchone()
        new_id = returned["id"] if returned else None
        conn.commit()
        log.info(f"[StudyLog] create id={new_id} student={student['id']} subj={subject} min={minutes}")
        return {"ok": True, "id": new_id}
    finally:
        conn.close()


@app.delete("/api/study-logs/{log_id}")
def delete_my_study_log(log_id: int, request: Request, authorization: Optional[str] = Header(None)):
    """生徒が自分の学習記録を削除 (誤投稿対策)。"""
    _check_rate_limit_caller(request, authorization, bucket="study_log_delete", limit=20, window=60)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)

    conn = db()
    try:
        c = conn.cursor()
        c.execute("SELECT student_id FROM study_logs WHERE id = ?", (log_id,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="記録が見つかりません")
        if int(row["student_id"]) != int(student["id"]):
            raise HTTPException(status_code=403, detail="権限がありません")

        # 塾長コメントが付いていたら削除を抑止 (励ましが消えるのを防ぐ)
        c.execute(
            "SELECT COUNT(*) AS n FROM study_log_reactions WHERE log_id = ? AND actor_type = 'admin' AND kind = 'comment'",
            (log_id,)
        )
        row2 = c.fetchone()
        admin_comments = int((row2["n"] if row2 else 0) or 0)
        if admin_comments > 0:
            raise HTTPException(status_code=409, detail="塾長コメントが付いた記録は削除できません。塾長に削除を依頼してください。")

        try:
            c.execute("DELETE FROM study_log_reactions WHERE log_id = ?", (log_id,))
            c.execute("DELETE FROM study_logs WHERE id = ?", (log_id,))
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        log.info(f"[StudyLog] delete id={log_id} student={student['id']}")
        return {"ok": True}
    finally:
        conn.close()


@app.get("/api/study-logs/me")
def get_my_study_logs(authorization: Optional[str] = Header(None), days: int = 30, limit: int = 200):
    """生徒が自分の学習記録を取得 (デフォルト直近30日)。"""
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)

    try:
        days = int(days or 30)
        limit = int(limit or 200)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="クエリパラメータが不正です")
    days = max(1, min(days, 365))
    limit = max(1, min(limit, 1000))
    today = _today_jst()
    cutoff_date = (today - timedelta(days=days - 1)).isoformat()

    conn = db()
    try:
        c = conn.cursor()
        # 詳細表示用 logs (LIMIT)
        c.execute(
            "SELECT id, studied_date, subject, material, minutes, pages, note, created_at "
            "FROM study_logs WHERE student_id = ? AND studied_date >= ? "
            "ORDER BY studied_date DESC, created_at DESC LIMIT ?",
            (student["id"], cutoff_date, limit)
        )
        rows = c.fetchall()
        logs = []
        log_ids = []
        for r in rows:
            log_ids.append(r["id"])
            logs.append({
                "id": r["id"],
                "date": str(r["studied_date"]),
                "subject": r["subject"],
                "material": r["material"],
                "minutes": int(r["minutes"] or 0),
                "pages": r["pages"],
                "note": r["note"],
                "created_at": str(r["created_at"]) if r["created_at"] else None
            })

        # 集計は LIMIT なしで全期間
        c.execute(
            "SELECT studied_date, subject, SUM(minutes) AS m "
            "FROM study_logs WHERE student_id = ? AND studied_date >= ? "
            "GROUP BY studied_date, subject",
            (student["id"], cutoff_date)
        )
        daily = {}
        by_subject = {}
        for r in c.fetchall():
            d = str(r["studied_date"])
            s = r["subject"]
            m = int(r["m"] or 0)
            daily[d] = daily.get(d, 0) + m
            by_subject[s] = by_subject.get(s, 0) + m

        # reactions
        reactions_map = {}
        if log_ids:
            placeholders = ",".join(["?"] * len(log_ids))
            c.execute(
                f"SELECT log_id, kind, comment, actor_type, created_at FROM study_log_reactions WHERE log_id IN ({placeholders}) ORDER BY created_at ASC",
                tuple(log_ids)
            )
            for r in c.fetchall():
                lid = r["log_id"]
                if lid not in reactions_map:
                    reactions_map[lid] = {"likes": 0, "comments": []}
                if r["kind"] == "like":
                    reactions_map[lid]["likes"] += 1
                elif r["kind"] == "comment" and r["comment"]:
                    reactions_map[lid]["comments"].append({
                        "actor_type": r["actor_type"],
                        "comment": r["comment"],
                        "created_at": str(r["created_at"]) if r["created_at"] else None
                    })
        for log_obj in logs:
            log_obj["reactions"] = reactions_map.get(log_obj["id"], {"likes": 0, "comments": []})

        return {
            "ok": True,
            "logs": logs,
            "daily": [{"date": d, "minutes": m} for d, m in sorted(daily.items())],
            "by_subject": [{"subject": s, "minutes": m} for s, m in sorted(by_subject.items(), key=lambda x: -x[1])],
            "total_minutes": sum(daily.values()),
            "days_active": len(daily),
            "period_days": days,
        }
    finally:
        conn.close()


@app.get("/api/admin/study-logs/timeline")
def admin_study_logs_timeline(authorization: Optional[str] = Header(None), days: int = 7, limit: int = 200, student_id: Optional[int] = None):
    """塾長: 国公立難関大学コース生徒の学習記録タイムライン。"""
