# ==========================================================================
# Routes: Study Plans (学習計画 - Phase 2)
# 塾長指示 2026-05-05: study_logs (実績) と study_plans (計画) を組み合わせ、
# ガントチャート + カレンダーで「計画 vs 実績」を可視化。
# 国公立難関大学コース限定。
# ==========================================================================
class StudyPlanCreateRequest(BaseModel):
    title: str
    subject: str
    material: Optional[str] = None
    start_date: str  # YYYY-MM-DD
    end_date: str    # YYYY-MM-DD
    target_minutes: Optional[int] = None
    target_pages: Optional[int] = None
    color: Optional[str] = None
    note: Optional[str] = None
    week_pattern: Optional[str] = None  # 'all' or '1,3,5' (1=月..7=日) - 2026-05-22 塾長指示


class StudyPlanUpdateRequest(BaseModel):
    title: Optional[str] = None
    subject: Optional[str] = None
    material: Optional[str] = None
    start_date: Optional[str] = None
    end_date: Optional[str] = None
    target_minutes: Optional[int] = None
    target_pages: Optional[int] = None
    color: Optional[str] = None
    status: Optional[str] = None
    note: Optional[str] = None  # 2026-05-22 fix: 元から欠落していたが PUT endpoint で参照あり (AttributeError fix)
    week_pattern: Optional[str] = None  # 'all' or '1,3,5' (1=月..7=日) - 2026-05-22 塾長指示


# 📅 week_pattern validator (2026-05-22 塾長指示: 隔日学習計画)
def _validate_week_pattern(pattern: Optional[str]) -> str:
    """week_pattern を validate。'all' or '1,3,5' (1-7 の int 群) を受け付け、正規化された string を返す。
    無効値や None は 'all' を返す (default = 毎日)。"""
    if not pattern or not isinstance(pattern, str):
        return 'all'
    p = pattern.strip().lower()
    if p == 'all' or p == '':
        return 'all'
    try:
        days = sorted(set(int(x.strip()) for x in p.split(',') if x.strip()))
        if not days or not all(1 <= d <= 7 for d in days):
            return 'all'
        if len(days) == 7:
            return 'all'
        return ','.join(str(d) for d in days)
    except (ValueError, TypeError):
        return 'all'


_PLAN_STATUSES = {"active", "completed", "archived"}
_PLAN_COLOR_RE_STR = r'^#[0-9a-fA-F]{6}$'


def _validate_plan_dates(start_date: str, end_date: str) -> tuple:
    """start_date / end_date を validate して date オブジェクト返す。"""
    try:
        sd = datetime.strptime(start_date.strip(), "%Y-%m-%d").date()
        ed = datetime.strptime(end_date.strip(), "%Y-%m-%d").date()
    except (ValueError, AttributeError):
        raise HTTPException(status_code=400, detail="日付フォーマットが不正です (YYYY-MM-DD)")
    if ed < sd:
        raise HTTPException(status_code=400, detail="終了日は開始日以降に指定してください")
    today = _today_jst()
    if (sd - today).days > 730:
        raise HTTPException(status_code=400, detail="2年以上先の計画は登録できません")
    if (today - sd).days > 730:
        raise HTTPException(status_code=400, detail="2年以上前の計画は登録できません")
    if (ed - sd).days > 730:
        raise HTTPException(status_code=400, detail="期間は最大2年までです")
    return sd, ed


def _validate_plan_color(color: Optional[str]) -> Optional[str]:
    import re as _re
    if not color:
        return None
    color = color.strip()
    if not _re.match(_PLAN_COLOR_RE_STR, color):
        raise HTTPException(status_code=400, detail="color は #RRGGBB 形式で指定してください")
    return color


@app.post("/api/study-plans")
def create_study_plan(payload: StudyPlanCreateRequest, request: Request, authorization: Optional[str] = Header(None)):
    """生徒が学習計画を作成。"""
    _check_rate_limit_caller(request, authorization, bucket="study_plan_create", limit=20, window=60)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)

    title = _sanitize_text(payload.title, 100)
    if not title:
        raise HTTPException(status_code=400, detail="タイトルは必須です")
    subject = (payload.subject or "").strip()
    if subject not in _STUDY_SUBJECTS:
        raise HTTPException(status_code=400, detail="科目が不正です")
    material = _sanitize_text(payload.material, 200)
    note = _sanitize_text(payload.note, 1000)
    sd, ed = _validate_plan_dates(payload.start_date, payload.end_date)
    color = _validate_plan_color(payload.color) or '#6366f1'

    target_minutes = None
    if payload.target_minutes is not None:
        try:
            tm = int(payload.target_minutes)
            if tm < 0 or tm > 60000:
                raise HTTPException(status_code=400, detail="目標分数は 0〜60000 で指定してください")
            target_minutes = tm
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="目標分数が不正です")

    target_pages = None
    if payload.target_pages is not None:
        try:
            tp = int(payload.target_pages)
            if tp < 0 or tp > 100000:
                raise HTTPException(status_code=400, detail="目標ページは 0〜100000 で指定してください")
            target_pages = tp
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="目標ページが不正です")

    # 📅 隔日学習計画 (2026-05-22 塾長指示): week_pattern validate
    week_pattern = _validate_week_pattern(payload.week_pattern)

    conn = db()
    try:
        c = conn.cursor()
        try:
            c.execute(
                "INSERT INTO study_plans (student_id, title, subject, material, start_date, end_date, target_minutes, target_pages, color, note, week_pattern) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?) RETURNING id",
                (student["id"], title, subject, material, sd.isoformat(), ed.isoformat(), target_minutes, target_pages, color, note, week_pattern)
            )
            returned = c.fetchone()
            new_id = returned["id"] if returned else None
            conn.commit()
        except IntegrityError:
            conn.rollback()
            raise HTTPException(status_code=409, detail="同じ内容の計画が既に存在します (subject + 教材 + 期間が一致)")
        log.info(f"[StudyPlan] create id={new_id} student={student['id']} subj={subject}")
        return {"ok": True, "id": new_id}
    finally:
        conn.close()


@app.put("/api/study-plans/{plan_id}")
def update_study_plan(plan_id: int, payload: StudyPlanUpdateRequest, request: Request, authorization: Optional[str] = Header(None)):
    """生徒が自分の学習計画を更新。"""
    _check_rate_limit_caller(request, authorization, bucket="study_plan_update", limit=30, window=60)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)

    conn = db()
    try:
        c = conn.cursor()
        c.execute("SELECT student_id, start_date, end_date FROM study_plans WHERE id = ?", (plan_id,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="計画が見つかりません")
        if int(row["student_id"]) != int(student["id"]):
            raise HTTPException(status_code=403, detail="権限がありません")

        # 更新するフィールドのみ抽出
        updates = {}
        if payload.title is not None:
            t = _sanitize_text(payload.title, 100)
            if not t:
                raise HTTPException(status_code=400, detail="タイトルは必須です")
            updates["title"] = t
        if payload.subject is not None:
            if payload.subject not in _STUDY_SUBJECTS:
                raise HTTPException(status_code=400, detail="科目が不正です")
            updates["subject"] = payload.subject
        if payload.material is not None:
            updates["material"] = _sanitize_text(payload.material, 200)
        if payload.note is not None:
            updates["note"] = _sanitize_text(payload.note, 1000)
        if payload.color is not None:
            updates["color"] = _validate_plan_color(payload.color) or '#6366f1'
        if payload.status is not None:
            if payload.status not in _PLAN_STATUSES:
                raise HTTPException(status_code=400, detail="status が不正です")
            updates["status"] = payload.status

        # 日付は両方 or どちらかが来た時に validate
        if payload.start_date is not None or payload.end_date is not None:
            new_sd = payload.start_date or str(row["start_date"])
            new_ed = payload.end_date or str(row["end_date"])
            sd, ed = _validate_plan_dates(new_sd, new_ed)
            updates["start_date"] = sd.isoformat()
            updates["end_date"] = ed.isoformat()

        if payload.target_minutes is not None:
            try:
                tm = int(payload.target_minutes)
                if tm < 0 or tm > 60000:
                    raise HTTPException(status_code=400, detail="目標分数は 0〜60000")
                updates["target_minutes"] = tm
            except (TypeError, ValueError):
                raise HTTPException(status_code=400, detail="目標分数が不正です")
        if payload.target_pages is not None:
            try:
                tp = int(payload.target_pages)
                if tp < 0 or tp > 100000:
                    raise HTTPException(status_code=400, detail="目標ページは 0〜100000")
                updates["target_pages"] = tp
            except (TypeError, ValueError):
                raise HTTPException(status_code=400, detail="目標ページが不正です")

        # 📅 隔日学習計画 (2026-05-22 塾長指示): week_pattern 更新
        if payload.week_pattern is not None:
            updates["week_pattern"] = _validate_week_pattern(payload.week_pattern)

        if not updates:
            return {"ok": True, "no_change": True}

        # updated_at も更新
        if USE_POSTGRES:
            updates["updated_at"] = datetime.now(timezone.utc).isoformat()
        else:
            updates["updated_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
        set_clause = ", ".join([f"{k} = ?" for k in updates.keys()])
        # WHERE id AND student_id (TOCTOU 防御: SELECT 後の race で他生徒の row を更新しないように二重ガード)
        c.execute(f"UPDATE study_plans SET {set_clause} WHERE id = ? AND student_id = ?", tuple(updates.values()) + (plan_id, student["id"]))
        conn.commit()
        log.info(f"[StudyPlan] update id={plan_id} student={student['id']}")
        return {"ok": True}
    finally:
        conn.close()


@app.delete("/api/study-plans/{plan_id}")
def delete_my_study_plan(plan_id: int, request: Request, authorization: Optional[str] = Header(None)):
    """生徒が自分の学習計画を削除。"""
    _check_rate_limit_caller(request, authorization, bucket="study_plan_delete", limit=20, window=60)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)

    conn = db()
    try:
        c = conn.cursor()
        c.execute("SELECT student_id FROM study_plans WHERE id = ?", (plan_id,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="計画が見つかりません")
        if int(row["student_id"]) != int(student["id"]):
            raise HTTPException(status_code=403, detail="権限がありません")
        c.execute("DELETE FROM study_plans WHERE id = ? AND student_id = ?", (plan_id, student["id"]))
        conn.commit()
        log.info(f"[StudyPlan] delete id={plan_id} student={student['id']}")
        return {"ok": True}
    finally:
        conn.close()


def _enrich_plans_with_progress(c, plans: List[dict]) -> List[dict]:
    """plans 配列に study_logs から集計した progress (実績分数/ページ + 達成率) を付与。
    バッチ化: 全生徒分の logs を 1 クエリで取得し Python 側で fold。N+1 回避。
    """
    if not plans:
        return plans

    student_ids = list({int(p["student_id"]) for p in plans})
    if not student_ids:
        return plans
    placeholders = ",".join(["?"] * len(student_ids))
    c.execute(
        f"""SELECT student_id, subject, COALESCE(material,'') AS mkey,
                   studied_date, COALESCE(SUM(minutes),0) AS m, COALESCE(SUM(pages),0) AS p
            FROM study_logs WHERE student_id IN ({placeholders})
            GROUP BY student_id, subject, COALESCE(material,''), studied_date""",
        tuple(student_ids)
    )
    daily_rows = c.fetchall()
    # (sid, subj, mkey) -> sorted list of (date_str, m, p)
    bucket = {}
    for r in daily_rows:
        key = (int(r["student_id"]), r["subject"], r["mkey"] or '')
        bucket.setdefault(key, []).append((str(r["studied_date"]), int(r["m"] or 0), int(r["p"] or 0)))

    for p in plans:
        sid = int(p["student_id"])
        subj = p["subject"]
        mat_key = (p.get("material") or '') if p.get("material") else None
        sd = str(p["start_date"])
        ed = str(p["end_date"])
        actual_min = 0
        actual_pages = 0
        # material 指定なし → subject 全 material 合算 / 指定あり → 完全一致のみ
        if mat_key is None:
            for (sub_key, lst) in bucket.items():
                if sub_key[0] == sid and sub_key[1] == subj:
                    for (d, m, pp) in lst:
                        if sd <= d <= ed:
                            actual_min += m
                            actual_pages += pp
        else:
            lst = bucket.get((sid, subj, mat_key), [])
            for (d, m, pp) in lst:
                if sd <= d <= ed:
                    actual_min += m
                    actual_pages += pp
        p["actual_minutes"] = actual_min
        p["actual_pages"] = actual_pages
        if p.get("target_minutes"):
            p["progress_minutes_pct"] = min(100, round(actual_min / p["target_minutes"] * 100, 1))
        else:
            p["progress_minutes_pct"] = None
        if p.get("target_pages"):
            p["progress_pages_pct"] = min(100, round(actual_pages / p["target_pages"] * 100, 1))
        else:
            p["progress_pages_pct"] = None
    return plans


@app.get("/api/study-plans/me")
def get_my_study_plans(authorization: Optional[str] = Header(None), status: Optional[str] = None):
    """生徒が自分の学習計画 + 進捗を取得。"""
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)
    if status and status not in _PLAN_STATUSES:
        raise HTTPException(status_code=400, detail="status が不正です")

    conn = db()
    try:
        c = conn.cursor()
        if status:
            c.execute(
                "SELECT id, student_id, title, subject, material, start_date, end_date, target_minutes, target_pages, color, status, note, week_pattern, created_at "
                "FROM study_plans WHERE student_id = ? AND status = ? ORDER BY start_date DESC",
                (student["id"], status)
            )
        else:
            c.execute(
                "SELECT id, student_id, title, subject, material, start_date, end_date, target_minutes, target_pages, color, status, note, week_pattern, created_at "
                "FROM study_plans WHERE student_id = ? ORDER BY start_date DESC",
                (student["id"],)
            )
        rows = c.fetchall()
        plans = []
        for r in rows:
            plans.append({
                "id": r["id"],
                "student_id": r["student_id"],
                "title": r["title"],
                "subject": r["subject"],
                "material": r["material"],
                "start_date": str(r["start_date"]),
                "end_date": str(r["end_date"]),
                "target_minutes": r["target_minutes"],
                "target_pages": r["target_pages"],
                "color": r["color"] or '#6366f1',
                "status": r["status"],
                "note": r["note"],
                "week_pattern": (r["week_pattern"] if "week_pattern" in r.keys() else 'all') or 'all',
                "created_at": str(r["created_at"]) if r["created_at"] else None,
            })
        plans = _enrich_plans_with_progress(c, plans)
        return {"ok": True, "plans": plans, "count": len(plans)}
    finally:
        conn.close()


# 📚 マイ参考書/問題集 endpoints (塾長指示 2026-05-14)
# 生徒が「自分で使っている参考書」を登録し、カリキュラム AI 生成時に継続使用前提で組み込む
_MATERIAL_STATUSES = {"using", "completed", "paused"}
# SSoT: 既存の _STUDY_SUBJECTS を参照 (将来 "韓国語" 等を追加した時の整合性破綻を防止)
_MATERIAL_SUBJECTS = _STUDY_SUBJECTS


class StudentMaterialCreateRequest(BaseModel):
    name: str
    subject: str
    status: Optional[str] = "using"
    note: Optional[str] = None


class StudentMaterialUpdateRequest(BaseModel):
    name: Optional[str] = None
    subject: Optional[str] = None
    status: Optional[str] = None
    note: Optional[str] = None


@app.post("/api/student/parent-email")
async def student_set_parent_email(request: Request, authorization: Optional[str] = Header(None)):
    """📊 保護者 email 設定 (本人 only・塾長指示 2026-05-26)
    POST body: {"parent_email": "...", "enabled": true/false}
    enabled=false で配信停止 (parent_email は保持)
    """
    _check_rate_limit_ip(request, bucket="parent_email_set", limit=10, window=60)
    if not (authorization and authorization.startswith("Bearer ")):
        raise HTTPException(status_code=403, detail="ログインが必要です")
    token = authorization[len("Bearer "):].strip()
    claims = _verify_session_token(token)
    if not claims or not claims.get("student_id"):
        raise HTTPException(status_code=403, detail="認証エラー")
    try:
        student_id = int(claims["student_id"])
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="student_id 不正")
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="JSON body 不正")
    parent_email = (body.get("parent_email") or "").strip()
    enabled = 1 if body.get("enabled", True) else 0
    # email format 簡易 validate
    import re as _re
    if parent_email and not _re.match(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", parent_email):
        raise HTTPException(status_code=400, detail="メールアドレスの形式が不正です")
    if len(parent_email) > 200:
        raise HTTPException(status_code=400, detail="email が長すぎます")
    conn = db()
    try:
        c = conn.cursor()
        c.execute(
            "UPDATE students SET parent_email = ?, parent_email_enabled = ? WHERE id = ?",
            (parent_email or None, enabled, student_id),
        )
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "parent_email": parent_email or None, "enabled": bool(enabled)}


@app.get("/api/student/parent-email")
def student_get_parent_email(request: Request, authorization: Optional[str] = Header(None)):
    """📊 保護者 email 取得 (本人 only)"""
    _check_rate_limit_ip(request, bucket="parent_email_get", limit=30, window=60)
    if not (authorization and authorization.startswith("Bearer ")):
        raise HTTPException(status_code=403, detail="ログインが必要です")
    token = authorization[len("Bearer "):].strip()
    claims = _verify_session_token(token)
    if not claims or not claims.get("student_id"):
        raise HTTPException(status_code=403, detail="認証エラー")
    try:
        student_id = int(claims["student_id"])
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="student_id 不正")
    conn = db()
    try:
        c = conn.cursor()
        c.execute("SELECT parent_email, COALESCE(parent_email_enabled, 1) AS enabled FROM students WHERE id = ?", (student_id,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="生徒が見つかりません")
        try:
            pe = row["parent_email"]; en = row["enabled"]
        except (TypeError, KeyError, IndexError):
            pe = row[0]; en = row[1]
        return {"parent_email": pe or "", "enabled": bool(en)}
    finally:
        conn.close()


@app.post("/api/student/materials")
def create_student_material(payload: StudentMaterialCreateRequest, request: Request, authorization: Optional[str] = Header(None)):
    """生徒: マイ参考書を登録。"""
    _check_rate_limit_ip(request, bucket="sm_create", limit=30, window=60)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)
    name = _sanitize_text(payload.name, 120)
    if not name:
        raise HTTPException(status_code=400, detail="参考書名は必須")
    subject = _sanitize_text(payload.subject, 30)
    if subject not in _MATERIAL_SUBJECTS:
        raise HTTPException(status_code=400, detail=f"科目が不正です (許可: {', '.join(sorted(_MATERIAL_SUBJECTS))})")
    status = (payload.status or "using").strip()
    if status not in _MATERIAL_STATUSES:
        raise HTTPException(status_code=400, detail="status は using/completed/paused")
    note = _sanitize_text(payload.note, 300) if payload.note else None
    conn = db()
    try:
        c = conn.cursor()
        try:
            # RETURNING で 1 query 完結 (race-safe・既存 study_plans/curricula と統一)
            c.execute(
                "INSERT INTO student_materials (student_id, name, subject, status, note) "
                "VALUES (?,?,?,?,?) RETURNING id, name, subject, status, note, created_at",
                (student["id"], name, subject, status, note)
            )
            row = c.fetchone()
            conn.commit()
        except IntegrityError:
            try: conn.rollback()
            except Exception: pass
            raise HTTPException(status_code=409, detail="同じ参考書名・科目で既に登録済みです")
        log.info(f"[StudentMaterial] create student={student['id']} name={name} subject={subject}")
        return {
            "ok": True,
            "material": {
                "id": row["id"], "name": row["name"], "subject": row["subject"],
                "status": row["status"], "note": row["note"],
                "created_at": str(row["created_at"]) if row["created_at"] else None,
            }
        }
    finally:
        conn.close()


