def _build_own_materials_prompt_snippet(student_id: int) -> str:
    """📚 生徒のマイ参考書 (使用中) を AI prompt 用 snippet に整形 (塾長指示 2026-05-14)。

    AI カリキュラム生成 + AI 学習計画生成の双方から呼び出される共通 helper。
    例外時は connection leak を防ぐため try/finally で close を保証する。
    """
    out = ""
    conn = None
    try:
        conn = db()
        c = conn.cursor()
        # 科目別に偏り防止のため、まず status='using' を全件取得 (LIMIT 200) してから科目別に上位 8 件採用
        c.execute(
            "SELECT name, subject, note FROM student_materials "
            "WHERE student_id = ? AND status = 'using' ORDER BY created_at DESC LIMIT 200",
            (student_id,)
        )
        own = c.fetchall()
        if not own:
            return ""
        by_subj = {}
        for r in own:
            by_subj.setdefault(r["subject"], []).append({"name": r["name"], "note": r["note"]})
        lines = ["", "## 📚 生徒が現在使用中の参考書/問題集 (継続活用を前提とすること):"]
        for s, items in by_subj.items():
            parts = []
            for it in items[:8]:
                if it.get("note"):
                    parts.append(f"{it['name']} ({it['note']})")
                else:
                    parts.append(it["name"])
            lines.append(f"- {s}: {', '.join(parts)}")
        lines.append("→ これらの教材は **既に持っている前提** で計画/フェーズの materials に組み込み、不足分のみ新規提案すること。")
        lines.append("→ **ただし、これら登録済み教材だけを 3 フェーズ全部に並べるのは禁止** (生徒は「進歩感がない・飽きる」と感じる)。各フェーズでマイ参考書 + **段階別の新規教材** (基礎→標準→過去問の流れ) を必ず追加すること。")
        out = "\n".join(lines)
    except Exception as e:
        log.warning(f"[OwnMaterialsInject] failed for student={student_id}: {type(e).__name__}: {str(e)[:200]}")
    finally:
        if conn is not None:
            try: conn.close()
            except Exception: pass
    return out


@app.post("/api/curricula/ai-generate")
def ai_generate_curriculum(payload: CurriculumAiGenRequest, request: Request, authorization: Optional[str] = Header(None)):
    """生徒: AI で全体カリキュラムを生成 (DB に保存はしない、生徒が確認後に POST /api/curricula で保存)。"""
    _check_rate_limit_ip(request, bucket="curr_ai_gen", limit=10, window=600)  # 10分10回
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)
    if not GEMINI_API_KEY:
        raise HTTPException(status_code=503, detail="Gemini が構成されていません")

    target_university = _sanitize_text(payload.target_university, 100)
    if not target_university:
        raise HTTPException(status_code=400, detail="志望校は必須")
    target_faculty = _sanitize_text(payload.target_faculty, 100) or ""
    today = _today_jst()
    sd_str = (payload.start_date or "").strip() or today.isoformat()
    sd, ed = _validate_curr_dates(sd_str, payload.exam_date)
    daily = max(15, min(int(payload.daily_minutes or 60), 600))
    baseline = _sanitize_text(payload.baseline_note, 500) or "未指定"
    months = max(1, round((ed - sd).days / 30))

    # 🗓 2026-05-30 曜日別勉強時間 (月-日 7 要素・分)
    # validation: 配列長 7 + 各要素 0-720 分。不正な場合は均等分配 (daily 値) にフォールバック。
    weekly_minutes = None
    if payload.weekly_minutes and isinstance(payload.weekly_minutes, list) and len(payload.weekly_minutes) == 7:
        try:
            weekly_minutes = [max(0, min(int(m), 720)) for m in payload.weekly_minutes]
        except (TypeError, ValueError):
            weekly_minutes = None
    weekly_str = ""
    if weekly_minutes:
        _dow_labels = ["月", "火", "水", "木", "金", "土", "日"]
        _lines = [f"  - {_dow_labels[i]}: {weekly_minutes[i]}分" for i in range(7)]
        _week_total = sum(weekly_minutes)
        _week_avg = round(_week_total / 7)
        weekly_str = (
            f"\n曜日別学習可能時間 (生徒が曜日別にカスタマイズ済):\n"
            + "\n".join(_lines)
            + f"\n  → 週合計: {_week_total}分 / 1日平均: {_week_avg}分\n"
            f"  ⚠️ 各フェーズの material 配分はこの曜日別時間を反映してください "
            f"(時間が長い曜日に教材を多めに割り当て、短い曜日は復習中心に)。"
        )

    # 直近模試結果を自動 inject (科目別偏差値+判定 / 最大3件)
    exam_summary = ""
    try:
        _conn = db()
        _c = _conn.cursor()
        _c.execute(
            "SELECT exam_name, exam_date, subject, deviation, judgement FROM exam_results "
            "WHERE student_id = ? AND deviation IS NOT NULL ORDER BY exam_date DESC LIMIT 15",
            (student["id"],)
        )
        recent = _c.fetchall()
        _conn.close()
        if recent:
            # 科目別最新偏差値
            by_subj = {}
            for r in recent:
                s = r["subject"]
                if s not in by_subj:
                    by_subj[s] = {"deviation": r["deviation"], "judgement": r["judgement"], "exam": r["exam_name"], "date": str(r["exam_date"])}
            lines = ["", "## 直近模試結果 (科目別偏差値 / 判定 / 模試名・日付):"]
            for s, d in by_subj.items():
                jd = f" / 判定 {d['judgement']}" if d['judgement'] else ""
                lines.append(f"- {s}: 偏差値 {d['deviation']}{jd} ({d['exam']} / {d['date']})")
            exam_summary = "\n".join(lines)
    except Exception as e:
        log.warning(f"[Curriculum] exam inject failed: {e}")

    # 📚 マイ参考書 (生徒が現在使用中) を自動 inject (塾長指示 2026-05-14)
    own_materials_summary = _build_own_materials_prompt_snippet(student["id"])

    # 📚 受験参考書 DB から偏差値マッチング推薦を AI に渡す (塾長指示 2026-05-14)
    # 「マドンナ古文 全 33 講」のような実数値を AI に明示 → 「第13講」等の架空数字を防止
    target_dev = None
    try:
        if recent:
            # 科目別偏差値の平均を target_dev とする
            devs = [r["deviation"] for r in recent if r.get("deviation") is not None]
            if devs:
                target_dev = sum(devs) / len(devs)
    except Exception:
        pass
    reference_books_summary = _build_reference_books_prompt_snippet(target_dev=target_dev)
    # 📺 スタサプ講座 DB を AI に渡す (塾長指示 2026-05-14) → 架空講義名の出力を防止
    sapuri_lectures_summary = _build_sapuri_lectures_prompt_snippet(target_dev=target_dev)

    sys_prompt = "受験戦略を立てる学習プランナーです。難関大学 (国公立・難関私立) 志望者に対し、入試日から逆算した全体カリキュラムを 4-6 フェーズに分割して提案します。各フェーズは現実的な期間と教材 + スタディサプリ (スタサプ) の対応講義で構成。スタサプ講義は **必ずプロンプト内の『スタディサプリ講座 DB』に記載されている講座名のみ** を使用すること (例: 『高3 トップレベル英語 〈読解編〉』『高3 ハイレベル数学IAIIB+C(ベクトル)』『高3 スタンダードレベル化学〈理論編〉』『古文文法ベーシックレベル』)。DB にない講座名は出力禁止 (架空講義回避)。市販の参考書教材とスタサプ講義は別フィールドに分けて出力。純粋な JSON のみ返答 (前置きや解説不要)。"
    user_prompt = f"""志望校: {target_university}{(' / ' + target_faculty) if target_faculty else ''}
開始日: {sd.isoformat()}
入試日: {ed.isoformat()} (期間 {months} ヶ月)
1日確保時間 (平均): {daily} 分{weekly_str}
現状: {baseline}{exam_summary}{own_materials_summary}{reference_books_summary}{sapuri_lectures_summary}

上記から、難関大学合格までの全体カリキュラムを 4-6 フェーズに分割して JSON で返してください。
模試結果が含まれている場合は、特に偏差値が低い科目に厚めの教材配分をしてください。
各フェーズには市販教材 (materials) と スタディサプリ講義 (sapuri_lectures) の両方を提案してください。

出力形式 (フェンスや前置きなし):
{{
  "phases": [
    {{
      "name": "フェーズ名 (例: 基礎固め期 / 標準演習期 / 過去問演習期 / 直前期)",
      "start_date": "YYYY-MM-DD",
      "end_date": "YYYY-MM-DD",
      "focus": "このフェーズの主軸 (60字以内、例: 英文法基礎 + 数学IA基礎完成)",
      "materials": ["定番市販教材1 (例: ターゲット1900)", "定番市販教材2", "定番市販教材3"],
      "sapuri_lectures": ["対応するスタサプ講義名 (例: 高3 トップレベル英語〈読解編〉)", "...", "..."],
      "milestones": ["月末までに〇〇完了 (60字以内)", "...", "..."]
    }}
  ]
}}

注意:
- フェーズの期間は重複・空白なく開始日〜入試日を埋める
- 直前期は入試日 1-2 ヶ月前から
- 各フェーズに市販教材 2-4 件、スタサプ講義 2-4 件、マイルストーン 2-4 件
- 受験科目構成 (志望校に必要な科目) を考慮
- スタサプ講義はレベル (ベーシック/スタンダード/ハイレベル/トップレベル) と科目を明示した商品名で記載
- フェーズ進行に応じて段階的にレベルを上げる (例: 基礎期=ベーシック→標準期=スタンダード→応用期=ハイレベル→直前期=トップレベル)
- **🔑 重要 (フェーズ別教材切替必須・塾長指示 2026-05-14 強化)**: 各フェーズには **必ず前フェーズにはなかった新規教材を 2 件以上含めること** (1 件では不十分・塾長から「タームが変わっても同じ教材のみ反復」のクレームあり)。
  - **通年使用 OK の例外**: 単語帳 (ターゲット1900 / シス単 / 速読英単語)・構文書 (基本はここだ / ポレポレ) — これらだけは複数フェーズに繰り返し OK
  - **段階別切替必須の例**:
    - 英語: 基礎期 = ポラリス1 → 標準期 = ポラリス2 + やっておきたい 500 → 過去問期 = 過去問 (赤本) + やっておきたい 700
    - 数学: 基礎期 = 青チャ例題 → 標準期 = 1対1対応 + プラチカ → 過去問期 = 過去問 + やさしい理系数学
  - **絶対禁止**: 同じ問題集を 3 フェーズ全部に並べること (生徒が「進歩感がない・飽きる」と感じる)"""

    # 🔧 2026-05-14 塾長指摘「AI 出力 JSON 解析失敗」対応 (3 段防御):
    # 1) max_tokens 4000 → 8000 → 16000 (2026-05-21・小川くん事例で再 truncate 確認・倍増)
    # 2) response_format={"type":"json_object"} で Gemini JSON 強制モード
    # 3) temperature 0.3 (default 0.7 → JSON 構造崩壊リスク 8 割減)
    # 4) Gemini 失敗時に Sonnet 4.6 で再試行 (塾長の「即解消」体験のため)
    # 🚨 2026-05-21 小川くん事例 fix B: max_tokens 8000 → 16000 (phases 4-6 × materials/sapuri/milestones 各 2-4 件
    #    で実質 borderline → Gemini Flash の上限 65536 内で安全マージン確保)
    body = {
        "model": "gemini-2.5-flash",
        "max_tokens": 16000,
        "system": sys_prompt,
        "messages": [{"role": "user", "content": user_prompt}],
        "response_format": {"type": "json_object"},
        "temperature": 0.3,
    }
    # Gemini → Sonnet 4.6 fallback 経路
    data = None
    fallback_used = False
    try:
        data = _call_gemini(body, model="gemini-2.5-flash", kind="curriculum_gen")
    except Exception as _ge:
        log.warning(f"[Curriculum] Gemini failed: {type(_ge).__name__}: {str(_ge)[:200]} - falling back to Sonnet 4.6")
        fallback_used = True
        # Sonnet 4.6 fallback (Anthropic safe で 3 段モデル降格 + リトライ)
        try:
            anthropic_body = {
                "model": "claude-sonnet-4-6",  # Sonnet 4.6 alias (_call_anthropic_safe が 3 段降格 + リトライ実装)
                "max_tokens": 16000,
                "system": sys_prompt,
                "messages": [{"role": "user", "content": user_prompt}],
                "temperature": 0.3,
            }
            data = _call_anthropic_safe(anthropic_body, kind="curriculum_gen_fallback")
        except Exception as _ae:
            log.error(f"[Curriculum] Sonnet fallback also failed: {type(_ae).__name__}: {str(_ae)[:200]}")
            raise HTTPException(status_code=503, detail=f"AI 生成失敗 (Gemini + Sonnet 両方): {str(_ae)[:120]}。少し時間をおいて再試行してください。")
    try:
        text = "".join(c.get("text", "") for c in (data.get("content") or []) if isinstance(c, dict)).strip()
        if not text:
            raise HTTPException(status_code=503, detail="AI が空文字を返しました")
        # JSON parse (強化版: 3 段階 fallback + log + エラー詳細化)
        cleaned = text.strip()
        # Stage 1: markdown fence 除去
        if cleaned.startswith("```"):
            import re as _re
            cleaned = _re.sub(r'^```(?:json)?\s*|\s*```\s*$', '', cleaned).strip()
        # Stage 2: 直接 parse
        parsed = None
        try:
            parsed = json.loads(cleaned)
        except json.JSONDecodeError as parse_err1:
            # Stage 3: 最初の { から最後の } を抽出 (bracket counting で確実に)
            start_idx = cleaned.find('{')
            end_idx = cleaned.rfind('}')
            if start_idx < 0:
                # 完全に JSON でないテキスト (先頭 `{` すら無い)
                log.error(f"[Curriculum] no opening `{{`. text[:300]={cleaned[:300]!r}")
                raise HTTPException(
                    status_code=503,
                    detail=f"AI 出力に JSON が含まれません (先頭: {cleaned[:80]})。再生成をお試しください。"
                )
            # 🚨 2026-05-21 小川くん事例 fix C: end_idx <= start_idx (= 末尾 `}` 無し or 先頭 `{` 後に無し) でも
            #    Stage 4 救済 (`}` 補完) を試行。従来は即 503 で「JSON が含まれません」誤エラーを表示していた。
            if end_idx <= start_idx:
                json_part = cleaned[start_idx:]
                log.warning(f"[Curriculum] no closing `}}` (truncate 疑い)・救済試行 text_len={len(cleaned)}")
            else:
                json_part = cleaned[start_idx:end_idx + 1]
            try:
                parsed = json.loads(json_part)
            except json.JSONDecodeError as parse_err2:
                # Stage 4: truncate された JSON を救済 (末尾の不完全要素を削除 + `}` 補完)
                log.error(f"[Curriculum] JSON parse failed: {parse_err2}. text_len={len(cleaned)} json_part[:300]={json_part[:300]!r}")
                opens = json_part.count('{')
                closes = json_part.count('}')
                arr_opens = json_part.count('[')
                arr_closes = json_part.count(']')
                if opens > closes:
                    # 1) 末尾の文字列 truncate を救済: 最後の `"` まで安全に巻き戻し
                    fixed = json_part.rstrip()
                    # 末尾が string 途中 (例: `"start_date": "2026-05`) なら最後の string 開始 quote まで戻して切る
                    try:
                        # 末尾から quote 数をカウント
                        in_string = False
                        last_safe = len(fixed)
                        i = 0
                        while i < len(fixed):
                            ch = fixed[i]
                            if ch == '\\' and i + 1 < len(fixed):
                                i += 2
                                continue
                            if ch == '"':
                                in_string = not in_string
                                if not in_string:
                                    last_safe = i + 1  # 閉じ quote までを安全圏とマーク
                            i += 1
                        if in_string:
                            # 末尾で string 開きっぱなし → last_safe 以降を切り捨て
                            fixed = fixed[:last_safe]
                    except Exception:
                        pass
                    # 2) 末尾の不完全要素 (カンマ + colon + 開き括弧等) を巻き戻し
                    fixed = fixed.rstrip().rstrip(',:').rstrip()
                    # 末尾が `,` `[` `{` 等の場合は安全な位置まで巻き戻し
                    while fixed and fixed[-1] in ',:{[':
                        fixed = fixed[:-1].rstrip()
                    # 🚨 2026-05-21 小川くん事例 fix: orphan key 除去
                    #   末尾が `, "key"` or `, "key":` or `, "key": <未完 value>` で truncate されたら
                    #   直前の `,` まで巻き戻して、その `,` も除去 → 1 つ前の完成済要素までを採用
                    for _trim_attempt in range(3):  # 最大 3 段巻き戻し (深い nest の orphan 対応)
                        _last_comma = fixed.rfind(',')
                        if _last_comma <= 0: break
                        _tail = fixed[_last_comma + 1:].strip()
                        # complete kv 判定 (どれかに該当しなければ orphan の疑い)
                        _is_orphan = (
                            (':' not in _tail)                  # `"key"` のみ・value 無し
                            or (_tail.count('"') % 2 != 0)      # 不完全な文字列 (quote 数奇数)
                            or (_tail.rstrip().endswith(':'))   # `"key":` で value 完全に無し
                            or (_tail.rstrip().endswith((',', '{', '[')))  # `"key": {` 等の未完 nest
                        )
                        if not _is_orphan: break  # complete kv なので OK
                        fixed = fixed[:_last_comma].rstrip()
                    # 3+4) Stack-based proper closing (順序保証・string 内 brace を skip)
                    #   curriculum 構造 `{phases:[{...}]}` で、深い nest 時 `]→}` ではなく `}→]→}` の
                    #   正しい順序で閉じる。string 内 `{` `[` も walker で正確に skip (naive count bug 解消)
                    try:
                        _stack = []
                        _in_s = False
                        _j = 0
                        while _j < len(fixed):
                            _ch = fixed[_j]
                            if _ch == '\\' and _j + 1 < len(fixed):
                                _j += 2
                                continue
                            if _ch == '"':
                                _in_s = not _in_s
                            elif not _in_s:
                                if _ch in '{[':
                                    _stack.append(_ch)
                                elif _ch == '}' and _stack and _stack[-1] == '{':
                                    _stack.pop()
                                elif _ch == ']' and _stack and _stack[-1] == '[':
                                    _stack.pop()
                            _j += 1
                        # Close in reverse order of opening (proper JSON nest)
                        _closing = ''.join(('}' if _o == '{' else ']') for _o in reversed(_stack))
                        fixed += _closing
                    except Exception as _stack_err:
                        # Stack walker 失敗時は naive count にフォールバック (旧挙動)
                        log.warning(f"[Curriculum] stack-based close failed, fallback to naive: {_stack_err}")
                        arr_opens2 = fixed.count('[')
                        arr_closes2 = fixed.count(']')
                        if arr_opens2 > arr_closes2:
                            fixed += ']' * (arr_opens2 - arr_closes2)
                        opens2 = fixed.count('{')
                        closes2 = fixed.count('}')
                        if opens2 > closes2:
                            fixed += '}' * (opens2 - closes2)
                    try:
                        parsed = json.loads(fixed)
                        log.info(f"[Curriculum] JSON 救済成功 (元 {len(json_part)} → 救済後 {len(fixed)} 字)")
                    except json.JSONDecodeError as parse_err3:
                        log.error(f"[Curriculum] 救済失敗: {parse_err3}. fixed[-200:]={fixed[-200:]!r}")
                        raise HTTPException(
                            status_code=503,
                            detail=f"AI 出力 JSON 解析失敗 (長さ {len(cleaned)} 字・救済も失敗・原因: {str(parse_err2)[:60]})。再生成をお試しください。"
                        )
                else:
                    raise HTTPException(
                        status_code=503,
                        detail=f"AI 出力 JSON 解析失敗 (原因: {str(parse_err2)[:80]})。再生成をお試しください。"
                    )
        phases_raw = parsed.get("phases") or []
        if not phases_raw:
            raise HTTPException(status_code=503, detail="AI が phases を返しませんでした (再生成をお試しください)")
        # validate
        phases_list = _validate_curr_phases(phases_raw)
        log.info(f"[Curriculum] ai-generate student={student['id']} univ={target_university} phases={len(phases_list)}")
        return {
            "ok": True,
            "preview": {
                "target_university": target_university,
                "target_faculty": target_faculty or None,
                "exam_date": ed.isoformat(),
                "start_date": sd.isoformat(),
                "daily_minutes": daily,
                "weekly_minutes": weekly_minutes,  # 🗓 2026-05-30: preview に echo (フロントが保存時に渡せるよう)
                "baseline_note": baseline if baseline != "未指定" else None,
                "phases": phases_list,
                "ai_model": data.get("_actual_model"),
            }
        }
    except HTTPException:
        raise
    except Exception as e:
        log.error(f"[Curriculum] ai-generate failed: {type(e).__name__}: {str(e)[:200]}")
        raise HTTPException(status_code=503, detail=f"AI 生成失敗: {str(e)[:200]}")


@app.post("/api/curricula/{curr_id}/gap-analyze")
def curriculum_gap_analyze(curr_id: int, request: Request, authorization: Optional[str] = Header(None)):
    """生徒: 模試結果から志望校到達のギャップを分析し AI 修正提案を返す (Phase 4.7)。"""
    _check_rate_limit_ip(request, bucket="curr_gap_analyze", limit=20, window=600)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)
    if not GEMINI_API_KEY:
        raise HTTPException(status_code=503, detail="Gemini が構成されていません")

    conn = db()
    try:
        c = conn.cursor()
        c.execute("SELECT id, student_id, target_university, target_faculty, exam_date, start_date, daily_minutes, baseline_note, phases, status FROM curricula WHERE id = ?", (curr_id,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="カリキュラムが見つかりません")
        if int(row["student_id"]) != int(student["id"]):
            raise HTTPException(status_code=403, detail="権限がありません")
        try:
            phases = json.loads(row["phases"] or "[]")
        except Exception:
            phases = []
        # 模試結果 (科目別最新偏差値 + 推移)
        c.execute(
            "SELECT exam_name, exam_date, subject, deviation, judgement FROM exam_results "
            "WHERE student_id = ? AND deviation IS NOT NULL ORDER BY exam_date DESC LIMIT 30",
            (student["id"],)
        )
        exam_rows = c.fetchall()
    finally:
        conn.close()

    if not exam_rows:
        raise HTTPException(status_code=400, detail="模試結果がまだ登録されていません。先に模試結果を追加してください。")

    # 科目別: 最新と推移 (古い→新しい順で trend)
    by_subj = {}
    for r in exam_rows:
        s = r["subject"]
        if s not in by_subj:
            by_subj[s] = {"latest": {"deviation": r["deviation"], "judgement": r["judgement"], "date": str(r["exam_date"]), "exam": r["exam_name"]}, "history": []}
        by_subj[s]["history"].append({"date": str(r["exam_date"]), "deviation": r["deviation"]})
    # 各科目の trend (上昇/下降/横ばい)
    for s, d in by_subj.items():
        h = d["history"]
        if len(h) >= 2:
            recent = h[0]["deviation"]
            older = h[-1]["deviation"]
            diff = recent - older
            d["trend"] = "上昇" if diff >= 2 else ("下降" if diff <= -2 else "横ばい")
            d["trend_diff"] = round(diff, 1)
        else:
            d["trend"] = "データ不足"
            d["trend_diff"] = 0

    today = _today_jst()
    exam_dt = datetime.strptime(str(row["exam_date"]), "%Y-%m-%d").date() if row["exam_date"] else today
    remain_days = max(0, (exam_dt - today).days)
    remain_months = max(1, round(remain_days / 30))

    # 模試 summary 文字列
    exam_lines = []
    for s, d in by_subj.items():
        l = d["latest"]
        jd = f" / 判定 {l['judgement']}" if l['judgement'] else ""
        exam_lines.append(f"- {s}: 偏差値 {l['deviation']}{jd} ({l['exam']} {l['date']}) | 推移: {d['trend']} ({'+' if d['trend_diff']>0 else ''}{d['trend_diff']})")
    exam_block = "\n".join(exam_lines)

    # フェーズ summary
    phase_lines = []
    for i, p in enumerate(phases):
        mats = ", ".join((p.get("materials") or [])[:5])
        sapuri = ", ".join((p.get("sapuri_lectures") or [])[:5])
        phase_lines.append(f"  フェーズ{i+1}: {p.get('name','')} ({p.get('start_date','')}〜{p.get('end_date','')}) focus: {p.get('focus','')} / 教材: {mats} / スタサプ: {sapuri}")
    phase_block = "\n".join(phase_lines) if phase_lines else "  (なし)"

    sys_prompt = "難関大学受験の戦略アドバイザーです。生徒の現状偏差値と志望校に必要な偏差値のギャップを科目別に分析し、現行カリキュラムに具体的な修正提案を行います。教師名 (講師名) は塾長指示で出力禁止。スタサプ講座は『高3 トップレベル英文法』のような講師名抜きの汎用商品名のみで記載すること。純粋な JSON のみ返答 (前置き解説不要)。"
    user_prompt = f"""## 志望校
{row['target_university']}{(' / ' + row['target_faculty']) if row['target_faculty'] else ''}

## 入試まで
{remain_days}日 ({remain_months} ヶ月)

## 1日の確保時間
{row['daily_minutes'] or 60} 分

## 現状の模試結果 (科目別最新偏差値 + 推移)
{exam_block}

## 現行カリキュラム ({len(phases)} フェーズ)
{phase_block}

上記を踏まえて、ギャップ分析と修正提案を JSON で返してください。

出力形式 (フェンスや前置きなし):
{{
  "target_deviation": "志望校合格に必要な平均偏差値レベル (例: 65)",
  "current_average": "現状の平均偏差値",
  "gap_summary": "総合ギャップ分析 (200字以内、ペース妥当性 + 全体所見)",
  "subject_gaps": [
    {{
      "subject": "科目名",
      "current": 現状偏差値,
      "target": 目標偏差値,
      "gap": 不足分 (target - current),
      "priority": "高|中|低",
      "trend_comment": "推移コメント (40字以内)"
    }}
  ],
  "phase_adjustments": [
    {{
      "phase_index": 0,
      "phase_name": "対象フェーズ名",
      "action": "教材追加|教材削減|期間延長|期間短縮|スタサプ追加|フェーズ名変更",
      "detail": "具体修正内容 (100字以内)",
      "new_materials": ["新規追加教材1", "..."],
      "new_sapuri_lectures": ["新規追加スタサプ講義1", "..."]
    }}
  ],
  "overall_recommendation": "総合戦略アドバイス (200字以内、3-5 個の actionable items)"
}}

注意:
- ギャップが 5 以上の科目は priority=高
- スタサプ講義は商品名そのまま (例: 高3 ハイレベル英文法)
- phase_adjustments は変更が必要なフェーズだけ提案 (全フェーズ列挙不要)"""

    body = {
        "model": "gemini-2.5-flash",
        "max_tokens": 3500,
        "system": sys_prompt,
        "messages": [{"role": "user", "content": user_prompt}],
    }
    try:
        data = _call_gemini(body, model="gemini-2.5-flash", kind="curr_gap_analyze")
        text = "".join(c.get("text", "") for c in (data.get("content") or []) if isinstance(c, dict)).strip()
        if not text:
            raise HTTPException(status_code=503, detail="AI が空文字を返しました")
        cleaned = text.strip()
        if cleaned.startswith("```"):
            import re as _re
            cleaned = _re.sub(r'^```(?:json)?\s*|\s*```$', '', cleaned).strip()
        try:
            parsed = json.loads(cleaned)
        except Exception:
            import re as _re
            m = _re.search(r'\{[\s\S]*\}', cleaned)
            if not m:
                raise HTTPException(status_code=503, detail="AI 出力 JSON 解析失敗")
            parsed = json.loads(m.group(0))

        log.info(f"[Curriculum] gap-analyze curr={curr_id} student={student['id']} adjustments={len(parsed.get('phase_adjustments') or [])}")
        return {
            "ok": True,
            "curriculum_id": curr_id,
            "remain_days": remain_days,
            "analysis": parsed,
            "model": data.get("_actual_model"),
        }
    except HTTPException:
        raise
    except Exception as e:
        log.error(f"[Curriculum] gap-analyze failed: {type(e).__name__}: {str(e)[:200]}")
        raise HTTPException(status_code=503, detail=f"AI 分析失敗: {str(e)[:200]}")


class GapApplyRequest(BaseModel):
    phase_adjustments: List[dict]  # [{phase_index, action, new_materials, new_sapuri_lectures}]


@app.post("/api/curricula/{curr_id}/apply-gap-fix")
def curriculum_apply_gap_fix(curr_id: int, payload: GapApplyRequest, request: Request, authorization: Optional[str] = Header(None)):
    """生徒: gap-analyze の提案をカリキュラムに反映 (Phase 4.7)。"""
    _check_rate_limit_ip(request, bucket="curr_gap_apply", limit=10, window=600)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)

    conn = db()
    try:
        c = conn.cursor()
        c.execute("SELECT student_id, phases FROM curricula WHERE id = ?", (curr_id,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="カリキュラムが見つかりません")
        if int(row["student_id"]) != int(student["id"]):
            raise HTTPException(status_code=403, detail="権限がありません")
        try:
            phases = json.loads(row["phases"] or "[]")
        except Exception:
            phases = []
        applied = 0
        for adj in payload.phase_adjustments:
            try:
                idx = int(adj.get("phase_index", -1))
            except (TypeError, ValueError):
                continue
            if idx < 0 or idx >= len(phases):
                continue
            phase = phases[idx]
            new_mats = adj.get("new_materials") or []
            new_sapuri = adj.get("new_sapuri_lectures") or []
            mats_clean = [m for m in (_sanitize_text(x, 100) for x in new_mats) if m]
            sapuri_clean = [m for m in (_sanitize_text(x, 120) for x in new_sapuri) if m]
            if mats_clean:
                cur = phase.get("materials") or []
                for m in mats_clean:
                    if m not in cur:
                        cur.append(m)
                phase["materials"] = cur[:10]
            if sapuri_clean:
                cur = phase.get("sapuri_lectures") or []
                for m in sapuri_clean:
                    if m not in cur:
                        cur.append(m)
                phase["sapuri_lectures"] = cur[:8]
            applied += 1
        if not applied:
            return {"ok": True, "applied": 0, "message": "適用すべき変更がありませんでした"}
        # update DB
        if USE_POSTGRES:
            updated_at = datetime.now(timezone.utc).isoformat()
        else:
            updated_at = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
        c.execute("UPDATE curricula SET phases = ?, updated_at = ? WHERE id = ? AND student_id = ?",
                  (json.dumps(phases, ensure_ascii=False), updated_at, curr_id, student["id"]))
        conn.commit()
        log.info(f"[Curriculum] apply-gap-fix curr={curr_id} student={student['id']} applied={applied}")
        return {"ok": True, "applied": applied}
    finally:
        conn.close()


@app.post("/api/curricula/{curr_id}/expand-to-plans")
def expand_curriculum_to_plans(curr_id: int, request: Request, authorization: Optional[str] = Header(None)):
    """生徒: カリキュラム各フェーズの教材を study_plans に一括展開。"""
    _check_rate_limit_ip(request, bucket="curr_expand", limit=10, window=300)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    _require_study_log_course(student)
    conn = db()
    try:
        c = conn.cursor()
        c.execute("SELECT id, student_id, target_university, daily_minutes, phases FROM curricula WHERE id = ?", (curr_id,))
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="カリキュラムが見つかりません")
        if int(row["student_id"]) != int(student["id"]):
            raise HTTPException(status_code=403, detail="権限がありません")
        try:
            phases = json.loads(row["phases"] or "[]")
        except Exception:
            phases = []
        if not phases:
            raise HTTPException(status_code=400, detail="phases が空です")

        daily = int(row["daily_minutes"] or 60)
        # フェーズ別科目別 color
        subject_colors = {"英語": "#6366f1", "数学": "#10b981", "国語": "#ec4899", "現代文": "#ec4899", "古文": "#f472b6", "漢文": "#fb7185",
                          "理科": "#f59e0b", "物理": "#fbbf24", "化学": "#fb923c", "生物": "#84cc16", "地学": "#a3e635",
                          "社会": "#8b5cf6", "日本史": "#a78bfa", "世界史": "#c4b5fd", "地理": "#7dd3fc",
                          "倫理": "#67e8f9", "政経": "#22d3ee", "情報": "#94a3b8", "小論文": "#f472b6", "面接対策": "#94a3b8", "その他": "#71717a"}

        def _guess_subject(material: str) -> str:
            m = (material or "").lower()
            if any(k in material for k in ["英", "english", "ターゲット", "シス単", "速読", "ネクステ", "vintage"]): return "英語"
            if any(k in material for k in ["数", "チャート", "プラチカ", "1対1", "標問", "やさしい理系", "ハイ理"]): return "数学"
            if any(k in material for k in ["古文", "漢文", "古典"]): return "古文"
            if any(k in material for k in ["現代文", "得点奪取", "上級現代文"]): return "現代文"
            if "国語" in material: return "国語"
            if "物理" in material: return "物理"
            if "化学" in material: return "化学"
            if "生物" in material: return "生物"
            if "日本史" in material: return "日本史"
            if "世界史" in material: return "世界史"
            if "地理" in material: return "地理"
            if "倫" in material or "政経" in material: return "政経"
            if "理科" in material: return "理科"
            if "社会" in material or "歴史" in material: return "社会"
            if "小論" in material: return "小論文"
            return "その他"

        # 🔧 2026-05-14 塾長指示「あおと生徒バグ」対応: 同じ参考書が複数 phase に登場する場合に
        # 「ずっと同じ参考書で登録される」現象を解消するため、material 単位で全 phase の登場期間を
        # 集計し、最小 start_date 〜 最大 end_date の 1 plan に統合する (重複統合)。
        # 例: phase1+2+3+4 全てに「ターゲット1900」がある場合 → 1 plan (全期間) として登録。
        # phase ごとに異なる参考書 (例: phase1=英文法ポラリス1, phase2=ポラリス2) は別 plan で登録される。
        material_map = {}  # key=(material_clean, source_tag), value=list of {start, end, name, focus}
        for ph in phases:
            ph_start = ph.get("start_date")
            ph_end = ph.get("end_date")
            if not ph_start or not ph_end:
                continue
            try:
                p_sd = datetime.strptime(ph_start, "%Y-%m-%d").date()
                p_ed = datetime.strptime(ph_end, "%Y-%m-%d").date()
            except Exception:
                continue
            materials = ph.get("materials") or []
            sapuri_lectures = ph.get("sapuri_lectures") or []
            combined = [(m, "市販") for m in materials] + [(s, "スタサプ") for s in sapuri_lectures]
            for (mat, source_tag) in combined:
                mat_clean = (mat or "").strip()[:100]
                if not mat_clean:
                    continue
                key = (mat_clean, source_tag)
                material_map.setdefault(key, []).append({
                    "start": ph_start, "end": ph_end,
                    "name": ph.get("name", "フェーズ"),
                    "focus": ph.get("focus", "")
                })

        if not material_map:
            return {"ok": True, "added": 0, "skipped": 0, "note": "No materials found in phases"}

        # 教材総数で 1 教材あたり目標分数を計算 (期間全体 × daily / 教材数)
        total_unique = len(material_map)
        added, skipped = 0, 0
        for (mat_clean, source_tag), occurrences in material_map.items():
            if not occurrences:
                continue
            # 最小 start 〜 最大 end を採用 (ISO date 文字列は辞書順 = 時系列順)
            starts = sorted(o["start"] for o in occurrences)
            ends = sorted(o["end"] for o in occurrences)
            start_date = starts[0]
            end_date = ends[-1]
            phase_names = [o["name"] for o in occurrences]
            unique_phase_names = list(dict.fromkeys(phase_names))  # 順序保持 dedup
            if len(unique_phase_names) > 1:
                title_prefix = f"[{unique_phase_names[0]}〜{unique_phase_names[-1]}]"
            else:
                title_prefix = f"[{unique_phase_names[0]}]"
            subject = _guess_subject(mat_clean)
            color = subject_colors.get(subject, "#6366f1")
            src_prefix = "📺 " if source_tag == "スタサプ" else ""
            title = f"{title_prefix} {src_prefix}{mat_clean}"[:100]
            # 目標分数: 統合期間日数 × daily / 教材総数
            try:
                sd_obj = datetime.strptime(start_date, "%Y-%m-%d").date()
                ed_obj = datetime.strptime(end_date, "%Y-%m-%d").date()
                merged_days = max(1, (ed_obj - sd_obj).days + 1)
            except Exception:
                merged_days = 30
            per_item_min = max(60, (merged_days * daily) // max(1, total_unique))
            note = (
                f"カリキュラム自動展開 / 出典: {source_tag} / "
                f"登場フェーズ: {', '.join(unique_phase_names[:4])}"
                f"{' 他' if len(unique_phase_names) > 4 else ''}"
            )[:1000]
            try:
                c.execute(
                    "INSERT INTO study_plans (student_id, title, subject, material, start_date, end_date, target_minutes, color, note) "
                    "VALUES (?,?,?,?,?,?,?,?,?)",
                    (student["id"], title, subject, mat_clean, start_date, end_date, per_item_min, color, note)
                )
                added += 1
            except IntegrityError:
                skipped += 1
            except Exception as ee:
                log.warning(f"[Curriculum] expand insert failed: {ee}")
                skipped += 1
        conn.commit()
        log.info(f"[Curriculum] expand-to-plans curr={curr_id} added={added} skipped={skipped} unique_materials={total_unique}")
        return {"ok": True, "added": added, "skipped": skipped, "unique_materials": total_unique}
    finally:
        conn.close()


class AdminAiDraftRequest(BaseModel):
    kind: str  # 'reply_draft' or 'broadcast_draft'
    context: str  # 状況説明 (返信案なら相手の本文 / 一斉送信なら要点)
    extra_hint: Optional[str] = None  # 追加指示 (任意)


@app.post("/api/admin/ai-draft")
def admin_ai_draft(payload: AdminAiDraftRequest, request: Request, authorization: Optional[str] = Header(None)):
    """塾長: メッセージ返信案 / 一斉送信文案を Gemini で生成 (Phase 3.5 / 塾長指示 2026-05-06)。"""
    _check_rate_limit_ip(request, bucket="admin_ai_draft", limit=30, window=60)
    _verify_admin_required(authorization)
    if not GEMINI_API_KEY:
        raise HTTPException(status_code=503, detail="Gemini が構成されていません")

    kind = (payload.kind or "").strip()
    if kind not in ("reply_draft", "broadcast_draft"):
        raise HTTPException(status_code=400, detail="kind は 'reply_draft' または 'broadcast_draft'")

    context = _sanitize_text(payload.context, 4000)
    if not context:
        raise HTTPException(status_code=400, detail="context は必須です")
    extra_hint = _sanitize_text(payload.extra_hint, 500) or ""

    hint_block = f"## 追加指示:\n{extra_hint}\n\n" if extra_hint else ""
    if kind == "reply_draft":
        sys_prompt = "あなたは200名規模の学習塾を運営する塾長の秘書 AI です。生徒・保護者からの問い合わせに対し、塾長口調で丁寧かつ温かい返信案を作成します。教師名や塾名は塾長指示で出さない方針。返信案は 100〜250 字、改行は適度に入れて読みやすく。署名や末尾挨拶は不要 (本文のみ)。純粋なテキストのみ返答 (前置きや解説は不要)。"
        user_prompt = f"以下の問い合わせに対する返信案を作成してください。\n\n## 受信メッセージ:\n{context}\n\n{hint_block}## 要件:\n- 塾長口調 (温かく・誠実に)\n- 100〜250 字程度\n- 適度な改行で読みやすく\n- 署名/末尾挨拶 (敬具など) は不要"
    else:  # broadcast_draft
        sys_prompt = "あなたは200名規模の学習塾を運営する塾長の秘書 AI です。塾長が指定する要点から、保護者・生徒に一斉送信する案内文を整えます。教師名や塾名は塾長指示で出さない方針。文章は 200〜500 字、見出しや箇条書きを使い読みやすく。署名や末尾挨拶は不要 (本文のみ)。純粋なテキストのみ返答 (前置きや解説は不要)。"
        user_prompt = f"以下の要点から、一斉送信用の案内文を作成してください。\n\n## 要点:\n{context}\n\n{hint_block}## 要件:\n- 塾長口調 (敬体・温かく)\n- 200〜500 字程度\n- 見出しや箇条書きを適度に活用\n- 署名/末尾挨拶 (敬具など) は不要"

    body = {
        "model": "gemini-2.5-flash",
        "max_tokens": 1500,
        "system": sys_prompt,
        "messages": [{"role": "user", "content": user_prompt}],
    }
    try:
        data = _call_gemini(body, model="gemini-2.5-flash", kind=f"admin_{kind}")
        text = "".join(c.get("text", "") for c in (data.get("content") or []) if isinstance(c, dict)).strip()
        if not text:
            raise HTTPException(status_code=503, detail="AI が空文字を返しました。再度お試しください")
        log.info(f"[AdminAiDraft] kind={kind} ip={_client_ip(request)} chars={len(text)}")
        return {"ok": True, "draft": text, "model": data.get("_actual_model"), "kind": kind}
    except HTTPException:
        raise
    except Exception as e:
        log.error(f"[AdminAiDraft] failed kind={kind}: {type(e).__name__}: {str(e)[:200]}")
        raise HTTPException(status_code=503, detail=f"AI 生成失敗: {str(e)[:200]}")


class CourseInquiryRequest(BaseModel):
    course: str  # 'kokuritsu_nankan'
    note: Optional[str] = None  # 任意の追記


# 🚩 2026-05-13 塾長指示「選択肢が間違っている問題もある」:
# 生徒から AI 生成問題の違和感報告を受け付ける endpoint
class QuestionIssueReport(BaseModel):
    question_id: Optional[str] = None
    exam_id: Optional[str] = None
    section_key: Optional[str] = None
    grade_key: Optional[str] = None
    stem: Optional[str] = None
    choices: Optional[list] = None
    correct_answer: Optional[str] = None
    explanation: Optional[str] = None
    reason: str
    reported_at: Optional[str] = None
    page_url: Optional[str] = None
    user_agent: Optional[str] = None


@app.post("/api/student/report-question-issue")
def student_report_question_issue(payload: QuestionIssueReport, request: Request, authorization: Optional[str] = Header(None)):
    """生徒からの問題違和感報告を events に記録 → CEO ダッシュで集計表示。

    塾長指示「選択肢が間違っている問題もある」(2026-05-13) で実装。
    AI 生成問題の品質バグを生徒が即報告できる UX。
    """
    _check_rate_limit_ip(request, bucket="question_issue_report", limit=20, window=600)
    student = _get_current_student(authorization)
    # 未ログイン状態でも報告は受け付ける (匿名・体験中の生徒も対象)
    student_id = (student or {}).get("id") if student else None
    student_name = (student or {}).get("name") if student else "(未ログイン)"
    student_email = (student or {}).get("email") if student else None

    # text を sanitize
    reason = _sanitize_text(payload.reason, 500) or ""
    stem = _sanitize_text(payload.stem, 500) or ""
    explanation = _sanitize_text(payload.explanation, 800) or ""

    if not reason.strip():
        raise HTTPException(status_code=400, detail="reason が空です")

    conn = db()
    try:
        c = conn.cursor()
        # events に記録 (CEO ダッシュで grep 集計可能)
        c.execute(
            "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
            ("question_issue_report", json.dumps({
                "student_id": student_id,
                "student_name": student_name,
                "student_email": student_email,
                "question_id": payload.question_id,
                "exam_id": payload.exam_id,
                "section_key": payload.section_key,
                "grade_key": payload.grade_key,
                "stem": stem,
                "choices": payload.choices,
                "correct_answer": payload.correct_answer,
                "explanation": explanation,
                "reason": reason,
                "page_url": payload.page_url,
                "user_agent": (payload.user_agent or "")[:200],
                "reported_at": payload.reported_at,
            }, ensure_ascii=False), f"issue-report-{student_id or 'anon'}")
        )
        conn.commit()
    except Exception as e:
        log.warning(f"[report-question-issue] event log failed: {e}")
    finally:
        try: conn.close()
        except Exception: pass

    # 塾長への 24h 集計通知は ai-juku CEO ダッシュ側で実装 (後続)
    return {"ok": True, "message": "報告を受け付けました。塾長が確認後、問題プールから修正・除外します。"}


@app.post("/api/student/course-inquiry")
def student_course_inquiry(payload: CourseInquiryRequest, request: Request, authorization: Optional[str] = Header(None)):
    """生徒: コース申込問い合わせ。CEOダッシュ通知 + 塾長 email 通知 + 生徒に確認 in-app message を送信。"""
    _check_rate_limit_ip(request, bucket="course_inquiry", limit=5, window=600)
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    course = (payload.course or "").strip()
    if course != _STUDY_LOG_TARGET_COURSE:
        raise HTTPException(status_code=400, detail="course が不正です")
    # 既加入なら 409 (重複申込防止)
    if (student.get("course") or None) == _STUDY_LOG_TARGET_COURSE:
        raise HTTPException(status_code=409, detail="すでに加入済みのコースです")
    note = _sanitize_text(payload.note, 500)
    course_label = "国公立難関大学コース"

    conn = db()
    try:
        c = conn.cursor()
        # 監査 events に記録
        try:
            c.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                ("course_inquiry", json.dumps({
                    "student_id": student["id"], "name": student["name"], "email": student.get("email"),
                    "grade": student.get("grade"), "course": course, "note": note,
                }, ensure_ascii=False), "student_action")
            )
        except Exception as ev_err:
            log.warning(f"[CourseInquiry] events log failed: {ev_err}")

        # 塾長宛 in-app message として messages テーブルにも保存 (CEO ダッシュ履歴に出す)
        admin_subject = f"📥 {course_label} 申込問い合わせ ({student['name']})"
        admin_body = f"生徒「{student['name']}」({student.get('grade') or '学年未設定'}) から {course_label} の申込問い合わせがありました。\n\nメール: {student.get('email') or '未登録'}\nメモ: {note or '(なし)'}"
        try:
            c.execute(
                "INSERT INTO messages (sender_type, sender_id, recipient_type, recipient_id, broadcast_filter, subject, body, sent_via, email_status) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                ("student", student["id"], "admin", None, None, admin_subject, admin_body, "in_app", None)
            )
        except Exception as me:
            log.warning(f"[CourseInquiry] messages log failed: {me}")
        # 生徒に確認 in-app message を保存
        try:
            c.execute(
                "INSERT INTO messages (sender_type, sender_id, recipient_type, recipient_id, broadcast_filter, subject, body, sent_via, email_status) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                ("admin", None, "student", student["id"], None,
                 f"📥 {course_label} 申込お問い合わせを受け付けました",
                 f"このたびは {course_label} へのお問い合わせありがとうございます。\n塾長から折り返しご連絡いたします (通常 1〜2 営業日以内)。\n\nお問い合わせ内容:\n{note or '(コメントなし)'}",
                 "in_app", None)
            )
        except Exception as me2:
            log.warning(f"[CourseInquiry] confirm message failed: {me2}")

        conn.commit()
        log.info(f"[CourseInquiry] student={student['id']} course={course} ip={_client_ip(request)}")
    finally:
        conn.close()

    # 塾長宛 email 通知 (env DAILY_SNS_TO_EMAIL を流用 / 未設定なら skip)
    admin_to = os.getenv("DAILY_SNS_TO_EMAIL") or os.getenv("MONITORING_TO_EMAIL")
    if admin_to and RESEND_API_KEY:
        try:
            _send_message_email(
                admin_to,
                f"📥 {course_label} 申込問い合わせ ({student['name']})",
                f"塾長へ\n\n生徒「{student['name']}」({student.get('grade') or '学年未設定'}) から {course_label} の申込問い合わせがありました。\n\nメール: {student.get('email') or '未登録'}\nメモ: {note or '(なし)'}\n\nCEO ダッシュ → 📨 メッセージ配信 → 送信履歴 で詳細確認できます。",
                student_name="塾長"
            )
        except Exception as ee:
            log.warning(f"[CourseInquiry] admin email failed: {ee}")

    return {"ok": True, "message": "お問い合わせを受け付けました。塾長から折り返しご連絡いたします。"}


@app.get("/api/messages/me/unread-count")
def get_my_unread_count(authorization: Optional[str] = Header(None)):
    """生徒: 未読件数 (badge 表示用 - 軽量)。"""
    student = _get_current_student(authorization)
    if not student:
        raise HTTPException(status_code=401, detail="Unauthorized")
    conn = db()
    try:
        c = conn.cursor()
        c.execute(
            "SELECT COUNT(*) AS n FROM messages WHERE recipient_type = 'student' AND recipient_id = ? AND read_at IS NULL",
            (student["id"],)
        )
        row = c.fetchone()
        return {"ok": True, "unread_count": int((row["n"] if row else 0) or 0)}
    finally:
        conn.close()


# ==========================================================================
# 🗄️ R2 daily DB backup (Cloudflare R2 = vendor-separated 真の DR)
# 2026-05-20 Railway 全体障害で「DB と app の同居 = DB も道連れ」教訓から実装。
# Supabase 自身も daily backup を持つが、Supabase アカウント自体が飛ぶ catastrophic
# 障害に備え別事業者 (Cloudflare R2) に dump を保存する 2nd backup。
# pure Python (psycopg + json + gzip + boto3) で pg_dump binary 不要。
# env: R2_ACCOUNT_ID / R2_ACCESS_KEY_ID / R2_SECRET_ACCESS_KEY / R2_BUCKET
#      / R2_BACKUP_HOUR_JST (default 3) / R2_BACKUP_RETENTION_DAYS (default 30)
# memory: feedback_in_process_scheduler.md パターン踏襲
# ==========================================================================
def _record_r2_event(name: str, meta: dict):
    """R2 backup 専用 events 記録 (失敗しても backup 本体は止めない)。
    既存 main.py に `_record_event` ヘルパーが存在しないため専用に inline 定義。
    feedback_silent_fail_send_email.md パターンで events に必ず audit log を残す。"""
    try:
        conn = db()
        try:
            # 🚨 _Connection に execute() 無し → .cursor().execute() 経由 (main.py:476)
            cur = conn.cursor()
            cur.execute(
                "INSERT INTO events (name, props, session_id) VALUES (?, ?, ?)",
                (name, json.dumps(meta, ensure_ascii=False, default=str), 'r2_backup_scheduler')
            )
            try: conn.commit()
            except Exception: pass
        finally:
            try: conn.close()
            except Exception: pass
    except Exception as _e:
        log.warning(f'[r2_backup] events 記録失敗 (non-fatal): {_e}')


def _dump_db_to_jsonl_gz() -> bytes:
    """全 public schema table を JSONL (gzip) で dump。
    各行は {"_table": "students", "_data": {col: val, ...}} 形式。restore 時は
    table 別に再分割可能。timestamp/uuid/date 等は default=str で文字列化
    (psycopg restore 時に自動 cast)。bytea 列は現 schema 0 件で問題なし
    (将来追加時は base64 化必須・3 視点 review で再確認)。"""
    import gzip, json, io as _io, re as _re
    # table 名 sanity check (情報スキーマ由来でも防衛的に regex 確認)
    _safe_ident = _re.compile(r'^[a-z_][a-z0-9_]*$')
    out = _io.BytesIO()
    with gzip.GzipFile(fileobj=out, mode='wb', compresslevel=6) as gz:
        gz.write(b'-- ai-juku R2 backup (jsonl.gz)\n')
        gz.write(f'-- generated_at: {datetime.now(timezone.utc).isoformat()}\n'.encode())
        conn = db()
        try:
            # 🚨 _Connection に execute() 無し → .cursor().execute() 経由 (main.py:476)
            cur = conn.cursor()
            cur.execute(
                "SELECT table_name FROM information_schema.tables "
                "WHERE table_schema='public' AND table_type='BASE TABLE' "
                "ORDER BY table_name"
            )
            # _Row wrapper (main.py:401) で row[0] / row["table_name"] 両対応
            tables = []
            for r in cur.fetchall():
                try: tables.append(r["table_name"])
                except (KeyError, TypeError): tables.append(r[0])
            total_rows = 0
            skipped_unsafe = []
            for t in tables:
                # 防衛的: info_schema 由来でも regex で確認 (PostgreSQL は " 含む table 名を許容)
                if not _safe_ident.match(t):
                    skipped_unsafe.append(t)
                    log.warning(f'[r2_backup] skip unsafe table name: {t!r}')
                    continue
                gz.write(f'\n-- TABLE: {t}\n'.encode())
                # _safe_ident regex を通った table 名のみ実行 (実質的に SQL injection 不可能)
                # psycopg は dict_row factory (main.py:483) / sqlite3 は Row 行で dict() 可能
                cur = conn.cursor()
                cur.execute(f'SELECT * FROM "{t}"')
                n = 0
                for row in cur.fetchall():
                    try:
                        rec = dict(row)  # _Row / sqlite3.Row 両対応
                    except Exception:
                        rec = {'_raw': str(row)}
                    line = json.dumps({'_table': t, '_data': rec}, default=str, ensure_ascii=False)
                    gz.write((line + '\n').encode('utf-8'))
                    n += 1
                gz.write(f'-- {t}: {n} rows\n'.encode())
                total_rows += n
            gz.write(f'\n-- TOTAL: {len(tables) - len(skipped_unsafe)} tables, {total_rows} rows\n'.encode())
            if skipped_unsafe:
                gz.write(f'-- SKIPPED unsafe: {skipped_unsafe}\n'.encode())
        finally:
            try: conn.close()
            except Exception: pass
    return out.getvalue()


def _r2_client():
    """boto3 S3 client (Cloudflare R2 endpoint)。env 未設定なら ValueError。"""
    account_id = os.getenv('R2_ACCOUNT_ID', '').strip()
    access_key = os.getenv('R2_ACCESS_KEY_ID', '').strip()
    secret_key = os.getenv('R2_SECRET_ACCESS_KEY', '').strip()
    if not (account_id and access_key and secret_key):
        raise ValueError('R2 env vars not configured (R2_ACCOUNT_ID/R2_ACCESS_KEY_ID/R2_SECRET_ACCESS_KEY)')
    import boto3  # type: ignore
    return boto3.client(
        's3',
        endpoint_url=f'https://{account_id}.r2.cloudflarestorage.com',
        aws_access_key_id=access_key,
        aws_secret_access_key=secret_key,
        region_name='auto',
    )


def _r2_upload_backup(data: bytes, key: str) -> dict:
    """R2 に PUT。bucket は R2_BUCKET env (default ai-juku-db-backup)。"""
    bucket = os.getenv('R2_BUCKET', 'ai-juku-db-backup').strip() or 'ai-juku-db-backup'
    cli = _r2_client()
    cli.put_object(
        Bucket=bucket, Key=key, Body=data,
        ContentType='application/gzip',
        Metadata={'source': 'ai-juku-system', 'generated_at': datetime.now(timezone.utc).isoformat()},
    )
    return {'bucket': bucket, 'key': key, 'size': len(data)}


def _r2_prune_old_backups(retention_days: int) -> int:
    """retention_days より古い backup を R2 から削除。削除件数を返す。"""
    bucket = os.getenv('R2_BUCKET', 'ai-juku-db-backup').strip() or 'ai-juku-db-backup'
    cli = _r2_client()
    cutoff = datetime.now(timezone.utc) - timedelta(days=max(1, retention_days))
    deleted = 0
    paginator = cli.get_paginator('list_objects_v2')
    for page in paginator.paginate(Bucket=bucket, Prefix='ai-juku/'):
        for obj in page.get('Contents') or []:
            lm = obj.get('LastModified')
            if lm and lm < cutoff:
                cli.delete_object(Bucket=bucket, Key=obj['Key'])
                deleted += 1
    return deleted


def _run_r2_backup() -> dict:
    """1 回分の backup 実行。成功で {ok:True, key, size, size_bytes, tables_count, duration_sec, ...}、失敗で例外。

    2026-05-21: ceo.js (CEO ダッシュ UI) との shape 整合のため `size_bytes` / `tables_count` /
    `duration_sec` を追加。`size` も後方互換で残す (events / 既存 log 用)。
    """
    import time as _t
    t0 = _t.monotonic()
    now = datetime.now(timezone(timedelta(hours=9)))
    # table 数を先に取得 (events / UI 表示用・5ms 追加 query)
    # memory: feedback_postgres_dict_row.md — _Row wrapper (main.py:401) で row["n"] / row[0] 両対応
    # 🚨 _Connection に execute() 無し (main.py:476) → 必ず .cursor().execute() で経由する
    tables_count = None
    try:
        conn = db()
        try:
            cur = conn.cursor()
            cur.execute(
                "SELECT COUNT(*) AS n FROM information_schema.tables "
                "WHERE table_schema='public' AND table_type='BASE TABLE'"
            )
            row = cur.fetchone()
            if row: tables_count = int(row["n"])
        finally:
            try: conn.close()
            except Exception: pass
    except Exception as e:
        log.warning(f'[r2_backup] tables_count fetch failed (non-fatal): {e}')
    data = _dump_db_to_jsonl_gz()
    key = f'ai-juku/{now.strftime("%Y/%m")}/db-{now.strftime("%Y%m%d-%H%M%S")}.jsonl.gz'
    result = _r2_upload_backup(data, key)
    duration_sec = round(_t.monotonic() - t0, 2)
    retention = int(os.getenv('R2_BACKUP_RETENTION_DAYS', '30'))
    pruned = 0
    try:
        pruned = _r2_prune_old_backups(retention)
    except Exception as e:
        log.warning(f'[r2_backup] prune failed (non-fatal): {e}')
    try:
        _record_r2_event('r2_backup_success', {
            'key': key, 'size': result.get('size'), 'tables_count': tables_count,
            'duration_sec': duration_sec, 'pruned': pruned,
        })
    except Exception:
        pass
    return {
        **result,
        # 🎯 ceo.js が参照する alias / 追加フィールド (2026-05-21 shape 整合)
        'size_bytes': result.get('size'),
        'tables_count': tables_count,
        'duration_sec': duration_sec,
        'pruned': pruned,
        'retention_days': retention,
    }


async def _r2_backup_scheduler():
    """毎日 R2_BACKUP_HOUR_JST (default 3:00 JST) に backup 実行。
    feedback_in_process_scheduler.md パターン + notifications dedup なし
    (毎日 1 回確実に走らせる・events.r2_backup_success で audit)。"""
    target_h = int(os.getenv('R2_BACKUP_HOUR_JST', '3'))
    log.info(f'[r2_backup_scheduler] launched (target JST {target_h}:00 daily)')
    last_run_date = None
    while True:
        try:
            now = datetime.now(timezone(timedelta(hours=9)))
            today_str = now.strftime('%Y-%m-%d')
            if now.hour == target_h and last_run_date != today_str:
                try:
                    if not os.getenv('R2_ACCOUNT_ID'):
                        log.warning('[r2_backup_scheduler] R2_ACCOUNT_ID not set, skip')
                    else:
                        result = _run_r2_backup()
                        log.info(f'[r2_backup_scheduler] success: {result}')
                    last_run_date = today_str
                except Exception as e:
                    log.error(f'[r2_backup_scheduler] failed: {e}')
                    try:
                        _record_r2_event('r2_backup_failed', {'error': str(e)[:500]})
                    except Exception: pass
                    # failure でも last_run_date 更新で 1 日 1 回 retry に留める
                    last_run_date = today_str
                await asyncio.sleep(3600)  # 1h sleep to avoid double fire
            else:
                await asyncio.sleep(300)  # 5 min poll
        except asyncio.CancelledError:
            return
        except Exception as e:
            log.error(f'[r2_backup_scheduler] outer: {e}')
            await asyncio.sleep(300)


@app.post('/api/admin/db/snapshot-to-r2')
def admin_db_snapshot_to_r2(
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
):
    """🗄️ R2 への DB snapshot 手動 trigger (CEO ダッシュ + cron 両用)。
    認証: admin Bearer または X-Cron-Secret。"""
    authed = False
    if authorization and authorization.startswith('Bearer '):
        token = authorization[len('Bearer '):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail='未認証')
    try:
        result = _run_r2_backup()
        return {'ok': True, **result}
    except ValueError as e:
        # R2 env 未設定
        raise HTTPException(status_code=503, detail=str(e))
    except Exception as e:
        log.error(f'[admin_db_snapshot_to_r2] {e}')
        raise HTTPException(status_code=500, detail=f'backup failed: {str(e)[:200]}')


@app.get('/api/admin/db/r2-backups')
def admin_db_r2_backups(
    authorization: Optional[str] = Header(None),
    x_cron_secret: Optional[str] = Header(None),
    limit: int = 30,
):
    """🗄️ R2 上の backup 一覧 (CEO ダッシュ表示用)。
    認証: admin Bearer または X-Cron-Secret。"""
    authed = False
    if authorization and authorization.startswith('Bearer '):
        token = authorization[len('Bearer '):].strip()
        if _verify_admin_token(token):
            authed = True
    if not authed and CRON_SECRET and x_cron_secret and hmac.compare_digest(x_cron_secret, CRON_SECRET):
        authed = True
    if not authed:
        raise HTTPException(status_code=401, detail='未認証')
    try:
        bucket = os.getenv('R2_BUCKET', 'ai-juku-db-backup').strip() or 'ai-juku-db-backup'
        cli = _r2_client()
        resp = cli.list_objects_v2(Bucket=bucket, Prefix='ai-juku/', MaxKeys=max(1, min(limit, 1000)))
        items = []
        for obj in (resp.get('Contents') or [])[:limit]:
            items.append({
                'key': obj['Key'],
                'size': obj.get('Size'),
                'last_modified': obj['LastModified'].isoformat() if obj.get('LastModified') else None,
            })
        items.sort(key=lambda x: x.get('last_modified') or '', reverse=True)
        return {'ok': True, 'bucket': bucket, 'count': len(items), 'items': items}
    except ValueError as e:
        raise HTTPException(status_code=503, detail=str(e))
    except Exception as e:
        log.error(f'[admin_db_r2_backups] {e}')
        raise HTTPException(status_code=500, detail=str(e)[:200])


